fn standard_output_function_contract(
    name: &str,
) -> Option<TransformTemplateStandardOutputFunctionContract> {
    TRANSFORM_TEMPLATE_STANDARD_OUTPUT_FUNCTIONS
        .iter()
        .copied()
        .find(|function| function.name == name)
}

fn output_function_matches(
    function: &TransformTemplateOutputFunctionDescriptor,
    query: &TransformTemplateOutputFunctionQuery,
) -> bool {
    query.kind.is_none_or(|kind| function.kind == kind)
        && output_function_visible_to(function, query)
        && query
            .owner
            .as_deref()
            .is_none_or(|owner| function.owner.as_deref() == Some(owner))
        && query
            .name
            .as_deref()
            .is_none_or(|name| function.name == name)
        && query.content_type.as_deref().is_none_or(|content_type| {
            content_type_essence(&function.content_type) == content_type_essence(content_type)
        })
        && query
            .schema
            .as_deref()
            .is_none_or(|schema| function.schema == schema)
        && query
            .category
            .as_deref()
            .is_none_or(|category| function.category == category)
        && query
            .subject
            .as_deref()
            .is_none_or(|subject| function.subject == subject)
        && query
            .profile
            .as_deref()
            .is_none_or(|profile| function.profile.as_deref() == Some(profile))
}

fn output_function_visible_to(
    function: &TransformTemplateOutputFunctionDescriptor,
    query: &TransformTemplateOutputFunctionQuery,
) -> bool {
    if function.visibility == TransformTemplateModuleVisibility::Public
        || function.owner.is_none()
        || standard_output_function_contract(&function.name)
            .is_some_and(|contract| contract.matches_descriptor(function))
    {
        return true;
    }

    query
        .owner
        .as_deref()
        .is_some_and(|owner| function.owner.as_deref() == Some(owner))
}

fn output_function_matches_alias(
    function: &TransformTemplateOutputFunctionDescriptor,
    query: &TransformTemplateOutputFunctionQuery,
) -> bool {
    let Some(name) = query.name.as_deref() else {
        return false;
    };
    function.extends.as_deref() == Some(name)
        && output_function_matches(
            function,
            &TransformTemplateOutputFunctionQuery {
                name: Some(function.name.clone()),
                ..query.clone()
            },
        )
}

impl TransformTemplateOutputFunctionQuery {
    pub fn for_identity(
        kind: TransformTemplateOutputFunctionKind,
        content_type: impl Into<String>,
        schema: impl Into<String>,
        category: impl Into<String>,
        subject: impl Into<String>,
    ) -> Self {
        Self {
            kind: Some(kind),
            content_type: Some(content_type.into()),
            schema: Some(schema.into()),
            category: Some(category.into()),
            subject: Some(subject.into()),
            ..Self::default()
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TransformTemplateOutputFunctionResolutionError {
    Unknown {
        kind: Option<TransformTemplateOutputFunctionKind>,
        name: Option<String>,
        category: Option<String>,
        subject: Option<String>,
    },
    Ambiguous {
        function_names: Vec<String>,
    },
    MissingCapability {
        function_name: String,
        capability: String,
    },
    FallbackUnavailable {
        function_name: String,
        fallback_name: String,
    },
    NonDeterministicCanonical {
        function_name: String,
    },
    SubjectTypeIncompatible {
        kind: Option<TransformTemplateOutputFunctionKind>,
        name: Option<String>,
        category: Option<String>,
        requested_subjects: Vec<String>,
        available_subjects: Vec<String>,
        function_names: Vec<String>,
    },
    ProducedKindIncompatible {
        function_name: String,
        produces: TransformTemplateOutputProducedKind,
        target_syntax: TransformTemplateTargetSyntaxKind,
        expected: String,
    },
    UnsafeRawInsertion {
        function_name: String,
        category: String,
        content_type: String,
    },
    LossyOutput {
        function_name: String,
        category: String,
        content_type: String,
    },
    UnsupportedCharset {
        charset: String,
    },
    CharsetMismatch {
        content_type: String,
        declared_charset: String,
        requested_charset: String,
    },
    InvalidTargetSyntax {
        message: String,
    },
    InvalidColorProfile {
        message: String,
    },
    UnsupportedTerminalColorCapability {
        selector: String,
    },
    InaccessibleHtmlPalette {
        selector: String,
    },
}

impl TransformTemplateOutputFunctionResolutionError {
    fn unknown_for_query(query: &TransformTemplateOutputFunctionQuery) -> Self {
        Self::Unknown {
            kind: query.kind,
            name: query.name.clone(),
            category: query.category.clone(),
            subject: query.subject.clone(),
        }
    }

    pub fn diagnostic(&self, uri: Option<&str>) -> Diagnostic {
        match self {
            Self::Unknown {
                kind,
                name,
                category,
                subject,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: transform_template_unknown_output_function_code(*kind).to_owned(),
                severity: Severity::Error,
                message: transform_template_unknown_output_function_message(
                    *kind,
                    name.as_deref(),
                    category.as_deref(),
                    subject.as_deref(),
                ),
                details: None,
                ..Diagnostic::default()
            },
            Self::Ambiguous { function_names } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_AMBIGUOUS_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function resolution is ambiguous: {}",
                    function_names.join(", ")
                ),
                ..Diagnostic::default()
            },
            Self::MissingCapability {
                function_name,
                capability,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_CAPABILITY_MISSING_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` requires unavailable capability `{capability}`"
                ),
                ..Diagnostic::default()
            },
            Self::FallbackUnavailable {
                function_name,
                fallback_name,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_FALLBACK_UNAVAILABLE_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` fallback `{fallback_name}` is unavailable"
                ),
                ..Diagnostic::default()
            },
            Self::NonDeterministicCanonical { function_name } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_CANONICAL_NONDETERMINISTIC_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` cannot produce canonical output because it is not declared deterministic"
                ),
                ..Diagnostic::default()
            },
            Self::SubjectTypeIncompatible {
                kind,
                name,
                category,
                requested_subjects,
                available_subjects,
                function_names,
            } => {
                let label = transform_template_output_function_label(*kind);
                let mut message = format!(
                    "CEMT {label} subject type is incompatible: requested {}, but matching {} {} accept {}",
                    format_transform_template_selector_list(requested_subjects),
                    label,
                    format_transform_template_selector_list(function_names),
                    format_transform_template_selector_list(available_subjects)
                );
                if let Some(name) = name.as_deref().filter(|name| !name.trim().is_empty()) {
                    message.push_str(&format!(" for requested function `{name}`"));
                }
                if let Some(category) = category
                    .as_deref()
                    .filter(|category| !category.trim().is_empty())
                {
                    message.push_str(&format!(" in category `{category}`"));
                }
                Diagnostic {
                    uri: uri.map(str::to_owned),
                    code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_SUBJECT_TYPE_INCOMPATIBLE_CODE
                        .to_owned(),
                    severity: Severity::Error,
                    message,
                    ..Diagnostic::default()
                }
            }
            Self::ProducedKindIncompatible {
                function_name,
                produces,
                target_syntax,
                expected,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_PRODUCED_KIND_INCOMPATIBLE_CODE
                    .to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` produces `{}` but `{}` target syntax requires {expected}",
                    produces.as_str(),
                    target_syntax.as_str()
                ),
                ..Diagnostic::default()
            },
            Self::UnsafeRawInsertion {
                function_name,
                category,
                content_type,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_UNSAFE_RAW_INSERTION_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` cannot insert raw `{category}` output for `{content_type}` because it is not declared trusted"
                ),
                ..Diagnostic::default()
            },
            Self::LossyOutput {
                function_name,
                category,
                content_type,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_LOSSY_OUTPUT_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT output function `{function_name}` is declared lossy for `{category}` output on `{content_type}`; set `allowLossy` to true to bind it"
                ),
                ..Diagnostic::default()
            },
            Self::UnsupportedCharset { charset } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_UNSUPPORTED_CHARSET_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "charset `{charset}` is not supported; supported charsets are utf-8, utf-16, utf-16be, utf-16le, and us-ascii"
                ),
                ..Diagnostic::default()
            },
            Self::CharsetMismatch {
                content_type,
                declared_charset,
                requested_charset,
            } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_CHARSET_MISMATCH_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "requested charset `{requested_charset}` does not match content type `{content_type}` charset `{declared_charset}`"
                ),
                ..Diagnostic::default()
            },
            Self::InvalidTargetSyntax { message } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_TARGET_SYNTAX_INVALID_CODE.to_owned(),
                severity: Severity::Error,
                message: message.clone(),
                ..Diagnostic::default()
            },
            Self::InvalidColorProfile { message } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_COLOR_PROFILE_INVALID_CODE.to_owned(),
                severity: Severity::Error,
                message: message.clone(),
                ..Diagnostic::default()
            },
            Self::UnsupportedTerminalColorCapability { selector } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_TERMINAL_COLOR_CAPABILITY_UNSUPPORTED_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "unsupported terminal color capability `{selector}`; supported capabilities are none, ansi-16, ansi-256, truecolor, and auto"
                ),
                ..Diagnostic::default()
            },
            Self::InaccessibleHtmlPalette { selector } => Diagnostic {
                uri: uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_HTML_PALETTE_INACCESSIBLE_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "HTML color palette `{selector}` is inaccessible or unavailable for this target"
                ),
                ..Diagnostic::default()
            },
        }
    }
}

fn transform_template_unknown_output_function_code(
    kind: Option<TransformTemplateOutputFunctionKind>,
) -> &'static str {
    match kind {
        Some(TransformTemplateOutputFunctionKind::Encoding) => {
            TRANSFORM_TEMPLATE_OUTPUT_ENCODER_UNKNOWN_CODE
        }
        Some(TransformTemplateOutputFunctionKind::Format) => {
            TRANSFORM_TEMPLATE_OUTPUT_FORMATTER_UNKNOWN_CODE
        }
        Some(TransformTemplateOutputFunctionKind::Color) => {
            TRANSFORM_TEMPLATE_OUTPUT_COLORIZER_UNKNOWN_CODE
        }
        None => TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_UNKNOWN_CODE,
    }
}

fn transform_template_unknown_output_function_message(
    kind: Option<TransformTemplateOutputFunctionKind>,
    name: Option<&str>,
    category: Option<&str>,
    subject: Option<&str>,
) -> String {
    let label = transform_template_output_function_label(kind);
    let mut message = format!("no CEMT {label} matched the requested identity");
    if let Some(name) = name.map(str::trim).filter(|name| !name.is_empty()) {
        message.push_str(&format!(" `{name}`"));
    }
    if let Some(category) = category
        .map(str::trim)
        .filter(|category| !category.is_empty())
    {
        message.push_str(&format!(" for category `{category}`"));
    }
    if let Some(subject) = subject.map(str::trim).filter(|subject| !subject.is_empty()) {
        message.push_str(&format!(" and subject `{subject}`"));
    }
    message
}

fn transform_template_output_function_label(
    kind: Option<TransformTemplateOutputFunctionKind>,
) -> &'static str {
    match kind {
        Some(TransformTemplateOutputFunctionKind::Encoding) => "encoder",
        Some(TransformTemplateOutputFunctionKind::Format) => "formatter",
        Some(TransformTemplateOutputFunctionKind::Color) => "colorizer",
        None => "output function",
    }
}

fn format_transform_template_selector_list(values: &[String]) -> String {
    if values.is_empty() {
        return "`<none>`".to_owned();
    }
    values
        .iter()
        .map(|value| format!("`{value}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

#[derive(Debug, Clone, Default)]
pub struct TransformTemplateOutputFunctionRegistry {
    functions: Vec<TransformTemplateOutputFunctionDescriptor>,
    runtime_functions: BTreeMap<String, CemtRuntimeFunction>,
}

impl TransformTemplateOutputFunctionRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_module_options(options: &TransformTemplateModuleOptions) -> Self {
        Self {
            functions: options.output_functions.clone(),
            runtime_functions: cemt_runtime_functions_from_module_options(options),
        }
    }

    pub fn register(&mut self, function: TransformTemplateOutputFunctionDescriptor) {
        if let Some((name, runtime_function)) = cemt_runtime_function_from_descriptor(&function) {
            self.runtime_functions.insert(name, runtime_function);
        }
        self.functions.push(function);
    }

    pub fn functions(&self) -> &[TransformTemplateOutputFunctionDescriptor] {
        &self.functions
    }

    fn matching_functions<'a>(
        &'a self,
        query: &TransformTemplateOutputFunctionQuery,
    ) -> Vec<&'a TransformTemplateOutputFunctionDescriptor> {
        let exact_matches = self
            .functions
            .iter()
            .filter(|function| output_function_matches(function, query))
            .collect::<Vec<_>>();
        if !exact_matches.is_empty() || query.name.is_none() {
            return exact_matches;
        }

        self.functions
            .iter()
            .filter(|function| output_function_matches_alias(function, query))
            .collect()
    }

    pub fn resolve<'a>(
        &'a self,
        query: &TransformTemplateOutputFunctionQuery,
        host_capabilities: &BTreeSet<String>,
    ) -> Result<
        &'a TransformTemplateOutputFunctionDescriptor,
        TransformTemplateOutputFunctionResolutionError,
    > {
        let matches = self.matching_functions(query);

        let function = match matches.as_slice() {
            [] => {
                return Err(
                    TransformTemplateOutputFunctionResolutionError::unknown_for_query(query),
                )
            }
            [function] => *function,
            many => {
                return Err(TransformTemplateOutputFunctionResolutionError::Ambiguous {
                    function_names: many.iter().map(|function| function.name.clone()).collect(),
                })
            }
        };

        self.resolve_function_capability(function, query, host_capabilities)
    }

    fn resolve_function_capability<'a>(
        &'a self,
        function: &'a TransformTemplateOutputFunctionDescriptor,
        query: &TransformTemplateOutputFunctionQuery,
        host_capabilities: &BTreeSet<String>,
    ) -> Result<
        &'a TransformTemplateOutputFunctionDescriptor,
        TransformTemplateOutputFunctionResolutionError,
    > {
        if function.implementation.requires_capability() {
            let Some(capability) = function.capability.as_deref() else {
                return self.resolve_output_function_fallback_or_capability_error(
                    function,
                    query,
                    host_capabilities,
                    "<missing>",
                );
            };
            if !host_capabilities.contains(capability) {
                return self.resolve_output_function_fallback_or_capability_error(
                    function,
                    query,
                    host_capabilities,
                    capability,
                );
            }
        }

        Ok(function)
    }

    fn resolve_output_function_fallback_or_capability_error<'a>(
        &'a self,
        function: &'a TransformTemplateOutputFunctionDescriptor,
        query: &TransformTemplateOutputFunctionQuery,
        host_capabilities: &BTreeSet<String>,
        capability: &str,
    ) -> Result<
        &'a TransformTemplateOutputFunctionDescriptor,
        TransformTemplateOutputFunctionResolutionError,
    > {
        let Some(fallback_name) = function
            .fallback
            .as_deref()
            .map(str::trim)
            .filter(|fallback| !fallback.is_empty())
        else {
            return Err(
                TransformTemplateOutputFunctionResolutionError::MissingCapability {
                    function_name: function.name.clone(),
                    capability: capability.to_owned(),
                },
            );
        };

        if fallback_name == function.name {
            return Err(
                TransformTemplateOutputFunctionResolutionError::FallbackUnavailable {
                    function_name: function.name.clone(),
                    fallback_name: fallback_name.to_owned(),
                },
            );
        }

        let fallback_query = TransformTemplateOutputFunctionQuery {
            name: Some(fallback_name.to_owned()),
            ..query.clone()
        };
        self.resolve(&fallback_query, host_capabilities)
            .map_err(|error| match error {
                TransformTemplateOutputFunctionResolutionError::Unknown { .. } => {
                    TransformTemplateOutputFunctionResolutionError::FallbackUnavailable {
                        function_name: function.name.clone(),
                        fallback_name: fallback_name.to_owned(),
                    }
                }
                other => other,
            })
    }

    pub fn resolve_encode_binding(
        &self,
        request: &TransformTemplateEncodeBindingRequest,
        host_capabilities: &BTreeSet<String>,
    ) -> Result<TransformTemplateEncodeBinding, TransformTemplateOutputFunctionResolutionError>
    {
        let syntax_rules = request.syntax_rules()?;
        let subject_types = request.subject_type_candidates();
        for subject_type in &subject_types {
            let query = TransformTemplateOutputFunctionQuery {
                kind: Some(TransformTemplateOutputFunctionKind::Encoding),
                owner: request.owner.clone(),
                name: request.options.encoder.clone(),
                content_type: Some(request.target.content_type.clone()),
                schema: Some(request.target.schema.clone()),
                category: Some(request.target.category.clone()),
                subject: Some(subject_type.clone()),
                profile: request.options.profile.clone(),
                ..TransformTemplateOutputFunctionQuery::default()
            };
            match self.resolve(&query, host_capabilities) {
                Ok(function) => {
                    validate_transform_template_output_kind_for_syntax(function, &syntax_rules)?;
                    validate_transform_template_canonical_determinism(function, &request.options)?;
                    validate_transform_template_raw_output_trust(function, &request.options)?;
                    validate_transform_template_lossy_output_policy(function, &request.options)?;
                    let mut identity = TransformTemplateEncodedArtifactIdentity::from_options(
                        function.produces,
                        request.target.clone(),
                        &request.options,
                    );
                    identity.canonical =
                        transform_template_encode_options_are_canonical(function, &request.options);
                    return Ok(TransformTemplateEncodeBinding {
                        function: function.clone(),
                        subject_type: subject_type.clone(),
                        identity,
                        options: request.options.clone(),
                    });
                }
                Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. }) => {
                    continue;
                }
                Err(error) => return Err(error),
            }
        }

        let subjectless_query = TransformTemplateOutputFunctionQuery {
            kind: Some(TransformTemplateOutputFunctionKind::Encoding),
            owner: request.owner.clone(),
            name: request.options.encoder.clone(),
            content_type: Some(request.target.content_type.clone()),
            schema: Some(request.target.schema.clone()),
            category: Some(request.target.category.clone()),
            profile: request.options.profile.clone(),
            ..TransformTemplateOutputFunctionQuery::default()
        };
        if let Some(error) =
            self.subject_type_incompatible_for_query(&subjectless_query, &subject_types)
        {
            return Err(error);
        }

        Err(TransformTemplateOutputFunctionResolutionError::Unknown {
            kind: Some(TransformTemplateOutputFunctionKind::Encoding),
            name: request.options.encoder.clone(),
            category: Some(request.target.category.clone()),
            subject: request.subject_type.as_ref().cloned(),
        })
    }

    pub fn resolve_format_binding(
        &self,
        request: &TransformTemplateEncodeBindingRequest,
        host_capabilities: &BTreeSet<String>,
    ) -> Result<TransformTemplateEncodeBinding, TransformTemplateOutputFunctionResolutionError>
    {
        let syntax_rules = request.syntax_rules()?;
        let subject_types = request.subject_type_candidates();
        let query_profile =
            transform_template_format_function_query_profile(&request.target, &request.options);
        for subject_type in &subject_types {
            let query = TransformTemplateOutputFunctionQuery {
                kind: Some(TransformTemplateOutputFunctionKind::Format),
                owner: request.owner.clone(),
                name: request.options.formatter.clone(),
                content_type: Some(request.target.content_type.clone()),
                schema: Some(request.target.schema.clone()),
                category: Some(request.target.category.clone()),
                subject: Some(subject_type.clone()),
                profile: query_profile.clone(),
                ..TransformTemplateOutputFunctionQuery::default()
            };
            match self.resolve(&query, host_capabilities) {
                Ok(function) => {
                    validate_transform_template_output_kind_for_syntax(function, &syntax_rules)?;
                    validate_transform_template_canonical_determinism(function, &request.options)?;
                    validate_transform_template_raw_output_trust(function, &request.options)?;
                    validate_transform_template_lossy_output_policy(function, &request.options)?;
                    let mut identity = TransformTemplateEncodedArtifactIdentity::from_options(
                        function.produces,
                        request.target.clone(),
                        &request.options,
                    );
                    if identity.formatter_profile.is_none() {
                        identity.formatter_profile = function.profile.clone();
                    }
                    identity.canonical =
                        transform_template_encode_options_are_canonical(function, &request.options);
                    return Ok(TransformTemplateEncodeBinding {
                        function: function.clone(),
                        subject_type: subject_type.clone(),
                        identity,
                        options: request.options.clone(),
                    });
                }
                Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. }) => {
                    continue;
                }
                Err(error) => return Err(error),
            }
        }

        let subjectless_query = TransformTemplateOutputFunctionQuery {
            kind: Some(TransformTemplateOutputFunctionKind::Format),
            owner: request.owner.clone(),
            name: request.options.formatter.clone(),
            content_type: Some(request.target.content_type.clone()),
            schema: Some(request.target.schema.clone()),
            category: Some(request.target.category.clone()),
            profile: query_profile,
            ..TransformTemplateOutputFunctionQuery::default()
        };
        if let Some(error) =
            self.subject_type_incompatible_for_query(&subjectless_query, &subject_types)
        {
            return Err(error);
        }

        Err(TransformTemplateOutputFunctionResolutionError::Unknown {
            kind: Some(TransformTemplateOutputFunctionKind::Format),
            name: request.options.formatter.clone(),
            category: Some(request.target.category.clone()),
            subject: request.subject_type.as_ref().cloned(),
        })
    }

    pub fn resolve_color_binding(
        &self,
        request: &TransformTemplateEncodeBindingRequest,
        host_capabilities: &BTreeSet<String>,
    ) -> Result<TransformTemplateColorBinding, TransformTemplateOutputFunctionResolutionError> {
        let syntax_rules = request.syntax_rules()?;
        let color_profile = request.color_output_profile()?;
        let explicit_profile = request.color_profile_selector();
        let query_profile = explicit_profile.as_ref().map(|selector| {
            transform_template_color_binding_profile_selector(
                &request.target,
                selector,
                &color_profile,
            )
        });

        let subject_types = request.subject_type_candidates();
        for subject_type in &subject_types {
            let query = TransformTemplateOutputFunctionQuery {
                kind: Some(TransformTemplateOutputFunctionKind::Color),
                owner: request.owner.clone(),
                name: request.options.colorizer.clone(),
                content_type: Some(request.target.content_type.clone()),
                schema: Some(request.target.schema.clone()),
                category: Some(request.target.category.clone()),
                subject: Some(subject_type.clone()),
                profile: query_profile.clone(),
                ..TransformTemplateOutputFunctionQuery::default()
            };
            match self.resolve(&query, host_capabilities) {
                Ok(function) => {
                    validate_transform_template_output_kind_for_syntax(function, &syntax_rules)?;
                    validate_transform_template_canonical_determinism(function, &request.options)?;
                    validate_transform_template_lossy_output_policy(function, &request.options)?;
                    let mut identity = TransformTemplateEncodedArtifactIdentity::from_options(
                        function.produces,
                        request.target.clone(),
                        &request.options,
                    );
                    identity.color_profile = Some(
                        explicit_profile
                            .as_deref()
                            .map(|selector| {
                                transform_template_color_binding_profile_selector(
                                    &request.target,
                                    selector,
                                    &color_profile,
                                )
                            })
                            .unwrap_or_else(|| {
                                transform_template_canonical_color_profile_selector(&color_profile)
                            }),
                    );
                    identity.color_capability =
                        transform_template_color_capability_selector(&color_profile);
                    identity.canonical =
                        transform_template_encode_options_are_canonical(function, &request.options);
                    return Ok(TransformTemplateColorBinding {
                        function: function.clone(),
                        subject_type: subject_type.clone(),
                        identity,
                        options: request.options.clone(),
                        color_profile,
                    });
                }
                Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. }) => {
                    continue;
                }
                Err(error) => return Err(error),
            }
        }

        let subjectless_query = TransformTemplateOutputFunctionQuery {
            kind: Some(TransformTemplateOutputFunctionKind::Color),
            owner: request.owner.clone(),
            name: request.options.colorizer.clone(),
            content_type: Some(request.target.content_type.clone()),
            schema: Some(request.target.schema.clone()),
            category: Some(request.target.category.clone()),
            profile: query_profile,
            ..TransformTemplateOutputFunctionQuery::default()
        };
        if let Some(error) =
            self.subject_type_incompatible_for_query(&subjectless_query, &subject_types)
        {
            return Err(error);
        }

        Err(TransformTemplateOutputFunctionResolutionError::Unknown {
            kind: Some(TransformTemplateOutputFunctionKind::Color),
            name: request.options.colorizer.clone(),
            category: Some(request.target.category.clone()),
            subject: request.subject_type.as_ref().cloned(),
        })
    }

    fn subject_type_incompatible_for_query(
        &self,
        query: &TransformTemplateOutputFunctionQuery,
        requested_subjects: &[String],
    ) -> Option<TransformTemplateOutputFunctionResolutionError> {
        let mut subjectless_query = query.clone();
        subjectless_query.subject = None;
        let matches = self.matching_functions(&subjectless_query);
        if matches.is_empty() {
            return None;
        }

        let available_subjects = matches
            .iter()
            .map(|function| function.subject.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        let function_names = matches
            .iter()
            .map(|function| function.name.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();

        Some(
            TransformTemplateOutputFunctionResolutionError::SubjectTypeIncompatible {
                kind: query.kind,
                name: query.name.clone(),
                category: query.category.clone(),
                requested_subjects: requested_subjects.to_vec(),
                available_subjects,
                function_names,
            },
        )
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
