#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodingTarget {
    pub content_type: String,
    pub schema: String,
    pub category: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub context: Option<String>,
}

impl TransformTemplateEncodingTarget {
    pub fn new(
        content_type: impl Into<String>,
        schema: impl Into<String>,
        category: impl Into<String>,
    ) -> Self {
        Self {
            content_type: content_type.into(),
            schema: schema.into(),
            category: category.into(),
            context: None,
        }
    }

    pub fn with_context(mut self, context: impl Into<String>) -> Self {
        self.context = Some(context.into());
        self
    }

    pub fn format_identity(&self) -> FormatIdentity {
        FormatIdentity {
            content_type: Some(self.content_type.clone()),
            schema: Some(self.schema.clone()),
            ..FormatIdentity::default()
        }
    }

    pub fn syntax_rules(
        &self,
        options: &TransformTemplateEncodeOptions,
    ) -> Result<TransformTemplateTargetSyntaxRules, String> {
        TransformTemplateTargetSyntaxRules::for_target(self, options)
    }
}

