fn builtin_cem_tree_formatter(
    binding: &TransformTemplateEncodeBinding,
    subject: &Value,
) -> Result<Value, String> {
    validate_builtin_cem_tree_formatter_binding(binding)?;
    let nodes = transform_template_cem_tree_nodes(subject)?;
    let nodes = transform_template_cem_tree_formatter_nodes(binding, Value::Array(nodes))?;
    transform_template_cem_tree_formatter_envelope(binding, nodes)
}

fn validate_builtin_cem_tree_formatter_binding(
    binding: &TransformTemplateEncodeBinding,
) -> Result<(), String> {
    if binding.function.kind != TransformTemplateOutputFunctionKind::Format {
        return Err(format!(
            "CEM tree formatter implementation cannot execute non-format function `{:?}`",
            binding.function.kind
        ));
    }
    if binding.function.name != "cem.format-tree" {
        return Err(format!(
            "CEM tree formatter implementation `cem.format-tree` cannot execute `{}`",
            binding.function.name
        ));
    }
    if binding.identity.produces != TransformTemplateOutputProducedKind::CemTree {
        return Err(format!(
            "CEM tree formatter expected `cem-tree` output, got `{}`",
            binding.identity.produces.as_str()
        ));
    }
    if content_type_essence(&binding.identity.target.content_type) != CEM_ML_CONTENT_TYPE {
        return Err(format!(
            "CEM tree formatter expected content type `{CEM_ML_CONTENT_TYPE}`, got `{}`",
            binding.identity.target.content_type
        ));
    }
    if binding.identity.target.schema != CEM_ML_SCHEMA_URI {
        return Err(format!(
            "CEM tree formatter expected schema `{CEM_ML_SCHEMA_URI}`, got `{}`",
            binding.identity.target.schema
        ));
    }
    if binding.identity.target.category != "cem-tree" {
        return Err(format!(
            "CEM tree formatter expected category `cem-tree`, got `{}`",
            binding.identity.target.category
        ));
    }
    Ok(())
}

fn transform_template_cem_tree_formatter_nodes(
    binding: &TransformTemplateEncodeBinding,
    subject: Value,
) -> Result<Value, String> {
    validate_builtin_cem_tree_formatter_binding(binding)?;
    let nodes = transform_template_cem_tree_nodes(&subject).map_err(|message| {
        format!("CEM tree formatter fallback expected CEM tree subject: {message}")
    })?;
    let nodes = nodes
        .into_iter()
        .map(|node| transform_template_format_cem_tree_node(node, binding, 0))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(transform_template_cem_tree_formatter_inter_node_whitespace(
        binding, nodes,
    ))
}

fn transform_template_cem_tree_formatter_inter_node_whitespace(
    binding: &TransformTemplateEncodeBinding,
    nodes: Vec<Value>,
) -> Value {
    Value::Array(transform_template_insert_formatter_whitespace_nodes(
        nodes,
        transform_template_cem_tree_formatter_line_ending_data(&binding.options),
        "formatter.line-ending",
    ))
}

fn transform_template_cem_tree_formatter_block_children(
    binding: &TransformTemplateEncodeBinding,
    nodes: Vec<Value>,
    depth: usize,
) -> Value {
    Value::Array(
        transform_template_insert_formatter_block_child_layout_nodes(
            nodes,
            &binding.options,
            depth,
        ),
    )
}

fn transform_template_cem_tree_formatter_envelope(
    binding: &TransformTemplateEncodeBinding,
    subject: Value,
) -> Result<Value, String> {
    validate_builtin_cem_tree_formatter_binding(binding)?;
    let nodes = transform_template_cemt_runtime_node_array_subject(
        "cem.format-tree.build-envelope",
        subject,
    )?;
    let format_nodes = transform_template_cem_tree_format_nodes(
        &nodes,
        binding.identity.formatter_profile.as_deref(),
        &binding.options,
    );
    Ok(serde_json::json!({
        "kind": "cem-tree",
        "contentType": binding.identity.target.content_type.clone(),
        "schema": binding.identity.target.schema.clone(),
        "category": binding.identity.target.category.clone(),
        "mode": binding.identity.mode.as_str(),
        "canonical": binding.identity.canonical,
        "formatterProfile": binding.identity.formatter_profile.clone(),
        "formatNodes": format_nodes,
        "nodes": nodes,
    }))
}

fn transform_template_cemt_runtime_node_array_subject(
    owner: &str,
    subject: Value,
) -> Result<Vec<Value>, String> {
    match subject {
        Value::Array(nodes) => Ok(nodes),
        _ => Err(format!(
            "{owner} expected formatted CEM tree node array subject"
        )),
    }
}

fn transform_template_cem_tree_nodes(subject: &Value) -> Result<Vec<Value>, String> {
    match subject {
        Value::Array(nodes) => Ok(nodes.clone()),
        Value::Object(fields) => {
            if fields.get("kind").and_then(Value::as_str) == Some("cem-tree") {
                if let Some(nodes) = fields.get("nodes").and_then(Value::as_array) {
                    return Ok(nodes.clone());
                }
                if let Some(node) = fields.get("node").filter(|node| node.is_object()) {
                    return Ok(vec![node.clone()]);
                }
                if let Some(root) = fields.get("root").filter(|root| root.is_object()) {
                    return Ok(vec![root.clone()]);
                }
            }
            Ok(vec![subject.clone()])
        }
        _ => Err("cem.format-tree expected CEM AST object or node array subject".to_owned()),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TransformTemplateCemTreeLayout {
    Inline,
    Block,
}

impl TransformTemplateCemTreeLayout {
    fn as_str(self) -> &'static str {
        match self {
            Self::Inline => "inline",
            Self::Block => "block",
        }
    }
}

fn transform_template_format_cem_tree_nodes_at_depth(
    nodes: Vec<Value>,
    binding: &TransformTemplateEncodeBinding,
    depth: usize,
) -> Result<Vec<Value>, String> {
    let nodes = nodes
        .into_iter()
        .map(|node| transform_template_format_cem_tree_node(node, binding, depth))
        .collect::<Result<Vec<_>, _>>()?;
    transform_template_cemt_runtime_node_array_subject(
        "cem.format-tree.format-nodes",
        transform_template_cem_tree_formatter_inter_node_whitespace(binding, nodes),
    )
}

fn transform_template_format_cem_tree_node(
    node: Value,
    binding: &TransformTemplateEncodeBinding,
    depth: usize,
) -> Result<Value, String> {
    match node {
        Value::Array(nodes) => Ok(Value::Array(
            transform_template_format_cem_tree_nodes_at_depth(nodes, binding, depth)?,
        )),
        Value::Object(fields) => transform_template_format_cem_tree_object(fields, binding, depth),
        other => Ok(other),
    }
}

fn transform_template_format_cem_tree_object(
    mut fields: serde_json::Map<String, Value>,
    binding: &TransformTemplateEncodeBinding,
    depth: usize,
) -> Result<Value, String> {
    let source_map = transform_template_cem_tree_node_source_map(&fields);
    let layout = transform_template_cem_tree_child_layout_for_fields(&fields);
    let attribute_count = transform_template_cem_tree_attribute_count(fields.get("attributes"));
    if attribute_count > 0 {
        let format_before_attributes = transform_template_cem_tree_formatter_whitespace_node(
            " ",
            "formatter.attribute-prefix",
            source_map.as_ref(),
        );
        fields
            .entry("formatBeforeAttributes".to_owned())
            .or_insert(format_before_attributes);
    }
    if attribute_count > 1 {
        transform_template_cem_tree_wrap_attributes_at_column(
            &mut fields,
            binding,
            depth,
            source_map.as_ref(),
        )?;
        let format_between_attributes = transform_template_cem_tree_formatter_whitespace_node(
            " ",
            "formatter.attribute-spacing",
            source_map.as_ref(),
        );
        fields
            .entry("formatBetweenAttributes".to_owned())
            .or_insert(format_between_attributes);
    }
    for field in ["children", "nodes", "slots"] {
        if let Some(value) = fields.remove(field) {
            let child_layout =
                layout.unwrap_or_else(|| transform_template_cem_tree_child_layout(&value));
            fields.insert(
                field.to_owned(),
                transform_template_format_cem_tree_child_value(
                    value,
                    binding,
                    depth.saturating_add(1),
                    child_layout,
                )?,
            );
        }
    }
    if transform_template_cem_tree_has_children(&fields) {
        let layout = layout.unwrap_or(TransformTemplateCemTreeLayout::Inline);
        fields.entry("formatLayout".to_owned()).or_insert_with(|| {
            transform_template_cem_tree_format_decision(
                "layout",
                "formatter.layout",
                layout.as_str().to_owned(),
                None,
                source_map.as_ref(),
            )
        });
        if !fields.contains_key("formatContentBoundary") {
            fields.insert(
                "formatContentBoundary".to_owned(),
                transform_template_cem_tree_content_boundary_nodes(
                    &binding.options,
                    layout,
                    source_map.as_ref(),
                ),
            );
        }
        if layout == TransformTemplateCemTreeLayout::Block {
            fields
                .entry("formatBeforeClose".to_owned())
                .or_insert_with(|| {
                    transform_template_cem_tree_formatter_whitespace_node(
                        &transform_template_cem_tree_formatter_indent_data(&binding.options, depth),
                        "formatter.close-indent",
                        source_map.as_ref(),
                    )
                });
        }
    }
    Ok(Value::Object(fields))
}

fn transform_template_cem_tree_wrap_attributes_at_column(
    fields: &mut serde_json::Map<String, Value>,
    binding: &TransformTemplateEncodeBinding,
    depth: usize,
    source_map: Option<&SourceMapStack>,
) -> Result<(), String> {
    let Some(wrap_column) =
        transform_template_cem_tree_attribute_wrap_column(&binding.options, binding)?
    else {
        return Ok(());
    };
    let name = match transform_template_cem_tree_name(fields) {
        Some("") => String::new(),
        Some("$") => "$".to_owned(),
        Some(raw_name) => transform_template_encode_cem_name(raw_name)?,
        None => "node".to_owned(),
    };
    let mut width = cemt_display_width(&transform_template_cem_tree_formatter_indent_data(
        &binding.options,
        depth,
    ))
    .saturating_add(1)
    .saturating_add(cemt_display_width(&name));
    let wrapped_indent_width =
        cemt_display_width(&transform_template_cem_tree_formatter_indent_data(
            &binding.options,
            depth.saturating_add(1),
        ));
    let Some(Value::Array(attributes)) = fields.get_mut("attributes") else {
        return Ok(());
    };
    for (index, attribute) in attributes.iter_mut().enumerate() {
        let attribute_fields = attribute.as_object().ok_or_else(|| {
            format!(
                "CEM tree formatter expected attribute object, got {}",
                json_value_type_name(attribute)
            )
        })?;
        let attribute_width = cemt_display_width(&transform_template_cem_tree_attribute_to_text(
            attribute_fields,
        )?);
        let inline_width = width.saturating_add(1).saturating_add(attribute_width);
        if index > 0 && inline_width > wrap_column {
            if let Some(attribute_fields) = attribute.as_object_mut() {
                attribute_fields
                    .entry("formatBefore".to_owned())
                    .or_insert_with(|| {
                        transform_template_cem_tree_formatter_attribute_line_break(
                            &binding.options,
                            depth,
                            "formatter.attribute-spacing",
                            source_map,
                        )
                    });
            }
            width = wrapped_indent_width.saturating_add(attribute_width);
        } else {
            width = inline_width;
        }
    }
    Ok(())
}

fn transform_template_cem_tree_attribute_wrap_column(
    options: &TransformTemplateEncodeOptions,
    binding: &TransformTemplateEncodeBinding,
) -> Result<Option<usize>, String> {
    match binding.identity.formatter_profile.as_deref() {
        Some("pretty" | "tabular") => {
            transform_template_cem_tree_formatter_wrap_column_limit(options)
        }
        _ => Ok(None),
    }
}

fn transform_template_cem_tree_formatter_wrap_column_limit(
    options: &TransformTemplateEncodeOptions,
) -> Result<Option<usize>, String> {
    let Some(value) = transform_template_encode_options_wrap_column_option(options) else {
        return Ok(Some(DEFAULT_FORMATTER_WRAP_COLUMN));
    };
    match value {
        "none" | "preserve" => Ok(None),
        _ => {
            let column = value
                .parse::<usize>()
                .map_err(|_| format!("Formatter option `wrapColumn` must be a positive integer, `none`, or `preserve`, got `{value}`"))?;
            if column == 0 {
                return Err("Formatter option `wrapColumn` must be greater than zero".to_owned());
            }
            Ok(Some(column))
        }
    }
}

fn transform_template_format_cem_tree_child_value(
    value: Value,
    binding: &TransformTemplateEncodeBinding,
    depth: usize,
    layout: TransformTemplateCemTreeLayout,
) -> Result<Value, String> {
    match value {
        Value::Array(children) => {
            let children = children
                .into_iter()
                .map(|child| transform_template_format_cem_tree_node(child, binding, depth))
                .collect::<Result<Vec<_>, _>>()?;
            match layout {
                TransformTemplateCemTreeLayout::Inline => Ok(Value::Array(
                    transform_template_insert_formatter_whitespace_nodes(
                        children,
                        " ".to_owned(),
                        "formatter.whitespace",
                    ),
                )),
                TransformTemplateCemTreeLayout::Block => Ok(
                    transform_template_cem_tree_formatter_block_children(binding, children, depth),
                ),
            }
        }
        Value::Object(_) | Value::String(_) => {
            let child = transform_template_format_cem_tree_node(value, binding, depth)?;
            match layout {
                TransformTemplateCemTreeLayout::Inline => Ok(child),
                TransformTemplateCemTreeLayout::Block => {
                    Ok(transform_template_cem_tree_formatter_block_children(
                        binding,
                        vec![child],
                        depth,
                    ))
                }
            }
        }
        other => Ok(other),
    }
}

fn transform_template_insert_formatter_block_child_layout_nodes(
    nodes: Vec<Value>,
    options: &TransformTemplateEncodeOptions,
    depth: usize,
) -> Vec<Value> {
    let mut formatted = Vec::with_capacity(nodes.len().saturating_mul(3));
    let indent = transform_template_cem_tree_formatter_indent_data(options, depth);
    let line_ending = transform_template_cem_tree_formatter_line_ending_data(options);
    for node in nodes {
        if transform_template_cem_tree_value_is_whitespace(&node) {
            continue;
        }
        let source_map = transform_template_first_cem_tree_source_map(&node);
        formatted.push(transform_template_cem_tree_formatter_whitespace_node(
            &indent,
            "formatter.indent",
            source_map.as_ref(),
        ));
        formatted.push(node);
        formatted.push(transform_template_cem_tree_formatter_whitespace_node(
            &line_ending,
            "formatter.line-ending",
            source_map.as_ref(),
        ));
    }
    formatted
}

fn transform_template_cem_tree_content_boundary_nodes(
    options: &TransformTemplateEncodeOptions,
    layout: TransformTemplateCemTreeLayout,
    source_map: Option<&SourceMapStack>,
) -> Value {
    let trailing = match layout {
        TransformTemplateCemTreeLayout::Inline => {
            transform_template_cem_tree_formatter_whitespace_node(
                " ",
                "formatter.boundary-spacing",
                source_map,
            )
        }
        TransformTemplateCemTreeLayout::Block => {
            transform_template_cem_tree_formatter_whitespace_node(
                &transform_template_cem_tree_formatter_line_ending_data(options),
                "formatter.line-ending",
                source_map,
            )
        }
    };
    Value::Array(vec![
        transform_template_cem_tree_formatter_whitespace_node(
            " ",
            "formatter.boundary-spacing",
            source_map,
        ),
        transform_template_cem_tree_formatter_raw_node(
            "|",
            "formatter.content-boundary",
            source_map,
        ),
        trailing,
    ])
}

fn transform_template_cem_tree_formatter_attribute_line_break(
    options: &TransformTemplateEncodeOptions,
    depth: usize,
    formatter_role: &str,
    source_map: Option<&SourceMapStack>,
) -> Value {
    Value::Array(vec![
        transform_template_cem_tree_formatter_whitespace_node(
            &transform_template_cem_tree_formatter_line_ending_data(options),
            formatter_role,
            source_map,
        ),
        transform_template_cem_tree_formatter_whitespace_node(
            &transform_template_cem_tree_formatter_indent_data(options, depth.saturating_add(1)),
            "formatter.attribute-indent",
            source_map,
        ),
    ])
}

fn transform_template_insert_formatter_whitespace_nodes(
    nodes: Vec<Value>,
    data: String,
    formatter_role: &str,
) -> Vec<Value> {
    let mut formatted = Vec::with_capacity(nodes.len().saturating_mul(2));
    for node in nodes {
        if transform_template_cem_tree_value_is_whitespace(&node) {
            continue;
        }
        if let Some(previous) = formatted.last() {
            if !transform_template_cem_tree_value_is_whitespace(previous)
                && !transform_template_cem_tree_value_is_whitespace(&node)
            {
                let source_map = transform_template_first_cem_tree_source_map(previous)
                    .or_else(|| transform_template_first_cem_tree_source_map(&node));
                formatted.push(transform_template_cem_tree_formatter_whitespace_node(
                    &data,
                    formatter_role,
                    source_map.as_ref(),
                ));
            }
        }
        formatted.push(node);
    }
    formatted
}

fn transform_template_cem_tree_child_layout_for_fields(
    fields: &serde_json::Map<String, Value>,
) -> Option<TransformTemplateCemTreeLayout> {
    fields
        .get("children")
        .or_else(|| fields.get("nodes"))
        .or_else(|| fields.get("slots"))
        .map(transform_template_cem_tree_child_layout)
}

fn transform_template_cem_tree_child_layout(value: &Value) -> TransformTemplateCemTreeLayout {
    let mut child_count = 0usize;
    let mut all_text = true;
    transform_template_visit_cem_tree_renderable_children(value, &mut |child| {
        child_count += 1;
        if !transform_template_cem_tree_value_is_text(child) {
            all_text = false;
        }
    });

    if child_count > 0 && all_text {
        TransformTemplateCemTreeLayout::Inline
    } else {
        TransformTemplateCemTreeLayout::Block
    }
}

fn transform_template_visit_cem_tree_renderable_children(
    value: &Value,
    visit: &mut impl FnMut(&Value),
) {
    match value {
        Value::Array(items) => {
            for item in items {
                if !transform_template_cem_tree_value_is_whitespace(item) {
                    visit(item);
                }
            }
        }
        other if !transform_template_cem_tree_value_is_whitespace(other) => visit(other),
        _ => {}
    }
}

fn transform_template_cem_tree_value_is_text(value: &Value) -> bool {
    match value {
        Value::String(_) => true,
        Value::Object(fields) => matches!(
            fields
                .get("kind")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or("element"),
            "text" | "content" | "string"
        ),
        _ => false,
    }
}

fn transform_template_cem_tree_formatter_whitespace_node(
    data: &str,
    formatter_role: &str,
    source_map: Option<&SourceMapStack>,
) -> Value {
    let mut whitespace = serde_json::Map::new();
    whitespace.insert("kind".to_owned(), Value::String("whitespace".to_owned()));
    whitespace.insert("value".to_owned(), Value::String(data.to_owned()));
    whitespace.insert("formatterOwned".to_owned(), Value::Bool(true));
    whitespace.insert(
        "formatterRole".to_owned(),
        Value::String(formatter_role.to_owned()),
    );
    whitespace.insert(
        "colorRole".to_owned(),
        Value::String("syntax.raw".to_owned()),
    );
    if let Some(source_map) = transform_template_cem_tree_format_source_map_value(source_map) {
        whitespace.insert("sourceMap".to_owned(), source_map);
    }
    Value::Object(whitespace)
}

fn transform_template_cem_tree_formatter_raw_node(
    data: &str,
    formatter_role: &str,
    source_map: Option<&SourceMapStack>,
) -> Value {
    let mut raw = serde_json::Map::new();
    raw.insert("kind".to_owned(), Value::String("raw".to_owned()));
    raw.insert("value".to_owned(), Value::String(data.to_owned()));
    raw.insert("formatterOwned".to_owned(), Value::Bool(true));
    raw.insert(
        "formatterRole".to_owned(),
        Value::String(formatter_role.to_owned()),
    );
    raw.insert(
        "colorRole".to_owned(),
        Value::String("syntax.raw".to_owned()),
    );
    if let Some(source_map) = transform_template_cem_tree_format_source_map_value(source_map) {
        raw.insert("sourceMap".to_owned(), source_map);
    }
    Value::Object(raw)
}

fn transform_template_cem_tree_format_nodes(
    nodes: &[Value],
    formatter_profile: Option<&str>,
    options: &TransformTemplateEncodeOptions,
) -> Vec<Value> {
    let source_map = transform_template_first_cem_tree_source_map_in_values(nodes);
    vec![
        transform_template_cem_tree_format_marker(formatter_profile, source_map.as_ref()),
        transform_template_cem_tree_format_decision(
            "line-ending",
            "formatter.line-ending",
            transform_template_cem_tree_formatter_line_ending(options),
            formatter_profile,
            source_map.as_ref(),
        ),
        transform_template_cem_tree_format_decision(
            "indent",
            "formatter.indent",
            transform_template_cem_tree_formatter_indent(options),
            formatter_profile,
            source_map.as_ref(),
        ),
        transform_template_cem_tree_format_decision(
            "tab-size",
            "formatter.tab-size",
            transform_template_cem_tree_formatter_tab_size(options).to_string(),
            formatter_profile,
            source_map.as_ref(),
        ),
        transform_template_cem_tree_format_decision(
            "ordering",
            "formatter.ordering",
            transform_template_cem_tree_formatter_ordering(options),
            formatter_profile,
            source_map.as_ref(),
        ),
        transform_template_cem_tree_format_decision(
            "wrapping",
            "formatter.wrapping",
            transform_template_cem_tree_formatter_wrapping(options),
            formatter_profile,
            source_map.as_ref(),
        ),
        transform_template_cem_tree_format_decision(
            "whitespace",
            "formatter.whitespace",
            "formatter-owned".to_owned(),
            formatter_profile,
            source_map.as_ref(),
        ),
    ]
}

