fn transform_template_validate_source_text_formatter_options(
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
    syntax_name: &str,
    syntax_prefix: &str,
) -> Result<(), String> {
    for selector in [
        options.formatter.as_deref(),
        options.formatter_profile.as_deref(),
        formatter_profile,
    ]
    .into_iter()
    .flatten()
    {
        let selector = selector.trim();
        if matches!(selector, "" | "preserve" | "canonical")
            || selector == format!("{syntax_prefix}.preserve")
            || selector == format!("{syntax_prefix}.canonical")
        {
            continue;
        }
        return Err(format!(
            "unsupported {syntax_name} source formatter `{selector}`"
        ));
    }
    Ok(())
}

fn transform_template_apply_source_text_line_ending(
    output: String,
    line_ending: Option<&str>,
    syntax_name: &str,
) -> Result<String, String> {
    match line_ending.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("preserve") => Ok(output),
        Some("lf") | Some("\\n") => Ok(normalize_line_endings_to_lf(&output)),
        Some("crlf") | Some("\\r\\n") => {
            Ok(normalize_line_endings_to_lf(&output).replace('\n', "\r\n"))
        }
        Some(other) => Err(format!(
            "unsupported {syntax_name} source formatter line ending `{other}`"
        )),
    }
}

pub fn transform_template_encode_cem_name(value: &str) -> Result<String, String> {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return Err("CEM name cannot be empty".to_owned());
    };
    if !transform_template_cem_name_start(first) {
        return Err(format!("CEM name cannot start with `{first}`"));
    }
    for ch in chars {
        if !transform_template_cem_qname_continue(ch) {
            return Err(format!("CEM name cannot contain `{ch}`"));
        }
    }
    Ok(value.to_owned())
}

pub fn transform_template_encode_cem_attribute_value(
    value: &str,
    context: &str,
) -> Result<String, String> {
    if value.chars().any(char::is_control) {
        return Err(format!("{context} cannot contain control characters"));
    }
    if transform_template_cem_attribute_bare_value_is_safe(value) {
        return Ok(value.to_owned());
    }
    transform_template_encode_cem_string_literal(value)
}

pub fn transform_template_encode_cem_string_literal(value: &str) -> Result<String, String> {
    if value.chars().any(char::is_control) {
        return Err("CEM string literal cannot contain control characters".to_owned());
    }
    if !value.contains('"') {
        return Ok(format!("\"{value}\""));
    }
    if !value.contains('\'') {
        return Ok(format!("'{value}'"));
    }
    Err(
        "CEM string literal cannot contain both single and double quotes with the current tokenizer"
            .to_owned(),
    )
}

pub fn transform_template_encode_cem_content_text(value: &str) -> Result<String, String> {
    if transform_template_cem_content_text_is_safe(value) {
        return Ok(value.to_owned());
    }
    if value.contains("```") {
        return Err(
            "CEM text containing rich-content delimiters cannot be safely fenced".to_owned(),
        );
    }
    Ok(format!("```{value}```"))
}

pub fn transform_template_encode_cemt_expression_string_literal(value: &str) -> String {
    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => output.push_str("\\\\"),
            '"' => output.push_str("\\\""),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            _ => output.push(ch),
        }
    }
    output.push('"');
    output
}

pub fn transform_template_encode_cem_ql_string(value: &str) -> String {
    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => output.push_str("\\\\"),
            '"' => output.push_str("\\\""),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            ch if ch.is_control() => output.push_str(&format!("\\u{{{:x}}}", ch as u32)),
            _ => output.push(ch),
        }
    }
    output.push('"');
    output
}

pub fn transform_template_encode_cem_ql_identifier(value: &str) -> Result<String, String> {
    if value.is_empty() {
        return Err("CEM-QL identifier cannot be empty".to_owned());
    }

    if let Some((prefix, local)) = value.split_once(':') {
        if local.contains(':') {
            return Err("CEM-QL prefixed identifier cannot contain more than one `:`".to_owned());
        }
        transform_template_validate_cem_ql_identifier_part(prefix, "CEM-QL identifier prefix")?;
        transform_template_validate_cem_ql_identifier_part(local, "CEM-QL identifier local name")?;
        return Ok(value.to_owned());
    }

    transform_template_validate_cem_ql_identifier_part(value, "CEM-QL identifier")?;
    if transform_template_cem_ql_keyword(value) {
        return Err(format!(
            "CEM-QL identifier `{value}` is reserved by the lexer"
        ));
    }
    Ok(value.to_owned())
}

pub fn transform_template_encode_rnc_name(value: &str) -> Result<String, String> {
    transform_template_encode_cem_name(value).map_err(|error| error.replacen("CEM", "RNC", 1))
}

pub fn transform_template_encode_rnc_literal(value: &str) -> Result<String, String> {
    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => output.push_str("\\\\"),
            '"' => output.push_str("\\\""),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            ch if ch.is_control() => {
                return Err("RNC literal cannot contain unsupported control characters".to_owned())
            }
            _ => output.push(ch),
        }
    }
    output.push('"');
    Ok(output)
}

fn transform_template_validate_cem_ql_identifier_part(
    value: &str,
    context: &str,
) -> Result<(), String> {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return Err(format!("{context} cannot be empty"));
    };
    if !transform_template_cem_ql_identifier_start(first) {
        return Err(format!("{context} cannot start with `{first}`"));
    }
    for ch in chars {
        if !transform_template_cem_ql_identifier_continue(ch) {
            return Err(format!("{context} cannot contain `{ch}`"));
        }
    }
    Ok(())
}

fn transform_template_cem_ql_identifier_start(ch: char) -> bool {
    ch.is_ascii_alphabetic() || ch == '_'
}

fn transform_template_cem_ql_identifier_continue(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-')
}

fn transform_template_cem_ql_keyword(value: &str) -> bool {
    matches!(
        value,
        "eq" | "ne"
            | "lt"
            | "le"
            | "gt"
            | "ge"
            | "div"
            | "mod"
            | "and"
            | "or"
            | "not"
            | "let"
            | "in"
            | "if"
            | "then"
            | "else"
            | "for"
            | "return"
            | "some"
            | "every"
            | "satisfies"
            | "import"
            | "as"
            | "declare"
            | "variable"
            | "function"
            | "module"
            | "instance"
            | "of"
            | "cast"
            | "treat"
            | "is"
            | "fn"
            | "null"
            | "true"
            | "false"
    )
}

fn transform_template_cem_attribute_bare_value_is_safe(value: &str) -> bool {
    !value.is_empty()
        && !value.starts_with('{')
        && value
            .chars()
            .all(|ch| ch.is_alphanumeric() || matches!(ch, '_' | '-' | '/' | '.' | ':'))
}

fn transform_template_cem_content_text_is_safe(value: &str) -> bool {
    !value.contains('{')
        && !value.contains('}')
        && !value.contains("```")
        && !value.contains("<?")
        && !value.contains("/*")
}

fn transform_template_cem_name_start(ch: char) -> bool {
    ch.is_alphabetic() || ch == '_'
}

fn transform_template_cem_name_continue(ch: char) -> bool {
    ch.is_alphanumeric() || matches!(ch, '_' | '-')
}

fn transform_template_cem_qname_continue(ch: char) -> bool {
    transform_template_cem_name_continue(ch) || ch == ':'
}

pub fn transform_template_encode_html_text(value: &str) -> String {
    let mut output = String::new();
    for ch in value.chars() {
        match ch {
            '&' => output.push_str("&amp;"),
            '<' => output.push_str("&lt;"),
            '>' => output.push_str("&gt;"),
            _ => output.push(ch),
        }
    }
    output
}

pub fn transform_template_encode_html_attribute(value: &str) -> String {
    let mut output = String::new();
    for ch in value.chars() {
        match ch {
            '&' => output.push_str("&amp;"),
            '"' => output.push_str("&quot;"),
            '<' => output.push_str("&lt;"),
            _ => output.push(ch),
        }
    }
    output
}

pub fn transform_template_encode_markdown_text(value: &str) -> String {
    let mut output = String::new();
    for ch in value.chars() {
        match ch {
            '\\' | '`' | '*' | '_' | '{' | '}' | '[' | ']' | '(' | ')' | '#' | '+' | '-' | '.'
            | '!' | '|' | '>' => {
                output.push('\\');
                output.push(ch);
            }
            _ => output.push(ch),
        }
    }
    output
}

pub fn transform_template_format_markdown_text(
    output: String,
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<String, String> {
    let wrap_column = transform_template_markdown_wrap_column(options, formatter_profile)?;
    let output = if let Some(wrap_column) = wrap_column {
        transform_template_wrap_markdown_text(&output, wrap_column)
    } else {
        output
    };
    transform_template_apply_markdown_line_ending(
        output,
        transform_template_encode_options_line_ending_option(options),
    )
}

fn transform_template_markdown_wrap_column(
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<Option<usize>, String> {
    let mut default_wrap = None;
    for selector in [
        options.formatter.as_deref(),
        options.formatter_profile.as_deref(),
        formatter_profile,
    ]
    .into_iter()
    .flatten()
    {
        match selector.trim() {
            "" | "preserve" | "markdown.preserve" | "canonical" | "markdown.canonical" => {}
            "wrap" | "markdown.wrap" => default_wrap = Some(DEFAULT_FORMATTER_WRAP_COLUMN),
            other => return Err(format!("unsupported Markdown formatter `{other}`")),
        }
    }

    let Some(selector) = transform_template_encode_options_wrap_column_option(options) else {
        return Ok(default_wrap);
    };

    match selector {
        "none" | "preserve" => Ok(None),
        _ => {
            let column = selector
                .parse::<usize>()
                .map_err(|_| format!("unsupported Markdown formatter wrap column `{selector}`"))?;
            if column < 8 {
                return Err(
                    "Markdown formatter wrap column must be at least 8 characters".to_owned(),
                );
            }
            Ok(Some(column))
        }
    }
}

fn transform_template_wrap_markdown_text(value: &str, column: usize) -> String {
    normalize_line_endings_to_lf(value)
        .split('\n')
        .map(|line| transform_template_wrap_markdown_line(line, column))
        .collect::<Vec<_>>()
        .join("\n")
}

fn transform_template_wrap_markdown_line(line: &str, column: usize) -> String {
    if line.trim().is_empty() {
        return String::new();
    }

    let mut lines = Vec::new();
    let mut current = String::new();
    for word in line.split_whitespace() {
        let current_len = current.chars().count();
        let word_len = word.chars().count();
        if current.is_empty() {
            current.push_str(word);
        } else if current_len + 1 + word_len <= column {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(current);
            current = word.to_owned();
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    lines.join("\n")
}

fn transform_template_apply_markdown_line_ending(
    output: String,
    line_ending: Option<&str>,
) -> Result<String, String> {
    match line_ending.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("preserve") => Ok(output),
        Some("lf") | Some("\\n") => Ok(normalize_line_endings_to_lf(&output)),
        Some("crlf") | Some("\\r\\n") => {
            Ok(normalize_line_endings_to_lf(&output).replace('\n', "\r\n"))
        }
        Some(other) => Err(format!(
            "unsupported Markdown formatter line ending `{other}`"
        )),
    }
}

pub fn transform_template_encode_markdown_inline_code(value: &str) -> String {
    let mut max_backtick_run = 0usize;
    let mut current_run = 0usize;
    for ch in value.chars() {
        if ch == '`' {
            current_run += 1;
            max_backtick_run = max_backtick_run.max(current_run);
        } else {
            current_run = 0;
        }
    }
    let fence_len = max_backtick_run.saturating_add(1);
    let fence = "`".repeat(fence_len.max(1));
    let needs_padding = value
        .chars()
        .next()
        .zip(value.chars().last())
        .is_some_and(|(first, last)| first == '`' || last == '`' || first == ' ' || last == ' ');
    if needs_padding {
        format!("{fence} {value} {fence}")
    } else {
        format!("{fence}{value}{fence}")
    }
}

pub fn transform_template_encode_csv_field(value: &str) -> String {
    let requires_quotes = value
        .chars()
        .any(|ch| matches!(ch, ',' | '"' | '\r' | '\n'))
        || value.starts_with(' ')
        || value.ends_with(' ');
    if !requires_quotes {
        return value.to_owned();
    }

    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        if ch == '"' {
            output.push('"');
        }
        output.push(ch);
    }
    output.push('"');
    output
}

pub fn transform_template_encode_csv_record(fields: &[Value]) -> Result<String, String> {
    fields
        .iter()
        .map(transform_template_csv_value_to_field)
        .collect::<Result<Vec<_>, _>>()
        .map(|fields| fields.join(","))
}

fn transform_template_csv_value_to_field(value: &Value) -> Result<String, String> {
    let text = match value {
        Value::Null => String::new(),
        Value::Bool(value) => value.to_string(),
        Value::Number(value) => value.to_string(),
        Value::String(value) => value.clone(),
        Value::Array(_) | Value::Object(_) => transform_template_encode_json_value(value)?,
    };
    Ok(transform_template_encode_csv_field(&text))
}

pub fn transform_template_encode_css_string(value: &str) -> String {
    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => output.push_str("\\\\"),
            '"' => output.push_str("\\\""),
            '\n' => output.push_str("\\A "),
            '\r' => output.push_str("\\D "),
            '\t' => output.push_str("\\9 "),
            ch if ch.is_control() => push_css_hex_escape(&mut output, ch),
            _ => output.push(ch),
        }
    }
    output.push('"');
    output
}

pub fn transform_template_encode_css_identifier(value: &str) -> String {
    if is_css_identifier(value) {
        return value.to_owned();
    }
    if value.is_empty() {
        return "\\0 ".to_owned();
    }

    let mut output = String::new();
    for (index, ch) in value.chars().enumerate() {
        let valid = if index == 0 {
            ch.is_ascii_alphabetic() || ch == '_' || ch == '-'
        } else {
            ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-')
        };
        if valid {
            output.push(ch);
        } else {
            push_css_hex_escape(&mut output, ch);
        }
    }
    output
}

fn push_css_hex_escape(output: &mut String, ch: char) {
    output.push('\\');
    output.push_str(&format!("{:X} ", ch as u32));
}

pub fn transform_template_encode_yaml_scalar(value: &str) -> String {
    let mut output = String::with_capacity(value.len() + 2);
    output.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => output.push_str("\\\\"),
            '"' => output.push_str("\\\""),
            '\0' => output.push_str("\\0"),
            '\x08' => output.push_str("\\b"),
            '\t' => output.push_str("\\t"),
            '\n' => output.push_str("\\n"),
            '\x0c' => output.push_str("\\f"),
            '\r' => output.push_str("\\r"),
            ch if ch.is_control() => push_yaml_hex_escape(&mut output, ch),
            _ => output.push(ch),
        }
    }
    output.push('"');
    output
}

pub fn transform_template_encode_yaml_value(value: &Value) -> Result<String, String> {
    match value {
        Value::String(value) => Ok(transform_template_encode_yaml_scalar(value)),
        Value::Null => Ok("null".to_owned()),
        Value::Bool(value) => Ok(value.to_string()),
        Value::Number(value) => Ok(value.to_string()),
        Value::Array(_) | Value::Object(_) => transform_template_encode_json_value(value),
    }
}

pub fn transform_template_format_yaml_scalar(
    value: &str,
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<String, String> {
    transform_template_yaml_formatter_mode(options, formatter_profile)?;
    let output = match transform_template_yaml_scalar_style(options)? {
        TransformTemplateYamlScalarStyle::DoubleQuoted => {
            transform_template_encode_yaml_scalar(value)
        }
        TransformTemplateYamlScalarStyle::SingleQuoted => {
            transform_template_encode_yaml_single_quoted_scalar(value)?
        }
        TransformTemplateYamlScalarStyle::Plain => {
            transform_template_encode_yaml_plain_scalar(value)?
        }
    };
    transform_template_apply_yaml_line_ending(
        output,
        transform_template_encode_options_line_ending_option(options),
    )
}

pub fn transform_template_format_yaml_value(
    value: &Value,
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<String, String> {
    let mode = transform_template_yaml_formatter_mode(options, formatter_profile)?;
    transform_template_yaml_scalar_style(options)?;
    let ordered_value;
    let value = if mode.ordering == TransformTemplateObjectOrdering::Lexical {
        ordered_value = transform_template_order_json_value(value);
        &ordered_value
    } else {
        value
    };

    let output = match value {
        Value::String(value) => {
            return transform_template_format_yaml_scalar(value, options, formatter_profile);
        }
        Value::Null => "null".to_owned(),
        Value::Bool(value) => value.to_string(),
        Value::Number(value) => value.to_string(),
        Value::Array(_) | Value::Object(_) if mode.pretty => transform_template_pretty_json_value(
            value,
            &transform_template_cem_tree_formatter_indent(options),
        )?,
        Value::Array(_) | Value::Object(_) => transform_template_encode_json_value(value)?,
    };
    transform_template_apply_yaml_line_ending(
        output,
        transform_template_encode_options_line_ending_option(options),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TransformTemplateYamlScalarStyle {
    DoubleQuoted,
    SingleQuoted,
    Plain,
}

fn transform_template_yaml_formatter_mode(
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<TransformTemplateFlowFormatterMode, String> {
    let mut pretty = options.pretty;
    let mut ordering = if options.canonical && !options.preserve {
        TransformTemplateObjectOrdering::Lexical
    } else {
        TransformTemplateObjectOrdering::Preserve
    };
    for selector in [
        options.formatter.as_deref(),
        options.formatter_profile.as_deref(),
        formatter_profile,
    ]
    .into_iter()
    .flatten()
    {
        match selector.trim() {
            "" | "preserve" | "yaml.preserve" => {}
            "pretty" | "yaml.pretty" => pretty = true,
            "canonical" | "yaml.canonical" => {
                pretty = false;
                ordering = TransformTemplateObjectOrdering::Lexical;
            }
            "flow" | "yaml.flow" => pretty = false,
            other => return Err(format!("unsupported YAML formatter `{other}`")),
        }
    }
    ordering = transform_template_formatter_ordering(options, ordering, "YAML")?;

    if pretty {
        let indent = transform_template_cem_tree_formatter_indent(options);
        if !indent.chars().all(|ch| ch == ' ' || ch == '\t') {
            return Err("YAML formatter indent may contain only spaces or tabs".to_owned());
        }
    }

    Ok(TransformTemplateFlowFormatterMode { pretty, ordering })
}

fn transform_template_yaml_scalar_style(
    options: &TransformTemplateEncodeOptions,
) -> Result<TransformTemplateYamlScalarStyle, String> {
    match options
        .quote_policy
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None | Some("double") | Some("double-quoted") | Some("canonical") => {
            Ok(TransformTemplateYamlScalarStyle::DoubleQuoted)
        }
        Some("single") | Some("single-quoted") => {
            Ok(TransformTemplateYamlScalarStyle::SingleQuoted)
        }
        Some("plain") => Ok(TransformTemplateYamlScalarStyle::Plain),
        Some(other) => Err(format!("unsupported YAML quote policy `{other}`")),
    }
}

fn transform_template_encode_yaml_single_quoted_scalar(value: &str) -> Result<String, String> {
    if value.chars().any(char::is_control) {
        return Err(
            "single-quoted YAML scalar cannot contain control characters; use double-quoted style"
                .to_owned(),
        );
    }

    let mut output = String::with_capacity(value.len() + 2);
    output.push('\'');
    for ch in value.chars() {
        if ch == '\'' {
            output.push_str("''");
        } else {
            output.push(ch);
        }
    }
    output.push('\'');
    Ok(output)
}

fn transform_template_encode_yaml_plain_scalar(value: &str) -> Result<String, String> {
    if transform_template_yaml_plain_scalar_is_safe(value) {
        Ok(value.to_owned())
    } else {
        Err(
            "YAML string cannot be emitted as a plain YAML scalar without changing syntax or type"
                .to_owned(),
        )
    }
}

fn transform_template_yaml_plain_scalar_is_safe(value: &str) -> bool {
    if value.is_empty()
        || value.trim() != value
        || value.chars().any(char::is_control)
        || transform_template_yaml_plain_scalar_would_change_type(value)
    {
        return false;
    }

    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if matches!(
        first,
        '-' | '?'
            | ':'
            | ','
            | '['
            | ']'
            | '{'
            | '}'
            | '#'
            | '&'
            | '*'
            | '!'
            | '|'
            | '>'
            | '\''
            | '"'
            | '%'
            | '@'
            | '`'
    ) {
        return false;
    }

    !value.chars().any(|ch| {
        matches!(
            ch,
            ':' | '#'
                | '['
                | ']'
                | '{'
                | '}'
                | ','
                | '&'
                | '*'
                | '!'
                | '|'
                | '>'
                | '\''
                | '"'
                | '%'
                | '@'
                | '`'
        )
    })
}

fn transform_template_yaml_plain_scalar_would_change_type(value: &str) -> bool {
    let normalized = value.trim().to_ascii_lowercase();
    matches!(
        normalized.as_str(),
        "null"
            | "~"
            | "true"
            | "false"
            | "yes"
            | "no"
            | "on"
            | "off"
            | ".nan"
            | ".inf"
            | "+.inf"
            | "-.inf"
    ) || value.parse::<i64>().is_ok()
        || value.parse::<f64>().is_ok()
}

fn transform_template_apply_yaml_line_ending(
    output: String,
    line_ending: Option<&str>,
) -> Result<String, String> {
    match line_ending.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("preserve") => Ok(output),
        Some("lf") | Some("\\n") => Ok(normalize_line_endings_to_lf(&output)),
        Some("crlf") | Some("\\r\\n") => {
            Ok(normalize_line_endings_to_lf(&output).replace('\n', "\r\n"))
        }
        Some(other) => Err(format!("unsupported YAML formatter line ending `{other}`")),
    }
}

fn push_yaml_hex_escape(output: &mut String, ch: char) {
    let code = ch as u32;
    if code <= 0xff {
        output.push_str(&format!("\\x{code:02X}"));
    } else if code <= 0xffff {
        output.push_str(&format!("\\u{code:04X}"));
    } else {
        output.push_str(&format!("\\U{code:08X}"));
    }
}

pub fn transform_template_encode_json_value(value: &Value) -> Result<String, String> {
    serde_json::to_string(value).map_err(|error| error.to_string())
}

pub fn transform_template_format_json_value(
    value: &Value,
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<String, String> {
    let mode = transform_template_json_formatter_mode(options, formatter_profile)?;
    let ordered_value;
    let value = if mode.ordering == TransformTemplateObjectOrdering::Lexical {
        ordered_value = transform_template_order_json_value(value);
        &ordered_value
    } else {
        value
    };
    let output = if mode.pretty {
        transform_template_pretty_json_value(
            value,
            &transform_template_cem_tree_formatter_indent(options),
        )?
    } else {
        transform_template_encode_json_value(value)?
    };
    transform_template_apply_json_line_ending(
        output,
        transform_template_encode_options_line_ending_option(options),
    )
}

fn transform_template_json_formatter_mode(
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<TransformTemplateFlowFormatterMode, String> {
    let mut pretty = options.pretty;
    let mut ordering = if options.canonical && !options.preserve {
        TransformTemplateObjectOrdering::Lexical
    } else {
        TransformTemplateObjectOrdering::Preserve
    };
    for selector in [
        options.formatter.as_deref(),
        options.formatter_profile.as_deref(),
        formatter_profile,
    ]
    .into_iter()
    .flatten()
    {
        match selector.trim() {
            "" | "preserve" | "json.preserve" => {}
            "pretty" | "json.pretty" => pretty = true,
            "canonical" | "json.canonical" => {
                pretty = false;
                ordering = TransformTemplateObjectOrdering::Lexical;
            }
            other => return Err(format!("unsupported JSON formatter `{other}`")),
        }
    }
    ordering = transform_template_formatter_ordering(options, ordering, "JSON")?;
    Ok(TransformTemplateFlowFormatterMode { pretty, ordering })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TransformTemplateFlowFormatterMode {
    pretty: bool,
    ordering: TransformTemplateObjectOrdering,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TransformTemplateObjectOrdering {
    Preserve,
    Lexical,
}

fn transform_template_formatter_ordering(
    options: &TransformTemplateEncodeOptions,
    default_ordering: TransformTemplateObjectOrdering,
    syntax_name: &str,
) -> Result<TransformTemplateObjectOrdering, String> {
    match options
        .ordering
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None => Ok(default_ordering),
        Some("preserve") | Some("source") | Some("input") => {
            Ok(TransformTemplateObjectOrdering::Preserve)
        }
        Some("lexical") | Some("sorted") | Some("canonical") => {
            Ok(TransformTemplateObjectOrdering::Lexical)
        }
        Some(other) => Err(format!(
            "unsupported {syntax_name} formatter ordering `{other}`"
        )),
    }
}

fn transform_template_order_json_value(value: &Value) -> Value {
    match value {
        Value::Array(values) => Value::Array(
            values
                .iter()
                .map(transform_template_order_json_value)
                .collect(),
        ),
        Value::Object(values) => {
            let ordered = values
                .iter()
                .map(|(key, value)| (key.clone(), transform_template_order_json_value(value)))
                .collect::<BTreeMap<_, _>>();
            let mut output = serde_json::Map::new();
            for (key, value) in ordered {
                output.insert(key, value);
            }
            Value::Object(output)
        }
        _ => value.clone(),
    }
}

fn transform_template_pretty_json_value(value: &Value, indent: &str) -> Result<String, String> {
    if !indent.chars().all(|ch| ch == ' ' || ch == '\t') {
        return Err("JSON formatter indent may contain only spaces or tabs".to_owned());
    }

    let mut output = Vec::new();
    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent.as_bytes());
    let mut serializer = serde_json::Serializer::with_formatter(&mut output, formatter);
    value
        .serialize(&mut serializer)
        .map_err(|error| error.to_string())?;
    String::from_utf8(output).map_err(|error| error.to_string())
}

fn transform_template_apply_json_line_ending(
    output: String,
    line_ending: Option<&str>,
) -> Result<String, String> {
    match line_ending.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("lf") | Some("\\n") | Some("preserve") => Ok(output),
        Some("crlf") | Some("\\r\\n") => Ok(output.replace('\n', "\r\n")),
        Some(other) => Err(format!("unsupported JSON formatter line ending `{other}`")),
    }
}

pub fn transform_template_encode_xml_text(value: &str) -> String {
    let mut output = String::new();
    for ch in value.chars() {
        match ch {
            '&' => output.push_str("&amp;"),
            '<' => output.push_str("&lt;"),
            '>' => output.push_str("&gt;"),
            _ => output.push(ch),
        }
    }
    output
}

pub fn transform_template_encode_xml_attribute(value: &str) -> String {
    let mut output = String::new();
    for ch in value.chars() {
        match ch {
            '&' => output.push_str("&amp;"),
            '"' => output.push_str("&quot;"),
            '\'' => output.push_str("&apos;"),
            '<' => output.push_str("&lt;"),
            '>' => output.push_str("&gt;"),
            _ => output.push(ch),
        }
    }
    output
}

pub fn transform_template_format_xml_text(
    output: String,
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<String, String> {
    transform_template_validate_xml_formatter_options(options, formatter_profile)?;
    transform_template_apply_xml_line_ending(
        output,
        transform_template_encode_options_line_ending_option(options),
    )
}

fn transform_template_validate_xml_formatter_options(
    options: &TransformTemplateEncodeOptions,
    formatter_profile: Option<&str>,
) -> Result<(), String> {
    for selector in [
        options.formatter.as_deref(),
        options.formatter_profile.as_deref(),
        formatter_profile,
    ]
    .into_iter()
    .flatten()
    {
        match selector.trim() {
            "" | "canonical" | "xml.canonical" | "preserve" | "xml.preserve" | "pretty"
            | "xml.pretty" => {}
            other => return Err(format!("unsupported XML formatter `{other}`")),
        }
    }

    if options.pretty {
        let indent = transform_template_cem_tree_formatter_indent(options);
        if !indent.chars().all(|ch| ch == ' ' || ch == '\t') {
            return Err("XML formatter indent may contain only spaces or tabs".to_owned());
        }
    }

    match options
        .namespace_policy
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None | Some("preserve") | Some("repair") | Some("canonical") => {}
        Some(other) => return Err(format!("unsupported XML namespace policy `{other}`")),
    }

    match options
        .namespace_placement
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        None
        | Some("preserve")
        | Some("root")
        | Some("document-root")
        | Some("local")
        | Some("nearest")
        | Some("canonical")
        | Some("none") => Ok(()),
        Some(other) => Err(format!(
            "unsupported XML namespace declaration placement `{other}`"
        )),
    }
}

fn transform_template_apply_xml_line_ending(
    output: String,
    line_ending: Option<&str>,
) -> Result<String, String> {
    match line_ending.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("preserve") => Ok(output),
        Some("lf") | Some("\\n") => Ok(normalize_line_endings_to_lf(&output)),
        Some("crlf") | Some("\\r\\n") => {
            Ok(normalize_line_endings_to_lf(&output).replace('\n', "\r\n"))
        }
        Some(other) => Err(format!("unsupported XML formatter line ending `{other}`")),
    }
}

fn normalize_line_endings_to_lf(value: &str) -> String {
    value.replace("\r\n", "\n").replace('\r', "\n")
}

#[derive(Debug, Clone, Copy)]
pub struct TransformTemplateEncodeEvaluationContext<'a> {
    pub registry: &'a TransformTemplateOutputFunctionRegistry,
    pub value_bindings: &'a BTreeMap<String, Value>,
    pub host_capabilities: &'a BTreeSet<String>,
    pub output_color_type: Option<&'a str>,
    pub uri: Option<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEvaluatedEncodeExpression {
    pub expression: TransformTemplateEncodeExpression,
    pub subject: Value,
    pub binding: TransformTemplateEncodeBinding,
    pub artifact: TransformTemplateEncodedArtifact,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodeEvaluationResponse {
    #[serde(default)]
    pub encoded: Vec<TransformTemplateEvaluatedEncodeExpression>,
    #[serde(default)]
    pub diagnostics: Vec<Diagnostic>,
}

impl TransformTemplateEncodeEvaluationResponse {
    pub fn validate_insertions(
        &self,
        context: &TransformTemplateEncodedArtifactInsertionContext,
        uri: Option<&str>,
    ) -> Vec<Diagnostic> {
        validate_transform_template_encoded_insertions(&self.encoded, context, uri)
    }

    pub fn compose_text_artifacts(
        &self,
        context: &TransformTemplateEncodedArtifactInsertionContext,
        uri: Option<&str>,
    ) -> TransformTemplateEncodedArtifactCompositionResponse {
        compose_transform_template_encoded_text_artifacts(&self.encoded, context, uri)
    }
}

pub fn validate_transform_template_cemt_native_encode_parity(
    cemt: &TransformTemplateEncodeEvaluationResponse,
    native: &TransformTemplateEncodeEvaluationResponse,
    uri: Option<&str>,
) -> Vec<Diagnostic> {
    let mut diagnostics = Vec::new();
    let cemt_diagnostic_codes = transform_template_diagnostic_codes(&cemt.diagnostics);
    let native_diagnostic_codes = transform_template_diagnostic_codes(&native.diagnostics);
    if cemt_diagnostic_codes != native_diagnostic_codes {
        diagnostics.push(transform_template_cemt_native_parity_diagnostic(
            uri,
            "diagnostics.codes",
            &cemt_diagnostic_codes,
            &native_diagnostic_codes,
            None,
        ));
    }

    if cemt.encoded.len() != native.encoded.len() {
        diagnostics.push(transform_template_cemt_native_parity_diagnostic(
            uri,
            "encoded.length",
            &cemt.encoded.len(),
            &native.encoded.len(),
            None,
        ));
    }

    for index in 0..cemt.encoded.len().min(native.encoded.len()) {
        let cemt_evaluated = &cemt.encoded[index];
        let native_evaluated = &native.encoded[index];
        let node = transform_template_cemt_native_parity_node(
            Some(cemt_evaluated),
            Some(native_evaluated),
        );
        validate_transform_template_cemt_native_artifact_parity_field(
            &mut diagnostics,
            uri,
            index,
            "identity",
            &cemt_evaluated.artifact.identity,
            &native_evaluated.artifact.identity,
            node.clone(),
        );
        validate_transform_template_cemt_native_artifact_parity_field(
            &mut diagnostics,
            uri,
            index,
            "value",
            &cemt_evaluated.artifact.value,
            &native_evaluated.artifact.value,
            node.clone(),
        );
        validate_transform_template_cemt_native_artifact_parity_field(
            &mut diagnostics,
            uri,
            index,
            "sourceMap",
            &cemt_evaluated.artifact.source_map,
            &native_evaluated.artifact.source_map,
            node.clone(),
        );
        validate_transform_template_cemt_native_artifact_parity_field(
            &mut diagnostics,
            uri,
            index,
            "outputSpans",
            &cemt_evaluated.artifact.output_spans,
            &native_evaluated.artifact.output_spans,
            node.clone(),
        );
        validate_transform_template_cemt_native_artifact_parity_field(
            &mut diagnostics,
            uri,
            index,
            "encoded",
            &cemt_evaluated.artifact.encoded,
            &native_evaluated.artifact.encoded,
            node,
        );
    }

    diagnostics
}

fn validate_transform_template_cemt_native_artifact_parity_field<T>(
    diagnostics: &mut Vec<Diagnostic>,
    uri: Option<&str>,
    index: usize,
    field: &str,
    cemt: &T,
    native: &T,
    node: Option<String>,
) where
    T: fmt::Debug + PartialEq,
{
    if cemt != native {
        diagnostics.push(transform_template_cemt_native_parity_diagnostic(
            uri,
            &format!("encoded[{index}].{field}"),
            cemt,
            native,
            node,
        ));
    }
}

fn transform_template_cemt_native_parity_diagnostic<T>(
    uri: Option<&str>,
    field: &str,
    cemt: &T,
    native: &T,
    node: Option<String>,
) -> Diagnostic
where
    T: fmt::Debug,
{
    Diagnostic {
        uri: uri.map(str::to_owned),
        code: TRANSFORM_TEMPLATE_CEMT_NATIVE_PARITY_MISMATCH_CODE.to_owned(),
        severity: Severity::Error,
        message: format!(
            "CEMT/native parity mismatch at `{field}`: CEMT produced {}; native produced {}",
            transform_template_parity_summary(cemt),
            transform_template_parity_summary(native)
        ),
        node,
        details: None,
        ..Diagnostic::default()
    }
}

fn transform_template_cemt_native_parity_node(
    cemt: Option<&TransformTemplateEvaluatedEncodeExpression>,
    native: Option<&TransformTemplateEvaluatedEncodeExpression>,
) -> Option<String> {
    cemt.and_then(|evaluated| evaluated.expression.owner.clone())
        .or_else(|| native.and_then(|evaluated| evaluated.expression.owner.clone()))
        .or_else(|| cemt.map(|evaluated| evaluated.expression.expression.clone()))
        .or_else(|| native.map(|evaluated| evaluated.expression.expression.clone()))
}

fn transform_template_diagnostic_codes(diagnostics: &[Diagnostic]) -> Vec<String> {
    diagnostics
        .iter()
        .map(|diagnostic| diagnostic.code.clone())
        .collect()
}

fn transform_template_parity_summary<T>(value: &T) -> String
where
    T: fmt::Debug,
{
    const LIMIT: usize = 240;
    let summary = format!("{value:?}");
    if summary.chars().count() <= LIMIT {
        return summary;
    }
    let mut truncated = summary.chars().take(LIMIT).collect::<String>();
    truncated.push_str("...");
    truncated
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodedArtifactCompositionResponse {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub artifact: Option<TransformTemplateEncodedArtifact>,
    #[serde(default)]
    pub diagnostics: Vec<Diagnostic>,
}

pub fn validate_transform_template_encoded_insertions(
    encoded: &[TransformTemplateEvaluatedEncodeExpression],
    context: &TransformTemplateEncodedArtifactInsertionContext,
    uri: Option<&str>,
) -> Vec<Diagnostic> {
    let mut diagnostics = Vec::new();
    for evaluated in encoded {
        if let Err(error) = evaluated.artifact.validate_insertion(context) {
            diagnostics.extend(diagnostics_for_evaluated_encode_error(
                error, evaluated, uri,
            ));
        }
    }
    diagnostics
}

pub fn compose_transform_template_encoded_text_artifacts(
    encoded: &[TransformTemplateEvaluatedEncodeExpression],
    context: &TransformTemplateEncodedArtifactInsertionContext,
    uri: Option<&str>,
) -> TransformTemplateEncodedArtifactCompositionResponse {
    let mut diagnostics = Vec::new();
    let mut output = String::new();
    let mut output_spans = Vec::new();
    let mut source_map = None;
    let mut identity = None;
    let mut composition_context = None;
    let mut byte_offset = 0u64;
    let mut text_context = context.clone();
    text_context.produces = Some(TransformTemplateOutputProducedKind::Text);
    let mut writer_boundary_context = text_context.clone();
    writer_boundary_context.produces = None;

    for evaluated in encoded {
        let artifact = match text_composition_artifact_for_evaluated_encode(
            evaluated,
            &writer_boundary_context,
            uri,
        ) {
            Ok(artifact) => artifact,
            Err(mut artifact_diagnostics) => {
                diagnostics.append(&mut artifact_diagnostics);
                continue;
            }
        };

        if let Err(error) = artifact.validate_insertion(&text_context) {
            diagnostics.extend(diagnostics_for_evaluated_encode_error(
                error, evaluated, uri,
            ));
            continue;
        }

        let Some(text) = artifact.value.as_str() else {
            diagnostics.push(diagnostic_for_evaluated_encode_value_type(evaluated, uri));
            continue;
        };

        if let Some(composition_context) = &composition_context {
            if let Err(error) = artifact.validate_insertion(composition_context) {
                diagnostics.extend(diagnostics_for_evaluated_encode_error(
                    error, evaluated, uri,
                ));
                continue;
            }
        } else {
            composition_context = Some(
                TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &artifact.identity,
                ),
            );
        }

        if identity.is_none() {
            identity = Some(artifact.identity.clone());
        }
        if source_map.is_none() {
            source_map = artifact.source_map.clone();
        }

        output_spans.extend(
            artifact
                .output_spans
                .iter()
                .map(|span| shift_output_span(span, byte_offset)),
        );
        output.push_str(text);
        byte_offset += text.len() as u64;
    }

    if !diagnostics.is_empty() {
        return TransformTemplateEncodedArtifactCompositionResponse {
            artifact: None,
            diagnostics,
        };
    }

    let Some(identity) = identity else {
        return TransformTemplateEncodedArtifactCompositionResponse {
            artifact: None,
            diagnostics,
        };
    };

    TransformTemplateEncodedArtifactCompositionResponse {
        artifact: Some(TransformTemplateEncodedArtifact {
            identity,
            value: Value::String(output),
            source_map,
            output_spans,
            encoded: true,
        }),
        diagnostics,
    }
}

fn text_composition_artifact_for_evaluated_encode(
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
    uri: Option<&str>,
) -> Result<TransformTemplateEncodedArtifact, Vec<Diagnostic>> {
    match evaluated.artifact.identity.produces {
        TransformTemplateOutputProducedKind::Text => Ok(
            transform_template_apply_artifact_source_map_policy(evaluated.artifact.clone()),
        ),
        TransformTemplateOutputProducedKind::Tokens => {
            if let Err(error) = evaluated
                .artifact
                .validate_insertion(writer_boundary_context)
            {
                return Err(diagnostics_for_evaluated_encode_error(
                    error, evaluated, uri,
                ));
            }
            transform_template_writer_token_artifact_to_text(
                &evaluated.artifact,
                writer_boundary_context,
            )
            .map_err(|message| {
                vec![diagnostic_for_evaluated_encode_writer_adapter_failed(
                    evaluated, message, uri,
                )]
            })
        }
        TransformTemplateOutputProducedKind::Chunks => {
            if let Err(error) = evaluated
                .artifact
                .validate_insertion(writer_boundary_context)
            {
                return Err(diagnostics_for_evaluated_encode_error(
                    error, evaluated, uri,
                ));
            }
            transform_template_writer_chunk_artifact_to_text(&evaluated.artifact).map_err(
                |message| {
                    vec![diagnostic_for_evaluated_encode_writer_adapter_failed(
                        evaluated, message, uri,
                    )]
                },
            )
        }
        TransformTemplateOutputProducedKind::CemTree => {
            transform_template_writer_cem_tree_artifact_to_text(
                &evaluated.artifact,
                writer_boundary_context,
            )
            .map_err(|message| {
                vec![diagnostic_for_evaluated_encode_writer_adapter_failed(
                    evaluated, message, uri,
                )]
            })
        }
        _ => {
            match evaluated
                .artifact
                .validate_insertion(writer_boundary_context)
            {
                Ok(()) => Err(vec![
                    diagnostic_for_evaluated_encode_writer_adapter_missing(
                        evaluated,
                        TransformTemplateOutputProducedKind::Text,
                        uri,
                    ),
                ]),
                Err(error) => Err(diagnostics_for_evaluated_encode_error(
                    error, evaluated, uri,
                )),
            }
        }
    }
}

fn transform_template_apply_artifact_source_map_policy(
    mut artifact: TransformTemplateEncodedArtifact,
) -> TransformTemplateEncodedArtifact {
    if artifact.identity.source_map_policy == TransformTemplateSourceMapPolicy::None {
        artifact.source_map = None;
        artifact.output_spans.clear();
    }
    artifact
}

fn transform_template_writer_token_artifact_to_text(
    artifact: &TransformTemplateEncodedArtifact,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> Result<TransformTemplateEncodedArtifact, String> {
    let token_stream: TransformTemplateWriterTokenStream =
        serde_json::from_value(artifact.value.clone())
            .map_err(|error| format!("token stream envelope is invalid: {error}"))?;
    let mut color_identity = artifact.identity.clone();
    if writer_boundary_context.color_profile.is_some() {
        color_identity.color_profile = writer_boundary_context.color_profile.clone();
    }
    if writer_boundary_context.color_capability.is_some() {
        color_identity.color_capability = writer_boundary_context.color_capability.clone();
    }
    let color_profile = transform_template_writer_token_color_profile(
        &artifact.value,
        &color_identity,
        writer_boundary_context.output_color_type.as_deref(),
    );
    let mut text = String::new();
    let mut token_output_spans = Vec::new();
    let mut has_token_output_spans = false;
    for (index, token) in token_stream.tokens.iter().enumerate() {
        let Some(token_text) = token.text.as_deref() else {
            return Err(format!(
                "`tokens[{index}]` has no text for the default token-to-text writer adapter"
            ));
        };
        let rendered_token_text = transform_template_writer_token_rendered_text(
            token_text,
            token,
            color_profile.as_ref(),
        );
        if let Some(output_span) = &token.output_span {
            has_token_output_spans = true;
            let mut generated_span = output_span.clone();
            generated_span.output_range =
                ByteRange::new(text.len() as u64, rendered_token_text.len() as u32);
            token_output_spans.push(generated_span);
        }
        text.push_str(&rendered_token_text);
    }

    let mut identity = artifact.identity.clone();
    identity.produces = TransformTemplateOutputProducedKind::Text;
    let (source_map, output_spans) = match artifact.identity.source_map_policy {
        TransformTemplateSourceMapPolicy::None => (None, Vec::new()),
        TransformTemplateSourceMapPolicy::Generated
        | TransformTemplateSourceMapPolicy::Preserve => {
            let output_spans = if has_token_output_spans {
                token_output_spans
            } else {
                artifact.output_spans.clone()
            };
            (artifact.source_map.clone(), output_spans)
        }
    };

    Ok(TransformTemplateEncodedArtifact {
        identity,
        value: Value::String(text),
        source_map,
        output_spans,
        encoded: true,
    })
}

#[derive(Debug, Clone)]
enum TransformTemplateWriterTokenColorProfile {
    Terminal(TransformTemplateColorOutputProfile),
    Html(TransformTemplateColorOutputProfile),
}

fn transform_template_writer_token_color_profile(
    value: &Value,
    identity: &TransformTemplateEncodedArtifactIdentity,
    output_color_type: Option<&str>,
) -> Option<TransformTemplateWriterTokenColorProfile> {
    if let Some(output_color_type) = trimmed_optional_str(output_color_type) {
        let selection = parse_transform_template_output_color_type(output_color_type).ok()?;
        if selection.target.category == "html-color" {
            let profile = TransformTemplateColorOutputProfile::html_from_selector(
                &selection.output_color_type,
            )
            .ok()?;
            return (!profile.no_color && profile.output == TransformTemplateColorOutputKind::Html)
                .then_some(TransformTemplateWriterTokenColorProfile::Html(profile));
        }
        if selection.target.category == "terminal-color" && selection.output_color_type != "none" {
            let profile = TransformTemplateColorOutputProfile::terminal_from_selector(
                &selection.output_color_type,
            )
            .ok()?;
            return (!profile.no_color
                && profile.output == TransformTemplateColorOutputKind::Terminal
                && profile.terminal_capability != TransformTemplateTerminalColorCapability::None)
                .then_some(TransformTemplateWriterTokenColorProfile::Terminal(profile));
        }
        return None;
    }

    match trimmed_value_string_field(value, "colorOutput") {
        Some("html") => {
            let selector = trimmed_optional_str(identity.color_profile.as_deref())
                .or_else(|| trimmed_value_string_field(value, "colorProfile"))
                .unwrap_or("html");
            let profile = TransformTemplateColorOutputProfile::html_from_selector(selector).ok()?;
            (!profile.no_color && profile.output == TransformTemplateColorOutputKind::Html)
                .then_some(TransformTemplateWriterTokenColorProfile::Html(profile))
        }
        Some("terminal") | None => {
            let selector = trimmed_optional_str(identity.color_capability.as_deref())
                .or_else(|| trimmed_value_string_field(value, "colorCapability"))
                .or_else(|| trimmed_optional_str(identity.color_profile.as_deref()))
                .or_else(|| trimmed_value_string_field(value, "colorProfile"))?;
            let profile =
                TransformTemplateColorOutputProfile::terminal_from_selector(selector).ok()?;
            (!profile.no_color
                && profile.output == TransformTemplateColorOutputKind::Terminal
                && profile.terminal_capability != TransformTemplateTerminalColorCapability::None)
                .then_some(TransformTemplateWriterTokenColorProfile::Terminal(profile))
        }
        _ => None,
    }
}

fn transform_template_writer_token_rendered_text(
    text: &str,
    token: &TransformTemplateWriterToken,
    color_profile: Option<&TransformTemplateWriterTokenColorProfile>,
) -> String {
    let Some(color_profile) = color_profile else {
        return text.to_owned();
    };
    let Some(role) = transform_template_writer_token_color_role(token) else {
        return match color_profile {
            TransformTemplateWriterTokenColorProfile::Terminal(_) => text.to_owned(),
            TransformTemplateWriterTokenColorProfile::Html(_) => {
                transform_template_encode_html_text(text)
            }
        };
    };
    match color_profile {
        TransformTemplateWriterTokenColorProfile::Terminal(profile) => {
            if !profile.supports_role(role) {
                return text.to_owned();
            }
            let Some(sgr) =
                transform_template_terminal_sgr_for_role(role, profile.terminal_capability)
            else {
                return text.to_owned();
            };
            format!("\u{1b}[{sgr}m{text}\u{1b}[0m")
        }
        TransformTemplateWriterTokenColorProfile::Html(profile) => {
            if !profile.supports_role(role) {
                return transform_template_encode_html_text(text);
            }
            transform_template_render_html_color_token(
                &TransformTemplateColorToken {
                    role: transform_template_canonical_color_role(role),
                    text: text.to_owned(),
                    href: None,
                },
                profile,
            )
        }
    }
}

fn transform_template_writer_token_color_role(
    token: &TransformTemplateWriterToken,
) -> Option<&str> {
    token
        .style
        .get("colorRole")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|role| !role.is_empty())
        .or_else(|| {
            token
                .role
                .as_deref()
                .map(str::trim)
                .filter(|role| !role.is_empty())
        })
}

fn transform_template_writer_chunk_artifact_to_text(
    artifact: &TransformTemplateEncodedArtifact,
) -> Result<TransformTemplateEncodedArtifact, String> {
    let chunk_stream: TransformTemplateWriterChunkStream =
        serde_json::from_value(artifact.value.clone())
            .map_err(|error| format!("chunk stream envelope is invalid: {error}"))?;
    let mut text = String::new();
    for (index, chunk) in chunk_stream.chunks.iter().enumerate() {
        if !chunk.bytes.is_empty() {
            return Err(format!(
                "`chunks[{index}]` contains bytes and cannot use the default chunk-to-text writer adapter"
            ));
        }
        let Some(chunk_text) = chunk.text.as_deref() else {
            return Err(format!(
                "`chunks[{index}]` has no text for the default chunk-to-text writer adapter"
            ));
        };
        text.push_str(chunk_text);
    }

    let mut identity = artifact.identity.clone();
    identity.produces = TransformTemplateOutputProducedKind::Text;
    let (source_map, output_spans) = match artifact.identity.source_map_policy {
        TransformTemplateSourceMapPolicy::None => (None, Vec::new()),
        TransformTemplateSourceMapPolicy::Generated
        | TransformTemplateSourceMapPolicy::Preserve => {
            (artifact.source_map.clone(), artifact.output_spans.clone())
        }
    };

    Ok(TransformTemplateEncodedArtifact {
        identity,
        value: Value::String(text),
        source_map,
        output_spans,
        encoded: true,
    })
}

fn transform_template_writer_cem_tree_artifact_to_text(
    artifact: &TransformTemplateEncodedArtifact,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> Result<TransformTemplateEncodedArtifact, String> {
    validate_cem_tree_value(&artifact.value)
        .map_err(|message| format!("CEM tree envelope is invalid: {message}"))?;
    validate_cem_tree_writer_boundary(artifact, writer_boundary_context)?;
    let rendered = transform_template_cem_tree_value_to_rendered_text(
        &artifact.value,
        writer_boundary_context,
    )?;

    let mut identity =
        transform_template_writer_text_identity_from_context(artifact, writer_boundary_context);
    identity.produces = TransformTemplateOutputProducedKind::Text;
    let (source_map, output_spans) = match artifact.identity.source_map_policy {
        TransformTemplateSourceMapPolicy::None => (None, Vec::new()),
        TransformTemplateSourceMapPolicy::Generated
        | TransformTemplateSourceMapPolicy::Preserve => {
            let output_spans = if rendered.output_spans.is_empty() {
                artifact.output_spans.clone()
            } else {
                rendered.output_spans.clone()
            };
            let source_map = artifact
                .source_map
                .clone()
                .or_else(|| output_spans.first().map(|span| span.origin.clone()));
            (source_map, output_spans)
        }
    };

    Ok(TransformTemplateEncodedArtifact {
        identity,
        value: Value::String(rendered.text),
        source_map,
        output_spans,
        encoded: true,
    })
}

fn validate_cem_tree_writer_boundary(
    artifact: &TransformTemplateEncodedArtifact,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> Result<(), String> {
    let identity_formatter_profile =
        trimmed_optional_str(artifact.identity.formatter_profile.as_deref());
    let value_formatter_profile = trimmed_value_string_field(&artifact.value, "formatterProfile");
    let formatter_profile = identity_formatter_profile
        .or(value_formatter_profile)
        .ok_or_else(|| {
            "CEM tree writer requires a formatted CEM tree with `formatterProfile`; run `cem.format-tree` before the writer"
                .to_owned()
        })?;
    if let (Some(identity), Some(value)) = (identity_formatter_profile, value_formatter_profile) {
        if identity != value {
            return Err(format!(
                "CEM tree formatter profile metadata mismatch: identity `{identity}`, tree `{value}`"
            ));
        }
    }
    if let Some(expected) =
        trimmed_optional_str(writer_boundary_context.formatter_profile.as_deref())
    {
        if expected.starts_with("cem.") && formatter_profile != expected {
            return Err(format!(
                "CEM tree writer expected formatterProfile `{expected}`, got `{formatter_profile}`"
            ));
        }
    }
    validate_cem_tree_formatter_metadata(&artifact.value, formatter_profile)?;

    let identity_color_profile = trimmed_optional_str(artifact.identity.color_profile.as_deref());
    let value_color_profile = trimmed_value_string_field(&artifact.value, "colorProfile");
    let colored = artifact.value.get("colored").and_then(Value::as_bool) == Some(true);
    let writer_color_profile =
        trimmed_optional_str(writer_boundary_context.color_profile.as_deref());
    let color_requested = colored
        || cemt_writer_color_profile_requests_color(identity_color_profile)
        || cemt_writer_color_profile_requests_color(value_color_profile)
        || cemt_writer_color_profile_requests_color(writer_color_profile);
    if !color_requested {
        return Ok(());
    }
    if !colored {
        return Err(
            "CEM tree writer requires a colored CEM tree with `colored: true` when a color profile is requested; run the package colorizer before the writer"
                .to_owned(),
        );
    }
    let color_profile = identity_color_profile
        .or(value_color_profile)
        .ok_or_else(|| {
            "CEM tree writer requires a colored CEM tree with `colorProfile` when a color profile is requested; run the package colorizer before the writer"
                .to_owned()
        })?;
    if let (Some(identity), Some(value)) = (identity_color_profile, value_color_profile) {
        if identity != value {
            return Err(format!(
                "CEM tree color profile metadata mismatch: identity `{identity}`, tree `{value}`"
            ));
        }
    }
    if let Some(expected) = writer_color_profile {
        if color_profile != expected {
            return Err(format!(
                "CEM tree writer expected colorProfile `{expected}`, got `{color_profile}`"
            ));
        }
    }
    if let (Some(identity), Some(value)) = (
        trimmed_optional_str(artifact.identity.color_capability.as_deref()),
        trimmed_value_string_field(&artifact.value, "colorCapability"),
    ) {
        if identity != value {
            return Err(format!(
                "CEM tree color capability metadata mismatch: identity `{identity}`, tree `{value}`"
            ));
        }
    }
    validate_cem_tree_color_metadata(&artifact.value, color_profile)?;

    Ok(())
}

fn cemt_writer_color_profile_requests_color(profile: Option<&str>) -> bool {
    profile.is_some_and(|profile| profile != "none")
}

fn validate_cem_tree_formatter_metadata(
    value: &Value,
    formatter_profile: &str,
) -> Result<(), String> {
    let format_nodes = value
        .get("formatNodes")
        .and_then(Value::as_array)
        .filter(|nodes| !nodes.is_empty())
        .ok_or_else(|| {
            "CEM tree writer requires formatter-owned `formatNodes`; run `cem.format-tree` before the writer"
                .to_owned()
        })?;
    let has_marker = format_nodes.iter().any(|node| {
        node.get("kind").and_then(Value::as_str) == Some("format-marker")
            && node
                .get("name")
                .and_then(Value::as_str)
                .map(str::trim)
                .is_some_and(|name| !name.is_empty())
    });
    if !has_marker {
        return Err(
            "CEM tree writer requires a package formatter marker in `formatNodes`, for example `cem.format-tree`"
                .to_owned(),
        );
    }
    let has_decision = format_nodes.iter().any(|node| {
        node.get("kind").and_then(Value::as_str) == Some("format-decision")
            && node
                .get("formatterRole")
                .and_then(Value::as_str)
                .is_some_and(|role| role.starts_with("formatter."))
    });
    if !has_decision {
        return Err(
            "CEM tree writer requires formatter decision nodes in `formatNodes`; run `cem.format-tree` before the writer"
                .to_owned(),
        );
    }
    if let Some(conflicting_profile) = format_nodes.iter().find_map(|node| {
        let profile = node.get("formatterProfile").and_then(Value::as_str)?;
        (profile != formatter_profile).then_some(profile)
    }) {
        return Err(format!(
            "CEM tree formatter metadata profile mismatch: tree `{formatter_profile}`, formatNodes `{conflicting_profile}`"
        ));
    }
    Ok(())
}

fn validate_cem_tree_color_metadata(value: &Value, color_profile: &str) -> Result<(), String> {
    let color_nodes = value
        .get("colorNodes")
        .and_then(Value::as_array)
        .filter(|nodes| !nodes.is_empty())
        .ok_or_else(|| {
            "CEM tree writer requires colorizer-owned `colorNodes`; run `cem.color-tree` before the writer"
                .to_owned()
        })?;
    let has_marker = color_nodes.iter().any(|node| {
        node.get("kind").and_then(Value::as_str) == Some("color-marker")
            && node
                .get("name")
                .and_then(Value::as_str)
                .map(str::trim)
                .is_some_and(|name| !name.is_empty())
    });
    if !has_marker {
        return Err(
            "CEM tree writer requires a package colorizer marker in `colorNodes`, for example `cem.color-tree`"
                .to_owned(),
        );
    }
    let has_decision = color_nodes.iter().any(|node| {
        node.get("kind").and_then(Value::as_str) == Some("color-decision")
            && node
                .get("colorizerRole")
                .and_then(Value::as_str)
                .is_some_and(|role| role.starts_with("colorizer."))
    });
    if !has_decision {
        return Err(
            "CEM tree writer requires colorizer decision nodes in `colorNodes`; run `cem.color-tree` before the writer"
                .to_owned(),
        );
    }
    if let Some(conflicting_profile) = color_nodes.iter().find_map(|node| {
        let profile = node.get("colorProfile").and_then(Value::as_str)?;
        (profile != color_profile).then_some(profile)
    }) {
        return Err(format!(
            "CEM tree color metadata profile mismatch: tree `{color_profile}`, colorNodes `{conflicting_profile}`"
        ));
    }
    if TransformTemplateColorOutputProfile::html_from_selector(color_profile).is_ok()
        && !cem_tree_contains_writer_token_nodes(value)
    {
        validate_cem_tree_materialized_html_color_metadata(value, color_profile)?;
    }
    Ok(())
}

fn validate_cem_tree_materialized_html_color_metadata(
    value: &Value,
    color_profile: &str,
) -> Result<(), String> {
    validate_cem_tree_materialized_html_color_metadata_value(value, color_profile)
}

fn validate_cem_tree_materialized_html_color_metadata_value(
    value: &Value,
    color_profile: &str,
) -> Result<(), String> {
    match value {
        Value::Object(fields) => {
            validate_cem_tree_materialized_html_color_metadata_object(fields, color_profile)?;
            for field in [
                "nodes",
                "node",
                "root",
                "attributes",
                "children",
                "slots",
                "formatNodes",
                "colorNodes",
                "formatLayout",
                "formatBefore",
                "formatBeforeAttribute",
                "formatBeforeAttributes",
                "formatBetweenAttributes",
                "formatContentBoundary",
                "formatBeforeClose",
            ] {
                if let Some(value) = fields.get(field) {
                    validate_cem_tree_materialized_html_color_metadata_value(value, color_profile)?;
                }
            }
            Ok(())
        }
        Value::Array(items) => {
            for item in items {
                validate_cem_tree_materialized_html_color_metadata_value(item, color_profile)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn validate_cem_tree_materialized_html_color_metadata_object(
    fields: &serde_json::Map<String, Value>,
    color_profile: &str,
) -> Result<(), String> {
    if fields.contains_key("writerAttributes") || fields.contains_key("writerAttributesSourceMap") {
        return Err(
            "CEM tree writer requires materialized `writerAttributeNodes`; flat `writerAttributes` metadata is not a writer input"
                .to_owned(),
        );
    }
    if fields.contains_key("colorWrapper") {
        return Err(
            "CEM tree writer requires materialized `colorWrapperNodes`; legacy `colorWrapper` metadata is not a writer input"
                .to_owned(),
        );
    }
    if transform_template_cem_tree_object_requires_writer_attribute_nodes(fields) {
        validate_cem_tree_writer_attribute_nodes(fields, color_profile)?;
    }
    if fields.contains_key("colorWrapperNodes") {
        validate_cem_tree_color_wrapper_nodes(fields, color_profile)?;
    }
    Ok(())
}

fn transform_template_cem_tree_object_requires_writer_attribute_nodes(
    fields: &serde_json::Map<String, Value>,
) -> bool {
    if !fields.contains_key("colorRole") {
        return false;
    }
    matches!(
        fields
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or_default(),
        "element"
            | "node"
            | "root"
            | "attribute"
            | "attr"
            | "text"
            | "content"
            | "string"
            | "comment"
            | "whitespace"
            | "raw"
            | "format-token"
            | "format-marker"
            | "format-decision"
            | "format-span"
            | "color-marker"
            | "color-decision"
            | "color-span"
    )
}

fn validate_cem_tree_writer_attribute_nodes(
    fields: &serde_json::Map<String, Value>,
    color_profile: &str,
) -> Result<(), String> {
    let nodes = fields
        .get("writerAttributeNodes")
        .and_then(Value::as_array)
        .filter(|nodes| !nodes.is_empty())
        .ok_or_else(|| {
            "CEM tree writer requires materialized `writerAttributeNodes` for HTML-colored CEM tree nodes"
                .to_owned()
        })?;
    for node in nodes {
        let fields = node.as_object().ok_or_else(|| {
            format!(
                "CEM tree writer expected writerAttributeNodes item object, got {}",
                json_value_type_name(node)
            )
        })?;
        if fields.get("kind").and_then(Value::as_str) != Some("writer-attribute") {
            return Err(
                "CEM tree writer expected writerAttributeNodes items with kind `writer-attribute`"
                    .to_owned(),
            );
        }
        if fields
            .get("name")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .is_none()
        {
            return Err("CEM tree writer expected writerAttributeNodes item name".to_owned());
        }
        if fields.get("value").is_none() {
            return Err("CEM tree writer expected writerAttributeNodes item value".to_owned());
        }
        if fields.get("colorizerOwned").and_then(Value::as_bool) != Some(true) {
            return Err("CEM tree writer expected colorizer-owned writerAttributeNodes".to_owned());
        }
        if !fields
            .get("colorizerRole")
            .and_then(Value::as_str)
            .is_some_and(|role| role.starts_with("colorizer."))
        {
            return Err(
                "CEM tree writer expected writerAttributeNodes colorizerRole metadata".to_owned(),
            );
        }
        if fields.get("colorProfile").and_then(Value::as_str) != Some(color_profile) {
            return Err(format!(
                "CEM tree writerAttributeNodes color profile mismatch: tree `{color_profile}`"
            ));
        }
    }
    Ok(())
}

fn validate_cem_tree_color_wrapper_nodes(
    fields: &serde_json::Map<String, Value>,
    color_profile: &str,
) -> Result<(), String> {
    let nodes = fields
        .get("colorWrapperNodes")
        .and_then(Value::as_array)
        .filter(|nodes| !nodes.is_empty())
        .ok_or_else(|| {
            "CEM tree writer requires materialized `colorWrapperNodes` for color wrapper elements"
                .to_owned()
        })?;
    let has_wrapper = nodes.iter().any(|node| {
        let Some(fields) = node.as_object() else {
            return false;
        };
        fields.get("kind").and_then(Value::as_str) == Some("color-wrapper")
            && fields.get("name").and_then(Value::as_str) == Some("span")
            && fields.get("colorizerOwned").and_then(Value::as_bool) == Some(true)
            && fields.get("colorizerRole").and_then(Value::as_str) == Some("colorizer.text-wrapper")
            && fields.get("colorProfile").and_then(Value::as_str) == Some(color_profile)
    });
    if !has_wrapper {
        return Err(
            "CEM tree writer expected `colorWrapperNodes` to include the colorizer text wrapper decision"
                .to_owned(),
        );
    }
    let has_wrapped_role = nodes.iter().any(|node| {
        let Some(fields) = node.as_object() else {
            return false;
        };
        fields.get("kind").and_then(Value::as_str) == Some("color-decision")
            && fields.get("name").and_then(Value::as_str) == Some("wrapped-role")
            && fields.get("colorizerOwned").and_then(Value::as_bool) == Some(true)
            && fields.get("colorizerRole").and_then(Value::as_str) == Some("colorizer.wrapped-role")
            && fields.get("colorProfile").and_then(Value::as_str) == Some(color_profile)
    });
    if !has_wrapped_role {
        return Err(
            "CEM tree writer expected `colorWrapperNodes` to include the wrapped color role decision"
                .to_owned(),
        );
    }
    Ok(())
}

fn transform_template_writer_text_identity_from_context(
    artifact: &TransformTemplateEncodedArtifact,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> TransformTemplateEncodedArtifactIdentity {
    let mut identity = artifact.identity.clone();
    if !writer_boundary_context.content_type.trim().is_empty()
        || !writer_boundary_context.schema.trim().is_empty()
        || writer_boundary_context.category.is_some()
    {
        identity.target = TransformTemplateEncodingTarget {
            content_type: if writer_boundary_context.content_type.trim().is_empty() {
                artifact.identity.target.content_type.clone()
            } else {
                writer_boundary_context.content_type.clone()
            },
            schema: if writer_boundary_context.schema.trim().is_empty() {
                artifact.identity.target.schema.clone()
            } else {
                writer_boundary_context.schema.clone()
            },
            category: writer_boundary_context
                .category
                .clone()
                .unwrap_or_else(|| artifact.identity.target.category.clone()),
            context: writer_boundary_context
                .context
                .clone()
                .or_else(|| artifact.identity.target.context.clone()),
        };
    }
    identity.formatter_profile = writer_boundary_context
        .formatter_profile
        .clone()
        .or_else(|| artifact.identity.formatter_profile.clone());
    identity.color_profile = writer_boundary_context
        .color_profile
        .clone()
        .or_else(|| artifact.identity.color_profile.clone());
    identity.color_capability = writer_boundary_context
        .color_capability
        .clone()
        .or_else(|| artifact.identity.color_capability.clone());
    if let Some(mode) = writer_boundary_context.mode {
        identity.mode = mode;
    }
    if let Some(canonical) = writer_boundary_context.canonical {
        identity.canonical = canonical;
    }
    if let Some(source_map_policy) = writer_boundary_context.source_map_policy {
        identity.source_map_policy = source_map_policy;
    }
    identity
}

fn trimmed_optional_str(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|value| !value.is_empty())
}

fn trimmed_value_string_field<'a>(value: &'a Value, field: &str) -> Option<&'a str> {
    value
        .get(field)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn transform_template_cem_tree_writer_line_ending(value: &Value) -> String {
    transform_template_line_ending_data_from_selector(
        transform_template_cem_tree_writer_format_decision_value(value, "line-ending"),
    )
}

fn transform_template_cem_tree_writer_format_decision_value<'a>(
    value: &'a Value,
    name: &str,
) -> Option<&'a str> {
    value
        .get("formatNodes")
        .and_then(Value::as_array)
        .and_then(|nodes| {
            nodes.iter().find_map(|node| {
                let fields = node.as_object()?;
                (fields.get("kind").and_then(Value::as_str) == Some("format-decision")
                    && fields.get("name").and_then(Value::as_str) == Some(name))
                .then(|| fields.get("value").and_then(Value::as_str))
                .flatten()
            })
        })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TransformTemplateCemTreeWriterSyntax {
    Cem,
    Html,
    Markdown,
    Xml,
}

impl TransformTemplateCemTreeWriterSyntax {
    fn is_cem_like(self) -> bool {
        matches!(self, Self::Cem | Self::Markdown)
    }

    fn is_markup(self) -> bool {
        matches!(self, Self::Html | Self::Xml)
    }
}

#[derive(Debug, Default)]
struct TransformTemplateCemTreeRenderedText {
    text: String,
    output_spans: Vec<OutputSpan>,
    line_ending: String,
    terminal_color_profile: Option<TransformTemplateColorOutputProfile>,
    markdown_color_profile: Option<TransformTemplateColorOutputProfile>,
    writer_token_color_profile: Option<TransformTemplateWriterTokenColorProfile>,
}

impl TransformTemplateCemTreeRenderedText {
    fn with_color_profiles(
        terminal_color_profile: Option<TransformTemplateColorOutputProfile>,
        markdown_color_profile: Option<TransformTemplateColorOutputProfile>,
        writer_token_color_profile: Option<TransformTemplateWriterTokenColorProfile>,
    ) -> Self {
        Self {
            terminal_color_profile,
            markdown_color_profile,
            writer_token_color_profile,
            ..Self::default()
        }
    }

    fn push_unmapped(&mut self, text: &str) {
        self.text.push_str(text);
    }

    fn push_line_ending(&mut self) {
        self.text.push_str(&self.line_ending);
    }

    fn push_colored_mapped(
        &mut self,
        text: &str,
        source_map: Option<&SourceMapStack>,
        role: Option<&str>,
    ) {
        if text.is_empty() {
            return;
        }
        let sgr = self
            .terminal_color_profile
            .as_ref()
            .filter(|profile| !profile.no_color)
            .and_then(|profile| {
                let role = role?;
                profile
                    .supports_role(role)
                    .then(|| {
                        transform_template_terminal_sgr_for_role(role, profile.terminal_capability)
                    })
                    .flatten()
            })
            .map(str::to_owned);

        if let Some(sgr) = sgr {
            self.push_unmapped(&format!("\u{1b}[{sgr}m"));
            self.push_mapped(text, source_map);
            self.push_unmapped("\u{1b}[0m");
        } else if let Some(role) = role.filter(|role| {
            self.markdown_color_profile
                .as_ref()
                .is_some_and(|profile| profile.supports_role(role))
        }) {
            self.push_unmapped(&transform_template_markdown_color_span_open(role));
            let text = transform_template_encode_html_text(text);
            self.push_mapped(&text, source_map);
            self.push_unmapped("</span>");
        } else {
            self.push_mapped(text, source_map);
        }
    }

    fn push_mapped(&mut self, text: &str, source_map: Option<&SourceMapStack>) {
        let start = self.text.len() as u64;
        self.text.push_str(text);
        let len = (self.text.len() as u64).saturating_sub(start);
        if len == 0 {
            return;
        }
        let Some(source_map) = source_map else {
            return;
        };
        let mut origin = source_map.clone();
        origin.push(SourceMapFrame {
            source_id: origin
                .frames
                .last()
                .map(|frame| frame.source_id)
                .unwrap_or(SourceId(0)),
            span: FrameSpan::Single(ByteRange::new(start, len as u32)),
            transform: TransformKind::InterpreterRender,
        });
        self.output_spans.push(OutputSpan {
            output_range: ByteRange::new(start, len as u32),
            origin,
        });
    }

    fn finish_terminal_color_boundary(&mut self) {
        if self.terminal_color_profile.as_ref().is_some_and(|profile| {
            profile.reset_at_artifact_boundaries
                && profile.terminal_capability != TransformTemplateTerminalColorCapability::None
                && !self.text.is_empty()
        }) {
            self.push_unmapped("\u{1b}[0m");
        }
    }

    fn apply_text_edits(&mut self, mut edits: Vec<TransformTemplateRenderedTextEdit>) {
        edits.sort_by(|left, right| right.start.cmp(&left.start));
        for edit in edits {
            self.text
                .replace_range(edit.start..edit.end, &edit.replacement);
            self.adjust_output_spans_for_edit(
                edit.start as u64,
                edit.end as u64,
                edit.replacement.len() as u64,
            );
        }
    }

    fn adjust_output_spans_for_edit(&mut self, start: u64, end: u64, replacement_len: u64) {
        let removed_len = end.saturating_sub(start);
        let delta = replacement_len as i128 - removed_len as i128;
        self.output_spans = self
            .output_spans
            .drain(..)
            .filter_map(|mut span| {
                let span_start = span.output_range.start;
                let span_end = span.output_range.end();
                if span_end <= start {
                    return Some(span);
                }
                if span_start >= end {
                    span.output_range.start =
                        transform_template_shift_byte_offset(span.output_range.start, delta);
                    transform_template_shift_interpreter_render_frames(&mut span.origin, delta);
                    return Some(span);
                }
                None
            })
            .collect();
    }
}

#[derive(Debug, Clone)]
struct TransformTemplateRenderedTextEdit {
    start: usize,
    end: usize,
    replacement: String,
}

#[derive(Debug, Clone, Copy)]
struct TransformTemplateRenderedTextLine {
    start: usize,
    content_end: usize,
}

#[derive(Debug, Clone)]
struct TransformTemplateCemTreeWriterTokenLine {
    tokens: Vec<Value>,
    line_ending: Option<Value>,
}

#[derive(Debug, Clone)]
struct TransformTemplateCemTreeWriterTokenCloseScopeLine {
    leading_tokens: Vec<Value>,
    close_token: Value,
}

#[derive(Debug, Clone)]
struct TransformTemplateRenderedTextCloseScopeLine {
    leading_whitespace: String,
    close_token: String,
}

#[derive(Debug, Clone)]
struct TransformTemplateRenderedTextTrailingCloseScope {
    close_start: usize,
    close_end: usize,
    close_scope: TransformTemplateRenderedTextCloseScopeLine,
}

#[derive(Debug, Clone, Copy)]
enum TransformTemplateRenderedTextLinePart {
    Escape { start: usize, end: usize },
    Visible { ch: char, start: usize, end: usize },
}

fn transform_template_shift_byte_offset(value: u64, delta: i128) -> u64 {
    if delta < 0 {
        value.saturating_sub((-delta) as u64)
    } else {
        value.saturating_add(delta as u64)
    }
}

fn transform_template_shift_interpreter_render_frames(
    source_map: &mut SourceMapStack,
    delta: i128,
) {
    for frame in &mut source_map.frames {
        if !matches!(frame.transform, TransformKind::InterpreterRender) {
            continue;
        }
        match &mut frame.span {
            FrameSpan::Single(range) => {
                range.start = transform_template_shift_byte_offset(range.start, delta);
            }
            FrameSpan::Multi(ranges) => {
                for range in ranges {
                    range.start = transform_template_shift_byte_offset(range.start, delta);
                }
            }
        }
    }
}

fn transform_template_merge_tabular_cem_closing_scopes(
    rendered: &mut TransformTemplateCemTreeRenderedText,
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
    syntax: TransformTemplateCemTreeWriterSyntax,
) {
    if syntax != TransformTemplateCemTreeWriterSyntax::Cem
        || !transform_template_cem_tree_writer_uses_tabular_profile(value, writer_boundary_context)
        || rendered.markdown_color_profile.is_some()
    {
        return;
    }
    let line_ending = rendered.line_ending.clone();
    if line_ending.is_empty() {
        return;
    }
    let indent = transform_template_cem_tree_writer_indent(value);
    if indent.is_empty() {
        return;
    }
    let lines = transform_template_rendered_text_lines(&rendered.text, &line_ending);
    if lines.len() < 2 {
        return;
    }
    let mut edits = Vec::new();
    let mut index = 0usize;
    while index + 1 < lines.len() {
        let line = lines[index];
        let line_text = &rendered.text[line.start..line.content_end];
        if let Some(close_scope) = transform_template_rendered_text_close_scope_line(line_text) {
            let mut close_scopes = vec![close_scope];
            let mut last_close_line = index;
            while last_close_line + 1 < lines.len() {
                let next_line = lines[last_close_line + 1];
                let next_line_text = &rendered.text[next_line.start..next_line.content_end];
                let Some(next_close_scope) =
                    transform_template_rendered_text_close_scope_line(next_line_text)
                else {
                    break;
                };
                close_scopes.push(next_close_scope);
                last_close_line += 1;
            }
            if close_scopes.len() > 1 {
                let merged =
                    transform_template_rendered_text_merged_close_scopes(&close_scopes, &indent);
                edits.push(TransformTemplateRenderedTextEdit {
                    start: line.start,
                    end: lines[last_close_line].content_end,
                    replacement: merged,
                });
                index = last_close_line + 1;
                continue;
            }
        } else if let Some(trailing_close_scope) =
            transform_template_rendered_text_trailing_close_scope(line_text)
        {
            let mut close_scopes = vec![trailing_close_scope.close_scope.clone()];
            let mut last_close_line = index;
            while last_close_line + 1 < lines.len() {
                let next_line = lines[last_close_line + 1];
                let next_line_text = &rendered.text[next_line.start..next_line.content_end];
                let Some(next_close_scope) =
                    transform_template_rendered_text_close_scope_line(next_line_text)
                else {
                    break;
                };
                close_scopes.push(next_close_scope);
                last_close_line += 1;
            }
            if close_scopes.len() <= 1 {
                index += 1;
                continue;
            }
            let merged =
                transform_template_rendered_text_merged_close_scopes(&close_scopes, &indent);
            edits.push(TransformTemplateRenderedTextEdit {
                start: line.start + trailing_close_scope.close_start,
                end: line.start + trailing_close_scope.close_end,
                replacement: String::new(),
            });
            edits.push(TransformTemplateRenderedTextEdit {
                start: lines[index + 1].start,
                end: lines[last_close_line].content_end,
                replacement: merged,
            });
            index = last_close_line + 1;
            continue;
        }
        index += 1;
    }
    if !edits.is_empty() {
        rendered.apply_text_edits(edits);
    }
}

fn transform_template_cem_tree_writer_uses_tabular_profile(
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> bool {
    trimmed_value_string_field(value, "formatterProfile")
        .or_else(|| trimmed_optional_str(writer_boundary_context.formatter_profile.as_deref()))
        == Some("tabular")
}

fn transform_template_cem_tree_writer_indent(value: &Value) -> String {
    transform_template_cem_tree_writer_format_decision_value(value, "indent")
        .map(str::to_owned)
        .unwrap_or_else(|| DEFAULT_FORMATTER_INDENT.to_owned())
}

fn transform_template_compact_tabular_cem_tree_writer_token_close_scopes(
    nodes: &[Value],
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
    line_ending: &str,
) -> Option<Vec<Value>> {
    if !transform_template_cem_tree_writer_uses_tabular_profile(value, writer_boundary_context)
        || line_ending.is_empty()
        || !nodes
            .iter()
            .all(transform_template_cem_tree_value_is_writer_token)
    {
        return None;
    }
    let indent = transform_template_cem_tree_writer_indent(value);
    if indent.is_empty() {
        return None;
    }
    let lines = transform_template_cem_tree_writer_token_lines(nodes, line_ending);
    if lines.len() < 2 {
        return None;
    }
    let separator = transform_template_rendered_text_close_scope_separator(&indent);
    let mut compacted = Vec::with_capacity(nodes.len());
    let mut changed = false;
    let mut index = 0usize;
    while index < lines.len() {
        let Some(first_close_scope) =
            transform_template_cem_tree_writer_token_close_scope_line(&lines[index])
        else {
            transform_template_push_cem_tree_writer_token_line(&mut compacted, &lines[index]);
            index += 1;
            continue;
        };
        let mut close_scopes = vec![first_close_scope];
        let mut last_close_line = index;
        while last_close_line + 1 < lines.len() {
            let Some(next_close_scope) = transform_template_cem_tree_writer_token_close_scope_line(
                &lines[last_close_line + 1],
            ) else {
                break;
            };
            close_scopes.push(next_close_scope);
            last_close_line += 1;
        }
        if close_scopes.len() <= 1 {
            transform_template_push_cem_tree_writer_token_line(&mut compacted, &lines[index]);
            index += 1;
            continue;
        }

        changed = true;
        if let Some(outer_close_scope) = close_scopes.last() {
            compacted.extend(outer_close_scope.leading_tokens.iter().cloned());
        }
        for (close_index, close_scope) in close_scopes.iter().enumerate() {
            if close_index > 0 {
                compacted.push(
                    transform_template_cem_tree_writer_token_close_scope_separator(&separator),
                );
            }
            compacted.push(close_scope.close_token.clone());
        }
        if let Some(line_ending) = lines[last_close_line].line_ending.as_ref() {
            compacted.push(line_ending.clone());
        }
        index = last_close_line + 1;
    }
    changed.then_some(compacted)
}

fn transform_template_cem_tree_writer_token_lines(
    nodes: &[Value],
    line_ending: &str,
) -> Vec<TransformTemplateCemTreeWriterTokenLine> {
    let mut lines = Vec::new();
    let mut current = Vec::new();
    for node in nodes {
        if transform_template_cem_tree_writer_token_text(node) == Some(line_ending) {
            lines.push(TransformTemplateCemTreeWriterTokenLine {
                tokens: std::mem::take(&mut current),
                line_ending: Some(node.clone()),
            });
        } else {
            current.push(node.clone());
        }
    }
    if !current.is_empty() {
        lines.push(TransformTemplateCemTreeWriterTokenLine {
            tokens: current,
            line_ending: None,
        });
    }
    lines
}

fn transform_template_push_cem_tree_writer_token_line(
    output: &mut Vec<Value>,
    line: &TransformTemplateCemTreeWriterTokenLine,
) {
    output.extend(line.tokens.iter().cloned());
    if let Some(line_ending) = line.line_ending.as_ref() {
        output.push(line_ending.clone());
    }
}

fn transform_template_cem_tree_writer_token_close_scope_line(
    line: &TransformTemplateCemTreeWriterTokenLine,
) -> Option<TransformTemplateCemTreeWriterTokenCloseScopeLine> {
    let mut leading_tokens = Vec::new();
    let mut close_token = None;
    for token in &line.tokens {
        let text = transform_template_cem_tree_writer_token_text(token)?;
        if text.is_empty() || text.chars().all(char::is_whitespace) {
            if close_token.is_none() {
                leading_tokens.push(token.clone());
            } else if !text.is_empty() {
                return None;
            }
            continue;
        }
        if close_token.is_none() && transform_template_cem_tree_writer_token_is_close_scope(text) {
            close_token = Some(token.clone());
            continue;
        }
        return None;
    }
    close_token.map(
        |close_token| TransformTemplateCemTreeWriterTokenCloseScopeLine {
            leading_tokens,
            close_token,
        },
    )
}

fn transform_template_cem_tree_writer_token_text(value: &Value) -> Option<&str> {
    let fields = value.as_object()?;
    transform_template_cem_tree_fields_are_writer_token(fields)
        .then(|| fields.get("text").and_then(Value::as_str))
        .flatten()
}

fn transform_template_cem_tree_writer_token_is_close_scope(text: &str) -> bool {
    matches!(text, "}" | "]")
}

fn transform_template_cem_tree_writer_token_close_scope_separator(separator: &str) -> Value {
    serde_json::json!({
        "kind": "formatter.close-spacing",
        "writerKind": "token",
        "text": separator,
        "role": "syntax.raw",
        "style": {
            "colorRole": "syntax.raw"
        },
        "value": {
            "formatterRole": "formatter.close-spacing"
        }
    })
}

fn transform_template_rendered_text_lines(
    text: &str,
    line_ending: &str,
) -> Vec<TransformTemplateRenderedTextLine> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    while let Some(relative_end) = text[start..].find(line_ending) {
        let content_end = start + relative_end;
        lines.push(TransformTemplateRenderedTextLine { start, content_end });
        start = content_end + line_ending.len();
    }
    if start < text.len() {
        lines.push(TransformTemplateRenderedTextLine {
            start,
            content_end: text.len(),
        });
    }
    lines
}

fn transform_template_rendered_text_merged_close_scopes(
    close_scopes: &[TransformTemplateRenderedTextCloseScopeLine],
    indent: &str,
) -> String {
    let Some(outer_close_scope) = close_scopes.last() else {
        return String::new();
    };
    let separator = transform_template_rendered_text_close_scope_separator(indent);
    let mut merged = outer_close_scope.leading_whitespace.clone();
    for (index, close_scope) in close_scopes.iter().enumerate() {
        if index > 0 {
            merged.push_str(&separator);
        }
        merged.push_str(&close_scope.close_token);
    }
    merged
}

fn transform_template_rendered_text_close_scope_line(
    line: &str,
) -> Option<TransformTemplateRenderedTextCloseScopeLine> {
    let parts = transform_template_rendered_text_line_parts(line);
    let visible_parts = parts
        .iter()
        .enumerate()
        .filter_map(|(index, part)| match part {
            TransformTemplateRenderedTextLinePart::Visible { ch, .. } => Some((index, *ch)),
            TransformTemplateRenderedTextLinePart::Escape { .. } => None,
        })
        .collect::<Vec<_>>();
    let (first_non_whitespace_index, first_non_whitespace) =
        visible_parts.iter().find(|(_, ch)| !ch.is_whitespace())?;
    let (last_non_whitespace_index, last_non_whitespace) = visible_parts
        .iter()
        .rev()
        .find(|(_, ch)| !ch.is_whitespace())?;
    if first_non_whitespace_index != last_non_whitespace_index
        || *first_non_whitespace != '}'
        || *last_non_whitespace != '}'
    {
        return None;
    }

    let mut leading_whitespace = String::new();
    for part in &parts[..*first_non_whitespace_index] {
        if let TransformTemplateRenderedTextLinePart::Visible { ch, .. } = part {
            leading_whitespace.push(*ch);
        }
    }
    let close_token =
        transform_template_rendered_text_close_token(line, &parts, *first_non_whitespace_index);
    Some(TransformTemplateRenderedTextCloseScopeLine {
        leading_whitespace,
        close_token,
    })
}

fn transform_template_rendered_text_trailing_close_scope(
    line: &str,
) -> Option<TransformTemplateRenderedTextTrailingCloseScope> {
    let parts = transform_template_rendered_text_line_parts(line);
    let visible_parts = parts
        .iter()
        .enumerate()
        .filter_map(|(index, part)| match part {
            TransformTemplateRenderedTextLinePart::Visible { ch, .. } => Some((index, *ch)),
            TransformTemplateRenderedTextLinePart::Escape { .. } => None,
        })
        .collect::<Vec<_>>();
    let visible_text = visible_parts.iter().map(|(_, ch)| *ch).collect::<String>();
    let trimmed_end = visible_text.trim_end();
    if trimmed_end.trim() == "}" || !trimmed_end.ends_with("```}") {
        return None;
    }
    let (close_part_index, close_char) = visible_parts
        .iter()
        .rev()
        .find(|(_, ch)| !ch.is_whitespace())?;
    if *close_char != '}' {
        return None;
    }
    let TransformTemplateRenderedTextLinePart::Visible {
        start: close_start,
        end: close_end,
        ..
    } = parts[*close_part_index]
    else {
        return None;
    };
    let close_scope = TransformTemplateRenderedTextCloseScopeLine {
        leading_whitespace: String::new(),
        close_token: transform_template_rendered_text_close_token(line, &parts, *close_part_index),
    };
    Some(TransformTemplateRenderedTextTrailingCloseScope {
        close_start,
        close_end,
        close_scope,
    })
}

fn transform_template_rendered_text_close_token(
    line: &str,
    parts: &[TransformTemplateRenderedTextLinePart],
    close_part_index: usize,
) -> String {
    let TransformTemplateRenderedTextLinePart::Visible {
        start: mut token_start,
        end: mut token_end,
        ..
    } = parts[close_part_index]
    else {
        return String::new();
    };
    let mut index = close_part_index;
    while index > 0 {
        let TransformTemplateRenderedTextLinePart::Escape { start, .. } = parts[index - 1] else {
            break;
        };
        token_start = start;
        index -= 1;
    }
    index = close_part_index + 1;
    while index < parts.len() {
        let TransformTemplateRenderedTextLinePart::Escape { end, .. } = parts[index] else {
            break;
        };
        token_end = end;
        index += 1;
    }
    line[token_start..token_end].to_owned()
}

#[cfg(test)]
fn transform_template_rendered_text_without_terminal_escapes(text: &str) -> String {
    let mut result = String::new();
    for part in transform_template_rendered_text_line_parts(text) {
        if let TransformTemplateRenderedTextLinePart::Visible { ch, .. } = part {
            result.push(ch);
        }
    }
    result
}

#[cfg(test)]
fn transform_template_rendered_text_without_html_tags(text: &str) -> String {
    let mut result = String::new();
    let mut in_tag = false;
    for ch in text.chars() {
        match ch {
            '<' => in_tag = true,
            '>' if in_tag => in_tag = false,
            _ if !in_tag => result.push(ch),
            _ => {}
        }
    }
    result
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn transform_template_rendered_text_line_parts(
    text: &str,
) -> Vec<TransformTemplateRenderedTextLinePart> {
    let mut parts = Vec::new();
    let mut index = 0usize;
    while index < text.len() {
        if text.as_bytes()[index] == 0x1b {
            if let Some(end) = transform_template_terminal_escape_sequence_end(text, index) {
                parts.push(TransformTemplateRenderedTextLinePart::Escape { start: index, end });
                index = end;
                continue;
            }
        }
        let Some(ch) = text[index..].chars().next() else {
            break;
        };
        let end = index + ch.len_utf8();
        parts.push(TransformTemplateRenderedTextLinePart::Visible {
            ch,
            start: index,
            end,
        });
        index = end;
    }
    parts
}

fn transform_template_terminal_escape_sequence_end(text: &str, start: usize) -> Option<usize> {
    let bytes = text.as_bytes();
    if bytes.get(start).copied()? != 0x1b {
        return None;
    }
    match bytes.get(start + 1).copied()? {
        b'[' => {
            let mut index = start + 2;
            while index < bytes.len() {
                if (0x40..=0x7e).contains(&bytes[index]) {
                    return Some(index + 1);
                }
                index += 1;
            }
            None
        }
        b']' => {
            let mut index = start + 2;
            while index < bytes.len() {
                match bytes[index] {
                    0x07 => return Some(index + 1),
                    0x1b if bytes.get(index + 1).copied() == Some(b'\\') => {
                        return Some(index + 2);
                    }
                    _ => index += 1,
                }
            }
            None
        }
        _ => Some((start + 2).min(bytes.len())),
    }
}

fn transform_template_rendered_text_close_scope_separator(indent: &str) -> String {
    if indent.chars().all(|ch| ch == ' ') {
        return " ".repeat(indent.chars().count().saturating_sub(1));
    }
    indent.to_owned()
}

fn transform_template_cem_tree_value_to_rendered_text(
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> Result<TransformTemplateCemTreeRenderedText, String> {
    let syntax = transform_template_cem_tree_writer_syntax(writer_boundary_context);
    let terminal_color_profile = transform_template_cem_tree_writer_terminal_color_profile(
        value,
        writer_boundary_context,
        syntax,
    );
    let markdown_color_profile = transform_template_cem_tree_writer_markdown_color_profile(
        value,
        writer_boundary_context,
        syntax,
    );
    let writer_token_color_profile =
        transform_template_cem_tree_writer_token_color_profile(value, writer_boundary_context);
    let line_ending = transform_template_cem_tree_writer_line_ending(value);
    let object = value
        .as_object()
        .ok_or_else(|| "CEM tree writer expected object value".to_owned())?;
    let mut rendered = TransformTemplateCemTreeRenderedText::with_color_profiles(
        terminal_color_profile,
        markdown_color_profile,
        writer_token_color_profile,
    );
    rendered.line_ending = line_ending;
    if let Some(nodes) = object.get("nodes").and_then(Value::as_array) {
        let compacted = transform_template_compact_tabular_cem_tree_writer_token_close_scopes(
            nodes,
            value,
            writer_boundary_context,
            &rendered.line_ending,
        );
        transform_template_render_cem_tree_nodes(
            compacted.as_deref().unwrap_or(nodes),
            syntax,
            &mut rendered,
        )?;
    } else if let Some(node) = object.get("node") {
        transform_template_render_cem_tree_node(node, syntax, &mut rendered)?;
    } else if let Some(root) = object.get("root") {
        match root {
            Value::Array(nodes) => {
                let compacted =
                    transform_template_compact_tabular_cem_tree_writer_token_close_scopes(
                        nodes,
                        value,
                        writer_boundary_context,
                        &rendered.line_ending,
                    );
                transform_template_render_cem_tree_nodes(
                    compacted.as_deref().unwrap_or(nodes),
                    syntax,
                    &mut rendered,
                )?
            }
            Value::Object(_) => {
                transform_template_render_cem_tree_node(root, syntax, &mut rendered)?
            }
            _ => {
                return Err(format!(
                    "CEM tree writer expected `root` object or array, got {}",
                    json_value_type_name(root)
                ))
            }
        }
    } else {
        return Err("CEM tree writer expected `nodes`, `node`, or `root`".to_owned());
    }
    transform_template_merge_tabular_cem_closing_scopes(
        &mut rendered,
        value,
        writer_boundary_context,
        syntax,
    );
    rendered.finish_terminal_color_boundary();
    Ok(rendered)
}

fn transform_template_render_cem_tree_nodes(
    nodes: &[Value],
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    for (index, node) in nodes.iter().enumerate() {
        if index > 0
            && !transform_template_cem_tree_value_is_whitespace(&nodes[index - 1])
            && !transform_template_cem_tree_value_is_whitespace(node)
            && !transform_template_cem_tree_value_is_writer_token(&nodes[index - 1])
            && !transform_template_cem_tree_value_is_writer_token(node)
        {
            match syntax {
                TransformTemplateCemTreeWriterSyntax::Cem
                | TransformTemplateCemTreeWriterSyntax::Markdown => rendered.push_line_ending(),
                TransformTemplateCemTreeWriterSyntax::Html
                | TransformTemplateCemTreeWriterSyntax::Xml => {}
            }
        }
        transform_template_render_cem_tree_node(node, syntax, rendered)?;
    }
    Ok(())
}

fn transform_template_render_cem_tree_node(
    node: &Value,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    match node {
        Value::String(text) => match syntax {
            TransformTemplateCemTreeWriterSyntax::Cem
            | TransformTemplateCemTreeWriterSyntax::Markdown => {
                rendered.push_unmapped(&transform_template_encode_cem_content_text(text)?);
                Ok(())
            }
            TransformTemplateCemTreeWriterSyntax::Html => {
                rendered.push_unmapped(&transform_template_encode_html_text(text));
                Ok(())
            }
            TransformTemplateCemTreeWriterSyntax::Xml => {
                rendered.push_unmapped(&transform_template_encode_xml_text(text));
                Ok(())
            }
        },
        Value::Object(fields) => {
            transform_template_render_cem_tree_object_node(fields, syntax, rendered)
        }
        other => Err(format!(
            "CEM tree writer expected node object or string, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_render_cem_tree_object_node(
    fields: &serde_json::Map<String, Value>,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let kind = fields
        .get("kind")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("element");
    if transform_template_cem_tree_fields_are_writer_token(fields) {
        return transform_template_render_cem_tree_writer_token_node(fields, rendered);
    }
    if syntax.is_markup() {
        return transform_template_render_cem_tree_markup_node(fields, syntax, rendered);
    }
    if kind == "directive"
        || transform_template_cem_tree_name(fields).is_some_and(|name| {
            name.strip_prefix('@')
                .is_some_and(|stripped| !stripped.trim().is_empty())
        })
    {
        return transform_template_render_cem_tree_directive(fields, rendered);
    }
    let source_map = transform_template_cem_tree_node_source_map(fields);
    let color_role = transform_template_cem_tree_render_color_role(fields);
    match kind {
        "text" | "content" | "string" => {
            let text = fields
                .get("value")
                .or_else(|| fields.get("text"))
                .or_else(|| fields.get("data"))
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    "CEM text node missing string `value`, `text`, or `data`".to_owned()
                })?;
            rendered.push_colored_mapped(
                &transform_template_encode_cem_content_text(text)?,
                source_map.as_ref(),
                color_role.as_deref(),
            );
            Ok(())
        }
        "whitespace" => {
            rendered.push_colored_mapped(
                transform_template_cem_tree_node_data(fields),
                source_map.as_ref(),
                color_role.as_deref(),
            );
            Ok(())
        }
        "comment" => {
            let text = format!(
                "{{comment @value={}}}",
                transform_template_encode_cem_attribute_value(
                    transform_template_cem_tree_node_data(fields),
                    "CEM comment value"
                )?
            );
            rendered.push_colored_mapped(&text, source_map.as_ref(), color_role.as_deref());
            Ok(())
        }
        "attribute" | "attr" => {
            rendered.push_colored_mapped(
                &transform_template_cem_tree_attribute_to_text(fields)?,
                source_map.as_ref(),
                color_role.as_deref(),
            );
            Ok(())
        }
        _ => transform_template_render_cem_tree_element(fields, syntax, rendered),
    }
}

fn transform_template_cem_tree_value_is_writer_token(value: &Value) -> bool {
    value
        .as_object()
        .is_some_and(transform_template_cem_tree_fields_are_writer_token)
}

fn transform_template_cem_tree_fields_are_writer_token(
    fields: &serde_json::Map<String, Value>,
) -> bool {
    fields
        .get("writerKind")
        .or_else(|| fields.get("writerNode"))
        .and_then(Value::as_str)
        .map(str::trim)
        .is_some_and(|value| value == "token")
        || fields.get("kind").and_then(Value::as_str) == Some("writer-token")
}

fn transform_template_render_cem_tree_writer_token_node(
    fields: &serde_json::Map<String, Value>,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let mut token_fields = fields.clone();
    if token_fields.get("kind").and_then(Value::as_str) == Some("writer-token") {
        let token_kind = token_fields
            .get("tokenKind")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| "CEM tree writer-token node missing `tokenKind`".to_owned())?;
        token_fields.insert("kind".to_owned(), Value::String(token_kind.to_owned()));
    }
    token_fields.remove("writerKind");
    token_fields.remove("writerNode");
    token_fields.remove("tokenKind");
    let token: TransformTemplateWriterToken =
        serde_json::from_value(Value::Object(token_fields))
            .map_err(|error| format!("CEM tree writer-token node is invalid: {error}"))?;
    let Some(token_text) = token.text.as_deref() else {
        return Err("CEM tree writer-token node has no text".to_owned());
    };
    if token_text.is_empty() {
        return Ok(());
    }
    let rendered_token_text = transform_template_writer_token_rendered_text(
        token_text,
        &token,
        rendered.writer_token_color_profile.as_ref(),
    );
    if let Some(output_span) = &token.output_span {
        let mut generated_span = output_span.clone();
        generated_span.output_range =
            ByteRange::new(rendered.text.len() as u64, rendered_token_text.len() as u32);
        rendered.output_spans.push(generated_span);
        rendered.push_unmapped(&rendered_token_text);
        return Ok(());
    }
    rendered.push_unmapped(&rendered_token_text);
    Ok(())
}

fn transform_template_render_cem_tree_markup_node(
    fields: &serde_json::Map<String, Value>,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let kind = fields
        .get("kind")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("element");
    let source_map = transform_template_cem_tree_node_source_map(fields);
    match kind {
        "text" | "content" | "string" => {
            let text = match syntax {
                TransformTemplateCemTreeWriterSyntax::Html => transform_template_encode_html_text(
                    transform_template_cem_tree_node_data(fields),
                ),
                TransformTemplateCemTreeWriterSyntax::Xml => transform_template_encode_xml_text(
                    transform_template_cem_tree_node_data(fields),
                ),
                TransformTemplateCemTreeWriterSyntax::Cem
                | TransformTemplateCemTreeWriterSyntax::Markdown => unreachable!(),
            };
            rendered.push_mapped(&text, source_map.as_ref());
            Ok(())
        }
        "whitespace" => {
            rendered.push_mapped(
                transform_template_cem_tree_node_data(fields),
                source_map.as_ref(),
            );
            Ok(())
        }
        "comment" => {
            let text = format!("<!--{}-->", transform_template_cem_tree_node_data(fields));
            rendered.push_mapped(&text, source_map.as_ref());
            Ok(())
        }
        "cdata" if syntax == TransformTemplateCemTreeWriterSyntax::Xml => {
            let text = format!(
                "<![CDATA[{}]]>",
                transform_template_cem_tree_node_data(fields)
            );
            rendered.push_mapped(&text, source_map.as_ref());
            Ok(())
        }
        "processing-instruction"
            if transform_template_cem_tree_processing_instruction_target(fields)
                .is_some_and(|target| target.eq_ignore_ascii_case("DOCTYPE")) =>
        {
            let data = transform_template_cem_tree_node_data(fields).trim();
            let text = if data.is_empty() {
                "<!DOCTYPE>".to_owned()
            } else {
                format!("<!DOCTYPE {data}>")
            };
            rendered.push_mapped(&text, source_map.as_ref());
            Ok(())
        }
        "processing-instruction" if syntax == TransformTemplateCemTreeWriterSyntax::Xml => {
            let target = transform_template_cem_tree_processing_instruction_target(fields)
                .ok_or_else(|| "XML processing-instruction node missing target".to_owned())?;
            let data = transform_template_cem_tree_node_data(fields);
            let text = if data.is_empty() {
                format!("<?{target}?>")
            } else {
                format!("<?{target} {data}?>")
            };
            rendered.push_mapped(&text, source_map.as_ref());
            Ok(())
        }
        "raw-text" if syntax == TransformTemplateCemTreeWriterSyntax::Html => {
            rendered.push_mapped(
                transform_template_cem_tree_node_data(fields),
                source_map.as_ref(),
            );
            Ok(())
        }
        "attribute" | "attr" => Ok(()),
        _ => transform_template_render_cem_tree_markup_element(fields, syntax, rendered),
    }
}

fn transform_template_render_cem_tree_markup_element(
    fields: &serde_json::Map<String, Value>,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let name = transform_template_cem_tree_markup_name(fields)?;
    let node_source_map = transform_template_cem_tree_node_source_map(fields);
    let writer_source_map = transform_template_cem_tree_color_wrapper_source_map(fields)
        .or_else(|| transform_template_cem_tree_writer_attribute_nodes_source_map(fields));
    let tag_source_map = writer_source_map.as_ref().or(node_source_map.as_ref());

    rendered.push_mapped("<", tag_source_map);
    rendered.push_mapped(&name, tag_source_map);
    for (name, value, source_map) in
        transform_template_cem_tree_markup_attribute_entries_with_source(fields)?
    {
        let text = format!(
            " {}",
            transform_template_cem_tree_markup_attribute_pair_to_text(&name, &value, syntax)?
        );
        rendered.push_mapped(&text, source_map.as_ref().or(tag_source_map));
    }
    if syntax == TransformTemplateCemTreeWriterSyntax::Html
        && transform_template_cem_tree_markup_name_is_html_void(&name)
    {
        rendered.push_mapped(">", tag_source_map);
        return Ok(());
    }
    if syntax == TransformTemplateCemTreeWriterSyntax::Xml
        && !transform_template_cem_tree_has_children(fields)
    {
        rendered.push_mapped("/>", tag_source_map);
        return Ok(());
    }
    rendered.push_mapped(">", tag_source_map);
    transform_template_render_cem_tree_children(fields, syntax, rendered)?;
    rendered.push_mapped("</", tag_source_map);
    rendered.push_mapped(&name, tag_source_map);
    rendered.push_mapped(">", tag_source_map);
    Ok(())
}

fn transform_template_render_cem_tree_element(
    fields: &serde_json::Map<String, Value>,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let name = match transform_template_cem_tree_name(fields) {
        Some("") => String::new(),
        Some("$") => "$".to_owned(),
        Some(raw_name) => transform_template_encode_cem_name(raw_name)?,
        None => "node".to_owned(),
    };
    let node_source_map = transform_template_cem_tree_node_source_map(fields);
    let writer_source_map = transform_template_cem_tree_color_wrapper_source_map(fields)
        .or_else(|| transform_template_cem_tree_writer_attribute_nodes_source_map(fields));
    let tag_source_map = writer_source_map.as_ref().or(node_source_map.as_ref());
    let color_role = transform_template_cem_tree_render_color_role(fields);
    let attributes =
        transform_template_cem_tree_attributes_to_text_entries(fields.get("attributes"))?;
    let has_children = transform_template_cem_tree_has_children(fields);

    rendered.push_colored_mapped("{", tag_source_map, color_role.as_deref());
    rendered.push_colored_mapped(&name, tag_source_map, color_role.as_deref());
    if !attributes.is_empty() {
        for (index, attribute) in attributes.iter().enumerate() {
            if let Some(format_before) = attribute.format_before.as_ref() {
                transform_template_render_cem_tree_format_value(format_before, rendered)?;
            } else if index == 0 {
                if !name.is_empty() {
                    if let Some(format_before_attributes) = fields.get("formatBeforeAttributes") {
                        transform_template_render_cem_tree_format_value(
                            format_before_attributes,
                            rendered,
                        )?;
                    } else {
                        rendered.push_mapped(" ", tag_source_map);
                    }
                }
            } else {
                if let Some(format_between_attributes) = fields.get("formatBetweenAttributes") {
                    transform_template_render_cem_tree_format_value(
                        format_between_attributes,
                        rendered,
                    )?;
                } else {
                    rendered.push_mapped(" ", tag_source_map);
                }
            }
            rendered.push_colored_mapped(
                &attribute.text,
                attribute.source_map.as_ref().or(tag_source_map),
                attribute.color_role.as_deref().or(Some("syntax.attribute")),
            );
        }
    }
    if has_children {
        if let Some(format_content_boundary) = fields.get("formatContentBoundary") {
            transform_template_render_cem_tree_format_value(format_content_boundary, rendered)?;
        } else {
            rendered.push_mapped(" | ", tag_source_map);
        }
        transform_template_render_cem_tree_children(fields, syntax, rendered)?;
        if let Some(format_before_close) = fields.get("formatBeforeClose") {
            transform_template_render_cem_tree_format_value(format_before_close, rendered)?;
        }
    }
    rendered.push_colored_mapped("}", tag_source_map, color_role.as_deref());
    Ok(())
}

fn transform_template_render_cem_tree_directive(
    fields: &serde_json::Map<String, Value>,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let raw_name = transform_template_cem_tree_name(fields)
        .ok_or_else(|| "CEM directive node missing name".to_owned())?;
    let name = raw_name.strip_prefix('@').unwrap_or(raw_name).trim();
    let name = transform_template_encode_cem_name(name)?;
    let source_map = transform_template_cem_tree_node_source_map(fields);
    let color_role = transform_template_cem_tree_render_color_role(fields);
    rendered.push_colored_mapped("@", source_map.as_ref(), color_role.as_deref());
    rendered.push_colored_mapped(&name, source_map.as_ref(), color_role.as_deref());
    let body = transform_template_cem_tree_directive_body(fields);
    if !body.is_empty() {
        rendered.push_mapped(" ", source_map.as_ref());
        rendered.push_colored_mapped(&body, source_map.as_ref(), color_role.as_deref());
    }
    Ok(())
}

fn transform_template_cem_tree_name<'a>(
    fields: &'a serde_json::Map<String, Value>,
) -> Option<&'a str> {
    fields
        .get("name")
        .or_else(|| fields.get("localName"))
        .or_else(|| fields.get("tag"))
        .or_else(|| fields.get("tagName"))
        .and_then(Value::as_str)
        .map(str::trim)
}

fn transform_template_cem_tree_directive_body(fields: &serde_json::Map<String, Value>) -> String {
    let mut parts = Vec::new();
    if let Some(children) = fields
        .get("children")
        .or_else(|| fields.get("nodes"))
        .or_else(|| fields.get("slots"))
    {
        transform_template_collect_cem_tree_directive_text(children, &mut parts);
    }
    parts.join(" ")
}

fn transform_template_collect_cem_tree_directive_text(value: &Value, parts: &mut Vec<String>) {
    match value {
        Value::Array(items) => {
            for item in items {
                transform_template_collect_cem_tree_directive_text(item, parts);
            }
        }
        Value::Object(fields) => {
            let kind = fields
                .get("kind")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or("element");
            match kind {
                "text" | "content" | "string" | "raw" | "raw-text" => {
                    let text = transform_template_cem_tree_node_data(fields).trim();
                    if !text.is_empty() {
                        parts.push(text.to_owned());
                    }
                }
                "whitespace" => {}
                _ => {
                    if let Some(children) = fields
                        .get("children")
                        .or_else(|| fields.get("nodes"))
                        .or_else(|| fields.get("slots"))
                    {
                        transform_template_collect_cem_tree_directive_text(children, parts);
                    }
                }
            }
        }
        Value::String(text) => {
            let text = text.trim();
            if !text.is_empty() {
                parts.push(text.to_owned());
            }
        }
        _ => {}
    }
}

fn transform_template_render_cem_tree_children(
    fields: &serde_json::Map<String, Value>,
    syntax: TransformTemplateCemTreeWriterSyntax,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    let Some(children) = fields
        .get("children")
        .or_else(|| fields.get("nodes"))
        .or_else(|| fields.get("slots"))
    else {
        return Ok(());
    };
    match children {
        Value::Array(items) => {
            for (index, child) in items.iter().enumerate() {
                if index > 0
                    && syntax.is_cem_like()
                    && !transform_template_cem_tree_value_is_whitespace(&items[index - 1])
                    && !transform_template_cem_tree_value_is_whitespace(child)
                {
                    rendered.push_unmapped(" ");
                }
                transform_template_render_cem_tree_node(child, syntax, rendered)?;
            }
            Ok(())
        }
        Value::Object(_) | Value::String(_) => {
            transform_template_render_cem_tree_node(children, syntax, rendered)
        }
        other => Err(format!(
            "CEM tree writer expected children array, object, or string, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_render_cem_tree_format_value(
    value: &Value,
    rendered: &mut TransformTemplateCemTreeRenderedText,
) -> Result<(), String> {
    match value {
        Value::Array(items) => {
            for item in items {
                transform_template_render_cem_tree_format_value(item, rendered)?;
            }
            Ok(())
        }
        Value::String(text) => {
            rendered.push_unmapped(text);
            Ok(())
        }
        Value::Object(fields) => {
            let kind = fields
                .get("kind")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            let source_map = transform_template_cem_tree_node_source_map(fields);
            match kind {
                "whitespace" | "raw" | "format-token" => {
                    rendered.push_mapped(
                        transform_template_cem_tree_node_data(fields),
                        source_map.as_ref(),
                    );
                    Ok(())
                }
                _ => Err(format!(
                    "CEM tree formatter fragment expected whitespace, raw, or format-token node, got `{kind}`"
                )),
            }
        }
        other => Err(format!(
            "CEM tree formatter fragment expected array, object, or string, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_cem_tree_attribute_count(attributes: Option<&Value>) -> usize {
    match attributes {
        Some(Value::Array(items)) => items.len(),
        Some(Value::Object(map)) => map.len(),
        _ => 0,
    }
}

fn transform_template_cem_tree_has_children(fields: &serde_json::Map<String, Value>) -> bool {
    match fields
        .get("children")
        .or_else(|| fields.get("nodes"))
        .or_else(|| fields.get("slots"))
    {
        Some(Value::Array(items)) => !items.is_empty(),
        Some(Value::Object(_)) | Some(Value::String(_)) => true,
        _ => false,
    }
}

fn transform_template_cem_tree_writer_attribute_nodes_source_map(
    fields: &serde_json::Map<String, Value>,
) -> Option<SourceMapStack> {
    fields
        .get("writerAttributeNodes")
        .and_then(transform_template_first_cem_tree_source_map)
}

fn transform_template_cem_tree_color_wrapper_source_map(
    fields: &serde_json::Map<String, Value>,
) -> Option<SourceMapStack> {
    fields
        .get("colorWrapperNodes")
        .and_then(transform_template_first_cem_tree_source_map)
}

fn transform_template_cem_tree_markup_attribute_entries_with_source(
    fields: &serde_json::Map<String, Value>,
) -> Result<Vec<(String, Value, Option<SourceMapStack>)>, String> {
    let mut entries =
        transform_template_cem_tree_markup_attribute_entries(fields.get("attributes"))?
            .into_iter()
            .map(|(name, value)| {
                (
                    name,
                    value,
                    transform_template_cem_tree_node_source_map(fields),
                )
            })
            .collect::<Vec<_>>();
    let writer_attribute_nodes =
        transform_template_cem_tree_writer_attribute_node_entries_with_source(fields)?;
    for (name, value, source_map) in writer_attribute_nodes {
        transform_template_merge_cem_tree_markup_attribute_with_source(
            &mut entries,
            name,
            value,
            source_map,
        );
    }
    Ok(entries)
}

fn transform_template_cem_tree_writer_attribute_node_entries_with_source(
    fields: &serde_json::Map<String, Value>,
) -> Result<Vec<(String, Value, Option<SourceMapStack>)>, String> {
    let Some(writer_attribute_nodes) = fields.get("writerAttributeNodes") else {
        return Ok(Vec::new());
    };
    let items = writer_attribute_nodes.as_array().ok_or_else(|| {
        format!(
            "CEM tree writer expected `writerAttributeNodes` array, got {}",
            json_value_type_name(writer_attribute_nodes)
        )
    })?;
    items
        .iter()
        .map(|item| {
            let fields = item.as_object().ok_or_else(|| {
                format!(
                    "CEM tree writer expected writerAttributeNodes item object, got {}",
                    json_value_type_name(item)
                )
            })?;
            let (name, value) = transform_template_cem_tree_markup_attribute_entry(fields)?;
            Ok((
                name,
                value,
                transform_template_cem_tree_node_source_map(fields),
            ))
        })
        .collect()
}

fn transform_template_merge_cem_tree_markup_attribute_with_source(
    entries: &mut Vec<(String, Value, Option<SourceMapStack>)>,
    name: String,
    value: Value,
    source_map: Option<SourceMapStack>,
) {
    let Some((_, existing, existing_source_map)) = entries
        .iter_mut()
        .find(|(candidate, _, _)| candidate == &name)
    else {
        entries.push((name, value, source_map));
        return;
    };

    match (name.as_str(), existing, value) {
        ("class", Value::String(existing), Value::String(generated)) => {
            transform_template_merge_space_separated_attribute(existing, &generated);
        }
        ("style", Value::String(existing), Value::String(generated)) => {
            transform_template_merge_css_declarations(existing, &generated);
        }
        (_, existing, value) => {
            *existing = value;
        }
    }
    if source_map.is_some() {
        *existing_source_map = source_map;
    }
}

fn transform_template_cem_tree_writer_syntax(
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> TransformTemplateCemTreeWriterSyntax {
    let content_type = content_type_essence(&writer_boundary_context.content_type);
    let schema = writer_boundary_context.schema.trim();
    let category = writer_boundary_context
        .category
        .as_deref()
        .map(str::trim)
        .unwrap_or_default();
    if content_type == HTML_CONTENT_TYPE || schema == HTML_SCHEMA_URI {
        TransformTemplateCemTreeWriterSyntax::Html
    } else if content_type == MARKDOWN_CONTENT_TYPE
        || schema == MARKDOWN_SCHEMA_URI
        || category.starts_with("markdown-")
    {
        TransformTemplateCemTreeWriterSyntax::Markdown
    } else if matches!(
        content_type.as_str(),
        XML_CONTENT_TYPE | XHTML_CONTENT_TYPE | SVG_CONTENT_TYPE | MATHML_CONTENT_TYPE
    ) || matches!(
        schema,
        XML_SCHEMA_URI | XHTML_SCHEMA_URI | SVG_SCHEMA_URI | MATHML_SCHEMA_URI
    ) {
        TransformTemplateCemTreeWriterSyntax::Xml
    } else {
        TransformTemplateCemTreeWriterSyntax::Cem
    }
}

fn transform_template_cem_tree_writer_terminal_color_profile(
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
    syntax: TransformTemplateCemTreeWriterSyntax,
) -> Option<TransformTemplateColorOutputProfile> {
    if syntax != TransformTemplateCemTreeWriterSyntax::Cem {
        return None;
    }
    if let Some(output_color_type) =
        trimmed_optional_str(writer_boundary_context.output_color_type.as_deref())
    {
        let selection = parse_transform_template_output_color_type(output_color_type).ok()?;
        if selection.target.category != "terminal-color" || selection.output_color_type == "none" {
            return None;
        }
        let profile = TransformTemplateColorOutputProfile::terminal_from_selector(
            &selection.output_color_type,
        )
        .ok()?;
        return (!profile.no_color
            && profile.output == TransformTemplateColorOutputKind::Terminal
            && profile.terminal_capability != TransformTemplateTerminalColorCapability::None)
            .then_some(profile);
    }
    if trimmed_value_string_field(value, "colorOutput").is_some_and(|output| output != "terminal") {
        return None;
    }
    let selector = trimmed_optional_str(writer_boundary_context.color_capability.as_deref())
        .or_else(|| trimmed_value_string_field(value, "colorCapability"))
        .or_else(|| trimmed_optional_str(writer_boundary_context.color_profile.as_deref()))
        .or_else(|| trimmed_value_string_field(value, "colorProfile"))?;
    let profile = TransformTemplateColorOutputProfile::terminal_from_selector(selector).ok()?;
    (!profile.no_color
        && profile.output == TransformTemplateColorOutputKind::Terminal
        && profile.terminal_capability != TransformTemplateTerminalColorCapability::None)
        .then_some(profile)
}

fn transform_template_cem_tree_writer_markdown_color_profile(
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
    syntax: TransformTemplateCemTreeWriterSyntax,
) -> Option<TransformTemplateColorOutputProfile> {
    if syntax != TransformTemplateCemTreeWriterSyntax::Markdown {
        return None;
    }
    let root_color_output = trimmed_value_string_field(value, "colorOutput");
    if root_color_output.is_some_and(|output| !matches!(output, "md" | "markdown")) {
        return None;
    }
    let selector_is_markdown =
        trimmed_optional_str(writer_boundary_context.color_profile.as_deref())
            .or_else(|| trimmed_value_string_field(value, "colorProfile"))
            .is_some_and(|selector| matches!(selector, "md" | "markdown"));
    if selector_is_markdown
        || root_color_output.is_some_and(|output| matches!(output, "md" | "markdown"))
    {
        Some(TransformTemplateColorOutputProfile::plain())
    } else {
        None
    }
}

fn transform_template_cem_tree_writer_token_color_profile(
    value: &Value,
    writer_boundary_context: &TransformTemplateEncodedArtifactInsertionContext,
) -> Option<TransformTemplateWriterTokenColorProfile> {
    let mut identity = TransformTemplateEncodedArtifactIdentity::new(
        TransformTemplateOutputProducedKind::CemTree,
        TransformTemplateEncodingTarget::new(
            writer_boundary_context.content_type.clone(),
            writer_boundary_context.schema.clone(),
            writer_boundary_context
                .category
                .clone()
                .unwrap_or_else(|| "cem-tree".to_owned()),
        ),
    );
    identity.color_profile = writer_boundary_context.color_profile.clone();
    identity.color_capability = writer_boundary_context.color_capability.clone();
    transform_template_writer_token_color_profile(
        value,
        &identity,
        writer_boundary_context.output_color_type.as_deref(),
    )
}

fn transform_template_markdown_color_span_open(role: &str) -> String {
    let class_role = transform_template_color_role_class(role);
    let role = transform_template_encode_html_attribute(role);
    format!(r#"<span class="cem-color cem-color-{class_role}" data-role="{role}">"#)
}

fn transform_template_cem_tree_render_color_role(
    fields: &serde_json::Map<String, Value>,
) -> Option<String> {
    fields
        .get("colorRole")
        .or_else(|| {
            fields
                .get("style")
                .and_then(Value::as_object)
                .and_then(|style| style.get("colorRole"))
        })
        .and_then(Value::as_str)
        .map(transform_template_canonical_color_role)
        .filter(|role| transform_template_is_color_role(role))
}

fn transform_template_cem_tree_markup_name(
    fields: &serde_json::Map<String, Value>,
) -> Result<String, String> {
    let local_name = fields
        .get("name")
        .or_else(|| fields.get("localName"))
        .or_else(|| fields.get("tag"))
        .or_else(|| fields.get("tagName"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "CEM tree element missing markup name".to_owned())?;
    let namespace = fields
        .get("namespace")
        .or_else(|| fields.get("prefix"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    Ok(namespace
        .map(|namespace| format!("{namespace}:{local_name}"))
        .unwrap_or_else(|| local_name.to_owned()))
}

fn transform_template_cem_tree_markup_name_is_html_void(name: &str) -> bool {
    !name.contains(':')
        && HTML_VOID_ELEMENTS
            .iter()
            .any(|void_name| void_name.eq_ignore_ascii_case(name))
}

fn transform_template_cem_tree_markup_name_is_html_boolean_attribute(name: &str) -> bool {
    !name.contains(':')
        && HTML_BOOLEAN_ATTRIBUTES
            .iter()
            .any(|boolean_name| boolean_name.eq_ignore_ascii_case(name))
}

fn transform_template_cem_tree_processing_instruction_target<'a>(
    fields: &'a serde_json::Map<String, Value>,
) -> Option<&'a str> {
    fields
        .get("target")
        .or_else(|| fields.get("name"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|target| !target.is_empty())
}

struct TransformTemplateCemTreeTextEntry {
    text: String,
    source_map: Option<SourceMapStack>,
    color_role: Option<String>,
    format_before: Option<Value>,
}

fn transform_template_cem_tree_attributes_to_text_entries(
    attributes: Option<&Value>,
) -> Result<Vec<TransformTemplateCemTreeTextEntry>, String> {
    let Some(attributes) = attributes else {
        return Ok(Vec::new());
    };
    match attributes {
        Value::Array(items) => items
            .iter()
            .map(|item| {
                let fields = item.as_object().ok_or_else(|| {
                    format!(
                        "CEM tree writer expected attribute object, got {}",
                        json_value_type_name(item)
                    )
                })?;
                Ok(TransformTemplateCemTreeTextEntry {
                    text: transform_template_cem_tree_attribute_to_text(fields)?,
                    source_map: transform_template_cem_tree_node_source_map(fields),
                    color_role: transform_template_cem_tree_render_color_role(fields)
                        .or_else(|| Some("syntax.attribute".to_owned())),
                    format_before: fields
                        .get("formatBefore")
                        .or_else(|| fields.get("formatBeforeAttribute"))
                        .cloned(),
                })
            })
            .collect(),
        Value::Object(map) => {
            let mut keys = map.keys().collect::<Vec<_>>();
            keys.sort();
            keys.into_iter()
                .map(|key| {
                    Ok(TransformTemplateCemTreeTextEntry {
                        text: transform_template_cem_tree_attribute_pair_to_text(
                            key,
                            map.get(key).unwrap(),
                        )?,
                        source_map: None,
                        color_role: Some("syntax.attribute".to_owned()),
                        format_before: None,
                    })
                })
                .collect()
        }
        other => Err(format!(
            "CEM tree writer expected `attributes` array or object, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_cem_tree_node_data(fields: &serde_json::Map<String, Value>) -> &str {
    fields
        .get("value")
        .or_else(|| fields.get("text"))
        .or_else(|| fields.get("data"))
        .and_then(Value::as_str)
        .unwrap_or_default()
}

fn transform_template_cem_tree_markup_attribute_entries(
    attributes: Option<&Value>,
) -> Result<Vec<(String, Value)>, String> {
    let Some(attributes) = attributes else {
        return Ok(Vec::new());
    };
    match attributes {
        Value::Array(items) => items
            .iter()
            .map(|item| {
                item.as_object()
                    .ok_or_else(|| {
                        format!(
                            "CEM tree writer expected attribute object, got {}",
                            json_value_type_name(item)
                        )
                    })
                    .and_then(transform_template_cem_tree_markup_attribute_entry)
            })
            .collect(),
        Value::Object(map) => {
            let mut keys = map.keys().collect::<Vec<_>>();
            keys.sort();
            keys.into_iter()
                .map(|key| Ok((key.to_owned(), map.get(key).unwrap().clone())))
                .collect()
        }
        other => Err(format!(
            "CEM tree writer expected `attributes` array or object, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_cem_tree_markup_attribute_entry(
    fields: &serde_json::Map<String, Value>,
) -> Result<(String, Value), String> {
    let name = transform_template_cem_tree_markup_name(fields)?;
    let value = fields
        .get("value")
        .or_else(|| fields.get("text"))
        .or_else(|| fields.get("data"));
    Ok((name, value.cloned().unwrap_or(Value::Null)))
}

fn transform_template_cem_tree_markup_attribute_pair_to_text(
    name: &str,
    value: &Value,
    syntax: TransformTemplateCemTreeWriterSyntax,
) -> Result<String, String> {
    match (syntax, value) {
        (TransformTemplateCemTreeWriterSyntax::Html, Value::Null)
        | (TransformTemplateCemTreeWriterSyntax::Html, Value::Bool(true)) => Ok(name.to_owned()),
        (TransformTemplateCemTreeWriterSyntax::Html, Value::String(text))
            if transform_template_cem_tree_markup_name_is_html_boolean_attribute(name)
                && (text.is_empty() || text.eq_ignore_ascii_case(name)) =>
        {
            Ok(name.to_owned())
        }
        _ => {
            let value = transform_template_cem_tree_markup_attribute_value(value)?;
            Ok(format!(
                "{name}=\"{}\"",
                match syntax {
                    TransformTemplateCemTreeWriterSyntax::Html => {
                        transform_template_encode_html_attribute(&value)
                    }
                    TransformTemplateCemTreeWriterSyntax::Xml => {
                        transform_template_encode_xml_attribute(&value)
                    }
                    TransformTemplateCemTreeWriterSyntax::Cem
                    | TransformTemplateCemTreeWriterSyntax::Markdown => unreachable!(),
                }
            ))
        }
    }
}

fn transform_template_cem_tree_markup_attribute_value(value: &Value) -> Result<String, String> {
    match value {
        Value::Null => Ok(String::new()),
        Value::String(text) => Ok(text.clone()),
        Value::Bool(value) => Ok(value.to_string()),
        Value::Number(value) => Ok(value.to_string()),
        other => Err(format!(
            "CEM tree writer expected scalar markup attribute value, got {}",
            json_value_type_name(other)
        )),
    }
}

fn transform_template_cem_tree_attribute_to_text(
    fields: &serde_json::Map<String, Value>,
) -> Result<String, String> {
    let name = fields
        .get("name")
        .or_else(|| fields.get("localName"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "CEM tree attribute missing non-empty `name`".to_owned())?;
    let Some(value) = fields.get("value").or_else(|| fields.get("text")) else {
        let name = transform_template_encode_cem_name(name)?;
        return Ok(format!("@{name}"));
    };
    transform_template_cem_tree_attribute_pair_to_text(name, value)
}

fn transform_template_cem_tree_attribute_pair_to_text(
    name: &str,
    value: &Value,
) -> Result<String, String> {
    let name = transform_template_encode_cem_name(name)?;
    if value.as_bool() == Some(true) || value.is_null() {
        return Ok(format!("@{name}"));
    }
    let value = transform_template_cem_tree_scalar_to_attribute_value(value)?;
    Ok(format!("@{name}={value}"))
}

fn transform_template_cem_tree_scalar_to_attribute_value(value: &Value) -> Result<String, String> {
    let text = match value {
        Value::String(text) => text.clone(),
        Value::Bool(value) => value.to_string(),
        Value::Number(value) => value.to_string(),
        other => {
            return Err(format!(
                "CEM tree writer expected scalar attribute value, got {}",
                json_value_type_name(other)
            ))
        }
    };
    transform_template_encode_cem_attribute_value(&text, "CEM tree attribute value")
}

fn shift_output_span(span: &OutputSpan, offset: u64) -> OutputSpan {
    let mut shifted = span.clone();
    shifted.output_range = ByteRange::new(span.output_range.start + offset, span.output_range.len);
    shifted
}

fn diagnostics_for_evaluated_encode_error(
    error: TransformTemplateEncodedArtifactError,
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
    uri: Option<&str>,
) -> Vec<Diagnostic> {
    let mut diagnostic = error.diagnostic(uri);
    attach_evaluated_encode_node(&mut diagnostic, evaluated);
    if !error.is_incompatible_insertion() {
        return vec![diagnostic];
    }

    let mut insertion_diagnostic = error.incompatible_insertion_diagnostic(uri);
    attach_evaluated_encode_node(&mut insertion_diagnostic, evaluated);
    vec![diagnostic, insertion_diagnostic]
}

fn diagnostic_for_evaluated_encode_value_type(
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
    uri: Option<&str>,
) -> Diagnostic {
    let mut diagnostic = Diagnostic {
        uri: uri.map(str::to_owned),
        code: TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE.to_owned(),
        severity: Severity::Error,
        message: format!(
            "encoded text artifact expected string value, got {}",
            json_value_type_name(&evaluated.artifact.value)
        ),
        details: None,
        ..Diagnostic::default()
    };
    attach_evaluated_encode_node(&mut diagnostic, evaluated);
    diagnostic
}

fn diagnostic_for_evaluated_encode_writer_adapter_missing(
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
    expected: TransformTemplateOutputProducedKind,
    uri: Option<&str>,
) -> Diagnostic {
    let actual = evaluated.artifact.identity.produces;
    let mut diagnostic = Diagnostic {
        uri: uri.map(str::to_owned),
        code: TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_WRITER_ADAPTER_MISSING_CODE.to_owned(),
        severity: Severity::Error,
        message: format!(
            "encoded artifact produced `{}` requires a writer adapter before insertion into `{}` output",
            actual.as_str(),
            expected.as_str()
        ),
        details: None,
        ..Diagnostic::default()
    };
    attach_evaluated_encode_node(&mut diagnostic, evaluated);
    diagnostic
}

fn diagnostic_for_evaluated_encode_writer_adapter_failed(
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
    message: String,
    uri: Option<&str>,
) -> Diagnostic {
    let mut diagnostic = Diagnostic {
        uri: uri.map(str::to_owned),
        code: TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_WRITER_ADAPTER_FAILED_CODE.to_owned(),
        severity: Severity::Error,
        message: format!(
            "encoded artifact produced `{}` cannot use the default writer adapter: {message}",
            evaluated.artifact.identity.produces.as_str()
        ),
        details: None,
        ..Diagnostic::default()
    };
    attach_evaluated_encode_node(&mut diagnostic, evaluated);
    diagnostic
}

fn attach_evaluated_encode_node(
    diagnostic: &mut Diagnostic,
    evaluated: &TransformTemplateEvaluatedEncodeExpression,
) {
    diagnostic.node = evaluated.expression.owner.clone();
    if diagnostic.node.is_none() {
        diagnostic.node = Some(evaluated.expression.expression.clone());
    }
}

fn json_value_type_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

pub fn evaluate_transform_template_encode_expressions<F>(
    expressions: &[TransformTemplateEncodeExpression],
    context: TransformTemplateEncodeEvaluationContext<'_>,
    mut encode_impl: F,
) -> TransformTemplateEncodeEvaluationResponse
where
    F: FnMut(&TransformTemplateEncodeBinding, &Value) -> Result<Value, String>,
{
    let mut encoded = Vec::new();
    let mut diagnostics = Vec::new();

    for expression in expressions {
        let Some(subject) =
            resolve_encode_subject_expression(&expression.subject, context.value_bindings)
        else {
            diagnostics.push(Diagnostic {
                uri: context.uri.map(str::to_owned),
                code: TRANSFORM_TEMPLATE_ENCODE_SUBJECT_UNRESOLVED_CODE.to_owned(),
                severity: Severity::Error,
                message: format!(
                    "CEMT encode subject expression `{}` could not be resolved",
                    expression.subject
                ),
                details: None,
                ..Diagnostic::default()
            });
            continue;
        };

        let mut request = expression.binding_request(subject.clone());
        if let Err(diagnostic) = resolve_encode_request_runtime_values(
            &mut request,
            context.value_bindings,
            context.uri,
            expression,
        ) {
            diagnostics.push(diagnostic);
            continue;
        }
        let format_first = request.requires_format_binding();
        if !format_first && request.requires_color_binding() {
            if let Some(output_color_type) = context.output_color_type {
                match parse_transform_template_output_color_type(output_color_type) {
                    Ok(selection) => selection.apply_to_request(&mut request),
                    Err(message) => {
                        diagnostics.push(Diagnostic {
                            uri: context.uri.map(str::to_owned),
                            code: TRANSFORM_TEMPLATE_COLOR_PROFILE_INVALID_CODE.to_owned(),
                            severity: Severity::Error,
                            message,
                            ..Diagnostic::default()
                        });
                        continue;
                    }
                }
            }
        }

        if format_first {
            let format_binding = match context
                .registry
                .resolve_format_binding(&request, context.host_capabilities)
            {
                Ok(binding) => binding,
                Err(error) => {
                    diagnostics.push(error.diagnostic(context.uri));
                    continue;
                }
            };
            let formatted_output = match execute_transform_template_encode_binding(
                &format_binding,
                &subject,
                &context,
                &mut encode_impl,
            ) {
                Ok(value) => value,
                Err(message) => {
                    diagnostics.push(Diagnostic {
                        uri: context.uri.map(str::to_owned),
                        code: TRANSFORM_TEMPLATE_ENCODE_IMPLEMENTATION_FAILED_CODE.to_owned(),
                        severity: Severity::Error,
                        message: format!(
                            "CEMT output function `{}` failed for expression `{}`: {message}",
                            format_binding.function.name, expression.expression
                        ),
                        details: None,
                        ..Diagnostic::default()
                    });
                    continue;
                }
            };
            let mut binding = format_binding;
            let mut artifact = binding.artifact_from_value(formatted_output);

            if request.requires_color_binding()
                || transform_template_encode_options_request_color(&request.options)
            {
                let color_request = TransformTemplateEncodeBindingRequest {
                    subject: artifact.value.clone(),
                    owner: request.owner.clone(),
                    subject_type: Some("cem-tree".to_owned()),
                    target: request.target.clone(),
                    options: request.options.clone(),
                };
                let mut color_request = color_request;
                if let Some(output_color_type) = context.output_color_type {
                    match parse_transform_template_output_color_type(output_color_type) {
                        Ok(selection) => {
                            if let Some(color_profile) =
                                transform_template_cem_tree_color_profile_for_output_selection(
                                    &selection,
                                )
                            {
                                color_request.options.color_profile =
                                    Some(color_profile.to_owned());
                            }
                        }
                        Err(message) => {
                            diagnostics.push(Diagnostic {
                                uri: context.uri.map(str::to_owned),
                                code: TRANSFORM_TEMPLATE_COLOR_PROFILE_INVALID_CODE.to_owned(),
                                severity: Severity::Error,
                                message,
                                ..Diagnostic::default()
                            });
                            continue;
                        }
                    }
                }
                let color_binding = match context
                    .registry
                    .resolve_color_binding(&color_request, context.host_capabilities)
                {
                    Ok(binding) => binding.into_encode_binding(),
                    Err(error) => {
                        diagnostics.push(error.diagnostic(context.uri));
                        continue;
                    }
                };
                let colored_output = match execute_transform_template_encode_binding(
                    &color_binding,
                    &artifact.value,
                    &context,
                    &mut encode_impl,
                ) {
                    Ok(value) => value,
                    Err(message) => {
                        diagnostics.push(Diagnostic {
                            uri: context.uri.map(str::to_owned),
                            code: TRANSFORM_TEMPLATE_ENCODE_IMPLEMENTATION_FAILED_CODE.to_owned(),
                            severity: Severity::Error,
                            message: format!(
                                "CEMT output function `{}` failed for expression `{}`: {message}",
                                color_binding.function.name, expression.expression
                            ),
                            details: None,
                            ..Diagnostic::default()
                        });
                        continue;
                    }
                };
                binding = color_binding;
                artifact = binding.artifact_from_value(colored_output);
            }

            encoded.push(TransformTemplateEvaluatedEncodeExpression {
                expression: expression.clone(),
                subject,
                binding,
                artifact,
            });
            continue;
        }

        let binding = if request.requires_color_binding() {
            match context
                .registry
                .resolve_color_binding(&request, context.host_capabilities)
            {
                Ok(binding) => binding.into_encode_binding(),
                Err(error) => {
                    diagnostics.push(error.diagnostic(context.uri));
                    continue;
                }
            }
        } else if request.requires_format_binding() {
            match context
                .registry
                .resolve_format_binding(&request, context.host_capabilities)
            {
                Ok(binding) => binding,
                Err(error) => {
                    diagnostics.push(error.diagnostic(context.uri));
                    continue;
                }
            }
        } else {
            match context
                .registry
                .resolve_encode_binding(&request, context.host_capabilities)
            {
                Ok(binding) => binding,
                Err(error) => {
                    diagnostics.push(error.diagnostic(context.uri));
                    continue;
                }
            }
        };

        let output = match execute_transform_template_encode_binding(
            &binding,
            &subject,
            &context,
            &mut encode_impl,
        ) {
            Ok(value) => value,
            Err(message) => {
                diagnostics.push(Diagnostic {
                    uri: context.uri.map(str::to_owned),
                    code: TRANSFORM_TEMPLATE_ENCODE_IMPLEMENTATION_FAILED_CODE.to_owned(),
                    severity: Severity::Error,
                    message: format!(
                        "CEMT output function `{}` failed for expression `{}`: {message}",
                        binding.function.name, expression.expression
                    ),
                    details: None,
                    ..Diagnostic::default()
                });
                continue;
            }
        };

        let artifact = binding.artifact_from_value(output);
        encoded.push(TransformTemplateEvaluatedEncodeExpression {
            expression: expression.clone(),
            subject,
            binding,
            artifact,
        });
    }

    TransformTemplateEncodeEvaluationResponse {
        encoded,
        diagnostics,
    }
}

pub(crate) fn execute_transform_template_encode_binding<F>(
    binding: &TransformTemplateEncodeBinding,
    subject: &Value,
    context: &TransformTemplateEncodeEvaluationContext<'_>,
    encode_impl: &mut F,
) -> Result<Value, String>
where
    F: FnMut(&TransformTemplateEncodeBinding, &Value) -> Result<Value, String>,
{
    if let Some(result) = execute_transform_template_cemt_body_expression(
        binding,
        subject,
        context.value_bindings,
        &context.registry.runtime_functions,
    ) {
        return result;
    }
    encode_impl(binding, subject)
}

fn execute_transform_template_cemt_body_expression(
    binding: &TransformTemplateEncodeBinding,
    subject: &Value,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
) -> Option<Result<Value, String>> {
    if binding.function.implementation != TransformTemplateOutputFunctionImplementation::Cemt {
        return None;
    }
    let body_expression = binding.function.body_expression.as_deref()?.trim();
    if cemt_expression_starts_with_call(body_expression, "encode") {
        return None;
    }

    let scoped_bindings =
        match cemt_runtime_bind_output_function_params(binding, subject, value_bindings) {
            Ok(scoped_bindings) => scoped_bindings,
            Err(message) => return Some(Err(message)),
        };
    Some(
        resolve_encode_subject_expression_with_binding(
            body_expression,
            &scoped_bindings,
            runtime_functions,
            binding,
        )
        .and_then(|resolved| {
            resolved.ok_or_else(|| {
                format!(
                    "CEMT output function `{}` body expression could not be resolved",
                    binding.function.name
                )
            })
        }),
    )
}

fn cemt_runtime_bind_output_function_params(
    binding: &TransformTemplateEncodeBinding,
    subject: &Value,
    value_bindings: &BTreeMap<String, Value>,
) -> Result<BTreeMap<String, Value>, String> {
    let mut scoped_bindings =
        cemt_runtime_clone_bindings_excluding_names(value_bindings, &["subject"]);
    scoped_bindings.insert("subject".to_owned(), subject.clone());
    cemt_runtime_bind_output_contract_metadata(binding, &mut scoped_bindings);

    for param in &binding.function.params {
        let value = if param.name == "subject" {
            subject.clone()
        } else if let Some(value) = scoped_bindings.get(&param.name) {
            value.clone()
        } else if let Some(value) = param.default_value.clone() {
            value
        } else if param.required {
            return Err(format!(
                "CEMT output function `{}` requires runtime param `{}`",
                binding.function.name, param.name
            ));
        } else {
            continue;
        };

        if !param.value_type.accepts(&value, param.nullable) {
            return Err(format!(
                "CEMT output function `{}` param `{}` expected {}, got {}",
                binding.function.name,
                param.name,
                param.value_type.as_contract_name(),
                json_value_type_name(&value)
            ));
        }
        scoped_bindings.insert(param.name.clone(), value);
    }

    Ok(scoped_bindings)
}

fn cemt_runtime_clone_bindings_excluding_names(
    value_bindings: &BTreeMap<String, Value>,
    excluded_names: &[&str],
) -> BTreeMap<String, Value> {
    if excluded_names.is_empty() {
        return value_bindings.clone();
    }
    value_bindings
        .iter()
        .filter(|(name, _)| {
            !excluded_names
                .iter()
                .any(|excluded| *excluded == name.as_str())
        })
        .map(|(name, value)| (name.clone(), value.clone()))
        .collect()
}

fn cemt_runtime_bind_output_contract_metadata(
    binding: &TransformTemplateEncodeBinding,
    scoped_bindings: &mut BTreeMap<String, Value>,
) {
    scoped_bindings
        .entry("functionName".to_owned())
        .or_insert_with(|| Value::String(binding.function.name.clone()));
    scoped_bindings
        .entry("mode".to_owned())
        .or_insert_with(|| Value::String(binding.identity.mode.as_str().to_owned()));
    scoped_bindings
        .entry("lineEnding".to_owned())
        .or_insert_with(|| {
            Value::String(transform_template_cem_tree_formatter_line_ending(
                &binding.options,
            ))
        });
    scoped_bindings
        .entry("indent".to_owned())
        .or_insert_with(|| {
            Value::String(transform_template_cem_tree_formatter_indent(
                &binding.options,
            ))
        });
    scoped_bindings
        .entry("tabSize".to_owned())
        .or_insert_with(|| {
            Value::Number(serde_json::Number::from(
                transform_template_cem_tree_formatter_tab_size(&binding.options),
            ))
        });
    scoped_bindings
        .entry("ordering".to_owned())
        .or_insert_with(|| {
            Value::String(transform_template_cem_tree_formatter_ordering(
                &binding.options,
            ))
        });
    scoped_bindings
        .entry("wrapColumn".to_owned())
        .or_insert_with(|| {
            Value::String(transform_template_cem_tree_formatter_wrapping(
                &binding.options,
            ))
        });
    if !binding.options.formatter_options.is_empty() {
        scoped_bindings
            .entry("formatterOptions".to_owned())
            .or_insert_with(|| {
                cemt_nested_string_options_value(&binding.options.formatter_options)
            });
    }
    if let Some(function_profile) = binding.function.profile.as_deref() {
        scoped_bindings
            .entry("functionProfile".to_owned())
            .or_insert_with(|| Value::String(function_profile.to_owned()));
    }
    if let Some(formatter_profile) = binding.identity.formatter_profile.as_deref() {
        scoped_bindings
            .entry("formatterProfile".to_owned())
            .or_insert_with(|| Value::String(formatter_profile.to_owned()));
    }
    if let Some(color_profile) = binding.identity.color_profile.as_deref() {
        scoped_bindings
            .entry("colorProfile".to_owned())
            .or_insert_with(|| Value::String(color_profile.to_owned()));
    }
    if let Some(color_capability) = binding.identity.color_capability.as_deref() {
        scoped_bindings
            .entry("colorCapability".to_owned())
            .or_insert_with(|| Value::String(color_capability.to_owned()));
    }
}

fn cemt_nested_string_options_value(options: &BTreeMap<String, String>) -> Value {
    let mut root = serde_json::Map::new();
    for (key, value) in options {
        let mut segments = key
            .split('.')
            .map(str::trim)
            .filter(|segment| !segment.is_empty());
        let Some(first) = segments.next() else {
            continue;
        };
        let mut cursor = &mut root;
        let mut current = first.to_owned();
        for segment in segments {
            let entry = cursor
                .entry(current)
                .or_insert_with(|| Value::Object(serde_json::Map::new()));
            if !entry.is_object() {
                *entry = Value::Object(serde_json::Map::new());
            }
            cursor = entry.as_object_mut().expect("entry is object");
            current = segment.to_owned();
        }
        cursor.insert(current, Value::String(value.clone()));
    }
    Value::Object(root)
}

fn resolve_encode_request_runtime_values(
    request: &mut TransformTemplateEncodeBindingRequest,
    value_bindings: &BTreeMap<String, Value>,
    uri: Option<&str>,
    expression: &TransformTemplateEncodeExpression,
) -> Result<(), Diagnostic> {
    resolve_runtime_string_field(
        &mut request.subject_type,
        "subjectType",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_required_string_field(
        &mut request.target.content_type,
        "contentType",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_required_string_field(
        &mut request.target.schema,
        "schema",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_required_string_field(
        &mut request.target.category,
        "category",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.target.context,
        "context",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.encoder,
        "encoder",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.formatter,
        "formatter",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.colorizer,
        "colorizer",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.profile,
        "profile",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.formatter_profile,
        "formatterProfile",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.color_profile,
        "colorProfile",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.charset,
        "charset",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.line_ending,
        "lineEnding",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.quote_policy,
        "quote",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.ordering,
        "ordering",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.wrap_column,
        "wrapColumn",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.indent,
        "indent",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.tab_size,
        "tabSize",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.namespace_policy,
        "namespacePolicy",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.namespace_placement,
        "namespacePlacement",
        value_bindings,
        uri,
        expression,
    )?;
    resolve_runtime_string_field(
        &mut request.options.binary_framing,
        "binaryFraming",
        value_bindings,
        uri,
        expression,
    )?;
    Ok(())
}

fn resolve_runtime_required_string_field(
    field: &mut String,
    label: &str,
    value_bindings: &BTreeMap<String, Value>,
    uri: Option<&str>,
    expression: &TransformTemplateEncodeExpression,
) -> Result<(), Diagnostic> {
    let resolved = resolve_runtime_string_value(field, label, value_bindings, uri, expression)?;
    *field = resolved;
    Ok(())
}

fn resolve_runtime_string_field(
    field: &mut Option<String>,
    label: &str,
    value_bindings: &BTreeMap<String, Value>,
    uri: Option<&str>,
    expression: &TransformTemplateEncodeExpression,
) -> Result<(), Diagnostic> {
    let Some(value) = field.as_deref() else {
        return Ok(());
    };
    let resolved = resolve_runtime_string_value(value, label, value_bindings, uri, expression)?;
    *field = Some(resolved);
    Ok(())
}

fn resolve_runtime_string_value(
    value: &str,
    label: &str,
    value_bindings: &BTreeMap<String, Value>,
    uri: Option<&str>,
    expression: &TransformTemplateEncodeExpression,
) -> Result<String, Diagnostic> {
    if !cemt_runtime_expression_is_dynamic(value) {
        return Ok(value.to_owned());
    }

    let Some(resolved) = resolve_encode_subject_expression(value, value_bindings) else {
        return Err(encode_runtime_value_diagnostic(
            uri,
            expression,
            format!("CEMT encode `{label}` value `{value}` could not be resolved"),
        ));
    };

    match resolved {
        Value::String(value) => Ok(value),
        Value::Bool(value) => Ok(value.to_string()),
        Value::Number(value) => Ok(value.to_string()),
        Value::Null => Err(encode_runtime_value_diagnostic(
            uri,
            expression,
            format!("CEMT encode `{label}` value `{value}` resolved to null"),
        )),
        Value::Array(_) | Value::Object(_) => Err(encode_runtime_value_diagnostic(
            uri,
            expression,
            format!(
                "CEMT encode `{label}` value `{value}` resolved to {} but requires a scalar string value",
                json_value_type_name(&resolved)
            ),
        )),
    }
}

fn encode_runtime_value_diagnostic(
    uri: Option<&str>,
    expression: &TransformTemplateEncodeExpression,
    message: impl Into<String>,
) -> Diagnostic {
    Diagnostic {
        uri: uri.map(str::to_owned),
        code: TRANSFORM_TEMPLATE_ENCODE_VALUE_UNRESOLVED_CODE.to_owned(),
        severity: Severity::Error,
        message: message.into(),
        node: expression
            .owner
            .clone()
            .or_else(|| Some(expression.expression.clone())),
        details: None,
        ..Diagnostic::default()
    }
}

pub fn transform_template_encode_subject_type_candidates(subject: &Value) -> Vec<String> {
    let mut candidates = Vec::new();
    append_transform_template_semantic_subject_type_candidates(&mut candidates, subject);
    append_transform_template_json_subject_type_candidates(&mut candidates, subject);
    candidates
}

fn append_transform_template_subject_type_candidate(
    candidates: &mut Vec<String>,
    candidate: impl AsRef<str>,
) {
    let candidate = candidate.as_ref().trim();
    if candidate.is_empty() || candidates.iter().any(|existing| existing == candidate) {
        return;
    }
    candidates.push(candidate.to_owned());
}

fn append_transform_template_subject_type_hint(candidates: &mut Vec<String>, value: &str) {
    let normalized = value.trim().replace('_', "-").to_ascii_lowercase();
    if normalized.is_empty() || normalized.chars().any(char::is_control) {
        return;
    }

    match normalized.as_str() {
        "cem-tree" | "cem-output-tree" | "formatted-cem-tree" | "colored-cem-tree" => {
            append_transform_template_subject_type_candidate(candidates, "cem-tree");
        }
        "qname" | "qualified-name" => {
            append_transform_template_subject_type_candidate(candidates, "qualified-name");
            append_transform_template_subject_type_candidate(candidates, "name");
        }
        "localname" | "local-name" => {
            append_transform_template_subject_type_candidate(candidates, "local-name");
            append_transform_template_subject_type_candidate(candidates, "name");
        }
        "namespace" | "namespace-uri" | "namespaceuri" => {
            append_transform_template_subject_type_candidate(candidates, "namespace-uri");
            append_transform_template_subject_type_candidate(candidates, "name");
        }
        "token-stream" | "writer-token-stream" | "tokens" => {
            append_transform_template_subject_type_candidate(candidates, "tokens");
            append_transform_template_subject_type_candidate(candidates, "token-stream");
        }
        "parser-events" | "parse-events" => {
            append_transform_template_subject_type_candidate(candidates, "parser-events");
            append_transform_template_subject_type_candidate(candidates, "event-stream");
            append_transform_template_subject_type_candidate(candidates, "events");
        }
        "transform-events" => {
            append_transform_template_subject_type_candidate(candidates, "transform-events");
            append_transform_template_subject_type_candidate(candidates, "event-stream");
            append_transform_template_subject_type_candidate(candidates, "events");
        }
        "event-stream" | "events" => {
            append_transform_template_subject_type_candidate(candidates, "event-stream");
            append_transform_template_subject_type_candidate(candidates, "events");
        }
        "sealed-binary-chunks" | "sealed-chunks" => {
            append_transform_template_subject_type_candidate(candidates, "sealed-binary-chunks");
            append_transform_template_subject_type_candidate(candidates, "binary-chunks");
            append_transform_template_subject_type_candidate(candidates, "chunks");
            append_transform_template_subject_type_candidate(candidates, "chunk-stream");
        }
        "binary-chunks" => {
            append_transform_template_subject_type_candidate(candidates, "binary-chunks");
            append_transform_template_subject_type_candidate(candidates, "chunks");
            append_transform_template_subject_type_candidate(candidates, "chunk-stream");
        }
        "chunk-stream" | "chunks" => {
            append_transform_template_subject_type_candidate(candidates, "chunks");
            append_transform_template_subject_type_candidate(candidates, "chunk-stream");
        }
        "fragment" | "document-fragment" => {
            append_transform_template_subject_type_candidate(candidates, "fragment");
            append_transform_template_subject_type_candidate(candidates, "document-fragment");
        }
        "attribute" | "attribute-node" => {
            append_transform_template_subject_type_candidate(candidates, "attribute");
        }
        "attributes" | "attribute-list" | "attribute-map" => {
            append_transform_template_subject_type_candidate(candidates, "attributes");
            append_transform_template_subject_type_candidate(candidates, "attribute-list");
        }
        "slot" | "slot-node" => {
            append_transform_template_subject_type_candidate(candidates, "slot");
        }
        "slots" | "slot-list" | "slot-map" => {
            append_transform_template_subject_type_candidate(candidates, "slots");
            append_transform_template_subject_type_candidate(candidates, "slot-list");
        }
        "raw" => append_transform_template_subject_type_candidate(candidates, "raw"),
        "raw-syntax" => {
            append_transform_template_subject_type_candidate(candidates, "raw-syntax");
            append_transform_template_subject_type_candidate(candidates, "raw");
        }
        "raw-html" | "html-raw" | "rawhtml" | "htmlraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "html");
        }
        "raw-xml" | "xml-raw" | "rawxml" | "xmlraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "xml");
        }
        "raw-json" | "json-raw" | "rawjson" | "jsonraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "json");
        }
        "raw-yaml" | "yaml-raw" | "rawyaml" | "yamlraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "yaml");
        }
        "raw-csv" | "csv-raw" | "rawcsv" | "csvraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "csv");
        }
        "raw-markdown" | "markdown-raw" | "rawmarkdown" | "markdownraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "markdown");
        }
        "raw-css" | "css-raw" | "rawcss" | "cssraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "css");
        }
        "raw-text" | "text-raw" | "rawtext" | "textraw" => {
            append_transform_template_raw_subject_type_hint(candidates, "text");
        }
        other if other.starts_with("raw-") => {
            append_transform_template_raw_subject_type_hint(candidates, &other["raw-".len()..]);
        }
        other if other.ends_with("-raw") => {
            append_transform_template_raw_subject_type_hint(
                candidates,
                &other[..other.len() - "-raw".len()],
            );
        }
        "cem-ast" | "cem-ast-node" => {
            append_transform_template_subject_type_candidate(candidates, "cem-ast-node");
        }
        "cem-dom" | "cem-dom-node" => {
            append_transform_template_subject_type_candidate(candidates, "cem-dom-node");
        }
        "xmlnode" | "xml-node" => {
            append_transform_template_subject_type_candidate(candidates, "xml-node");
        }
        "htmlnode" | "html-node" => {
            append_transform_template_subject_type_candidate(candidates, "html-node");
        }
        other => append_transform_template_subject_type_candidate(candidates, other),
    }
}

fn append_transform_template_raw_subject_type_hint(candidates: &mut Vec<String>, syntax: &str) {
    let syntax = syntax.trim().replace('_', "-").to_ascii_lowercase();
    if syntax.is_empty() || syntax.chars().any(char::is_control) {
        append_transform_template_subject_type_candidate(candidates, "raw");
        return;
    }
    if syntax == "raw" {
        append_transform_template_subject_type_candidate(candidates, "raw");
        return;
    }
    if syntax == "raw-syntax" {
        append_transform_template_subject_type_candidate(candidates, "raw-syntax");
        append_transform_template_subject_type_candidate(candidates, "raw");
        return;
    }
    append_transform_template_subject_type_candidate(candidates, format!("raw-{syntax}"));
    append_transform_template_subject_type_candidate(candidates, "raw-syntax");
    append_transform_template_subject_type_candidate(candidates, "raw");
}

fn append_transform_template_semantic_subject_type_candidates(
    candidates: &mut Vec<String>,
    subject: &Value,
) {
    if let Some(items) = subject.as_array() {
        if transform_template_array_looks_like_color_tokens(items) {
            append_transform_template_subject_type_hint(candidates, "tokens");
        }
        return;
    }

    let Some(object) = subject.as_object() else {
        return;
    };

    for key in [
        "subjectType",
        "subject-type",
        "cemtSubjectType",
        "cemt-subject-type",
    ] {
        if let Some(subject_type) = object.get(key).and_then(Value::as_str) {
            append_transform_template_subject_type_hint(candidates, subject_type);
        }
    }

    if let Some(raw_syntax) = transform_template_explicit_raw_subject_syntax(object) {
        append_transform_template_raw_subject_type_hint(candidates, raw_syntax);
    }

    if object.get("tokens").is_some_and(Value::is_array) {
        append_transform_template_subject_type_hint(candidates, "tokens");
    }

    if object.get("kind").and_then(Value::as_str) == Some("cem-tree") {
        append_transform_template_subject_type_hint(candidates, "cem-tree");
    }

    if object.get("bytes").is_some_and(Value::is_array) {
        append_transform_template_subject_type_hint(candidates, "bytes");
    }

    if let Some(events) = object.get("events").and_then(Value::as_array) {
        let has_parse_events = events.iter().any(|event| {
            event.as_object().is_some_and(|event| {
                event.get("parse").is_some()
                    || event.get("channel").and_then(Value::as_str) == Some("parse")
            })
        });
        let has_transform_events = events.iter().any(|event| {
            event.as_object().is_some_and(|event| {
                event.get("transform").is_some()
                    || event.get("channel").and_then(Value::as_str) == Some("transform")
            })
        });
        match (has_parse_events, has_transform_events) {
            (true, false) => {
                append_transform_template_subject_type_hint(candidates, "parser-events")
            }
            (false, true) => {
                append_transform_template_subject_type_hint(candidates, "transform-events")
            }
            _ => append_transform_template_subject_type_hint(candidates, "event-stream"),
        }
    }

    if let Some(chunks) = object.get("chunks").and_then(Value::as_array) {
        let has_binary_chunks = chunks.iter().any(|chunk| {
            chunk.as_object().is_some_and(|chunk| {
                chunk
                    .get("bytes")
                    .and_then(Value::as_array)
                    .is_some_and(|bytes| !bytes.is_empty())
            })
        });
        let all_chunks_sealed = !chunks.is_empty()
            && chunks.iter().all(|chunk| {
                chunk
                    .as_object()
                    .and_then(|chunk| chunk.get("sealed"))
                    .and_then(Value::as_bool)
                    == Some(true)
            });
        if has_binary_chunks && all_chunks_sealed {
            append_transform_template_subject_type_hint(candidates, "sealed-binary-chunks");
        } else if has_binary_chunks {
            append_transform_template_subject_type_hint(candidates, "binary-chunks");
        } else {
            append_transform_template_subject_type_hint(candidates, "chunks");
        }
    }

    if transform_template_object_string_field(object, &["qualifiedName", "qualified-name", "qName"])
        .is_some()
        || transform_template_object_string_field(object, &["prefix"]).is_some()
    {
        append_transform_template_subject_type_hint(candidates, "qualified-name");
    } else if transform_template_object_string_field(object, &["localName", "local-name"]).is_some()
    {
        append_transform_template_subject_type_hint(candidates, "local-name");
    }

    if transform_template_object_string_field(
        object,
        &["namespaceUri", "namespaceURI", "namespace-uri"],
    )
    .is_some()
    {
        append_transform_template_subject_type_hint(candidates, "namespace-uri");
    }

    if transform_template_object_string_field(object, &["identifier"]).is_some() {
        append_transform_template_subject_type_hint(candidates, "identifier");
    }

    match transform_template_object_string_field(object, &["kind"])
        .map(|kind| kind.trim().replace('_', "-").to_ascii_lowercase())
    {
        Some(kind) if kind == "attribute" => {
            append_transform_template_subject_type_hint(candidates, "attribute");
        }
        Some(kind) if kind == "slot" => {
            append_transform_template_subject_type_hint(candidates, "slot");
        }
        Some(kind) if kind == "fragment" => {
            append_transform_template_subject_type_hint(candidates, "fragment");
        }
        Some(kind)
            if matches!(
                kind.as_str(),
                "cem-ast-node" | "cem-dom-node" | "xml-node" | "html-node"
            ) =>
        {
            append_transform_template_subject_type_hint(candidates, &kind);
        }
        _ => {}
    }

    if object
        .get("fragment")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || object.get("mode").and_then(Value::as_str) == Some("fragment")
    {
        append_transform_template_subject_type_hint(candidates, "fragment");
    }

    if object
        .get("attributeName")
        .or_else(|| object.get("attribute-name"))
        .is_some()
    {
        append_transform_template_subject_type_hint(candidates, "attribute");
    }

    if object
        .get("attributes")
        .is_some_and(|value| value.is_array() || value.is_object())
    {
        append_transform_template_subject_type_hint(candidates, "attributes");
    }

    if object
        .get("slotName")
        .or_else(|| object.get("slot-name"))
        .or_else(|| object.get("slot"))
        .is_some()
    {
        append_transform_template_subject_type_hint(candidates, "slot");
    }

    if object
        .get("slots")
        .is_some_and(|value| value.is_array() || value.is_object())
    {
        append_transform_template_subject_type_hint(candidates, "slots");
    }
}

fn transform_template_explicit_raw_subject_syntax<'a>(
    object: &'a serde_json::Map<String, Value>,
) -> Option<&'a str> {
    if let Some(syntax) = transform_template_object_string_field(
        object,
        &[
            "rawSyntax",
            "raw-syntax",
            "cemtRawSyntax",
            "cemt-raw-syntax",
        ],
    ) {
        return Some(syntax);
    }

    let is_raw_kind = transform_template_object_string_field(object, &["kind"])
        .map(|kind| kind.trim().replace('_', "-").to_ascii_lowercase())
        .is_some_and(|kind| kind == "raw" || kind == "raw-syntax");
    let is_raw_flag = object
        .get("raw")
        .or_else(|| object.get("rawSubject"))
        .or_else(|| object.get("raw-subject"))
        .and_then(Value::as_bool)
        == Some(true);
    let has_raw_payload = transform_template_object_string_field(
        object,
        &[
            "rawText",
            "raw-text",
            "rawValue",
            "raw-value",
            "rawBytes",
            "raw-bytes",
        ],
    )
    .is_some()
        || object
            .get("raw")
            .is_some_and(|value| value.is_string() || value.is_array() || value.is_object());

    if !(is_raw_kind || is_raw_flag || has_raw_payload) {
        return None;
    }

    transform_template_object_string_field(
        object,
        &[
            "syntax",
            "targetSyntax",
            "target-syntax",
            "contentSyntax",
            "content-syntax",
        ],
    )
    .or(Some("raw"))
}

fn transform_template_object_string_field<'a>(
    object: &'a serde_json::Map<String, Value>,
    keys: &[&str],
) -> Option<&'a str> {
    keys.iter().find_map(|key| {
        object
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
    })
}

fn append_transform_template_json_subject_type_candidates(
    candidates: &mut Vec<String>,
    subject: &Value,
) {
    match subject {
        Value::Null => {
            append_transform_template_subject_type_candidate(candidates, "null");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::Bool(_) => {
            append_transform_template_subject_type_candidate(candidates, "boolean");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::Number(number) if number.is_i64() || number.is_u64() => {
            append_transform_template_subject_type_candidate(candidates, "integer");
            append_transform_template_subject_type_candidate(candidates, "number");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::Number(_) => {
            append_transform_template_subject_type_candidate(candidates, "number");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::String(_) => {
            append_transform_template_subject_type_candidate(candidates, "string");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::Array(_) => {
            append_transform_template_subject_type_candidate(candidates, "array");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
        Value::Object(_) => {
            append_transform_template_subject_type_candidate(candidates, "map");
            append_transform_template_subject_type_candidate(candidates, "object");
            append_transform_template_subject_type_candidate(candidates, "json");
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateWriterToken {
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub role: Option<String>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub style: BTreeMap<String, Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value: Option<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output_span: Option<OutputSpan>,
}

impl TransformTemplateWriterToken {
    pub fn new(kind: impl Into<String>) -> Self {
        Self {
            kind: kind.into(),
            text: None,
            role: None,
            style: BTreeMap::new(),
            value: None,
            output_span: None,
        }
    }

    pub fn with_text(mut self, text: impl Into<String>) -> Self {
        self.text = Some(text.into());
        self
    }

    pub fn with_role(mut self, role: impl Into<String>) -> Self {
        self.role = Some(role.into());
        self
    }

    pub fn with_style(mut self, style: BTreeMap<String, Value>) -> Self {
        self.style = style;
        self
    }

    pub fn with_style_property(mut self, name: impl Into<String>, value: Value) -> Self {
        self.style.insert(name.into(), value);
        self
    }

    pub fn with_value(mut self, value: Value) -> Self {
        self.value = Some(value);
        self
    }

    pub fn with_output_span(mut self, output_span: OutputSpan) -> Self {
        self.output_span = Some(output_span);
        self
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateWriterTokenStream {
    pub tokens: Vec<TransformTemplateWriterToken>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateWriterByteStream {
    pub encoding: String,
    pub bytes: Vec<u8>,
    pub byte_length: usize,
}

impl TransformTemplateWriterByteStream {
    pub fn new(bytes: Vec<u8>) -> Self {
        Self {
            byte_length: bytes.len(),
            encoding: "u8-array".to_owned(),
            bytes,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateWriterChunk {
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub bytes: Vec<u8>,
    #[serde(default, skip_serializing_if = "is_false")]
    pub sealed: bool,
}

impl TransformTemplateWriterChunk {
    pub fn text(kind: impl Into<String>, text: impl Into<String>) -> Self {
        Self {
            kind: kind.into(),
            id: None,
            text: Some(text.into()),
            bytes: Vec::new(),
            sealed: false,
        }
    }

    pub fn bytes(kind: impl Into<String>, bytes: Vec<u8>) -> Self {
        Self {
            kind: kind.into(),
            id: None,
            text: None,
            bytes,
            sealed: false,
        }
    }

    pub fn with_id(mut self, id: impl Into<String>) -> Self {
        self.id = Some(id.into());
        self
    }

    pub fn sealed(mut self) -> Self {
        self.sealed = true;
        self
    }
}

