const CEMT_RUNTIME_CALL_RECURSION_LIMIT: usize = 64;
const CEMT_RUNTIME_STACK_DEPTH_LIMIT: usize = 128;
const CEMT_RUNTIME_QUEUE_LENGTH_LIMIT: usize = 1024;
const CEMT_RUNTIME_REPEAT_LIMIT: usize = 4096;
const CEMT_RUNTIME_PARSE_CACHE_LIMIT: usize = 4096;

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct CemtRuntimeFunction {
    params: Vec<TransformTemplateModuleParamDeclaration>,
    return_type: TransformTemplateModuleParamType,
    nullable: bool,
    body: String,
}

pub(crate) fn cemt_runtime_functions_from_module_options(
    options: &TransformTemplateModuleOptions,
) -> BTreeMap<String, CemtRuntimeFunction> {
    let mut functions: BTreeMap<String, CemtRuntimeFunction> = options
        .functions
        .iter()
        .filter_map(cemt_runtime_function_from_declaration)
        .collect();
    functions.extend(
        options
            .output_functions
            .iter()
            .filter_map(cemt_runtime_function_from_descriptor),
    );
    functions
}

fn cemt_runtime_function_from_declaration(
    function: &TransformTemplateModuleFunctionDeclaration,
) -> Option<(String, CemtRuntimeFunction)> {
    let body = function.body_expression.as_ref()?;
    Some((
        function.name.clone(),
        CemtRuntimeFunction {
            params: function.params.clone(),
            return_type: function.return_type,
            nullable: function.nullable,
            body: body.clone(),
        },
    ))
}

fn cemt_runtime_function_from_descriptor(
    function: &TransformTemplateOutputFunctionDescriptor,
) -> Option<(String, CemtRuntimeFunction)> {
    if function.implementation != TransformTemplateOutputFunctionImplementation::Cemt {
        return None;
    }
    let body = function.body_expression.as_ref()?;
    if cemt_expression_starts_with_call(body, "encode") {
        return None;
    }
    Some((
        function.name.clone(),
        CemtRuntimeFunction {
            params: function.params.clone(),
            return_type: TransformTemplateModuleParamType::Any,
            nullable: true,
            body: body.clone(),
        },
    ))
}

fn resolve_encode_subject_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
) -> Option<Value> {
    let runtime_functions = BTreeMap::new();
    resolve_encode_subject_expression_with_functions(expression, value_bindings, &runtime_functions)
}

fn resolve_encode_subject_expression_with_functions(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
) -> Option<Value> {
    resolve_encode_subject_expression_at_depth(
        expression,
        value_bindings,
        runtime_functions,
        None,
        0,
    )
    .ok()
    .flatten()
}

fn resolve_encode_subject_expression_with_binding(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: &TransformTemplateEncodeBinding,
) -> Result<Option<Value>, String> {
    resolve_encode_subject_expression_at_depth(
        expression,
        value_bindings,
        runtime_functions,
        Some(binding),
        0,
    )
}

fn resolve_encode_subject_expression_at_depth(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let expression = expression.trim();
    if let Some(function_name) = cemt_expression_call_name(expression) {
        return resolve_cemt_function_call_expression_by_name(
            function_name,
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        );
    }
    if expression.starts_with('{') {
        if let Some(value) = resolve_cemt_object_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )? {
            return Ok(Some(value));
        }
    }
    if expression.starts_with('[') {
        if let Some(value) = resolve_cemt_array_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )? {
            return Ok(Some(value));
        }
    }
    if expression.starts_with('"') || expression.starts_with('\'') {
        return Ok(parse_cemt_quoted_string(expression).ok().map(Value::String));
    }
    if let Some(path) = expression.strip_prefix('$') {
        return Ok(resolve_encode_subject_path(path, value_bindings).cloned());
    }
    if let Ok(value) = serde_json::from_str::<Value>(expression) {
        return Ok(Some(value));
    }
    Ok(None)
}

fn resolve_cemt_function_call_expression_by_name(
    function_name: &str,
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    match function_name {
        "call" => resolve_cemt_call_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "map" => resolve_cemt_map_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "fold" => resolve_cemt_fold_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "append" => resolve_cemt_append_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "extend" => resolve_cemt_extend_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "appendFormatNode"
        | "appendColorNode"
        | "appendDiagnostic"
        | "appendNamespace"
        | "appendOutputSpan"
        | "appendWriterBoundary" => resolve_cemt_metadata_accumulator_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "merge" => resolve_cemt_merge_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "set" => resolve_cemt_set_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "replaceNode" | "appendNode" | "prependNode" | "wrapNode" => {
            resolve_cemt_tree_patch_expression(
                expression,
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )
        }
        "applyEdits" => resolve_cemt_apply_edits_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "setEdit" | "replaceEdit" | "appendEdit" | "prependEdit" | "wrapEdit" => {
            resolve_cemt_edit_constructor_expression(
                expression,
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )
        }
        "withStack" => resolve_cemt_with_stack_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "stackPush" => resolve_cemt_stack_push_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "stackPop" => resolve_cemt_stack_pop_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "stackTop" => resolve_cemt_stack_top_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "stackDepth" => resolve_cemt_stack_depth_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "stackPath" => resolve_cemt_stack_path_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "defer" | "queuePush" => resolve_cemt_queue_push_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            function_name,
        ),
        "queueShift" => resolve_cemt_queue_shift_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "queuePeek" => resolve_cemt_queue_peek_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "queueLength" => resolve_cemt_queue_length_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "length" => resolve_cemt_length_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "last" => resolve_cemt_last_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "typeOf" => resolve_cemt_type_of_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "add" => resolve_cemt_add_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "sub" => resolve_cemt_sub_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "mul" => resolve_cemt_mul_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "div" => resolve_cemt_div_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "min" => resolve_cemt_min_max_expression(
            expression,
            "min",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |left, right| left.min(right),
        ),
        "max" => resolve_cemt_min_max_expression(
            expression,
            "max",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |left, right| left.max(right),
        ),
        "lt" => resolve_cemt_compare_expression(
            expression,
            "lt",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |ordering| ordering.is_lt(),
        ),
        "lte" => resolve_cemt_compare_expression(
            expression,
            "lte",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |ordering| ordering.is_le(),
        ),
        "gt" => resolve_cemt_compare_expression(
            expression,
            "gt",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |ordering| ordering.is_gt(),
        ),
        "gte" => resolve_cemt_compare_expression(
            expression,
            "gte",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            |ordering| ordering.is_ge(),
        ),
        "mod" => resolve_cemt_mod_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "concat" => resolve_cemt_concat_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "get" => resolve_cemt_get_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "contains" => resolve_cemt_contains_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "replace" => resolve_cemt_replace_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "trim" => resolve_cemt_trim_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "substring" => resolve_cemt_substring_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "indexOf" => resolve_cemt_index_of_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "displayWidth" => resolve_cemt_display_width_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "displayPrefix" => resolve_cemt_display_prefix_suffix_expression(
            expression,
            "displayPrefix",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            false,
        ),
        "displaySuffix" => resolve_cemt_display_prefix_suffix_expression(
            expression,
            "displaySuffix",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            true,
        ),
        "toInteger" => resolve_cemt_to_integer_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "toString" => resolve_cemt_to_string_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "isAsciiInteger" => resolve_cemt_ascii_number_predicate_expression(
            expression,
            "isAsciiInteger",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            cemt_is_ascii_integer,
        ),
        "isAsciiDecimal" => resolve_cemt_ascii_number_predicate_expression(
            expression,
            "isAsciiDecimal",
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
            cemt_is_ascii_decimal,
        ),
        "startsWith" => resolve_cemt_starts_with_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "endsWith" => resolve_cemt_ends_with_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "repeat" => resolve_cemt_repeat_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "sourceMap" => resolve_cemt_source_map_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "drainQueue" => resolve_cemt_drain_queue_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "diagnostic" => resolve_cemt_diagnostic_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "diagnostics" => resolve_cemt_diagnostics_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "match" => resolve_cemt_match_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        "exists" => resolve_cemt_exists_expression(
            expression,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        ),
        _ => Ok(None),
    }
}

fn resolve_cemt_call_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "call").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    if call_depth >= CEMT_RUNTIME_CALL_RECURSION_LIMIT {
        return Err(format!(
            "CEMT call recursion limit exceeded while calling `{}`",
            args[0].trim()
        ));
    }
    let function_name_literal = parse_cemt_literal(&args[0]).map_err(|error| error.to_string())?;
    let function_name = resolve_cemt_literal_runtime_value(
        &function_name_literal,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?;
    let Some(function_name) = function_name else {
        return Ok(None);
    };
    let Some(function_name) = function_name.as_str().map(str::trim) else {
        return Ok(None);
    };
    if function_name.is_empty() {
        return Ok(None);
    }
    if function_name == "cem.color-tree.apply" {
        return Err(
            "CEMT runtime operation `cem.color-tree.apply` has been removed; use schema-owned `cem.color-tree.apply-stage` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.envelope" {
        return Err(
            "CEMT runtime operation `cem.format-tree.envelope` has been removed; use schema-owned `cem.format-tree.build-envelope` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.nodes" {
        return Err(
            "CEMT runtime operation `cem.format-tree.nodes` has been removed; use schema-owned `cem.format-tree.build-node-list` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.format-nodes" {
        return Err(
            "CEMT runtime operation `cem.format-tree.format-nodes` has been removed; use schema-owned `cem.format-tree.add-format-nodes` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.content-boundary" {
        return Err(
            "CEMT runtime operation `cem.format-tree.content-boundary` has been removed; use schema-owned `cem.format-tree.build-content-boundary` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.inter-node-whitespace" {
        return Err(
            "CEMT runtime operation `cem.format-tree.inter-node-whitespace` has been removed; use schema-owned `cem.format-tree.format-inter-node-whitespace` helpers"
                .to_owned(),
        );
    }
    if function_name == "cem.format-tree.block-children" {
        return Err(
            "CEMT runtime operation `cem.format-tree.block-children` has been removed; use schema-owned `cem.format-tree.format-block-children` helpers"
                .to_owned(),
        );
    }
    let arguments = parse_cemt_object_literal(&args[1]).map_err(|error| error.to_string())?;
    let Some(function) = runtime_functions.get(function_name) else {
        return Ok(None);
    };
    for name in arguments.keys() {
        if !function.params.iter().any(|param| param.name == *name) {
            return Err(format!(
                "CEMT function `{function_name}` received unknown argument `{name}`"
            ));
        }
    }

    let mut bound_arguments = Vec::new();
    for param in &function.params {
        let value = if let Some(literal) = arguments.get(&param.name) {
            let Some(value) = resolve_cemt_literal_runtime_value(
                literal,
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )?
            else {
                return Err(format!(
                    "CEMT function `{function_name}` argument `{}` could not be resolved",
                    param.name
                ));
            };
            value
        } else if let Some(value) = param.default_value.clone() {
            value
        } else if param.required {
            return Err(format!(
                "CEMT function `{function_name}` requires argument `{}`",
                param.name
            ));
        } else {
            continue;
        };

        if !param.value_type.accepts(&value, param.nullable) {
            return Err(format!(
                "CEMT function `{function_name}` argument `{}` expected {}, got {}",
                param.name,
                param.value_type.as_contract_name(),
                json_value_type_name(&value)
            ));
        }
        bound_arguments.push((param.name.clone(), value));
    }

    let bound_argument_names = bound_arguments
        .iter()
        .map(|(name, _)| name.as_str())
        .collect::<Vec<_>>();
    let mut scoped_bindings =
        cemt_runtime_clone_bindings_excluding_names(value_bindings, &bound_argument_names);
    for (name, value) in bound_arguments {
        scoped_bindings.insert(name, value);
    }

    let result = resolve_encode_subject_expression_at_depth(
        &function.body,
        &scoped_bindings,
        runtime_functions,
        binding,
        call_depth + 1,
    )?;
    if let Some(value) = result.as_ref() {
        if !function.return_type.accepts(value, function.nullable) {
            return Err(format!(
                "CEMT function `{function_name}` returned {}, expected {}",
                json_value_type_name(value),
                function.return_type.as_contract_name()
            ));
        }
    }
    Ok(result)
}

fn resolve_cemt_map_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "map").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let collection = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?;
    let Some(collection) = collection else {
        return Ok(None);
    };
    let Value::Array(items) = collection else {
        return Ok(None);
    };

    let mut mapped = Vec::with_capacity(items.len());
    for (index, item) in items.into_iter().enumerate() {
        let mut scoped_bindings =
            cemt_runtime_clone_bindings_excluding_names(value_bindings, &["item", "index"]);
        scoped_bindings.insert("item".to_owned(), item);
        scoped_bindings.insert(
            "index".to_owned(),
            Value::Number(serde_json::Number::from(index as u64)),
        );
        let Some(value) = resolve_encode_subject_expression_at_depth(
            &args[1],
            &scoped_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        mapped.push(value);
    }

    Ok(Some(Value::Array(mapped)))
}

fn resolve_cemt_fold_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "fold").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 3 {
        return Ok(None);
    }
    let collection = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?;
    let Some(collection) = collection else {
        return Ok(None);
    };
    let Value::Array(items) = collection else {
        return Ok(None);
    };
    let Some(mut accumulator) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };

    for (index, item) in items.into_iter().enumerate() {
        let mut scoped_bindings = cemt_runtime_clone_bindings_excluding_names(
            value_bindings,
            &["item", "index", "acc", "accumulator"],
        );
        scoped_bindings.insert("item".to_owned(), item);
        scoped_bindings.insert(
            "index".to_owned(),
            Value::Number(serde_json::Number::from(index as u64)),
        );
        scoped_bindings.insert("acc".to_owned(), accumulator.clone());
        scoped_bindings.insert("accumulator".to_owned(), accumulator);
        let Some(next) = resolve_encode_subject_expression_at_depth(
            &args[2],
            &scoped_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        accumulator = next;
    }

    Ok(Some(accumulator))
}

fn resolve_cemt_append_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "append").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let accumulator = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?;
    let Some(accumulator) = accumulator else {
        return Ok(None);
    };
    let Value::Array(mut accumulator) = accumulator else {
        return Err(format!(
            "CEMT append expected array accumulator, got {}",
            json_value_type_name(&accumulator)
        ));
    };
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    accumulator.push(value);
    Ok(Some(Value::Array(accumulator)))
}

fn resolve_cemt_extend_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "extend").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(accumulator) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Value::Array(mut accumulator) = accumulator else {
        return Err(format!(
            "CEMT extend expected array accumulator, got {}",
            json_value_type_name(&accumulator)
        ));
    };
    let Some(values) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Value::Array(values) = values else {
        return Err(format!(
            "CEMT extend expected array values, got {}",
            json_value_type_name(&values)
        ));
    };
    accumulator.extend(values);
    Ok(Some(Value::Array(accumulator)))
}

#[derive(Debug, Clone, Copy)]
enum CemtMetadataAccumulatorKind {
    FormatNode,
    ColorNode,
    Diagnostic,
    Namespace,
    OutputSpan,
    WriterBoundary,
}

impl CemtMetadataAccumulatorKind {
    fn from_expression(expression: &str) -> Result<Option<(Self, Vec<String>)>, String> {
        for (name, kind) in [
            ("appendFormatNode", Self::FormatNode),
            ("appendColorNode", Self::ColorNode),
            ("appendDiagnostic", Self::Diagnostic),
            ("appendNamespace", Self::Namespace),
            ("appendOutputSpan", Self::OutputSpan),
            ("appendWriterBoundary", Self::WriterBoundary),
        ] {
            if let Some(args) = parse_cemt_function_call_args(expression, name)
                .map_err(|error| error.to_string())?
            {
                return Ok(Some((kind, args)));
            }
        }
        Ok(None)
    }

    fn function_name(self) -> &'static str {
        match self {
            Self::FormatNode => "appendFormatNode",
            Self::ColorNode => "appendColorNode",
            Self::Diagnostic => "appendDiagnostic",
            Self::Namespace => "appendNamespace",
            Self::OutputSpan => "appendOutputSpan",
            Self::WriterBoundary => "appendWriterBoundary",
        }
    }

    fn field_name(self) -> &'static str {
        match self {
            Self::FormatNode => "formatNodes",
            Self::ColorNode => "colorNodes",
            Self::Diagnostic => "diagnostics",
            Self::Namespace => "namespaceDeclarations",
            Self::OutputSpan => "outputSpans",
            Self::WriterBoundary => "writerBoundaries",
        }
    }

    fn default_source_map_function_name(
        self,
        binding: Option<&TransformTemplateEncodeBinding>,
    ) -> String {
        match (self, binding) {
            (Self::FormatNode, Some(binding))
                if binding.function.kind == TransformTemplateOutputFunctionKind::Format =>
            {
                binding.function.name.clone()
            }
            (Self::ColorNode, Some(binding))
                if binding.function.kind == TransformTemplateOutputFunctionKind::Color =>
            {
                binding.function.name.clone()
            }
            (Self::FormatNode, _) => "cem.format-tree".to_owned(),
            (Self::ColorNode, _) => "cem.color-tree".to_owned(),
            (_, Some(binding)) => binding.function.name.clone(),
            _ => self.function_name().to_owned(),
        }
    }

    fn normalize_item(self, value: Value) -> Result<Value, String> {
        match self {
            Self::FormatNode => {
                let mut object = cemt_metadata_object(self, value, "format node")?;
                cemt_required_metadata_string_field(&mut object, self, "kind")?;
                cemt_required_metadata_string_field(&mut object, self, "formatterRole")?;
                cemt_optional_metadata_string_field(&mut object, self, "name")?;
                cemt_optional_metadata_string_field(&mut object, self, "value")?;
                Ok(Value::Object(object))
            }
            Self::ColorNode => {
                let mut object = cemt_metadata_object(self, value, "color node")?;
                cemt_required_metadata_string_field(&mut object, self, "kind")?;
                cemt_required_metadata_string_field(&mut object, self, "colorizerRole")?;
                cemt_optional_metadata_string_field(&mut object, self, "name")?;
                cemt_optional_metadata_string_field(&mut object, self, "colorRole")?;
                cemt_optional_metadata_string_field(&mut object, self, "value")?;
                Ok(Value::Object(object))
            }
            Self::Diagnostic => {
                let Value::Object(object) = value else {
                    return Err(format!(
                        "CEMT {} expected diagnostic object, got {}",
                        self.function_name(),
                        json_value_type_name(&value)
                    ));
                };
                normalize_cemt_diagnostic_object(object).map(Value::Object)
            }
            Self::Namespace => {
                let mut object = cemt_metadata_object(self, value, "namespace declaration")?;
                cemt_required_metadata_string_field(&mut object, self, "uri")?;
                cemt_optional_metadata_string_field(&mut object, self, "prefix")?;
                Ok(Value::Object(object))
            }
            Self::OutputSpan => {
                let mut object = cemt_metadata_object(self, value, "output span")?;
                cemt_required_metadata_string_field(&mut object, self, "kind")?;
                let start = cemt_required_metadata_u64_field(&mut object, self, "start")?;
                let end = cemt_required_metadata_u64_field(&mut object, self, "end")?;
                if end < start {
                    return Err(format!(
                        "CEMT {} output span `end` must be greater than or equal to `start`",
                        self.function_name()
                    ));
                }
                Ok(Value::Object(object))
            }
            Self::WriterBoundary => {
                let mut object = cemt_metadata_object(self, value, "writer boundary")?;
                cemt_required_metadata_string_field(&mut object, self, "kind")?;
                cemt_required_metadata_string_field(&mut object, self, "stage")?;
                Ok(Value::Object(object))
            }
        }
    }
}

fn cemt_metadata_object(
    kind: CemtMetadataAccumulatorKind,
    value: Value,
    label: &str,
) -> Result<serde_json::Map<String, Value>, String> {
    let Value::Object(object) = value else {
        return Err(format!(
            "CEMT {} expected {label} object, got {}",
            kind.function_name(),
            json_value_type_name(&value)
        ));
    };
    Ok(object)
}

fn cemt_required_metadata_string_field(
    object: &mut serde_json::Map<String, Value>,
    kind: CemtMetadataAccumulatorKind,
    field: &str,
) -> Result<String, String> {
    let Some(value) = object.get(field) else {
        return Err(format!(
            "CEMT {} metadata missing `{field}`",
            kind.function_name()
        ));
    };
    let Some(value) = value
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Err(format!(
            "CEMT {} metadata `{field}` expected non-empty string, got {}",
            kind.function_name(),
            json_value_type_name(value)
        ));
    };
    let value = value.to_owned();
    object.insert(field.to_owned(), Value::String(value.clone()));
    Ok(value)
}

fn cemt_optional_metadata_string_field(
    object: &mut serde_json::Map<String, Value>,
    kind: CemtMetadataAccumulatorKind,
    field: &str,
) -> Result<Option<String>, String> {
    let Some(value) = object.get(field) else {
        return Ok(None);
    };
    if value.is_null() {
        object.remove(field);
        return Ok(None);
    }
    let Some(value) = value.as_str() else {
        return Err(format!(
            "CEMT {} metadata `{field}` expected string, got {}",
            kind.function_name(),
            json_value_type_name(value)
        ));
    };
    let value = if field == "value" {
        value.to_owned()
    } else {
        let value = value.trim();
        if value.is_empty() {
            return Err(format!(
                "CEMT {} metadata `{field}` expected non-empty string, got {}",
                kind.function_name(),
                json_value_type_name(object.get(field).unwrap_or(&Value::Null))
            ));
        }
        value.to_owned()
    };
    object.insert(field.to_owned(), Value::String(value.clone()));
    Ok(Some(value))
}

fn cemt_required_metadata_u64_field(
    object: &mut serde_json::Map<String, Value>,
    kind: CemtMetadataAccumulatorKind,
    field: &str,
) -> Result<u64, String> {
    let Some(value) = object.get(field) else {
        return Err(format!(
            "CEMT {} metadata missing `{field}`",
            kind.function_name()
        ));
    };
    let Some(value) = value.as_u64() else {
        return Err(format!(
            "CEMT {} metadata `{field}` expected unsigned integer, got {}",
            kind.function_name(),
            json_value_type_name(value)
        ));
    };
    object.insert(
        field.to_owned(),
        Value::Number(serde_json::Number::from(value)),
    );
    Ok(value)
}

fn resolve_cemt_metadata_accumulator_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some((kind, args)) = CemtMetadataAccumulatorKind::from_expression(expression)? else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(accumulator) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Value::Object(mut accumulator) = accumulator else {
        return Err(format!(
            "CEMT {} expected object accumulator, got {}",
            kind.function_name(),
            json_value_type_name(&accumulator)
        ));
    };
    let Some(item) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let mut item = kind.normalize_item(item)?;
    apply_cemt_metadata_source_map_default(&mut item, &accumulator, kind, binding);
    append_cemt_metadata_accumulator_item(&mut accumulator, kind, item)?;
    Ok(Some(Value::Object(accumulator)))
}

fn apply_cemt_metadata_source_map_default(
    item: &mut Value,
    accumulator: &serde_json::Map<String, Value>,
    kind: CemtMetadataAccumulatorKind,
    binding: Option<&TransformTemplateEncodeBinding>,
) {
    let Value::Object(item_fields) = item else {
        return;
    };
    if item_fields.contains_key("sourceMap") {
        return;
    }
    let source_map = transform_template_first_cem_tree_source_map(&Value::Object(
        accumulator.clone(),
    ))
    .or_else(|| transform_template_first_cem_tree_source_map(&Value::Object(item_fields.clone())));
    let Some(source_map) = source_map else {
        return;
    };
    let function = kind.default_source_map_function_name(binding);
    if let Some(source_map) =
        transform_template_cem_tree_transform_source_map_value(Some(&source_map), &function)
    {
        item_fields.insert("sourceMap".to_owned(), source_map);
    }
}

fn append_cemt_metadata_accumulator_item(
    accumulator: &mut serde_json::Map<String, Value>,
    kind: CemtMetadataAccumulatorKind,
    item: Value,
) -> Result<(), String> {
    let field = kind.field_name();
    match accumulator.entry(field.to_owned()) {
        serde_json::map::Entry::Vacant(entry) => {
            entry.insert(Value::Array(vec![item]));
            Ok(())
        }
        serde_json::map::Entry::Occupied(mut entry) => {
            let value = entry.get_mut();
            let Value::Array(items) = value else {
                return Err(format!(
                    "CEMT {} expected `{field}` array, got {}",
                    kind.function_name(),
                    json_value_type_name(value)
                ));
            };
            items.push(item);
            Ok(())
        }
    }
}

fn resolve_cemt_merge_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "merge").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(target) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(patch) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Value::Object(mut target) = target else {
        return Err(format!(
            "CEMT merge expected object target, got {}",
            json_value_type_name(&target)
        ));
    };
    let Value::Object(patch) = patch else {
        return Err(format!(
            "CEMT merge expected object patch, got {}",
            json_value_type_name(&patch)
        ));
    };
    for (key, value) in patch {
        target.insert(key, value);
    }
    Ok(Some(Value::Object(target)))
}

fn resolve_cemt_set_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "set").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 3 {
        return Ok(None);
    }
    let Some(mut target) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(path) = resolve_cemt_patch_path_argument(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[2],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    set_cemt_value_path(&mut target, &path, value)?;
    Ok(Some(target))
}

#[derive(Debug, Clone, Copy)]
enum CemtTreePatchOperation {
    Set,
    Replace,
    Append,
    Prepend,
    Wrap,
}

impl CemtTreePatchOperation {
    fn from_expression(expression: &str) -> Result<Option<(Self, Vec<String>)>, String> {
        for (name, operation) in [
            ("replaceNode", Self::Replace),
            ("appendNode", Self::Append),
            ("prependNode", Self::Prepend),
            ("wrapNode", Self::Wrap),
        ] {
            if let Some(args) = parse_cemt_function_call_args(expression, name)
                .map_err(|error| error.to_string())?
            {
                return Ok(Some((operation, args)));
            }
        }
        Ok(None)
    }

    fn function_name(self) -> &'static str {
        match self {
            Self::Set => "set",
            Self::Replace => "replaceNode",
            Self::Append => "appendNode",
            Self::Prepend => "prependNode",
            Self::Wrap => "wrapNode",
        }
    }
}

fn resolve_cemt_tree_patch_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some((operation, args)) = CemtTreePatchOperation::from_expression(expression)? else {
        return Ok(None);
    };
    if args.len() != 3 {
        return Ok(None);
    }
    let owner = operation.function_name();
    let Some(mut target) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(path) = resolve_cemt_patch_path_argument_for_owner(
        &args[1],
        owner,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[2],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    apply_cemt_tree_patch_operation(&mut target, operation, &path, value, owner, binding)?;
    Ok(Some(target))
}

fn resolve_cemt_apply_edits_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "applyEdits")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(mut target) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(edits) = resolve_cemt_queue_argument(
        &args[1],
        "applyEdits",
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };

    for (index, edit) in edits.into_iter().enumerate() {
        let edit = parse_cemt_tree_patch_edit(index, edit)?;
        apply_cemt_tree_patch_operation(
            &mut target,
            edit.operation,
            &edit.path,
            edit.value,
            "applyEdits",
            binding,
        )?;
    }

    Ok(Some(target))
}

#[derive(Debug, Clone, Copy)]
enum CemtTreePatchEditConstructor {
    Set,
    Replace,
    Append,
    Prepend,
    Wrap,
}

impl CemtTreePatchEditConstructor {
    fn from_expression(expression: &str) -> Result<Option<(Self, Vec<String>)>, String> {
        for (name, constructor) in [
            ("setEdit", Self::Set),
            ("replaceEdit", Self::Replace),
            ("appendEdit", Self::Append),
            ("prependEdit", Self::Prepend),
            ("wrapEdit", Self::Wrap),
        ] {
            if let Some(args) = parse_cemt_function_call_args(expression, name)
                .map_err(|error| error.to_string())?
            {
                return Ok(Some((constructor, args)));
            }
        }
        Ok(None)
    }

    fn function_name(self) -> &'static str {
        match self {
            Self::Set => "setEdit",
            Self::Replace => "replaceEdit",
            Self::Append => "appendEdit",
            Self::Prepend => "prependEdit",
            Self::Wrap => "wrapEdit",
        }
    }

    fn kind_name(self) -> &'static str {
        match self {
            Self::Set => "set",
            Self::Replace => "replace",
            Self::Append => "append",
            Self::Prepend => "prepend",
            Self::Wrap => "wrap",
        }
    }

    fn value_field(self) -> &'static str {
        match self {
            Self::Set => "value",
            Self::Replace | Self::Append | Self::Prepend => "node",
            Self::Wrap => "wrapper",
        }
    }

    fn operation(self) -> CemtTreePatchOperation {
        match self {
            Self::Set => CemtTreePatchOperation::Set,
            Self::Replace => CemtTreePatchOperation::Replace,
            Self::Append => CemtTreePatchOperation::Append,
            Self::Prepend => CemtTreePatchOperation::Prepend,
            Self::Wrap => CemtTreePatchOperation::Wrap,
        }
    }
}

fn resolve_cemt_edit_constructor_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some((constructor, args)) = CemtTreePatchEditConstructor::from_expression(expression)?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(path) = resolve_cemt_patch_path_argument_for_owner(
        &args[0],
        constructor.function_name(),
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    cemt_patch_path_segments(&path, constructor.function_name())?;
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    validate_cemt_edit_constructor_value(constructor, &value)?;
    let mut edit = serde_json::Map::new();
    edit.insert(
        "kind".to_owned(),
        Value::String(constructor.kind_name().to_owned()),
    );
    edit.insert("path".to_owned(), Value::String(path));
    edit.insert(constructor.value_field().to_owned(), value);
    Ok(Some(Value::Object(edit)))
}

fn validate_cemt_edit_constructor_value(
    constructor: CemtTreePatchEditConstructor,
    value: &Value,
) -> Result<(), String> {
    match constructor.operation() {
        CemtTreePatchOperation::Append | CemtTreePatchOperation::Prepend => {
            if value.is_null() {
                return Err(format!(
                    "CEMT {} node value must not be null",
                    constructor.function_name()
                ));
            }
        }
        CemtTreePatchOperation::Wrap => {
            if !value.is_object() {
                return Err(format!(
                    "CEMT {} expected object wrapper, got {}",
                    constructor.function_name(),
                    json_value_type_name(value)
                ));
            }
        }
        CemtTreePatchOperation::Set | CemtTreePatchOperation::Replace => {}
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct CemtTreePatchEdit {
    operation: CemtTreePatchOperation,
    path: String,
    value: Value,
}

fn parse_cemt_tree_patch_edit(index: usize, value: Value) -> Result<CemtTreePatchEdit, String> {
    let Value::Object(object) = value else {
        return Err(format!(
            "CEMT applyEdits expected edit object at index {index}, got {}",
            json_value_type_name(&value)
        ));
    };
    let kind = required_cemt_tree_patch_edit_string(&object, index, &["kind", "op"])?;
    let normalized_kind = kind.trim().replace('_', "-").to_ascii_lowercase();
    let operation = match normalized_kind.as_str() {
        "set" => CemtTreePatchOperation::Set,
        "replace" | "replace-node" => CemtTreePatchOperation::Replace,
        "append" | "append-node" => CemtTreePatchOperation::Append,
        "prepend" | "prepend-node" => CemtTreePatchOperation::Prepend,
        "wrap" | "wrap-node" => CemtTreePatchOperation::Wrap,
        _ => {
            return Err(format!(
                "CEMT applyEdits edit {index} has unsupported kind `{kind}`"
            ))
        }
    };
    let path = required_cemt_tree_patch_edit_string(&object, index, &["path"])?;
    validate_cemt_tree_patch_edit_path(index, &path)?;
    let (_value_key, value) = required_cemt_tree_patch_edit_value(
        &object,
        index,
        match operation {
            CemtTreePatchOperation::Wrap => &["wrapper", "value", "node"],
            _ => &["value", "node", "replacement"],
        },
    )?;
    validate_cemt_tree_patch_edit_value(index, operation, &value)?;
    Ok(CemtTreePatchEdit {
        operation,
        path,
        value,
    })
}

fn required_cemt_tree_patch_edit_string(
    object: &serde_json::Map<String, Value>,
    index: usize,
    keys: &[&str],
) -> Result<String, String> {
    let Some((key, value)) = keys
        .iter()
        .find_map(|key| object.get(*key).map(|value| (*key, value)))
    else {
        return Err(format!(
            "CEMT applyEdits edit {index} is missing `{}`",
            keys[0]
        ));
    };
    let Some(value) = value
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Err(format!(
            "CEMT applyEdits edit {index} expected `{key}` string, got {}",
            json_value_type_name(value)
        ));
    };
    Ok(value.to_owned())
}

fn required_cemt_tree_patch_edit_value(
    object: &serde_json::Map<String, Value>,
    index: usize,
    keys: &[&str],
) -> Result<(String, Value), String> {
    let mut found = keys
        .iter()
        .filter_map(|key| object.get(*key).map(|value| (*key, value)));
    let Some((key, value)) = found.next() else {
        return Err(format!(
            "CEMT applyEdits edit {index} is missing `{}`",
            keys[0]
        ));
    };
    if let Some((other_key, _)) = found.next() {
        return Err(format!(
            "CEMT applyEdits edit {index} has ambiguous value fields `{key}` and `{other_key}`"
        ));
    }
    Ok((key.to_owned(), value.clone()))
}

fn validate_cemt_tree_patch_edit_path(index: usize, path: &str) -> Result<(), String> {
    cemt_patch_path_segments(path, &format!("applyEdits edit {index}"))?;
    Ok(())
}

fn validate_cemt_tree_patch_edit_value(
    index: usize,
    operation: CemtTreePatchOperation,
    value: &Value,
) -> Result<(), String> {
    match operation {
        CemtTreePatchOperation::Wrap => {
            if !value.is_object() {
                return Err(format!(
                    "CEMT applyEdits edit {index} wrap expected object wrapper, got {}",
                    json_value_type_name(value)
                ));
            }
        }
        CemtTreePatchOperation::Append | CemtTreePatchOperation::Prepend => {
            if value.is_null() {
                return Err(format!(
                    "CEMT applyEdits edit {index} node value must not be null"
                ));
            }
        }
        CemtTreePatchOperation::Replace | CemtTreePatchOperation::Set => {}
    }
    Ok(())
}

fn resolve_cemt_with_stack_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "withStack")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 3 {
        return Ok(None);
    }
    let stack_name = parse_cemt_stack_binding_name_argument(&args[0])?;
    let mut stack = match value_bindings.get(&stack_name) {
        Some(Value::Array(items)) => items.clone(),
        Some(other) => {
            return Err(format!(
                "CEMT stack `{stack_name}` expected array binding, got {}",
                json_value_type_name(other)
            ))
        }
        None => Vec::new(),
    };
    push_cemt_stack_frame(
        &mut stack,
        stack_name.as_str(),
        resolve_encode_subject_expression_at_depth(
            &args[1],
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        .ok_or_else(|| format!("CEMT withStack frame for `{stack_name}` could not be resolved"))?,
    )?;

    let mut scoped_bindings =
        cemt_runtime_clone_bindings_excluding_names(value_bindings, &[stack_name.as_str()]);
    scoped_bindings.insert(stack_name, Value::Array(stack));
    resolve_encode_subject_expression_at_depth(
        &args[2],
        &scoped_bindings,
        runtime_functions,
        binding,
        call_depth,
    )
}

