fn resolve_cemt_substring_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "substring")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 && args.len() != 3 {
        return Ok(None);
    }
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(start) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let value = cemt_string_argument("substring", 0, value)?;
    let start = cemt_usize_number(&start).ok_or_else(|| {
        format!(
            "CEMT substring expected unsigned integer start, got {}",
            json_value_type_name(&start)
        )
    })?;
    let count = if let Some(count_arg) = args.get(2) {
        let Some(count) = resolve_encode_subject_expression_at_depth(
            count_arg,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        Some(cemt_usize_number(&count).ok_or_else(|| {
            format!(
                "CEMT substring expected unsigned integer count, got {}",
                json_value_type_name(&count)
            )
        })?)
    } else {
        None
    };
    let chars = value.chars().skip(start);
    let output = match count {
        Some(count) => chars.take(count).collect::<String>(),
        None => chars.collect::<String>(),
    };
    Ok(Some(Value::String(output)))
}

fn resolve_cemt_index_of_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "indexOf").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(needle) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let value = cemt_string_argument("indexOf", 0, value)?;
    let needle = cemt_string_argument("indexOf", 1, needle)?;
    if needle.is_empty() {
        return Ok(Some(Value::Number(serde_json::Number::from(0))));
    }
    let index = value
        .find(&needle)
        .map(|byte_index| value[..byte_index].chars().count() as i64)
        .unwrap_or(-1);
    Ok(Some(Value::Number(serde_json::Number::from(index))))
}

