fn resolve_cemt_repeat_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "repeat").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(count) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(value) = value.as_str() else {
        return Err(format!(
            "CEMT repeat expected string value, got {}",
            json_value_type_name(&value)
        ));
    };
    let count = cemt_usize_number(&count).ok_or_else(|| {
        format!(
            "CEMT repeat expected unsigned integer count, got {}",
            json_value_type_name(&count)
        )
    })?;
    if count > CEMT_RUNTIME_REPEAT_LIMIT {
        return Err(format!(
            "CEMT repeat exceeded count limit {CEMT_RUNTIME_REPEAT_LIMIT}"
        ));
    }
    Ok(Some(Value::String(value.repeat(count))))
}

fn resolve_cemt_source_map_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "sourceMap")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(function_name) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(function_name) = function_name
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Err(format!(
            "CEMT sourceMap expected non-empty string function name, got {}",
            json_value_type_name(&function_name)
        ));
    };
    let source_map = transform_template_first_cem_tree_source_map(&value);
    Ok(Some(
        transform_template_cem_tree_transform_source_map_value(source_map.as_ref(), function_name)
            .unwrap_or(Value::Null),
    ))
}

fn cemt_i64_number(value: &Value) -> Option<i64> {
    value
        .as_i64()
        .or_else(|| value.as_u64().and_then(|value| i64::try_from(value).ok()))
}

fn cemt_usize_number(value: &Value) -> Option<usize> {
    value.as_u64().and_then(|value| usize::try_from(value).ok())
}

fn resolve_cemt_drain_queue_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "drainQueue")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 3 {
        return Ok(None);
    }
    let Some(queue) = resolve_cemt_queue_argument(
        &args[0],
        "drainQueue",
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(mut accumulator) = resolve_encode_subject_expression_at_depth(
        &args[1],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };

    for (index, item) in queue.iter().cloned().enumerate() {
        let mut scoped_bindings = cemt_runtime_clone_bindings_excluding_names(
            value_bindings,
            &["item", "index", "acc", "accumulator", "queue"],
        );
        scoped_bindings.insert("item".to_owned(), item);
        scoped_bindings.insert(
            "index".to_owned(),
            Value::Number(serde_json::Number::from(index as u64)),
        );
        scoped_bindings.insert("acc".to_owned(), accumulator.clone());
        scoped_bindings.insert("accumulator".to_owned(), accumulator);
        scoped_bindings.insert(
            "queue".to_owned(),
            Value::Array(queue[index + 1..].to_vec()),
        );
        let Some(next) = resolve_encode_subject_expression_at_depth(
            &args[2],
            &scoped_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        accumulator = next;
    }

    Ok(Some(accumulator))
}

fn resolve_cemt_queue_argument(
    expression: &str,
    owner: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Vec<Value>>, String> {
    let Some(value) = resolve_encode_subject_expression_at_depth(
        expression,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Value::Array(items) = value else {
        return Err(format!(
            "CEMT {owner} expected array queue, got {}",
            json_value_type_name(&value)
        ));
    };
    Ok(Some(items))
}

fn push_cemt_queue_item(queue: &mut Vec<Value>, owner: &str, item: Value) -> Result<(), String> {
    if queue.len() >= CEMT_RUNTIME_QUEUE_LENGTH_LIMIT {
        return Err(format!(
            "CEMT queue `{owner}` exceeded length limit {CEMT_RUNTIME_QUEUE_LENGTH_LIMIT}"
        ));
    }
    queue.push(item);
    Ok(())
}

fn resolve_cemt_diagnostic_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "diagnostic")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };

    match args.len() {
        1 => {
            let Some(value) = resolve_encode_subject_expression_at_depth(
                &args[0],
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )?
            else {
                return Ok(None);
            };
            let Value::Object(object) = value else {
                return Err(format!(
                    "CEMT diagnostic expected object argument, got {}",
                    json_value_type_name(&value)
                ));
            };
            Ok(Some(Value::Object(normalize_cemt_diagnostic_object(
                object,
            )?)))
        }
        3 => {
            let Some(code) = resolve_cemt_diagnostic_string_argument(
                &args[0],
                "code",
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )?
            else {
                return Ok(None);
            };
            let Some(severity) = resolve_cemt_diagnostic_string_argument(
                &args[1],
                "severity",
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )?
            else {
                return Ok(None);
            };
            let Some(message) = resolve_cemt_diagnostic_string_argument(
                &args[2],
                "message",
                value_bindings,
                runtime_functions,
                binding,
                call_depth,
            )?
            else {
                return Ok(None);
            };
            let severity = normalize_cemt_diagnostic_severity(&severity)?;
            let mut object = serde_json::Map::new();
            object.insert("code".to_owned(), Value::String(code));
            object.insert("severity".to_owned(), Value::String(severity));
            object.insert("message".to_owned(), Value::String(message));
            Ok(Some(Value::Object(object)))
        }
        _ => Ok(None),
    }
}

fn resolve_cemt_diagnostics_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) = parse_cemt_function_call_args(expression, "diagnostics")
        .map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 1 {
        return Ok(None);
    }
    let Some(value) = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };

    let diagnostics = match value {
        Value::Array(items) => normalize_cemt_diagnostic_array(items)?,
        Value::Object(mut object) if object.contains_key("diagnostics") => {
            let Some(items) = object.get("diagnostics").and_then(Value::as_array) else {
                return Err("CEMT diagnostics expected `diagnostics` array".to_owned());
            };
            let diagnostics = normalize_cemt_diagnostic_array(items.clone())?;
            object.insert("diagnostics".to_owned(), Value::Array(diagnostics));
            return Ok(Some(Value::Object(object)));
        }
        Value::Object(object) => vec![Value::Object(normalize_cemt_diagnostic_object(object)?)],
        other => {
            return Err(format!(
                "CEMT diagnostics expected diagnostic object or array, got {}",
                json_value_type_name(&other)
            ))
        }
    };

    let mut object = serde_json::Map::new();
    object.insert("diagnostics".to_owned(), Value::Array(diagnostics));
    Ok(Some(Value::Object(object)))
}

fn resolve_cemt_diagnostic_string_argument(
    expression: &str,
    field: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<String>, String> {
    let Some(value) = resolve_encode_subject_expression_at_depth(
        expression,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    cemt_required_diagnostic_string_value(&value, field).map(Some)
}

fn normalize_cemt_diagnostic_array(items: Vec<Value>) -> Result<Vec<Value>, String> {
    items
        .into_iter()
        .enumerate()
        .map(|(index, item)| {
            let Value::Object(object) = item else {
                return Err(format!(
                    "CEMT diagnostics expected diagnostic object at index {index}, got {}",
                    json_value_type_name(&item)
                ));
            };
            Ok(Value::Object(normalize_cemt_diagnostic_object(object)?))
        })
        .collect()
}

fn normalize_cemt_diagnostic_object(
    mut object: serde_json::Map<String, Value>,
) -> Result<serde_json::Map<String, Value>, String> {
    let code = cemt_required_diagnostic_string_field(&object, "code")?;
    let message = cemt_required_diagnostic_string_field(&object, "message")?;
    let severity = cemt_optional_diagnostic_string_field(&object, "severity")?
        .map(|value| normalize_cemt_diagnostic_severity(&value))
        .transpose()?
        .unwrap_or_else(|| "info".to_owned());

    object.insert("code".to_owned(), Value::String(code));
    object.insert("severity".to_owned(), Value::String(severity));
    object.insert("message".to_owned(), Value::String(message));

    for field in ["uri", "node"] {
        if let Some(value) = cemt_optional_diagnostic_string_field(&object, field)? {
            object.insert(field.to_owned(), Value::String(value));
        }
    }
    for field in ["line", "column", "byteOffset"] {
        if let Some(value) = cemt_optional_diagnostic_u64_field(&object, field)? {
            object.insert(
                field.to_owned(),
                Value::Number(serde_json::Number::from(value)),
            );
        }
    }

    Ok(object)
}

fn cemt_required_diagnostic_string_field(
    object: &serde_json::Map<String, Value>,
    field: &str,
) -> Result<String, String> {
    let Some(value) = object.get(field) else {
        return Err(format!("CEMT diagnostic missing `{field}`"));
    };
    cemt_required_diagnostic_string_value(value, field)
}

fn cemt_required_diagnostic_string_value(value: &Value, field: &str) -> Result<String, String> {
    value
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .ok_or_else(|| {
            format!(
                "CEMT diagnostic `{field}` expected non-empty string, got {}",
                json_value_type_name(value)
            )
        })
}

fn cemt_optional_diagnostic_string_field(
    object: &serde_json::Map<String, Value>,
    field: &str,
) -> Result<Option<String>, String> {
    let Some(value) = object.get(field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    cemt_required_diagnostic_string_value(value, field).map(Some)
}

fn cemt_optional_diagnostic_u64_field(
    object: &serde_json::Map<String, Value>,
    field: &str,
) -> Result<Option<u64>, String> {
    let Some(value) = object.get(field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    value.as_u64().map(Some).ok_or_else(|| {
        format!(
            "CEMT diagnostic `{field}` expected unsigned integer, got {}",
            json_value_type_name(value)
        )
    })
}

fn normalize_cemt_diagnostic_severity(value: &str) -> Result<String, String> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "info" | "warning" | "error" | "fatal" => Ok(normalized),
        _ => Err(format!(
            "CEMT diagnostic severity expected one of info, warning, error, fatal, got `{value}`"
        )),
    }
}

fn resolve_cemt_patch_path_argument(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<String>, String> {
    resolve_cemt_patch_path_argument_for_owner(
        expression,
        "set",
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )
}

fn resolve_cemt_patch_path_argument_for_owner(
    expression: &str,
    owner: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<String>, String> {
    let literal = parse_cemt_literal(expression).map_err(|error| error.to_string())?;
    let Some(value) = resolve_cemt_literal_runtime_value(
        &literal,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    else {
        return Ok(None);
    };
    let Some(path) = value
        .as_str()
        .map(str::trim)
        .filter(|path| !path.is_empty())
    else {
        return Err(format!(
            "CEMT {owner} expected string path, got {}",
            json_value_type_name(&value)
        ));
    };
    Ok(Some(path.to_owned()))
}

fn set_cemt_value_path(target: &mut Value, path: &str, value: Value) -> Result<(), String> {
    set_cemt_value_path_with_owner(target, path, value, "set")
}

fn set_cemt_value_path_with_owner(
    target: &mut Value,
    path: &str,
    value: Value,
    owner: &str,
) -> Result<(), String> {
    let segments: Vec<&str> = path
        .split('.')
        .map(str::trim)
        .filter(|segment| !segment.is_empty())
        .collect();
    if segments.is_empty() {
        return Err(format!(
            "CEMT {owner} path must contain at least one segment"
        ));
    }
    set_cemt_value_path_segments(target, &segments, path, value, owner)
}

fn set_cemt_value_path_segments(
    target: &mut Value,
    segments: &[&str],
    original_path: &str,
    value: Value,
    owner: &str,
) -> Result<(), String> {
    let (segment, rest) = segments
        .split_first()
        .expect("set path segments are checked before recursion");
    match target {
        Value::Object(object) => {
            if rest.is_empty() {
                object.insert((*segment).to_owned(), value);
                return Ok(());
            }
            let child = object
                .entry((*segment).to_owned())
                .or_insert_with(|| Value::Object(serde_json::Map::new()));
            if !child.is_object() && !child.is_array() {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` crosses non-container field `{segment}`"
                ));
            }
            set_cemt_value_path_segments(child, rest, original_path, value, owner)
        }
        Value::Array(items) => {
            let index = segment.parse::<usize>().map_err(|_| {
                format!("CEMT {owner} path `{original_path}` expected array index, got `{segment}`")
            })?;
            let Some(child) = items.get_mut(index) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` index `{index}` is out of bounds"
                ));
            };
            if rest.is_empty() {
                *child = value;
                return Ok(());
            }
            set_cemt_value_path_segments(child, rest, original_path, value, owner)
        }
        other => Err(format!(
            "CEMT {owner} expected object or array target, got {}",
            json_value_type_name(other)
        )),
    }
}

fn apply_cemt_tree_patch_operation(
    target: &mut Value,
    operation: CemtTreePatchOperation,
    path: &str,
    mut value: Value,
    owner: &str,
    binding: Option<&TransformTemplateEncodeBinding>,
) -> Result<(), String> {
    match operation {
        CemtTreePatchOperation::Set => {
            apply_cemt_patch_value_source_map_default(&mut value, target, owner, binding);
            set_cemt_value_path_with_owner(target, path, value, owner)
        }
        CemtTreePatchOperation::Replace => {
            apply_cemt_patch_value_source_map_default(&mut value, target, owner, binding);
            replace_cemt_value_path(target, path, value, owner)
        }
        CemtTreePatchOperation::Append => {
            apply_cemt_patch_value_source_map_default(&mut value, target, owner, binding);
            insert_cemt_array_value_path(target, path, value, CemtArrayInsertPosition::Back, owner)
        }
        CemtTreePatchOperation::Prepend => {
            apply_cemt_patch_value_source_map_default(&mut value, target, owner, binding);
            insert_cemt_array_value_path(target, path, value, CemtArrayInsertPosition::Front, owner)
        }
        CemtTreePatchOperation::Wrap => wrap_cemt_value_path(target, path, value, owner, binding),
    }
}

fn apply_cemt_patch_value_source_map_default(
    value: &mut Value,
    target: &Value,
    owner: &str,
    binding: Option<&TransformTemplateEncodeBinding>,
) {
    let Value::Object(fields) = value else {
        return;
    };
    if fields.contains_key("sourceMap") {
        return;
    }
    let source_map = transform_template_first_cem_tree_source_map(target)
        .or_else(|| transform_template_first_cem_tree_source_map(&Value::Object(fields.clone())));
    let Some(source_map) = source_map else {
        return;
    };
    let function = cemt_tree_patch_source_map_function_name(fields, owner, binding);
    if let Some(source_map) =
        transform_template_cem_tree_transform_source_map_value(Some(&source_map), &function)
    {
        fields.insert("sourceMap".to_owned(), source_map);
    }
}

fn cemt_patch_path_segments<'a>(path: &'a str, owner: &str) -> Result<Vec<&'a str>, String> {
    let path = path.trim();
    if path.is_empty() {
        return Err(format!(
            "CEMT {owner} path must contain at least one segment"
        ));
    }
    let mut segments = Vec::new();
    for segment in path.split('.') {
        let segment = segment.trim();
        if segment.is_empty() {
            return Err(format!(
                "CEMT {owner} path `{path}` contains an empty segment"
            ));
        }
        segments.push(segment);
    }
    Ok(segments)
}

fn replace_cemt_value_path(
    target: &mut Value,
    path: &str,
    value: Value,
    owner: &str,
) -> Result<(), String> {
    let segments = cemt_patch_path_segments(path, owner)?;
    replace_cemt_value_path_segments(target, &segments, path, value, owner)
}

fn replace_cemt_value_path_segments(
    target: &mut Value,
    segments: &[&str],
    original_path: &str,
    value: Value,
    owner: &str,
) -> Result<(), String> {
    let (segment, rest) = segments
        .split_first()
        .expect("replace path segments are checked before recursion");
    match target {
        Value::Object(object) => {
            let Some(child) = object.get_mut(*segment) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` missing field `{segment}`"
                ));
            };
            if rest.is_empty() {
                *child = value;
                return Ok(());
            }
            if !child.is_object() && !child.is_array() {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` crosses non-container field `{segment}`"
                ));
            }
            replace_cemt_value_path_segments(child, rest, original_path, value, owner)
        }
        Value::Array(items) => {
            let index = segment.parse::<usize>().map_err(|_| {
                format!("CEMT {owner} path `{original_path}` expected array index, got `{segment}`")
            })?;
            let Some(child) = items.get_mut(index) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` index `{index}` is out of bounds"
                ));
            };
            if rest.is_empty() {
                *child = value;
                return Ok(());
            }
            replace_cemt_value_path_segments(child, rest, original_path, value, owner)
        }
        other => Err(format!(
            "CEMT {owner} expected object or array target, got {}",
            json_value_type_name(other)
        )),
    }
}

#[derive(Debug, Clone, Copy)]
enum CemtArrayInsertPosition {
    Front,
    Back,
}

fn insert_cemt_array_value_path(
    target: &mut Value,
    path: &str,
    value: Value,
    position: CemtArrayInsertPosition,
    owner: &str,
) -> Result<(), String> {
    let segments = cemt_patch_path_segments(path, owner)?;
    let items = cemt_array_value_path_mut(target, &segments, path, owner)?;
    match position {
        CemtArrayInsertPosition::Front => items.insert(0, value),
        CemtArrayInsertPosition::Back => items.push(value),
    }
    Ok(())
}

fn cemt_array_value_path_mut<'a>(
    target: &'a mut Value,
    segments: &[&str],
    original_path: &str,
    owner: &str,
) -> Result<&'a mut Vec<Value>, String> {
    let (segment, rest) = segments
        .split_first()
        .expect("array path segments are checked before recursion");
    match target {
        Value::Object(object) => {
            let child = if rest.is_empty() {
                object
                    .entry((*segment).to_owned())
                    .or_insert_with(|| Value::Array(Vec::new()))
            } else {
                object
                    .entry((*segment).to_owned())
                    .or_insert_with(|| Value::Object(serde_json::Map::new()))
            };
            if rest.is_empty() {
                return match child {
                    Value::Array(items) => Ok(items),
                    other => Err(format!(
                        "CEMT {owner} path `{original_path}` expected array field `{segment}`, got {}",
                        json_value_type_name(other)
                    )),
                };
            }
            if !child.is_object() && !child.is_array() {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` crosses non-container field `{segment}`"
                ));
            }
            cemt_array_value_path_mut(child, rest, original_path, owner)
        }
        Value::Array(items) => {
            let index = segment.parse::<usize>().map_err(|_| {
                format!("CEMT {owner} path `{original_path}` expected array index, got `{segment}`")
            })?;
            let Some(child) = items.get_mut(index) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` index `{index}` is out of bounds"
                ));
            };
            if rest.is_empty() {
                return match child {
                    Value::Array(items) => Ok(items),
                    other => Err(format!(
                        "CEMT {owner} path `{original_path}` expected array at index `{index}`, got {}",
                        json_value_type_name(other)
                    )),
                };
            }
            cemt_array_value_path_mut(child, rest, original_path, owner)
        }
        other => Err(format!(
            "CEMT {owner} expected object or array target, got {}",
            json_value_type_name(other)
        )),
    }
}

fn wrap_cemt_value_path(
    target: &mut Value,
    path: &str,
    wrapper: Value,
    owner: &str,
    binding: Option<&TransformTemplateEncodeBinding>,
) -> Result<(), String> {
    let mut wrapper = match wrapper {
        Value::Object(wrapper) => wrapper,
        other => {
            return Err(format!(
                "CEMT {owner} expected object wrapper, got {}",
                json_value_type_name(&other)
            ))
        }
    };
    let wrapped = clone_cemt_existing_value_path(target, path, owner)?;
    apply_cemt_wrapper_source_map_default(&mut wrapper, &wrapped, owner, binding);
    let wrapper = cemt_wrap_node_value(wrapper, wrapped, owner)?;
    replace_cemt_value_path(target, path, wrapper, owner)
}

fn apply_cemt_wrapper_source_map_default(
    wrapper: &mut serde_json::Map<String, Value>,
    wrapped: &Value,
    owner: &str,
    binding: Option<&TransformTemplateEncodeBinding>,
) {
    if wrapper.contains_key("sourceMap") {
        return;
    }
    let Some(source_map) = transform_template_first_cem_tree_source_map(wrapped) else {
        return;
    };
    let function = cemt_tree_patch_source_map_function_name(wrapper, owner, binding);
    if let Some(source_map) =
        transform_template_cem_tree_transform_source_map_value(Some(&source_map), &function)
    {
        wrapper.insert("sourceMap".to_owned(), source_map);
    }
}

fn cemt_tree_patch_source_map_function_name(
    wrapper: &serde_json::Map<String, Value>,
    owner: &str,
    binding: Option<&TransformTemplateEncodeBinding>,
) -> String {
    if let Some(binding) = binding {
        return binding.function.name.clone();
    }
    if wrapper.contains_key("colorRole")
        || wrapper.contains_key("colorizerRole")
        || wrapper.contains_key("colorWrapperNodes")
    {
        return "cem.color-tree".to_owned();
    }
    if wrapper.contains_key("formatterRole")
        || wrapper.contains_key("formatLayout")
        || wrapper.contains_key("formatNodes")
    {
        return "cem.format-tree".to_owned();
    }
    owner.to_owned()
}

fn cemt_wrap_node_value(
    mut wrapper: serde_json::Map<String, Value>,
    wrapped: Value,
    owner: &str,
) -> Result<Value, String> {
    match wrapper.entry("children".to_owned()) {
        serde_json::map::Entry::Vacant(entry) => {
            entry.insert(Value::Array(vec![wrapped]));
        }
        serde_json::map::Entry::Occupied(mut entry) => match entry.get_mut() {
            Value::Array(items) => items.push(wrapped),
            Value::Null => {
                *entry.get_mut() = Value::Array(vec![wrapped]);
            }
            other => {
                return Err(format!(
                    "CEMT {owner} expected wrapper `children` array, got {}",
                    json_value_type_name(other)
                ))
            }
        },
    }
    Ok(Value::Object(wrapper))
}

fn clone_cemt_existing_value_path(value: &Value, path: &str, owner: &str) -> Result<Value, String> {
    let segments = cemt_patch_path_segments(path, owner)?;
    clone_cemt_existing_value_path_segments(value, &segments, path, owner)
}

fn clone_cemt_existing_value_path_segments(
    value: &Value,
    segments: &[&str],
    original_path: &str,
    owner: &str,
) -> Result<Value, String> {
    let (segment, rest) = segments
        .split_first()
        .expect("clone path segments are checked before recursion");
    match value {
        Value::Object(object) => {
            let Some(child) = object.get(*segment) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` missing field `{segment}`"
                ));
            };
            if rest.is_empty() {
                return Ok(child.clone());
            }
            if !child.is_object() && !child.is_array() {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` crosses non-container field `{segment}`"
                ));
            }
            clone_cemt_existing_value_path_segments(child, rest, original_path, owner)
        }
        Value::Array(items) => {
            let index = segment.parse::<usize>().map_err(|_| {
                format!("CEMT {owner} path `{original_path}` expected array index, got `{segment}`")
            })?;
            let Some(child) = items.get(index) else {
                return Err(format!(
                    "CEMT {owner} path `{original_path}` index `{index}` is out of bounds"
                ));
            };
            if rest.is_empty() {
                return Ok(child.clone());
            }
            clone_cemt_existing_value_path_segments(child, rest, original_path, owner)
        }
        other => Err(format!(
            "CEMT {owner} expected object or array target, got {}",
            json_value_type_name(other)
        )),
    }
}

fn resolve_cemt_object_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let fields = match parse_cemt_object_literal(expression) {
        Ok(fields) => fields,
        Err(_) => return Ok(None),
    };
    let mut object = serde_json::Map::new();
    for (key, literal) in fields {
        let Some(value) = resolve_cemt_literal_runtime_value(
            &literal,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        object.insert(key, value);
    }
    Ok(Some(Value::Object(object)))
}

fn resolve_cemt_array_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let expression = expression.trim();
    if !expression.starts_with('[') {
        return Ok(None);
    }
    let end =
        matching_closing_delimiter(expression, 0, '[', ']').map_err(|error| error.to_string())?;
    if !expression[end + 1..].trim().is_empty() {
        return Ok(None);
    }
    let body = expression[1..end].trim();
    if body.is_empty() {
        return Ok(Some(Value::Array(Vec::new())));
    }

    let mut items = Vec::new();
    for item in split_top_level(body, ',').map_err(|error| error.to_string())? {
        let literal = parse_cemt_literal(&item).map_err(|error| error.to_string())?;
        let Some(value) = resolve_cemt_literal_runtime_value(
            &literal,
            value_bindings,
            runtime_functions,
            binding,
            call_depth,
        )?
        else {
            return Ok(None);
        };
        items.push(value);
    }
    Ok(Some(Value::Array(items)))
}

fn resolve_cemt_match_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "match").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 2 {
        return Ok(None);
    }
    let cases = parse_cemt_object_literal(&args[1]).map_err(|error| error.to_string())?;
    let selected = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    .and_then(|value| cemt_match_key(&value))
    .and_then(|key| cases.get(&key))
    .or_else(|| cases.get("default"))
    .or_else(|| cases.get("_"));
    let Some(selected) = selected else {
        return Ok(None);
    };

    resolve_cemt_literal_runtime_value(
        selected,
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )
}

fn resolve_cemt_exists_expression(
    expression: &str,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    let Some(args) =
        parse_cemt_function_call_args(expression, "exists").map_err(|error| error.to_string())?
    else {
        return Ok(None);
    };
    if args.len() != 1 {
        return Ok(None);
    }
    let exists = resolve_encode_subject_expression_at_depth(
        &args[0],
        value_bindings,
        runtime_functions,
        binding,
        call_depth,
    )?
    .is_some();
    Ok(Some(Value::Bool(exists)))
}

fn resolve_cemt_literal_runtime_value(
    literal: &CemtExpressionLiteral,
    value_bindings: &BTreeMap<String, Value>,
    runtime_functions: &BTreeMap<String, CemtRuntimeFunction>,
    binding: Option<&TransformTemplateEncodeBinding>,
    call_depth: usize,
) -> Result<Option<Value>, String> {
    match literal {
        CemtExpressionLiteral::String(value) => Ok(Some(Value::String(value.clone()))),
        CemtExpressionLiteral::Bool(value) => Ok(Some(Value::Bool(*value))),
        CemtExpressionLiteral::Number(value) => Ok(serde_json::from_str(value).ok()),
        CemtExpressionLiteral::Null => Ok(Some(Value::Null)),
        CemtExpressionLiteral::Bare(value) => {
            let value = value.trim();
            if cemt_runtime_expression_is_dynamic(value) {
                resolve_encode_subject_expression_at_depth(
                    value,
                    value_bindings,
                    runtime_functions,
                    binding,
                    call_depth,
                )
            } else if value.is_empty() {
                Ok(None)
            } else {
                Ok(Some(Value::String(value.to_owned())))
            }
        }
    }
}

fn cemt_match_key(value: &Value) -> Option<String> {
    match value {
        Value::Null => Some("null".to_owned()),
        Value::Bool(value) => Some(value.to_string()),
        Value::Number(value) => Some(value.to_string()),
        Value::String(value) => Some(value.clone()),
        Value::Array(_) | Value::Object(_) => None,
    }
}

fn cemt_runtime_expression_is_dynamic(value: &str) -> bool {
    let value = value.trim_start();
    value.starts_with('$')
        || cemt_expression_starts_with_call(value, "call")
        || cemt_expression_starts_with_call(value, "map")
        || cemt_expression_starts_with_call(value, "fold")
        || cemt_expression_starts_with_call(value, "append")
        || cemt_expression_starts_with_call(value, "extend")
        || cemt_expression_starts_with_call(value, "appendFormatNode")
        || cemt_expression_starts_with_call(value, "appendColorNode")
        || cemt_expression_starts_with_call(value, "appendDiagnostic")
        || cemt_expression_starts_with_call(value, "appendNamespace")
        || cemt_expression_starts_with_call(value, "appendOutputSpan")
        || cemt_expression_starts_with_call(value, "appendWriterBoundary")
        || cemt_expression_starts_with_call(value, "merge")
        || cemt_expression_starts_with_call(value, "set")
        || cemt_expression_starts_with_call(value, "replaceNode")
        || cemt_expression_starts_with_call(value, "appendNode")
        || cemt_expression_starts_with_call(value, "prependNode")
        || cemt_expression_starts_with_call(value, "wrapNode")
        || cemt_expression_starts_with_call(value, "applyEdits")
        || cemt_expression_starts_with_call(value, "setEdit")
        || cemt_expression_starts_with_call(value, "replaceEdit")
        || cemt_expression_starts_with_call(value, "appendEdit")
        || cemt_expression_starts_with_call(value, "prependEdit")
        || cemt_expression_starts_with_call(value, "wrapEdit")
        || cemt_expression_starts_with_call(value, "withStack")
        || cemt_expression_starts_with_call(value, "stackPush")
        || cemt_expression_starts_with_call(value, "stackPop")
        || cemt_expression_starts_with_call(value, "stackTop")
        || cemt_expression_starts_with_call(value, "stackDepth")
        || cemt_expression_starts_with_call(value, "stackPath")
        || cemt_expression_starts_with_call(value, "defer")
        || cemt_expression_starts_with_call(value, "queuePush")
        || cemt_expression_starts_with_call(value, "queueShift")
        || cemt_expression_starts_with_call(value, "queuePeek")
        || cemt_expression_starts_with_call(value, "queueLength")
        || cemt_expression_starts_with_call(value, "length")
        || cemt_expression_starts_with_call(value, "last")
        || cemt_expression_starts_with_call(value, "typeOf")
        || cemt_expression_starts_with_call(value, "add")
        || cemt_expression_starts_with_call(value, "sub")
        || cemt_expression_starts_with_call(value, "mul")
        || cemt_expression_starts_with_call(value, "div")
        || cemt_expression_starts_with_call(value, "min")
        || cemt_expression_starts_with_call(value, "max")
        || cemt_expression_starts_with_call(value, "lt")
        || cemt_expression_starts_with_call(value, "lte")
        || cemt_expression_starts_with_call(value, "gt")
        || cemt_expression_starts_with_call(value, "gte")
        || cemt_expression_starts_with_call(value, "mod")
        || cemt_expression_starts_with_call(value, "concat")
        || cemt_expression_starts_with_call(value, "get")
        || cemt_expression_starts_with_call(value, "contains")
        || cemt_expression_starts_with_call(value, "replace")
        || cemt_expression_starts_with_call(value, "trim")
        || cemt_expression_starts_with_call(value, "substring")
        || cemt_expression_starts_with_call(value, "indexOf")
        || cemt_expression_starts_with_call(value, "displayWidth")
        || cemt_expression_starts_with_call(value, "displayPrefix")
        || cemt_expression_starts_with_call(value, "displaySuffix")
        || cemt_expression_starts_with_call(value, "toInteger")
        || cemt_expression_starts_with_call(value, "toString")
        || cemt_expression_starts_with_call(value, "isAsciiInteger")
        || cemt_expression_starts_with_call(value, "isAsciiDecimal")
        || cemt_expression_starts_with_call(value, "startsWith")
        || cemt_expression_starts_with_call(value, "endsWith")
        || cemt_expression_starts_with_call(value, "repeat")
        || cemt_expression_starts_with_call(value, "sourceMap")
        || cemt_expression_starts_with_call(value, "drainQueue")
        || cemt_expression_starts_with_call(value, "diagnostic")
        || cemt_expression_starts_with_call(value, "diagnostics")
        || cemt_expression_starts_with_call(value, "match")
        || cemt_expression_starts_with_call(value, "exists")
        || value.starts_with('{')
        || value.starts_with('[')
}

fn cemt_expression_starts_with_call(expression: &str, name: &str) -> bool {
    let Some(rest) = expression.strip_prefix(name) else {
        return false;
    };
    if expression.len() > name.len()
        && expression[name.len()..]
            .chars()
            .next()
            .is_some_and(is_identifier_continue)
    {
        return false;
    }
    rest.trim_start().starts_with('(')
}

fn resolve_encode_subject_path<'a>(
    path: &str,
    value_bindings: &'a BTreeMap<String, Value>,
) -> Option<&'a Value> {
    let mut segments = path.split('.');
    let root = segments.next()?.trim();
    if root.is_empty() {
        return None;
    }
    let mut cursor = value_bindings.get(root)?;
    for segment in segments {
        let segment = segment.trim();
        if segment.is_empty() {
            return None;
        }
        cursor = match cursor {
            Value::Object(object) => object.get(segment)?,
            Value::Array(items) => items.get(segment.parse::<usize>().ok()?)?,
            _ => return None,
        };
    }
    Some(cursor)
}

fn resolve_cemt_value_path<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    let mut cursor = value;
    for segment in path.split('.') {
        let segment = segment.trim();
        if segment.is_empty() {
            return None;
        }
        cursor = match cursor {
            Value::Object(object) => object.get(segment)?,
            Value::Array(items) => items.get(segment.parse::<usize>().ok()?)?,
            _ => return None,
        };
    }
    Some(cursor)
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CemtExpressionLiteral {
    String(String),
    Bool(bool),
    Number(String),
    Null,
    Bare(String),
}

impl CemtExpressionLiteral {
    fn as_string(&self) -> Option<String> {
        match self {
            Self::String(value) | Self::Number(value) | Self::Bare(value) => Some(value.clone()),
            Self::Bool(value) => Some(value.to_string()),
            Self::Null => None,
        }
    }

    fn as_bool(&self) -> Option<bool> {
        match self {
            Self::Bool(value) => Some(*value),
            Self::String(value) | Self::Bare(value) => match value.trim() {
                "true" => Some(true),
                "false" => Some(false),
                _ => None,
            },
            _ => None,
        }
    }
}

type CemtFunctionCallArgsParseResult =
    Result<Option<Vec<String>>, TransformTemplateEncodeExpressionParseError>;
type CemtObjectLiteralParseResult =
    Result<BTreeMap<String, CemtExpressionLiteral>, TransformTemplateEncodeExpressionParseError>;

thread_local! {
    static CEMT_FUNCTION_CALL_ARG_CACHE: RefCell<BTreeMap<(String, String), CemtFunctionCallArgsParseResult>> =
        RefCell::new(BTreeMap::new());
    static CEMT_OBJECT_LITERAL_CACHE: RefCell<BTreeMap<String, CemtObjectLiteralParseResult>> =
        RefCell::new(BTreeMap::new());
}

fn cemt_expression_call_name(expression: &str) -> Option<&str> {
    let expression = expression.trim_start();
    let mut end = 0usize;
    for (index, ch) in expression.char_indices() {
        if index == 0 && !(ch.is_ascii_alphabetic() || ch == '_') {
            return None;
        }
        if is_identifier_continue(ch) {
            end = index + ch.len_utf8();
            continue;
        }
        return (end > 0 && expression[index..].trim_start().starts_with('('))
            .then_some(&expression[..end]);
    }
    None
}

fn parse_cemt_function_call_args(
    expression: &str,
    name: &str,
) -> Result<Option<Vec<String>>, TransformTemplateEncodeExpressionParseError> {
    let expression = expression.trim();
    let key = (expression.to_owned(), name.to_owned());
    if let Some(cached) =
        CEMT_FUNCTION_CALL_ARG_CACHE.with(|cache| cache.borrow().get(&key).cloned())
    {
        return cached;
    }

    let result = parse_cemt_function_call_args_uncached(expression, name);
    CEMT_FUNCTION_CALL_ARG_CACHE.with(|cache| {
        let mut cache = cache.borrow_mut();
        if cache.len() >= CEMT_RUNTIME_PARSE_CACHE_LIMIT {
            cache.clear();
        }
        cache.insert(key, result.clone());
    });
    result
}

fn parse_cemt_function_call_args_uncached(
    expression: &str,
    name: &str,
) -> Result<Option<Vec<String>>, TransformTemplateEncodeExpressionParseError> {
    let expression = expression.trim();
    let Some(mut rest) = expression.strip_prefix(name) else {
        return Ok(None);
    };
    if expression.len() > name.len()
        && expression[name.len()..]
            .chars()
            .next()
            .is_some_and(is_identifier_continue)
    {
        return Ok(None);
    }
    rest = rest.trim_start();
    if !rest.starts_with('(') {
        return Ok(None);
    }
    let end = matching_closing_delimiter(rest, 0, '(', ')')?;
    if !rest[end + 1..].trim().is_empty() {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "`encode` call has trailing expression content",
        ));
    }
    let inner = &rest[1..end];
    split_top_level(inner, ',').map(Some)
}

fn parse_cemt_object_literal(
    raw: &str,
) -> Result<BTreeMap<String, CemtExpressionLiteral>, TransformTemplateEncodeExpressionParseError> {
    let key = raw.trim().to_owned();
    if let Some(cached) = CEMT_OBJECT_LITERAL_CACHE.with(|cache| cache.borrow().get(&key).cloned())
    {
        return cached;
    }

    let result = parse_cemt_object_literal_uncached(&key);
    CEMT_OBJECT_LITERAL_CACHE.with(|cache| {
        let mut cache = cache.borrow_mut();
        if cache.len() >= CEMT_RUNTIME_PARSE_CACHE_LIMIT {
            cache.clear();
        }
        cache.insert(key, result.clone());
    });
    result
}

fn parse_cemt_object_literal_uncached(
    raw: &str,
) -> Result<BTreeMap<String, CemtExpressionLiteral>, TransformTemplateEncodeExpressionParseError> {
    let raw = raw.trim();
    if !raw.starts_with('{') {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "expected object literal",
        ));
    }
    let end = matching_closing_delimiter(raw, 0, '{', '}')?;
    if !raw[end + 1..].trim().is_empty() {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "object literal has trailing content",
        ));
    }

    let body = raw[1..end].trim();
    let mut fields = BTreeMap::new();
    if body.is_empty() {
        return Ok(fields);
    }

    for field in split_top_level(body, ',')? {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let Some(colon) = find_top_level_delimiter(field, ':')? else {
            return Err(TransformTemplateEncodeExpressionParseError::new(format!(
                "object field `{field}` is missing `:`"
            )));
        };
        let key = parse_cemt_object_key(&field[..colon])?;
        let value = parse_cemt_literal(&field[colon + 1..])?;
        fields.insert(key, value);
    }

    Ok(fields)
}

fn parse_cemt_encode_options(
    raw: &str,
) -> Result<TransformTemplateEncodeOptions, TransformTemplateEncodeExpressionParseError> {
    let fields = parse_cemt_object_literal(raw)?;
    let mut options = TransformTemplateEncodeOptions::default();

    if let Some(mode) = optional_object_string(&fields, &["mode"])? {
        match mode.as_str() {
            "canonical" => options.canonical = true,
            "preserve" => options.preserve = true,
            "pretty" => options.pretty = true,
            "fragment" => options.mode = TransformTemplateEncodedArtifactMode::Fragment,
            "document" => options.mode = TransformTemplateEncodedArtifactMode::Document,
            other => {
                return Err(TransformTemplateEncodeExpressionParseError::new(format!(
                    "unsupported `encode` mode `{other}`"
                )))
            }
        }
    }

    if let Some(value) = optional_object_bool(&fields, &["canonical"])? {
        options.canonical = value;
    }
    if let Some(value) = optional_object_bool(&fields, &["preserve"])? {
        options.preserve = value;
    }
    if let Some(value) = optional_object_bool(&fields, &["pretty"])? {
        options.pretty = value;
    }
    if let Some(value) = optional_object_bool(&fields, &["raw", "rawOutput", "raw-output"])? {
        options.raw = value;
    }
    if let Some(value) = optional_object_bool(&fields, &["allowLossy", "allow-lossy"])? {
        options.allow_lossy = value;
    }
    options.encoder = optional_object_string(&fields, &["encoder"])?;
    options.formatter = optional_object_string(&fields, &["formatter"])?;
    options.colorizer = optional_object_string(&fields, &["colorizer"])?;
    options.profile = optional_object_string(&fields, &["profile"])?;
    options.formatter_profile =
        optional_object_string(&fields, &["formatterProfile", "formatter-profile"])?;
    options.color_profile = optional_object_string(&fields, &["colorProfile", "color-profile"])?;
    options.charset = optional_object_string(&fields, &["charset"])?;
    options.line_ending = optional_object_string(&fields, &["lineEnding", "line-ending"])?;
    options.quote_policy =
        optional_object_string(&fields, &["quote", "quotePolicy", "quote-policy"])?;
    options.ordering =
        optional_object_string(&fields, &["ordering", "order", "keyOrder", "key-order"])?;
    options.wrap_column = optional_object_string(&fields, &["wrap", "wrapColumn", "wrap-column"])?;
    options.indent = optional_object_string_preserve(&fields, &["indent"])?;
    options.tab_size = optional_object_string(&fields, &["tabSize", "tab-size"])?;
    options.namespace_policy =
        optional_object_string(&fields, &["namespacePolicy", "namespace-policy"])?;
    options.namespace_placement = optional_object_string(
        &fields,
        &[
            "namespacePlacement",
            "namespace-placement",
            "namespaceDeclarationPlacement",
            "namespace-declaration-placement",
        ],
    )?;
    options.binary_framing = optional_object_string(&fields, &["binaryFraming", "binary-framing"])?;

    if let Some(source_map) = optional_object_string(&fields, &["sourceMap", "source-map"])? {
        options.source_map_policy = match source_map.as_str() {
            "preserve" => TransformTemplateSourceMapPolicy::Preserve,
            "generated" => TransformTemplateSourceMapPolicy::Generated,
            "none" => TransformTemplateSourceMapPolicy::None,
            other => {
                return Err(TransformTemplateEncodeExpressionParseError::new(format!(
                    "unsupported `encode` sourceMap policy `{other}`"
                )))
            }
        };
    }

    Ok(options)
}

fn required_object_string(
    fields: &BTreeMap<String, CemtExpressionLiteral>,
    keys: &[&str],
    owner: &str,
) -> Result<String, TransformTemplateEncodeExpressionParseError> {
    optional_object_string(fields, keys)?.ok_or_else(|| {
        TransformTemplateEncodeExpressionParseError::new(format!(
            "{owner} is missing required `{}` field",
            keys[0]
        ))
    })
}

fn optional_object_string(
    fields: &BTreeMap<String, CemtExpressionLiteral>,
    keys: &[&str],
) -> Result<Option<String>, TransformTemplateEncodeExpressionParseError> {
    let Some(value) = keys.iter().find_map(|key| fields.get(*key)) else {
        return Ok(None);
    };
    Ok(value
        .as_string()
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty()))
}

fn optional_object_string_preserve(
    fields: &BTreeMap<String, CemtExpressionLiteral>,
    keys: &[&str],
) -> Result<Option<String>, TransformTemplateEncodeExpressionParseError> {
    let Some(value) = keys.iter().find_map(|key| fields.get(*key)) else {
        return Ok(None);
    };
    Ok(value.as_string())
}

fn optional_object_bool(
    fields: &BTreeMap<String, CemtExpressionLiteral>,
    keys: &[&str],
) -> Result<Option<bool>, TransformTemplateEncodeExpressionParseError> {
    let Some((key, value)) = keys
        .iter()
        .find_map(|key| fields.get(*key).map(|value| (*key, value)))
    else {
        return Ok(None);
    };
    value.as_bool().map(Some).ok_or_else(|| {
        TransformTemplateEncodeExpressionParseError::new(format!(
            "`{key}` must be `true` or `false`"
        ))
    })
}

fn parse_cemt_object_key(raw: &str) -> Result<String, TransformTemplateEncodeExpressionParseError> {
    let raw = raw.trim();
    if raw.is_empty() {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "object field key is empty",
        ));
    }
    if raw.starts_with('"') || raw.starts_with('\'') {
        let literal = parse_cemt_literal(raw)?;
        return literal.as_string().ok_or_else(|| {
            TransformTemplateEncodeExpressionParseError::new("object field key must be a string")
        });
    }
    Ok(raw.to_owned())
}

fn parse_cemt_literal(
    raw: &str,
) -> Result<CemtExpressionLiteral, TransformTemplateEncodeExpressionParseError> {
    let raw = raw.trim();
    if raw.is_empty() {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "object field value is empty",
        ));
    }
    if raw.starts_with('"') || raw.starts_with('\'') {
        return parse_cemt_quoted_string(raw).map(CemtExpressionLiteral::String);
    }
    match raw {
        "true" => Ok(CemtExpressionLiteral::Bool(true)),
        "false" => Ok(CemtExpressionLiteral::Bool(false)),
        "null" => Ok(CemtExpressionLiteral::Null),
        _ if raw.parse::<f64>().is_ok() => Ok(CemtExpressionLiteral::Number(raw.to_owned())),
        _ => Ok(CemtExpressionLiteral::Bare(raw.to_owned())),
    }
}

fn parse_cemt_quoted_string(
    raw: &str,
) -> Result<String, TransformTemplateEncodeExpressionParseError> {
    let mut chars = raw.chars();
    let quote = chars
        .next()
        .expect("quoted string parser is called after quote check");
    let mut value = String::new();
    let mut escaped = false;
    let mut closed_at = None;
    for (index, ch) in raw.char_indices().skip(1) {
        if escaped {
            value.push(match ch {
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                other => other,
            });
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        if ch == quote {
            closed_at = Some(index);
            break;
        }
        value.push(ch);
    }
    let Some(closed_at) = closed_at else {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "quoted string is not closed",
        ));
    };
    if !raw[closed_at + quote.len_utf8()..].trim().is_empty() {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "quoted string has trailing content",
        ));
    }
    Ok(value)
}

fn split_top_level(
    raw: &str,
    delimiter: char,
) -> Result<Vec<String>, TransformTemplateEncodeExpressionParseError> {
    let mut parts = Vec::new();
    let mut start = 0usize;
    let mut quote = None;
    let mut escaped = false;
    let mut paren_depth = 0i32;
    let mut brace_depth = 0i32;
    let mut bracket_depth = 0i32;

    for (index, ch) in raw.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        match ch {
            '"' | '\'' => quote = Some(ch),
            '(' => paren_depth += 1,
            ')' => paren_depth -= 1,
            '{' => brace_depth += 1,
            '}' => brace_depth -= 1,
            '[' => bracket_depth += 1,
            ']' => bracket_depth -= 1,
            _ if ch == delimiter && paren_depth == 0 && brace_depth == 0 && bracket_depth == 0 => {
                parts.push(raw[start..index].trim().to_owned());
                start = index + ch.len_utf8();
            }
            _ => {}
        }
        if paren_depth < 0 || brace_depth < 0 || bracket_depth < 0 {
            return Err(TransformTemplateEncodeExpressionParseError::new(
                "expression delimiters are unbalanced",
            ));
        }
    }

    if quote.is_some() || paren_depth != 0 || brace_depth != 0 || bracket_depth != 0 {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "expression delimiters are unbalanced",
        ));
    }

    parts.push(raw[start..].trim().to_owned());
    Ok(parts)
}

fn find_top_level_delimiter(
    raw: &str,
    delimiter: char,
) -> Result<Option<usize>, TransformTemplateEncodeExpressionParseError> {
    let mut quote = None;
    let mut escaped = false;
    let mut paren_depth = 0i32;
    let mut brace_depth = 0i32;
    let mut bracket_depth = 0i32;

    for (index, ch) in raw.char_indices() {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        match ch {
            '"' | '\'' => quote = Some(ch),
            '(' => paren_depth += 1,
            ')' => paren_depth -= 1,
            '{' => brace_depth += 1,
            '}' => brace_depth -= 1,
            '[' => bracket_depth += 1,
            ']' => bracket_depth -= 1,
            _ if ch == delimiter && paren_depth == 0 && brace_depth == 0 && bracket_depth == 0 => {
                return Ok(Some(index));
            }
            _ => {}
        }
        if paren_depth < 0 || brace_depth < 0 || bracket_depth < 0 {
            return Err(TransformTemplateEncodeExpressionParseError::new(
                "expression delimiters are unbalanced",
            ));
        }
    }

    if quote.is_some() || paren_depth != 0 || brace_depth != 0 || bracket_depth != 0 {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "expression delimiters are unbalanced",
        ));
    }

    Ok(None)
}

fn matching_closing_delimiter(
    raw: &str,
    open_index: usize,
    open: char,
    close: char,
) -> Result<usize, TransformTemplateEncodeExpressionParseError> {
    if !raw[open_index..].starts_with(open) {
        return Err(TransformTemplateEncodeExpressionParseError::new(
            "expression delimiter does not start at the requested index",
        ));
    }
    let mut quote = None;
    let mut escaped = false;
    let mut depth = 0i32;
    for (index, ch) in raw
        .char_indices()
        .skip_while(|(index, _)| *index < open_index)
    {
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        match ch {
            '"' | '\'' => quote = Some(ch),
            _ if ch == open => depth += 1,
            _ if ch == close => {
                depth -= 1;
                if depth == 0 {
                    return Ok(index);
                }
            }
            _ => {}
        }
    }
    Err(TransformTemplateEncodeExpressionParseError::new(
        "expression delimiter is not closed",
    ))
}

fn is_identifier_continue(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' || ch == '.'
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodedArtifactIdentity {
    pub produces: TransformTemplateOutputProducedKind,
    pub target: TransformTemplateEncodingTarget,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub charset: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub binary_framing: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub formatter_profile: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color_profile: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color_capability: Option<String>,
    #[serde(default)]
    pub mode: TransformTemplateEncodedArtifactMode,
    #[serde(default, skip_serializing_if = "is_false")]
    pub canonical: bool,
    #[serde(default)]
    pub source_map_policy: TransformTemplateSourceMapPolicy,
}

impl TransformTemplateEncodedArtifactIdentity {
    pub fn new(
        produces: TransformTemplateOutputProducedKind,
        target: TransformTemplateEncodingTarget,
    ) -> Self {
        Self {
            produces,
            target,
            charset: None,
            binary_framing: None,
            formatter_profile: None,
            color_profile: None,
            color_capability: None,
            mode: TransformTemplateEncodedArtifactMode::Document,
            canonical: false,
            source_map_policy: TransformTemplateSourceMapPolicy::Generated,
        }
    }

    pub fn from_options(
        produces: TransformTemplateOutputProducedKind,
        target: TransformTemplateEncodingTarget,
        options: &TransformTemplateEncodeOptions,
    ) -> Self {
        let formatter_profile =
            transform_template_encode_options_formatter_profile(&target, options);
        Self {
            produces,
            target,
            charset: options.charset.clone(),
            binary_framing: options.binary_framing.clone(),
            formatter_profile,
            color_profile: options
                .color_profile
                .clone()
                .or_else(|| options.profile.clone()),
            color_capability: None,
            mode: options.mode,
            canonical: !options.preserve && !options.pretty && options.canonical,
            source_map_policy: options.source_map_policy,
        }
    }

    pub fn format_identity(&self) -> FormatIdentity {
        self.target.format_identity()
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodedArtifact {
    pub identity: TransformTemplateEncodedArtifactIdentity,
    pub value: Value,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_map: Option<SourceMapStack>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub output_spans: Vec<OutputSpan>,
    #[serde(default = "default_true")]
    pub encoded: bool,
}

impl TransformTemplateEncodedArtifact {
    pub fn new(identity: TransformTemplateEncodedArtifactIdentity, value: Value) -> Self {
        Self {
            identity,
            value,
            source_map: None,
            output_spans: Vec::new(),
            encoded: true,
        }
    }

    pub fn from_writer_tokens(
        mut identity: TransformTemplateEncodedArtifactIdentity,
        tokens: Vec<TransformTemplateWriterToken>,
    ) -> Self {
        identity.produces = TransformTemplateOutputProducedKind::Tokens;
        Self::new(
            identity,
            serde_json::to_value(TransformTemplateWriterTokenStream { tokens })
                .expect("writer token stream serializes"),
        )
    }

    pub fn from_writer_bytes(
        mut identity: TransformTemplateEncodedArtifactIdentity,
        bytes: Vec<u8>,
    ) -> Self {
        identity.produces = TransformTemplateOutputProducedKind::Bytes;
        Self::new(
            identity,
            serde_json::to_value(TransformTemplateWriterByteStream::new(bytes))
                .expect("writer byte stream serializes"),
        )
    }

    pub fn from_writer_chunks(
        mut identity: TransformTemplateEncodedArtifactIdentity,
        chunks: Vec<TransformTemplateWriterChunk>,
    ) -> Self {
        identity.produces = TransformTemplateOutputProducedKind::Chunks;
        Self::new(
            identity,
            serde_json::to_value(TransformTemplateWriterChunkStream { chunks })
                .expect("writer chunk stream serializes"),
        )
    }

    pub fn from_writer_diagnostics(
        mut identity: TransformTemplateEncodedArtifactIdentity,
        diagnostics: Vec<Diagnostic>,
    ) -> Self {
        identity.produces = TransformTemplateOutputProducedKind::Diagnostics;
        Self::new(
            identity,
            serde_json::to_value(TransformTemplateWriterDiagnostics { diagnostics })
                .expect("writer diagnostics serialize"),
        )
    }

    pub fn validate_insertion(
        &self,
        context: &TransformTemplateEncodedArtifactInsertionContext,
    ) -> Result<(), TransformTemplateEncodedArtifactError> {
        if let Some(expected) = context.produces {
            if self.identity.produces != expected {
                return Err(
                    TransformTemplateEncodedArtifactError::ProducedKindMismatch {
                        expected,
                        actual: self.identity.produces,
                    },
                );
            }
        }

        validate_encoded_artifact_value_shape(self.identity.produces, &self.value)?;

        if !context.content_type.trim().is_empty()
            && content_type_essence(&self.identity.target.content_type)
                != content_type_essence(&context.content_type)
        {
            return Err(TransformTemplateEncodedArtifactError::IdentityMismatch {
                field: "contentType".to_owned(),
                expected: context.content_type.clone(),
                actual: self.identity.target.content_type.clone(),
            });
        }

        if !context.schema.trim().is_empty()
            && self.identity.target.schema.trim() != context.schema.trim()
        {
            return Err(TransformTemplateEncodedArtifactError::IdentityMismatch {
                field: "schema".to_owned(),
                expected: context.schema.clone(),
                actual: self.identity.target.schema.clone(),
            });
        }

        validate_optional_artifact_context(
            "category",
            context.category.as_deref(),
            Some(self.identity.target.category.as_str()),
        )?;
        validate_optional_artifact_context(
            "context",
            context.context.as_deref(),
            self.identity.target.context.as_deref(),
        )?;
        validate_optional_artifact_context(
            "formatterProfile",
            context.formatter_profile.as_deref(),
            self.identity.formatter_profile.as_deref(),
        )?;
        validate_optional_artifact_context(
            "colorProfile",
            context.color_profile.as_deref(),
            self.identity.color_profile.as_deref(),
        )?;
        validate_optional_artifact_context(
            "colorCapability",
            context.color_capability.as_deref(),
            self.identity.color_capability.as_deref(),
        )?;
        validate_optional_artifact_context(
            "binaryFraming",
            context.binary_framing.as_deref(),
            self.identity.binary_framing.as_deref(),
        )?;

        if let Some(expected) = context.mode {
            if self.identity.mode != expected {
                return Err(TransformTemplateEncodedArtifactError::ContextMismatch {
                    field: "mode".to_owned(),
                    expected: format!("{expected:?}"),
                    actual: format!("{:?}", self.identity.mode),
                });
            }
        }

        if let Some(expected) = context.canonical {
            if self.identity.canonical != expected {
                return Err(TransformTemplateEncodedArtifactError::ContextMismatch {
                    field: "canonical".to_owned(),
                    expected: expected.to_string(),
                    actual: self.identity.canonical.to_string(),
                });
            }
        }

        if let Some(expected) = context.source_map_policy {
            if self.identity.source_map_policy != expected {
                return Err(TransformTemplateEncodedArtifactError::ContextMismatch {
                    field: "sourceMapPolicy".to_owned(),
                    expected: expected.as_str().to_owned(),
                    actual: self.identity.source_map_policy.as_str().to_owned(),
                });
            }
        }

        Ok(())
    }

    pub fn validate_as_encode_input(&self) -> Result<(), TransformTemplateEncodedArtifactError> {
        if self.encoded {
            Err(TransformTemplateEncodedArtifactError::DoubleEncoding {
                content_type: self.identity.target.content_type.clone(),
                schema: self.identity.target.schema.clone(),
                category: self.identity.target.category.clone(),
                context: self.identity.target.context.clone(),
            })
        } else {
            Ok(())
        }
    }

    pub fn into_output_artifact(self, uri: Option<String>) -> TransformTemplateOutputArtifact {
        TransformTemplateOutputArtifact {
            uri,
            identity: Some(self.identity.format_identity()),
            value: self.value,
            source_map: self.source_map,
            output_spans: self.output_spans,
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateEncodedArtifactInsertionContext {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub produces: Option<TransformTemplateOutputProducedKind>,
    pub content_type: String,
    pub schema: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub context: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub formatter_profile: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color_profile: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color_capability: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output_color_type: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub binary_framing: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<TransformTemplateEncodedArtifactMode>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub canonical: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_map_policy: Option<TransformTemplateSourceMapPolicy>,
}

impl TransformTemplateEncodedArtifactInsertionContext {
    pub fn new(content_type: impl Into<String>, schema: impl Into<String>) -> Self {
        Self {
            content_type: content_type.into(),
            schema: schema.into(),
            ..Self::default()
        }
    }

    pub fn from_encoding_target(
        target: &TransformTemplateEncodingTarget,
        produces: Option<TransformTemplateOutputProducedKind>,
    ) -> Self {
        Self {
            produces,
            content_type: target.content_type.clone(),
            schema: target.schema.clone(),
            category: Some(target.category.clone()),
            context: target.context.clone(),
            ..Self::default()
        }
    }

    pub fn from_format_identity(identity: &FormatIdentity) -> Self {
        Self {
            content_type: identity.content_type.clone().unwrap_or_default(),
            schema: identity.schema.clone().unwrap_or_default(),
            ..Self::default()
        }
    }

    pub fn from_encoded_artifact_identity(
        identity: &TransformTemplateEncodedArtifactIdentity,
    ) -> Self {
        Self {
            produces: Some(identity.produces),
            content_type: identity.target.content_type.clone(),
            schema: identity.target.schema.clone(),
            category: Some(identity.target.category.clone()),
            context: identity.target.context.clone(),
            formatter_profile: identity.formatter_profile.clone(),
            color_profile: identity.color_profile.clone(),
            color_capability: identity.color_capability.clone(),
            output_color_type: None,
            binary_framing: identity.binary_framing.clone(),
            mode: Some(identity.mode),
            canonical: Some(identity.canonical),
            source_map_policy: Some(identity.source_map_policy),
        }
    }

    pub fn with_category(mut self, category: impl Into<String>) -> Self {
        self.category = Some(category.into());
        self
    }

    pub fn with_context(mut self, context: impl Into<String>) -> Self {
        self.context = Some(context.into());
        self
    }

    pub fn with_produces(mut self, produces: TransformTemplateOutputProducedKind) -> Self {
        self.produces = Some(produces);
        self
    }

    pub fn with_binary_framing(mut self, binary_framing: impl Into<String>) -> Self {
        self.binary_framing = Some(binary_framing.into());
        self
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TransformTemplateEncodedArtifactError {
    IdentityMismatch {
        field: String,
        expected: String,
        actual: String,
    },
    ContextMismatch {
        field: String,
        expected: String,
        actual: String,
    },
    ProducedKindMismatch {
        expected: TransformTemplateOutputProducedKind,
        actual: TransformTemplateOutputProducedKind,
    },
    ValueShapeMismatch {
        expected: String,
        actual: String,
    },
    DoubleEncoding {
        content_type: String,
        schema: String,
        category: String,
        context: Option<String>,
    },
}

impl TransformTemplateEncodedArtifactError {
    pub fn code(&self) -> &'static str {
        match self {
            Self::IdentityMismatch { .. } => {
                TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_IDENTITY_MISMATCH_CODE
            }
            Self::ContextMismatch { .. } => {
                TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_CONTEXT_MISMATCH_CODE
            }
            Self::ProducedKindMismatch { .. } => {
                TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_PRODUCED_KIND_MISMATCH_CODE
            }
            Self::ValueShapeMismatch { .. } => TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE,
            Self::DoubleEncoding { .. } => TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_DOUBLE_ENCODING_CODE,
        }
    }

    pub fn diagnostic(&self, uri: Option<&str>) -> Diagnostic {
        Diagnostic {
            uri: uri.map(str::to_owned),
            code: self.code().to_owned(),
            severity: Severity::Error,
            message: self.message(),
            details: None,
            ..Diagnostic::default()
        }
    }

    pub fn incompatible_insertion_diagnostic(&self, uri: Option<&str>) -> Diagnostic {
        Diagnostic {
            uri: uri.map(str::to_owned),
            code: TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_INSERTION_INCOMPATIBLE_CODE.to_owned(),
            severity: Severity::Error,
            message: format!(
                "encoded artifact insertion is incompatible: {}",
                self.message()
            ),
            details: None,
            ..Diagnostic::default()
        }
    }

    fn is_incompatible_insertion(&self) -> bool {
        !matches!(self, Self::DoubleEncoding { .. })
    }

    fn message(&self) -> String {
        match self {
            Self::IdentityMismatch {
                field,
                expected,
                actual,
            } => format!(
                "encoded artifact {field} `{actual}` is incompatible with insertion target `{expected}`"
            ),
            Self::ContextMismatch {
                field,
                expected,
                actual,
            } => format!(
                "encoded artifact {field} `{actual}` is incompatible with insertion context `{expected}`"
            ),
            Self::ProducedKindMismatch { expected, actual } => format!(
                "encoded artifact produced kind `{actual:?}` is incompatible with insertion target `{expected:?}`"
            ),
            Self::ValueShapeMismatch { expected, actual } => format!(
                "encoded artifact value shape expected {expected}, got {actual}"
            ),
            Self::DoubleEncoding {
                content_type,
                schema,
                category,
                context,
            } => {
                let context = context
                    .as_deref()
                    .map(|value| format!(" context `{value}`"))
                    .unwrap_or_default();
                format!(
                    "artifact for `{content_type}` schema `{schema}` category `{category}`{context} is already encoded"
                )
            }
        }
    }
}

fn validate_encoded_artifact_value_shape(
    produces: TransformTemplateOutputProducedKind,
    value: &Value,
) -> Result<(), TransformTemplateEncodedArtifactError> {
    let result = match produces {
        TransformTemplateOutputProducedKind::Text => {
            if value.is_string() {
                Ok(())
            } else {
                Err(format!("{}", json_value_type_name(value)))
            }
        }
        TransformTemplateOutputProducedKind::Bytes => validate_writer_byte_stream_value(value),
        TransformTemplateOutputProducedKind::CemTree => validate_cem_tree_value(value),
        TransformTemplateOutputProducedKind::Tokens => validate_writer_token_stream_value(value),
        TransformTemplateOutputProducedKind::Chunks => validate_writer_chunk_stream_value(value),
        TransformTemplateOutputProducedKind::Diagnostics => {
            validate_writer_diagnostics_value(value)
        }
    };

    result.map_err(
        |actual| TransformTemplateEncodedArtifactError::ValueShapeMismatch {
            expected: transform_template_produced_value_shape(produces).to_owned(),
            actual,
        },
    )
}

fn transform_template_produced_value_shape(
    produces: TransformTemplateOutputProducedKind,
) -> &'static str {
    match produces {
        TransformTemplateOutputProducedKind::Text => "string",
        TransformTemplateOutputProducedKind::Bytes => {
            "object with `encoding: \"u8-array\"`, `bytes`, and `byteLength`"
        }
        TransformTemplateOutputProducedKind::CemTree => {
            "object with `kind: \"cem-tree\"` and `nodes`, `node`, or `root`"
        }
        TransformTemplateOutputProducedKind::Tokens => "object with `tokens` array",
        TransformTemplateOutputProducedKind::Chunks => "object with `chunks` array",
        TransformTemplateOutputProducedKind::Diagnostics => "object with `diagnostics` array",
    }
}

fn validate_cem_tree_value(value: &Value) -> Result<(), String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{}", json_value_type_name(value)))?;
    let kind = object
        .get("kind")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|kind| !kind.is_empty())
        .ok_or_else(|| "`kind` missing or not a non-empty string".to_owned())?;
    if kind != "cem-tree" {
        return Err(format!("unsupported CEM tree kind `{kind}`"));
    }
    for field in ["contentType", "schema", "category"] {
        validate_optional_writer_string_field(object.get(field), field)?;
    }
    validate_cem_tree_pipeline_metadata(value, object)?;
    if let Some(nodes) = object.get("nodes") {
        if let Some(nodes) = nodes.as_array() {
            validate_cem_tree_writer_token_nodes(nodes, "nodes")?;
        } else {
            return Err(format!("`nodes` {}", json_value_type_name(nodes)));
        }
        return Ok(());
    }
    if let Some(node) = object.get("node") {
        if !node.is_object() {
            return Err(format!("`node` {}", json_value_type_name(node)));
        }
        return Ok(());
    }
    if let Some(root) = object.get("root") {
        if root.is_object() || root.is_array() {
            return Ok(());
        }
        return Err(format!("`root` {}", json_value_type_name(root)));
    }
    Err("missing `nodes`, `node`, or `root`".to_owned())
}

fn validate_cem_tree_writer_token_nodes(nodes: &[Value], field: &str) -> Result<(), String> {
    for (index, node) in nodes.iter().enumerate() {
        let Some(object) = node.as_object() else {
            continue;
        };
        if !transform_template_cem_tree_fields_are_writer_token(object) {
            continue;
        }
        let mut token = object.clone();
        if token.get("kind").and_then(Value::as_str) == Some("writer-token") {
            let token_kind = token
                .get("tokenKind")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    format!("`{field}[{index}]` writer-token node missing `tokenKind`")
                })?;
            token.insert("kind".to_owned(), Value::String(token_kind.to_owned()));
        }
        token.remove("writerKind");
        token.remove("writerNode");
        token.remove("tokenKind");
        let stream = serde_json::json!({ "tokens": [Value::Object(token)] });
        validate_writer_token_stream_value(&stream)
            .map_err(|message| format!("`{field}[{index}]` writer token is invalid: {message}"))?;
    }
    Ok(())
}

fn cem_tree_contains_writer_token_nodes(value: &Value) -> bool {
    fn contains(value: &Value) -> bool {
        match value {
            Value::Array(items) => items.iter().any(contains),
            Value::Object(fields) => {
                transform_template_cem_tree_fields_are_writer_token(fields)
                    || fields.values().any(contains)
            }
            _ => false,
        }
    }

    ["nodes", "node", "root"]
        .iter()
        .filter_map(|field| value.get(*field))
        .any(contains)
}

fn validate_cem_tree_pipeline_metadata(
    value: &Value,
    object: &serde_json::Map<String, Value>,
) -> Result<(), String> {
    if let Some(formatter_profile) = trimmed_value_string_field(value, "formatterProfile") {
        validate_cem_tree_formatter_metadata(value, formatter_profile)?;
    }

    let colored = match object.get("colored") {
        Some(Value::Bool(value)) => *value,
        Some(other) => {
            return Err(format!("`colored` {}", json_value_type_name(other)));
        }
        None => false,
    };
    let color_profile = trimmed_value_string_field(value, "colorProfile");
    if colored || color_profile.is_some() {
        if !colored {
            return Err(
                "colored CEM tree metadata requires `colored: true`; run `cem.color-tree` before validation"
                    .to_owned(),
            );
        }
        let color_profile = color_profile.ok_or_else(|| {
            "colored CEM tree metadata requires `colorProfile`; run `cem.color-tree` before validation"
                .to_owned()
        })?;
        validate_cem_tree_color_metadata(value, color_profile)?;
    }
    Ok(())
}

fn validate_writer_token_stream_value(value: &Value) -> Result<(), String> {
    let tokens = required_writer_array_field(value, "tokens")?;
    for (index, token) in tokens.iter().enumerate() {
        let object = token
            .as_object()
            .ok_or_else(|| format!("`tokens[{index}]` {}", json_value_type_name(token)))?;
        let kind = object
            .get("kind")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        if kind.is_none() {
            return Err(format!(
                "`tokens[{index}].kind` missing or not a non-empty string"
            ));
        }
        validate_optional_writer_string_field(
            object.get("text"),
            &format!("tokens[{index}].text"),
        )?;
        validate_optional_writer_string_field(
            object.get("role"),
            &format!("tokens[{index}].role"),
        )?;
        if let Some(style) = object.get("style") {
            validate_writer_token_style(style, &format!("tokens[{index}].style"))?;
        }
        if let Some(output_span) = object.get("outputSpan").filter(|value| !value.is_null()) {
            serde_json::from_value::<OutputSpan>(output_span.clone()).map_err(|error| {
                format!("`tokens[{index}].outputSpan` is not a valid output span: {error}")
            })?;
        }
        if !object.contains_key("text") && !object.contains_key("value") {
            return Err(format!("`tokens[{index}]` missing `text` or `value`"));
        }
    }
    Ok(())
}

fn validate_writer_token_style(value: &Value, field: &str) -> Result<(), String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("`{field}` {}", json_value_type_name(value)))?;
    for (name, value) in object {
        if name.trim().is_empty() {
            return Err(format!("`{field}` contains an empty style property name"));
        }
        if !(value.is_string() || value.is_boolean() || value.is_number()) {
            return Err(format!(
                "`{field}.{name}` must be a string, boolean, or number"
            ));
        }
    }
    Ok(())
}

fn validate_writer_byte_stream_value(value: &Value) -> Result<(), String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{}", json_value_type_name(value)))?;
    let encoding = object
        .get("encoding")
        .and_then(Value::as_str)
        .unwrap_or("u8-array");
    if encoding != "u8-array" {
        return Err(format!("unsupported byte stream encoding `{encoding}`"));
    }
    let bytes = required_writer_array_field(value, "bytes")?;
    validate_writer_byte_array(bytes, "bytes")?;
    match object.get("byteLength") {
        None => Ok(()),
        Some(length) if length.as_u64() == Some(bytes.len() as u64) => Ok(()),
        Some(length) => Err(format!(
            "`byteLength` {} does not match byte count `{}`",
            json_value_type_name(length),
            bytes.len()
        )),
    }
}

fn validate_writer_chunk_stream_value(value: &Value) -> Result<(), String> {
    let chunks = required_writer_array_field(value, "chunks")?;
    for (index, chunk) in chunks.iter().enumerate() {
        let object = chunk
            .as_object()
            .ok_or_else(|| format!("`chunks[{index}]` {}", json_value_type_name(chunk)))?;
        let kind = object
            .get("kind")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        if kind.is_none() {
            return Err(format!(
                "`chunks[{index}].kind` missing or not a non-empty string"
            ));
        }
        validate_optional_writer_string_field(object.get("id"), &format!("chunks[{index}].id"))?;
        validate_optional_writer_string_field(
            object.get("text"),
            &format!("chunks[{index}].text"),
        )?;
        if let Some(bytes) = object.get("bytes") {
            let bytes = bytes.as_array().ok_or_else(|| {
                format!("`chunks[{index}].bytes` {}", json_value_type_name(bytes))
            })?;
            validate_writer_byte_array(bytes, &format!("chunks[{index}].bytes"))?;
        }
        if let Some(sealed) = object.get("sealed") {
            if !sealed.is_boolean() {
                return Err(format!(
                    "`chunks[{index}].sealed` {}",
                    json_value_type_name(sealed)
                ));
            }
        }
        if !object.contains_key("text") && !object.contains_key("bytes") {
            return Err(format!("`chunks[{index}]` missing `text` or `bytes`"));
        }
    }
    Ok(())
}

fn validate_writer_diagnostics_value(value: &Value) -> Result<(), String> {
    let diagnostics = required_writer_array_field(value, "diagnostics")?;
    for (index, diagnostic) in diagnostics.iter().enumerate() {
        let object = diagnostic.as_object().ok_or_else(|| {
            format!(
                "`diagnostics[{index}]` {}",
                json_value_type_name(diagnostic)
            )
        })?;
        for field in ["code", "message"] {
            let value = object
                .get(field)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty());
            if value.is_none() {
                return Err(format!(
                    "`diagnostics[{index}].{field}` missing or not a non-empty string"
                ));
            }
        }
    }
    Ok(())
}

fn required_writer_array_field<'a>(
    value: &'a Value,
    field: &str,
) -> Result<&'a Vec<Value>, String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{}", json_value_type_name(value)))?;
    object
        .get(field)
        .and_then(Value::as_array)
        .ok_or_else(|| format!("missing `{field}` array"))
}

fn validate_writer_byte_array(bytes: &[Value], field: &str) -> Result<(), String> {
    for (index, byte) in bytes.iter().enumerate() {
        if !byte.as_u64().is_some_and(|value| value <= 255) {
            return Err(format!("`{field}[{index}]` {}", json_value_type_name(byte)));
        }
    }
    Ok(())
}

fn validate_optional_writer_string_field(value: Option<&Value>, field: &str) -> Result<(), String> {
    if let Some(value) = value {
        if !value.is_string() {
            return Err(format!("`{field}` {}", json_value_type_name(value)));
        }
    }
    Ok(())
}

fn default_true() -> bool {
    true
}

fn validate_optional_artifact_context(
    field: &str,
    expected: Option<&str>,
    actual: Option<&str>,
) -> Result<(), TransformTemplateEncodedArtifactError> {
    let Some(expected) = expected.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(());
    };
    if actual.map(str::trim) == Some(expected) {
        Ok(())
    } else {
        Err(TransformTemplateEncodedArtifactError::ContextMismatch {
            field: field.to_owned(),
            expected: expected.to_owned(),
            actual: actual.unwrap_or_default().to_owned(),
        })
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum TransformTemplateModuleParamType {
    #[default]
    Any,
    String,
    Boolean,
    Number,
    Integer,
    Array,
    Object,
    Json,
}

impl TransformTemplateModuleParamType {
    pub fn is_any(value: &Self) -> bool {
        *value == Self::Any
    }

    pub fn accepts(self, value: &Value, nullable: bool) -> bool {
        if value.is_null() {
            return nullable;
        }
        match self {
            Self::Any | Self::Json => true,
            Self::String => value.is_string(),
            Self::Boolean => value.is_boolean(),
            Self::Number => value.is_number(),
            Self::Integer => value.as_i64().is_some() || value.as_u64().is_some(),
            Self::Array => value.is_array(),
            Self::Object => value.is_object(),
        }
    }

    pub fn as_contract_name(self) -> &'static str {
        match self {
            Self::Any => "any",
            Self::String => "string",
            Self::Boolean => "boolean",
            Self::Number => "number",
            Self::Integer => "integer",
            Self::Array => "array",
            Self::Object => "object",
            Self::Json => "json",
        }
    }
}

fn is_false(value: &bool) -> bool {
    !*value
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateModuleCallSite {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub owner_entrypoint: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub from: Option<String>,
    pub template: String,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub arguments: BTreeMap<String, Value>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateModuleLetBinding {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub owner_entrypoint: Option<String>,
    pub name: String,
    #[serde(
        default,
        rename = "type",
        skip_serializing_if = "TransformTemplateModuleParamType::is_any"
    )]
    pub value_type: TransformTemplateModuleParamType,
    #[serde(default, skip_serializing_if = "is_false")]
    pub nullable: bool,
    pub value: Value,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expression: Option<String>,
}

pub fn apply_transform_template_let_bindings(
    value_bindings: &mut BTreeMap<String, Value>,
    let_bindings: &[TransformTemplateModuleLetBinding],
    owner_entrypoint: Option<&str>,
) {
    let _ =
        try_apply_transform_template_let_bindings(value_bindings, let_bindings, owner_entrypoint);
}

pub fn try_apply_transform_template_let_bindings(
    value_bindings: &mut BTreeMap<String, Value>,
    let_bindings: &[TransformTemplateModuleLetBinding],
    owner_entrypoint: Option<&str>,
) -> Result<(), String> {
    for binding in let_bindings
        .iter()
        .filter(|binding| binding.owner_entrypoint.is_none())
    {
        apply_transform_template_let_binding(value_bindings, binding)?;
    }

    let Some(owner_entrypoint) = owner_entrypoint else {
        return Ok(());
    };
    for binding in let_bindings
        .iter()
        .filter(|binding| binding.owner_entrypoint.as_deref() == Some(owner_entrypoint))
    {
        apply_transform_template_let_binding(value_bindings, binding)?;
    }

    Ok(())
}

fn apply_transform_template_let_binding(
    value_bindings: &mut BTreeMap<String, Value>,
    binding: &TransformTemplateModuleLetBinding,
) -> Result<(), String> {
    let value = if let Some(expression) = binding.expression.as_deref() {
        resolve_encode_subject_expression(expression, value_bindings).ok_or_else(|| {
            format!(
                "template let `{}` expression `{expression}` could not be resolved",
                binding.name
            )
        })?
    } else {
        binding.value.clone()
    };

    if !binding.value_type.accepts(&value, binding.nullable) {
        return Err(format!(
            "template let `{}` expected {}, got {}",
            binding.name,
            binding.value_type.as_contract_name(),
            json_value_type_name(&value)
        ));
    }

    value_bindings.insert(binding.name.clone(), value);
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateModuleLimits {
    pub max_import_depth: u32,
    pub max_recursion_depth: u32,
}

impl Default for TransformTemplateModuleLimits {
    fn default() -> Self {
        Self {
            max_import_depth: 32,
            max_recursion_depth: 64,
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TransformTemplateModuleOptions {
    #[serde(default)]
    pub imports: Vec<TransformTemplateModuleImport>,
    #[serde(default)]
    pub entrypoints: Vec<TransformTemplateModuleEntrypointDeclaration>,
    #[serde(default)]
    pub params: Vec<TransformTemplateModuleParamDeclaration>,
    #[serde(default)]
    pub calls: Vec<TransformTemplateModuleCallSite>,
    #[serde(default)]
    pub let_bindings: Vec<TransformTemplateModuleLetBinding>,
    #[serde(default)]
    pub encode_expressions: Vec<TransformTemplateEncodeExpression>,
    #[serde(default)]
    pub functions: Vec<TransformTemplateModuleFunctionDeclaration>,
    #[serde(default)]
    pub output_functions: Vec<TransformTemplateOutputFunctionDescriptor>,
    #[serde(default)]
    pub limits: TransformTemplateModuleLimits,
}

impl TransformTemplateModuleOptions {
    pub fn is_empty(&self) -> bool {
        self.imports.is_empty()
            && self.entrypoints.is_empty()
            && self.params.is_empty()
            && self.calls.is_empty()
            && self.let_bindings.is_empty()
            && self.encode_expressions.is_empty()
            && self.functions.is_empty()
            && self.output_functions.is_empty()
            && self.limits == TransformTemplateModuleLimits::default()
    }
}

pub fn parse_cem_native_template_module_options(
    request: TransformTemplateModuleParseRequest,
) -> TransformTemplateModuleParseResponse {
    let explicit_template_schema = template_has_native_module_schema(&request.template);
    let explicit_transform_schema = template_has_transform_module_schema(&request.template);
    let mut tokenizer =
        CemTokenizer::from_source(BytesSource::new(SourceId(1), request.template.bytes));
    let tokenizer_diagnostics = tokenizer.take_diagnostics();
    let normalizer = CemEventNormalizer::new(tokenizer);
    let document = CemAstBuilder::new(normalizer).build();
    let mut parser = NativeTemplateModuleLowerer {
        document: &document,
        template_uri: request.template.uri.as_str(),
        options: TransformTemplateModuleOptions::default(),
        call_source_maps: Vec::new(),
        diagnostics: Vec::new(),
        module_count: 0,
        saw_doc_directive: false,
        explicit_template_schema,
        explicit_transform_schema,
    };
    parser.lower_document();
    parser.validate_declarations();

    let module_declared = parser.module_count > 0;
    let mut diagnostics = parser.diagnostics;
    if module_declared || explicit_template_schema {
        diagnostics.extend(tokenizer_diagnostics);
        diagnostics.extend(document.diagnostics.clone());
    }

    TransformTemplateModuleParseResponse {
        module_options: if module_declared {
            parser.options
        } else {
            TransformTemplateModuleOptions::default()
        },
        diagnostics,
        module_declared,
    }
}

fn template_has_native_module_schema(template: &TemplateInput) -> bool {
    template.identity.as_ref().is_some_and(|identity| {
        identity.schema.as_deref().map(str::trim) == Some(CEM_NATIVE_TEMPLATE_SCHEMA_URI)
            || identity.default_namespace.as_deref().map(str::trim)
                == Some(CEM_NATIVE_TEMPLATE_NAMESPACE_URI)
    })
}

fn template_has_transform_module_schema(template: &TemplateInput) -> bool {
    template.identity.as_ref().is_some_and(|identity| {
        identity
            .content_type
            .as_deref()
            .is_some_and(|content_type| {
                content_type_essence(content_type) == CEM_TRANSFORM_CONTENT_TYPE
            })
            || identity.schema.as_deref().map(str::trim) == Some(CEM_TRANSFORM_SCHEMA_URI)
            || identity.default_namespace.as_deref().map(str::trim)
                == Some(CEM_TRANSFORM_SCHEMA_URI)
    })
}

struct NativeTemplateModuleLowerer<'a> {
    document: &'a CemDocument,
    template_uri: &'a str,
    options: TransformTemplateModuleOptions,
    call_source_maps: Vec<Option<SourceMapStack>>,
    diagnostics: Vec<Diagnostic>,
    module_count: usize,
    saw_doc_directive: bool,
    explicit_template_schema: bool,
    explicit_transform_schema: bool,
}

impl NativeTemplateModuleLowerer<'_> {
    fn lower_document(&mut self) {
        let Some(CemAstNode::Document { root_children, .. }) = self.document.root() else {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                "CEM-native template has no document root",
            );
            return;
        };

        for child in root_children {
            let Some(name) = template_element_name(self.document, *child) else {
                continue;
            };
            match name {
                "@doc" => self.saw_doc_directive = true,
                directive if directive.starts_with('@') => {}
                "module" => {
                    self.module_count += 1;
                    self.lower_module(*child);
                }
                other if self.explicit_template_schema || self.explicit_transform_schema => self
                    .push_diag(
                        TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                        format!("top-level `{other}` is not valid in CEM template module schema"),
                    ),
                _ => {}
            }
        }

        if (self.explicit_template_schema || self.explicit_transform_schema)
            && self.module_count == 0
        {
            self.push_diag(
                self.module_required_code(),
                "CEM template schema requires one top-level `module` node",
            );
        } else if self.module_count > 1 {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE,
                "CEM-native template schema allows only one top-level `module` node",
            );
        }
    }

    fn lower_module(&mut self, module_id: AstNodeId) {
        let Some(CemAstNode::Element { children, .. }) = self.document.get(module_id) else {
            return;
        };

        for child in children {
            let Some(name) = template_element_name(self.document, *child) else {
                continue;
            };
            match name {
                "import" => self.lower_import(*child),
                "param" => self.lower_param(*child, None),
                "template" => self.lower_template(*child),
                "body" => self.collect_body_expressions(*child, None),
                "function" if self.explicit_transform_schema => self.lower_function(*child),
                "encoding-function" if self.explicit_transform_schema => self
                    .lower_output_function(*child, TransformTemplateOutputFunctionKind::Encoding),
                "format-function" if self.explicit_transform_schema => {
                    self.lower_output_function(*child, TransformTemplateOutputFunctionKind::Format)
                }
                "color-function" if self.explicit_transform_schema => {
                    self.lower_output_function(*child, TransformTemplateOutputFunctionKind::Color)
                }
                "include" => self.push_diag(
                    TRANSFORM_TEMPLATE_INCLUDE_RESERVED_CODE,
                    "`include` is reserved in CEM-native template modules; use `import`",
                ),
                other => self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                    format!("`{other}` is not valid inside CEM-native template `module`"),
                ),
            }
        }
    }

    fn lower_import(&mut self, import_id: AstNodeId) {
        let attrs = template_collect_attrs(self.document, import_id);
        let Some(alias) = required_attr(&attrs, "as") else {
            self.push_missing_attr("import", "as");
            return;
        };
        let Some(uri) = required_attr(&attrs, "src") else {
            self.push_missing_attr("import", "src");
            return;
        };
        let identity = import_identity_from_attrs(&attrs);
        self.options.imports.push(TransformTemplateModuleImport {
            alias,
            uri,
            identity,
            kind: TransformTemplateModuleDependencyKind::Import,
            source_range: template_node_source_map(self.document, import_id)
                .and_then(|source_map| source_map_byte_range(&source_map)),
        });
        self.reject_decl_children(import_id, "import");
    }

    fn lower_param(&mut self, param_id: AstNodeId, owner_entrypoint: Option<&str>) {
        let Some(mut declaration) = self.parse_param_declaration(param_id) else {
            return;
        };
        if let Some(entrypoint) = owner_entrypoint {
            declaration.name = format!("{entrypoint}.{}", declaration.name);
        }
        self.options.params.push(declaration);
        self.reject_decl_children(param_id, "param");
    }

    fn parse_param_declaration(
        &mut self,
        param_id: AstNodeId,
    ) -> Option<TransformTemplateModuleParamDeclaration> {
        let attrs = template_collect_attrs(self.document, param_id);
        let Some(name) = required_attr(&attrs, "name") else {
            self.push_missing_attr("param", "name");
            return None;
        };
        let visibility =
            self.parse_visibility(attr_value(&attrs, "", "visibility").as_deref(), false);
        let value_type = self.parse_param_type(attr_value(&attrs, "", "type").as_deref());
        let nullable = parse_bool_attr(attr_value(&attrs, "", "nullable").as_deref())
            .unwrap_or_else(|message| {
                self.push_diag(TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE, message);
                false
            });
        let default_expr = attr_value(&attrs, "", "default-expr")
            .or_else(|| attr_value(&attrs, "", "defaultExpr"));
        if default_expr.is_some() {
            self.push_diag(
                self.param_default_expr_reserved_code(),
                format!(
                    "template param `{name}` uses reserved `@default-expr`; use literal `@default` until default expression semantics are defined"
                ),
            );
        }
        let default_value = attr_value(&attrs, "", "default")
            .and_then(|value| self.parse_param_default(&name, value_type, nullable, &value));
        let required = parse_bool_attr(attr_value(&attrs, "", "required").as_deref())
            .unwrap_or_else(|message| {
                self.push_diag(TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE, message);
                false
            });
        Some(TransformTemplateModuleParamDeclaration {
            name,
            value_type,
            nullable,
            default_value,
            required,
            visibility,
        })
    }

    fn lower_template(&mut self, template_id: AstNodeId) {
        let attrs = template_collect_attrs(self.document, template_id);
        let Some(name) = required_attr(&attrs, "name") else {
            self.push_missing_attr("template", "name");
            return;
        };
        let visibility =
            self.parse_visibility(attr_value(&attrs, "", "visibility").as_deref(), false);
        self.options
            .entrypoints
            .push(TransformTemplateModuleEntrypointDeclaration {
                name: name.clone(),
                visibility,
            });

        let Some(CemAstNode::Element { children, .. }) = self.document.get(template_id) else {
            return;
        };
        for child in children {
            let Some(child_name) = template_element_name(self.document, *child) else {
                continue;
            };
            match child_name {
                "param" => self.lower_param(*child, Some(&name)),
                "body" => self.collect_body_expressions(*child, Some(&name)),
                other => self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                    format!(
                        "`{other}` is not valid inside CEM-native template declaration `{name}`"
                    ),
                ),
            }
        }
    }

    fn lower_function(&mut self, function_id: AstNodeId) {
        let element_name = "function";
        let attrs = template_collect_attrs(self.document, function_id);
        let Some(name) = required_attr(&attrs, "name") else {
            self.push_missing_attr(element_name, "name");
            return;
        };
        let Some(returns_raw) = required_attr(&attrs, "returns") else {
            self.push_missing_attr(element_name, "returns");
            return;
        };
        let visibility =
            self.parse_visibility(attr_value(&attrs, "", "visibility").as_deref(), true);
        let return_type = self.parse_value_type(Some(returns_raw.as_str()), "function return");
        let nullable = parse_bool_attr(attr_value(&attrs, "", "nullable").as_deref())
            .unwrap_or_else(|message| {
                self.push_diag(TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE, message);
                false
            });
        let deterministic = self.parse_bool_decl_attr(&attrs, "deterministic");
        let trusted = self.parse_bool_decl_attr(&attrs, "trusted");

        let Some(CemAstNode::Element { children, .. }) = self.document.get(function_id) else {
            return;
        };
        let mut params = Vec::new();
        let mut body_declared = false;
        let mut body_expression = None;
        for child in children {
            let Some(child_name) = template_element_name(self.document, *child) else {
                continue;
            };
            match child_name {
                "param" => {
                    if let Some(param) = self.parse_param_declaration(*child) {
                        self.validate_function_param(*child, element_name, &name, &param);
                        params.push(param);
                    }
                    self.reject_decl_children(*child, "param");
                }
                "body" => {
                    body_declared = true;
                    body_expression = self.runtime_body_expression(*child, element_name, &name);
                }
                other => self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                    format!("`{element_name}` declarations cannot contain `{other}`"),
                ),
            }
        }
        if !body_declared || body_expression.is_none() {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                format!("CEMT `{element_name}` `{name}` requires one executable body expression"),
            );
        }

        self.options
            .functions
            .push(TransformTemplateModuleFunctionDeclaration {
                owner: output_function_owner(&name),
                name,
                visibility,
                return_type,
                nullable,
                deterministic,
                trusted,
                params,
                body_declared,
                body_expression,
            });
    }

    fn lower_output_function(
        &mut self,
        function_id: AstNodeId,
        kind: TransformTemplateOutputFunctionKind,
    ) {
        let element_name = match kind {
            TransformTemplateOutputFunctionKind::Encoding => "encoding-function",
            TransformTemplateOutputFunctionKind::Format => "format-function",
            TransformTemplateOutputFunctionKind::Color => "color-function",
        };
        let attrs = template_collect_attrs(self.document, function_id);
        let Some(name) = required_attr(&attrs, "name") else {
            self.push_missing_attr(element_name, "name");
            return;
        };
        let Some(category) = required_attr(&attrs, "category") else {
            self.push_missing_attr(element_name, "category");
            return;
        };
        let Some(subject) = required_attr(&attrs, "subject") else {
            self.push_missing_attr(element_name, "subject");
            return;
        };
        let Some(produces_raw) = required_attr(&attrs, "produces") else {
            self.push_missing_attr(element_name, "produces");
            return;
        };
        let Some(content_type) = required_attr(&attrs, "content-type") else {
            self.push_missing_attr(element_name, "content-type");
            return;
        };
        let Some(schema) = required_attr(&attrs, "schema") else {
            self.push_missing_attr(element_name, "schema");
            return;
        };
        let Some(canonical_raw) = required_attr(&attrs, "canonical") else {
            self.push_missing_attr(element_name, "canonical");
            return;
        };
        let Some(streamable_raw) = required_attr(&attrs, "streamable") else {
            self.push_missing_attr(element_name, "streamable");
            return;
        };
        let Some(produces) = TransformTemplateOutputProducedKind::parse(&produces_raw) else {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                format!(
                    "`{element_name}` `{name}` has unsupported `@produces` value `{produces_raw}`"
                ),
            );
            return;
        };
        let implementation = match optional_trimmed_attr(&attrs, "implementation").as_deref() {
            None => TransformTemplateOutputFunctionImplementation::Cemt,
            Some(value) => {
                if let Some(implementation) =
                    TransformTemplateOutputFunctionImplementation::parse(value)
                {
                    implementation
                } else {
                    self.push_diag(
                        TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                        format!(
                            "`{element_name}` `{name}` has unsupported `@implementation` value `{value}`"
                        ),
                    );
                    TransformTemplateOutputFunctionImplementation::Cemt
                }
            }
        };
        let canonical =
            self.parse_required_bool_decl_attr(element_name, &name, "canonical", &canonical_raw);
        let streamable =
            self.parse_required_bool_decl_attr(element_name, &name, "streamable", &streamable_raw);
        let deterministic = self.parse_bool_decl_attr(&attrs, "deterministic");
        let trusted = self.parse_bool_decl_attr(&attrs, "trusted");
        let lossy = self.parse_bool_decl_attr(&attrs, "lossy");
        let visibility =
            self.parse_visibility(attr_value(&attrs, "", "visibility").as_deref(), true);
        let capability = optional_trimmed_attr(&attrs, "capability");
        if implementation.requires_capability() && capability.is_none() {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                format!(
                    "`{element_name}` `{name}` with native or external implementation requires `@capability`"
                ),
            );
        }

        let Some(CemAstNode::Element { children, .. }) = self.document.get(function_id) else {
            return;
        };
        let mut params = Vec::new();
        let mut body_declared = false;
        let mut body_expression = None;
        for child in children {
            let Some(child_name) = template_element_name(self.document, *child) else {
                continue;
            };
            match child_name {
                "param" => {
                    if let Some(param) = self.parse_param_declaration(*child) {
                        self.validate_output_function_param(*child, element_name, &name, &param);
                        params.push(param);
                    }
                    self.reject_decl_children(*child, "param");
                }
                "body" => {
                    body_declared = true;
                    body_expression = self.runtime_body_expression(*child, element_name, &name);
                    if body_expression.as_deref().is_some_and(|expression| {
                        cemt_expression_starts_with_call(expression, "encode")
                    }) {
                        self.collect_body_expressions(*child, Some(&name));
                    }
                }
                other => self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                    format!("`{element_name}` declarations cannot contain `{other}`"),
                ),
            }
        }

        self.options
            .output_functions
            .push(TransformTemplateOutputFunctionDescriptor {
                kind,
                owner: output_function_owner(&name),
                name,
                category,
                subject,
                produces,
                content_type,
                schema,
                canonical,
                streamable,
                visibility,
                implementation,
                profile: optional_trimmed_attr(&attrs, "profile"),
                extends: optional_trimmed_attr(&attrs, "extends"),
                capability,
                deterministic,
                trusted,
                lossy,
                fallback: optional_trimmed_attr(&attrs, "fallback"),
                params,
                body_declared,
                body_expression,
            });
    }

    fn runtime_body_expression(
        &mut self,
        body_id: AstNodeId,
        element_name: &str,
        function_name: &str,
    ) -> Option<String> {
        let expressions = self.collect_runtime_body_expressions(body_id);
        if expressions.len() > 1 {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                format!(
                    "`{element_name}` `{function_name}` body must contain at most one executable `$` expression"
                ),
            );
        }
        expressions.into_iter().next()
    }

    fn collect_runtime_body_expressions(&self, node_id: AstNodeId) -> Vec<String> {
        let Some(CemAstNode::Element { children, .. }) = self.document.get(node_id) else {
            return Vec::new();
        };
        if template_element_name(self.document, node_id) == Some("$") {
            return template_expression_body(self.document, node_id)
                .into_iter()
                .collect();
        }
        let mut expressions = Vec::new();
        for child in children {
            expressions.extend(self.collect_runtime_body_expressions(*child));
        }
        expressions
    }

    fn collect_body_expressions(&mut self, body_id: AstNodeId, owner: Option<&str>) {
        let Some(CemAstNode::Element { children, .. }) = self.document.get(body_id) else {
            return;
        };
        for child in children {
            self.collect_expressions_in_subtree(*child, owner);
        }
    }

    fn collect_expressions_in_subtree(&mut self, node_id: AstNodeId, owner: Option<&str>) {
        let Some(CemAstNode::Element { children, .. }) = self.document.get(node_id) else {
            return;
        };
        if template_element_name(self.document, node_id) == Some("let") {
            self.lower_let(node_id, owner);
            self.reject_decl_children(node_id, "let");
            return;
        }
        if template_element_name(self.document, node_id) == Some("call") {
            self.lower_call(node_id, owner);
            self.reject_decl_children(node_id, "call");
            return;
        }
        if template_element_name(self.document, node_id) == Some("$") {
            self.lower_encode_expression(node_id, owner);
            return;
        }
        for child in children {
            self.collect_expressions_in_subtree(*child, owner);
        }
    }

    fn lower_call(&mut self, call_id: AstNodeId, owner_entrypoint: Option<&str>) {
        let attrs = template_collect_attrs(self.document, call_id);
        let Some(template) = required_attr(&attrs, "template") else {
            self.push_missing_attr("call", "template");
            return;
        };
        self.options.calls.push(TransformTemplateModuleCallSite {
            owner_entrypoint: owner_entrypoint.map(str::to_owned),
            from: optional_trimmed_attr(&attrs, "from"),
            template,
            arguments: call_arguments(&attrs),
        });
        self.call_source_maps
            .push(template_node_source_map(self.document, call_id));
    }

    fn lower_let(&mut self, let_id: AstNodeId, owner_entrypoint: Option<&str>) {
        let Some(binding) = self.parse_let_binding(let_id, owner_entrypoint) else {
            return;
        };
        self.options.let_bindings.push(binding);
    }

    fn parse_let_binding(
        &mut self,
        let_id: AstNodeId,
        owner_entrypoint: Option<&str>,
    ) -> Option<TransformTemplateModuleLetBinding> {
        let attrs = template_collect_attrs(self.document, let_id);
        let Some(name) = required_attr(&attrs, "name") else {
            self.push_missing_attr("let", "name");
            return None;
        };
        let value_type = self.parse_value_type(attr_value(&attrs, "", "type").as_deref(), "let");
        let nullable = parse_bool_attr(attr_value(&attrs, "", "nullable").as_deref())
            .unwrap_or_else(|message| {
                self.push_diag(TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE, message);
                false
            });
        let expression =
            attr_value(&attrs, "", "expr").or_else(|| attr_value(&attrs, "", "expression"));
        let literal_value = attr_value(&attrs, "", "value");
        if expression.is_some() && literal_value.is_some() {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                format!(
                    "template let `{name}` must use either literal `@value` or expression `@expr`, not both"
                ),
            );
        }
        let (value, expression) = if let Some(expression) = expression
            .map(|value| value.trim().to_owned())
            .filter(|value| !value.is_empty())
        {
            (Value::Null, Some(expression))
        } else {
            let Some(value) = literal_value else {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                    "CEM-native template `let` declaration requires `@value` or `@expr`",
                );
                return None;
            };
            let value = self.parse_typed_literal(
                "template let",
                &name,
                "value",
                value_type,
                nullable,
                &value,
            )?;
            (value, None)
        };

        Some(TransformTemplateModuleLetBinding {
            owner_entrypoint: owner_entrypoint.map(str::to_owned),
            name,
            value_type,
            nullable,
            value,
            expression,
        })
    }

    fn lower_encode_expression(&mut self, expression_id: AstNodeId, owner: Option<&str>) {
        let Some(expression) = template_expression_body(self.document, expression_id) else {
            return;
        };
        match parse_transform_template_encode_expression(&expression, owner) {
            Ok(Some(expression)) => self.options.encode_expressions.push(expression),
            Ok(None) => {}
            Err(error) => self.push_diag(
                TRANSFORM_TEMPLATE_ENCODE_CALL_INVALID_CODE,
                format!("invalid CEMT encode expression: {error}"),
            ),
        }
    }

    fn validate_declarations(&mut self) {
        let mut aliases = BTreeSet::new();
        for import in self.options.imports.clone() {
            if !aliases.insert(import.alias.clone()) {
                self.push_diag(
                    self.import_alias_duplicate_code(),
                    format!(
                        "template module import alias `{}` is declared more than once",
                        import.alias
                    ),
                );
            }
        }

        let mut entrypoints = BTreeSet::new();
        for entrypoint in self.options.entrypoints.clone() {
            if !entrypoints.insert(entrypoint.name.clone()) {
                self.push_diag(
                    self.entrypoint_duplicate_code(),
                    format!(
                        "template entrypoint `{}` is declared more than once",
                        entrypoint.name
                    ),
                );
            }
        }

        let mut params = BTreeSet::new();
        for param in self.options.params.clone() {
            if !params.insert(param.name.clone()) {
                self.push_diag(
                    self.param_duplicate_code(),
                    format!("template param `{}` is declared more than once", param.name),
                );
            }
        }

        let mut let_bindings = BTreeSet::new();
        for binding in self.options.let_bindings.clone() {
            if !let_bindings.insert((binding.owner_entrypoint.clone(), binding.name.clone())) {
                let scope = binding.owner_entrypoint.as_deref().unwrap_or("module body");
                self.push_diag(
                    self.let_duplicate_code(),
                    format!(
                        "template let `{}` is declared more than once in `{scope}`",
                        binding.name
                    ),
                );
            }
        }

        let mut functions = BTreeSet::new();
        for function in self.options.functions.clone() {
            if !output_function_name_is_package_qualified(&function.name) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_NAME_UNQUALIFIED_CODE,
                    format!(
                        "CEMT function `{}` must use a package-qualified name such as `package.function`",
                        function.name
                    ),
                );
            }
            if !functions.insert(function.name.clone()) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE,
                    format!(
                        "CEMT function `{}` is declared more than once",
                        function.name
                    ),
                );
            }
        }

        let mut output_functions = BTreeSet::new();
        for function in self.options.output_functions.clone() {
            if !output_function_name_is_package_qualified(&function.name) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_NAME_UNQUALIFIED_CODE,
                    format!(
                        "CEMT output function `{}` must use a package-qualified name such as `package.function`",
                        function.name
                    ),
                );
            }
            if let Some(standard) = standard_output_function_contract(&function.name) {
                if !standard.matches_descriptor(&function) {
                    self.push_diag(
                        TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_STANDARD_SHADOW_CODE,
                        format!(
                            "CEMT output function `{}` shadows the standard {}; use a package-qualified custom name and `@extends=\"{}\"` to define an explicit alias",
                            function.name,
                            standard.expected_contract(),
                            standard.name
                        ),
                    );
                }
            }
            if !output_functions.insert(function.key()) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE,
                    format!(
                        "CEMT output function `{}` is declared more than once for category `{}` and subject `{}`",
                        function.name, function.category, function.subject
                    ),
                );
            }
            if functions.contains(&function.name) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE,
                    format!(
                        "CEMT output function `{}` conflicts with an internal function of the same name",
                        function.name
                    ),
                );
            }
        }

        self.validate_call_sites();
    }

    fn validate_call_sites(&mut self) {
        let imports = self
            .options
            .imports
            .iter()
            .map(|import| import.alias.clone())
            .collect::<BTreeSet<_>>();
        let templates = self
            .options
            .entrypoints
            .iter()
            .map(|entrypoint| entrypoint.name.clone())
            .collect::<BTreeSet<_>>();
        let mut params_by_template =
            BTreeMap::<String, Vec<TransformTemplateModuleParamDeclaration>>::new();

        for param in &self.options.params {
            let Some((template, local_name)) = param.name.split_once('.') else {
                continue;
            };
            if !templates.contains(template) {
                continue;
            }

            let mut param = param.clone();
            param.name = local_name.to_owned();
            params_by_template
                .entry(template.to_owned())
                .or_default()
                .push(param);
        }

        for (index, call) in self.options.calls.clone().into_iter().enumerate() {
            let source_map = self
                .call_source_maps
                .get(index)
                .and_then(|source_map| source_map.clone());

            if let Some(import_alias) = call.from.as_deref() {
                if !imports.contains(import_alias) {
                    self.push_call_diag(
                        source_map.as_ref(),
                        self.call_unknown_code(),
                        format!(
                            "template call to `{}` references unknown import alias `{import_alias}`",
                            call.template
                        ),
                    );
                }
                continue;
            }

            if !templates.contains(&call.template) {
                self.push_call_diag(
                    source_map.as_ref(),
                    self.call_unknown_code(),
                    format!("template call target `{}` is not declared", call.template),
                );
                continue;
            }

            let params = params_by_template
                .get(&call.template)
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            for argument_name in call.arguments.keys() {
                if !params.iter().any(|param| param.name == *argument_name) {
                    self.push_call_diag(
                        source_map.as_ref(),
                        TRANSFORM_TEMPLATE_PARAM_UNKNOWN_CODE,
                        format!(
                            "template call to `{}` provides unknown argument `{argument_name}`",
                            call.template
                        ),
                    );
                }
            }

            for param in params {
                let Some(argument) = call.arguments.get(&param.name) else {
                    if param.required && param.default_value.is_none() {
                        self.push_call_diag(
                            source_map.as_ref(),
                            TRANSFORM_TEMPLATE_PARAM_REQUIRED_CODE,
                            format!(
                                "template call to `{}` requires argument `{}`",
                                call.template, param.name
                            ),
                        );
                    }
                    continue;
                };

                if !template_call_argument_matches_param(argument, param) {
                    self.push_call_diag(
                        source_map.as_ref(),
                        TRANSFORM_TEMPLATE_PARAM_TYPE_CODE,
                        format!(
                            "template call to `{}` argument `{}` expected {}, got {}",
                            call.template,
                            param.name,
                            param.value_type.as_contract_name(),
                            json_value_type_name(argument)
                        ),
                    );
                }
            }
        }
    }

    fn reject_decl_children(&mut self, ast_id: AstNodeId, parent_name: &str) {
        let Some(CemAstNode::Element { children, .. }) = self.document.get(ast_id) else {
            return;
        };
        for child in children {
            if let Some(name) = template_element_name(self.document, *child) {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_UNSUPPORTED_CODE,
                    format!("`{parent_name}` declarations cannot contain `{name}`"),
                );
            }
        }
    }

    fn parse_visibility(
        &mut self,
        value: Option<&str>,
        allow_package: bool,
    ) -> TransformTemplateModuleVisibility {
        match value.map(str::trim).filter(|value| !value.is_empty()) {
            None | Some("private") => TransformTemplateModuleVisibility::Private,
            Some("package") if allow_package => TransformTemplateModuleVisibility::Package,
            Some("public") => TransformTemplateModuleVisibility::Public,
            Some(other) => {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                    if allow_package {
                        format!(
                            "unsupported template declaration visibility `{other}`; use `private`, `package`, or `public`"
                        )
                    } else {
                        format!(
                            "unsupported template declaration visibility `{other}`; use `private` or `public`"
                        )
                    },
                );
                TransformTemplateModuleVisibility::Private
            }
        }
    }

    fn parse_bool_decl_attr(
        &mut self,
        attrs: &BTreeMap<(String, String), Option<String>>,
        name: &str,
    ) -> bool {
        parse_bool_attr(attr_value(attrs, "", name).as_deref()).unwrap_or_else(|message| {
            self.push_diag(TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE, message);
            false
        })
    }

    fn parse_required_bool_decl_attr(
        &mut self,
        element_name: &str,
        function_name: &str,
        attr_name: &str,
        value: &str,
    ) -> bool {
        parse_bool_attr(Some(value)).unwrap_or_else(|message| {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                format!("`{element_name}` `{function_name}` has invalid `@{attr_name}`: {message}"),
            );
            false
        })
    }

    fn validate_output_function_param(
        &mut self,
        param_id: AstNodeId,
        element_name: &str,
        function_name: &str,
        param: &TransformTemplateModuleParamDeclaration,
    ) {
        self.validate_function_param(param_id, element_name, function_name, param);
    }

    fn validate_function_param(
        &mut self,
        param_id: AstNodeId,
        element_name: &str,
        function_name: &str,
        param: &TransformTemplateModuleParamDeclaration,
    ) {
        let attrs = template_collect_attrs(self.document, param_id);
        if attr_value(&attrs, "", "type")
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .is_none()
        {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                format!(
                    "`{element_name}` `{function_name}` param `{}` requires explicit `@type` metadata",
                    param.name
                ),
            );
        }

        let has_default = attr_value(&attrs, "", "default").is_some();
        if !param.required && !has_default {
            self.push_diag(
                TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
                format!(
                    "`{element_name}` `{function_name}` param `{}` must declare `@required=true` or a literal `@default`",
                    param.name
                ),
            );
        }
    }

    fn parse_param_type(&mut self, value: Option<&str>) -> TransformTemplateModuleParamType {
        self.parse_value_type(value, "param")
    }

    fn parse_value_type(
        &mut self,
        value: Option<&str>,
        declaration: &str,
    ) -> TransformTemplateModuleParamType {
        match value.map(str::trim).filter(|value| !value.is_empty()) {
            None | Some("any") => TransformTemplateModuleParamType::Any,
            Some("string") => TransformTemplateModuleParamType::String,
            Some("boolean") => TransformTemplateModuleParamType::Boolean,
            Some("number") => TransformTemplateModuleParamType::Number,
            Some("integer") => TransformTemplateModuleParamType::Integer,
            Some("array") => TransformTemplateModuleParamType::Array,
            Some("object") => TransformTemplateModuleParamType::Object,
            Some("json") => TransformTemplateModuleParamType::Json,
            Some(other) => {
                self.push_diag(
                    TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
                    format!(
                        "unsupported template {declaration} type `{other}`; use `any`, `string`, `boolean`, `number`, `integer`, `array`, `object`, or `json`"
                    ),
                );
                TransformTemplateModuleParamType::Any
            }
        }
    }

    fn parse_param_default(
        &mut self,
        name: &str,
        value_type: TransformTemplateModuleParamType,
        nullable: bool,
        value: &str,
    ) -> Option<Value> {
        self.parse_typed_literal(
            "template param",
            name,
            "default",
            value_type,
            nullable,
            value,
        )
    }

    fn parse_typed_literal(
        &mut self,
        declaration: &str,
        name: &str,
        attr_name: &str,
        value_type: TransformTemplateModuleParamType,
        nullable: bool,
        value: &str,
    ) -> Option<Value> {
        match parse_template_typed_literal_value(value_type, nullable, value) {
            Some(literal_value) => Some(literal_value),
            None => {
                self.push_typed_literal_invalid(declaration, name, attr_name, value_type, value);
                None
            }
        }
    }

    fn push_typed_literal_invalid(
        &mut self,
        declaration: &str,
        name: &str,
        attr_name: &str,
        value_type: TransformTemplateModuleParamType,
        value: &str,
    ) {
        self.push_diag(
            TRANSFORM_TEMPLATE_DECLARATION_INVALID_CODE,
            format!(
                "{declaration} `{name}` {attr_name} `{value}` is not a valid {} value",
                value_type.as_contract_name()
            ),
        );
    }

    fn uses_cem_template_diagnostics(&self) -> bool {
        self.explicit_template_schema && !self.explicit_transform_schema
    }

    fn module_required_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_MODULE_REQUIRED_CODE
        } else {
            TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE
        }
    }

    fn import_alias_duplicate_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_IMPORT_ALIAS_DUPLICATE_CODE
        } else {
            TRANSFORM_TEMPLATE_IMPORT_ALIAS_DUPLICATE_CODE
        }
    }

    fn entrypoint_duplicate_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_ENTRYPOINT_DUPLICATE_CODE
        } else {
            TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE
        }
    }

    fn param_duplicate_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_PARAM_DUPLICATE_CODE
        } else {
            TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE
        }
    }

    fn let_duplicate_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_LET_DUPLICATE_CODE
        } else {
            TRANSFORM_TEMPLATE_DECLARATION_DUPLICATE_CODE
        }
    }

    fn call_unknown_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_CALL_UNKNOWN_CODE
        } else {
            TRANSFORM_TEMPLATE_CALL_UNKNOWN_CODE
        }
    }

    fn param_default_expr_reserved_code(&self) -> &'static str {
        if self.uses_cem_template_diagnostics() {
            CEM_TEMPLATE_PARAM_DEFAULT_EXPR_RESERVED_CODE
        } else {
            TRANSFORM_TEMPLATE_PARAM_DEFAULT_EXPR_RESERVED_CODE
        }
    }

    fn push_missing_attr(&mut self, element: &str, attr: &str) {
        self.push_diag(
            TRANSFORM_TEMPLATE_DECLARATION_REQUIRED_CODE,
            format!("CEM-native template `{element}` declaration requires `@{attr}`"),
        );
    }

    fn push_diag(&mut self, code: &str, message: impl Into<String>) {
        self.diagnostics.push(Diagnostic {
            uri: Some(self.template_uri.to_owned()),
            code: code.to_owned(),
            severity: Severity::Fatal,
            message: message.into(),
            details: None,
            ..Diagnostic::default()
        });
    }

    fn push_call_diag(
        &mut self,
        source_map: Option<&SourceMapStack>,
        code: &str,
        message: impl Into<String>,
    ) {
        self.diagnostics.push(Diagnostic {
            uri: Some(self.template_uri.to_owned()),
            byte_offset: source_map.and_then(source_map_start_offset),
            code: code.to_owned(),
            severity: Severity::Fatal,
            message: message.into(),
            details: None,
            source_map: source_map.cloned(),
            ..Diagnostic::default()
        });
    }
}

fn template_call_argument_matches_param(
    argument: &Value,
    param: &TransformTemplateModuleParamDeclaration,
) -> bool {
    if transform_template_call_argument_is_dynamic(argument) {
        return true;
    }

    match argument {
        Value::String(raw) => {
            parse_template_typed_literal_value(param.value_type, param.nullable, raw).is_some()
        }
        value => param.value_type.accepts(value, param.nullable),
    }
}

pub(crate) fn transform_template_call_argument_is_dynamic(argument: &Value) -> bool {
    let Value::String(raw) = argument else {
        return false;
    };
    let trimmed = raw.trim();
    trimmed.starts_with("{$") && trimmed.ends_with('}')
}

fn parse_template_typed_literal_value(
    value_type: TransformTemplateModuleParamType,
    nullable: bool,
    value: &str,
) -> Option<Value> {
    let literal_value = if nullable && value.trim() == "null" {
        Value::Null
    } else {
        match value_type {
            TransformTemplateModuleParamType::Any | TransformTemplateModuleParamType::String => {
                Value::String(value.to_owned())
            }
            TransformTemplateModuleParamType::Boolean => match value.trim() {
                "true" => Value::Bool(true),
                "false" => Value::Bool(false),
                _ => return None,
            },
            TransformTemplateModuleParamType::Number
            | TransformTemplateModuleParamType::Integer
            | TransformTemplateModuleParamType::Array
            | TransformTemplateModuleParamType::Object
            | TransformTemplateModuleParamType::Json => {
                serde_json::from_str::<Value>(value).ok()?
            }
        }
    };

    value_type
        .accepts(&literal_value, nullable)
        .then_some(literal_value)
}

fn template_element_name(doc: &CemDocument, node_id: AstNodeId) -> Option<&str> {
    match doc.get(node_id) {
        Some(CemAstNode::Element { expanded_name, .. }) if !expanded_name.local_name.is_empty() => {
            Some(expanded_name.local_name.as_str())
        }
        _ => None,
    }
}

fn template_node_source_map(doc: &CemDocument, node_id: AstNodeId) -> Option<SourceMapStack> {
    match doc.get(node_id)? {
        CemAstNode::Document { source, .. }
        | CemAstNode::Element { source, .. }
        | CemAstNode::Attribute { source, .. }
        | CemAstNode::Text { source, .. }
        | CemAstNode::Whitespace { source, .. }
        | CemAstNode::Comment { source, .. }
        | CemAstNode::ProcessingInstruction { source, .. }
        | CemAstNode::Cdata { source, .. }
        | CemAstNode::RawText { source, .. }
        | CemAstNode::Error { source, .. } => Some(source.clone()),
    }
}

fn source_map_start_offset(source_map: &SourceMapStack) -> Option<u64> {
    source_map_byte_range(source_map).map(|range| range.start)
}

fn source_map_byte_range(source_map: &SourceMapStack) -> Option<ByteRange> {
    source_map.current().and_then(|frame| match &frame.span {
        FrameSpan::Single(range) => Some(*range),
        FrameSpan::Multi(ranges) => ranges.first().copied(),
    })
}

fn template_expression_body(doc: &CemDocument, node_id: AstNodeId) -> Option<String> {
    let Some(CemAstNode::Element { children, .. }) = doc.get(node_id) else {
        return None;
    };
    let mut body = String::new();
    for child in children {
        match doc.get(*child) {
            Some(CemAstNode::Text { data, .. }) | Some(CemAstNode::RawText { data, .. }) => {
                body.push_str(data);
            }
            _ => {}
        }
    }
    Some(body.trim().to_owned()).filter(|body| !body.is_empty())
}

fn template_collect_attrs(
    doc: &CemDocument,
    node_id: AstNodeId,
) -> BTreeMap<(String, String), Option<String>> {
    let mut attrs = BTreeMap::new();
    let Some(CemAstNode::Element { attributes, .. }) = doc.get(node_id) else {
        return attrs;
    };
    for attr_id in attributes {
        let Some(CemAstNode::Attribute {
            expanded_name,
            value,
            ..
        }) = doc.get(*attr_id)
        else {
            continue;
        };
        attrs.insert(
            (
                expanded_name.namespace_uri.clone(),
                expanded_name.local_name.clone(),
            ),
            value.clone(),
        );
    }
    attrs
}

fn attr_value(
    attrs: &BTreeMap<(String, String), Option<String>>,
    prefix: &str,
    local: &str,
) -> Option<String> {
    attrs
        .get(&(prefix.to_owned(), local.to_owned()))
        .cloned()
        .flatten()
}

fn required_attr(
    attrs: &BTreeMap<(String, String), Option<String>>,
    local: &str,
) -> Option<String> {
    optional_trimmed_attr(attrs, local)
}

fn optional_trimmed_attr(
    attrs: &BTreeMap<(String, String), Option<String>>,
    local: &str,
) -> Option<String> {
    attr_value(attrs, "", local)
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
}

fn call_arguments(attrs: &BTreeMap<(String, String), Option<String>>) -> BTreeMap<String, Value> {
    attrs
        .iter()
        .filter(|((prefix, local), _)| prefix == "with" && !local.trim().is_empty())
        .map(|((_, local), value)| {
            (
                local.trim().to_owned(),
                Value::String(value.clone().unwrap_or_default()),
            )
        })
        .collect()
}

fn output_function_owner(name: &str) -> Option<String> {
    name.split_once('.')
        .map(|(owner, _)| owner.trim())
        .filter(|owner| !owner.is_empty())
        .map(str::to_owned)
}

fn output_function_name_is_package_qualified(name: &str) -> bool {
    name.split_once('.')
        .is_some_and(|(owner, local)| !owner.trim().is_empty() && !local.trim().is_empty())
}

fn import_identity_from_attrs(
    attrs: &BTreeMap<(String, String), Option<String>>,
) -> Option<FormatIdentity> {
    let content_type = optional_trimmed_attr(attrs, "content-type")
        .or_else(|| optional_trimmed_attr(attrs, "contentType"));
    let schema = optional_trimmed_attr(attrs, "schema");
    if content_type.is_none() && schema.is_none() {
        return None;
    }
    Some(FormatIdentity {
        content_type,
        schema,
        ..FormatIdentity::default()
    })
}

fn parse_bool_attr(value: Option<&str>) -> Result<bool, String> {
    match value.map(str::trim).filter(|value| !value.is_empty()) {
        None | Some("false") => Ok(false),
        Some("true") => Ok(true),
        Some(other) => Err(format!(
            "unsupported boolean value `{other}`; use `true` or `false`"
        )),
    }
}

