#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum TransformTemplateAdapterExecutionPhase {
    Compile,
    Render,
}

impl TransformTemplateAdapterExecutionPhase {
    pub fn diagnostic_origin(self) -> TransformDiagnosticOrigin {
        match self {
            Self::Compile => TransformDiagnosticOrigin::TemplateCompile,
            Self::Render => TransformDiagnosticOrigin::TemplateExecution,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Compile => "compile",
            Self::Render => "render",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TransformTemplateAdapterError {
    NotImplemented {
        adapter_id: &'static str,
        phase: TransformTemplateAdapterExecutionPhase,
    },
    Failed {
        adapter_id: &'static str,
        phase: TransformTemplateAdapterExecutionPhase,
        message: String,
    },
}

impl TransformTemplateAdapterError {
    pub const NOT_IMPLEMENTED_CODE: &'static str = "cem.transform_template.adapter_not_implemented";
    pub const FAILED_CODE: &'static str = "cem.transform_template.adapter_failed";

    pub fn not_implemented(
        adapter_id: &'static str,
        phase: TransformTemplateAdapterExecutionPhase,
    ) -> Self {
        Self::NotImplemented { adapter_id, phase }
    }

    pub fn failed(
        adapter_id: &'static str,
        phase: TransformTemplateAdapterExecutionPhase,
        message: impl Into<String>,
    ) -> Self {
        Self::Failed {
            adapter_id,
            phase,
            message: message.into(),
        }
    }

    pub fn adapter_id(&self) -> &'static str {
        match self {
            Self::NotImplemented { adapter_id, .. } | Self::Failed { adapter_id, .. } => adapter_id,
        }
    }

    pub fn phase(&self) -> TransformTemplateAdapterExecutionPhase {
        match self {
            Self::NotImplemented { phase, .. } | Self::Failed { phase, .. } => *phase,
        }
    }

    pub fn code(&self) -> &'static str {
        match self {
            Self::NotImplemented { .. } => Self::NOT_IMPLEMENTED_CODE,
            Self::Failed { .. } => Self::FAILED_CODE,
        }
    }

    pub fn diagnostic_origin(&self) -> TransformDiagnosticOrigin {
        self.phase().diagnostic_origin()
    }

    pub fn diagnostic(&self, uri: Option<&str>) -> Diagnostic {
        Diagnostic {
            uri: uri.map(str::to_owned),
            code: self.code().to_owned(),
            severity: Severity::Fatal,
            message: self.to_string(),
            details: None,
            ..Diagnostic::default()
        }
    }
}

impl fmt::Display for TransformTemplateAdapterError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NotImplemented { adapter_id, phase } => write!(
                f,
                "transform template adapter `{adapter_id}` does not implement {}",
                phase.label()
            ),
            Self::Failed {
                adapter_id,
                phase,
                message,
            } => write!(
                f,
                "transform template adapter `{adapter_id}` failed during {}: {message}",
                phase.label()
            ),
        }
    }
}

impl std::error::Error for TransformTemplateAdapterError {}

pub type TransformTemplateAdapterResult<T> = Result<T, TransformTemplateAdapterError>;

pub trait TransformTemplateAdapter: Send + Sync {
    fn id(&self) -> &'static str;
    fn kind(&self) -> TransformTemplateKind;
    fn capability(&self) -> TransformTemplateAdapterCapability {
        TransformTemplateAdapterCapability::SelectorOnly
    }

    fn matches_template(&self, identity: &FormatIdentity) -> bool;

    fn compile(
        &self,
        request: TransformTemplateCompileRequest<'_>,
    ) -> TransformTemplateAdapterResult<TransformTemplateCompileResponse> {
        let _ = request;
        Err(TransformTemplateAdapterError::not_implemented(
            self.id(),
            TransformTemplateAdapterExecutionPhase::Compile,
        ))
    }

    fn render(
        &self,
        request: TransformTemplateRenderRequest<'_>,
    ) -> TransformTemplateAdapterResult<TransformTemplateRenderResponse> {
        let _ = request;
        Err(TransformTemplateAdapterError::not_implemented(
            self.id(),
            TransformTemplateAdapterExecutionPhase::Render,
        ))
    }
}

#[derive(Clone, Default)]
pub struct TransformTemplateAdapterRegistry {
    adapters: Vec<Arc<dyn TransformTemplateAdapter>>,
}

impl fmt::Debug for TransformTemplateAdapterRegistry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("TransformTemplateAdapterRegistry")
            .field("adapter_count", &self.adapters.len())
            .finish()
    }
}

impl TransformTemplateAdapterRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn with_builtin_adapters() -> Self {
        let mut registry = Self::new();
        registry.register(StaticTransformTemplateAdapter::new(
            "cem-native-template",
            TransformTemplateKind::CemNative,
            &[
                "application/cem+xml",
                "application/cem",
                CEM_NATIVE_TEMPLATE_CONTENT_TYPE,
                CEM_TRANSFORM_CONTENT_TYPE,
                "text/cem",
                "text/cem-ml",
            ],
            &[
                CEM_NATIVE_TEMPLATE_SCHEMA_URI,
                CEM_TRANSFORM_SCHEMA_URI,
                crate::schema::ir::CEM_CORE_NAMESPACE,
            ],
            &[crate::schema::ir::CEM_CORE_NAMESPACE],
        ));
        registry.register(StaticTransformTemplateAdapter::new(
            "cem-ql-expression",
            TransformTemplateKind::CemQlExpression,
            &[CEM_QL_EXPRESSION_CONTENT_TYPE],
            &[CEM_QL_EXPRESSION_SCHEMA_URI],
            &[],
        ));
        registry.register(StaticTransformTemplateAdapter::new(
            "xslt-template",
            TransformTemplateKind::Xslt,
            crate::legacy_custom_element::TEMPLATE_CONTENT_TYPES,
            &[XSLT_SCHEMA_URI],
            &[crate::schema::xslt::XSL_NAMESPACE],
        ));
        registry
    }

    pub fn register(&mut self, adapter: impl TransformTemplateAdapter + 'static) {
        self.adapters.push(Arc::new(adapter));
    }

    pub fn register_arc(&mut self, adapter: Arc<dyn TransformTemplateAdapter>) {
        self.adapters.push(adapter);
    }

    pub fn select(&self, identity: &FormatIdentity) -> TransformTemplateAdapterResolution {
        let matches = self
            .adapters
            .iter()
            .filter(|adapter| adapter.matches_template(identity))
            .cloned()
            .collect::<Vec<_>>();
        let candidates = preferred_adapter_matches(&matches);
        let selections = candidates
            .iter()
            .map(|adapter| TransformTemplateAdapterSelection {
                adapter_id: adapter.id(),
                kind: adapter.kind(),
            })
            .collect::<Vec<_>>();

        match selections.as_slice() {
            [selection] => TransformTemplateAdapterResolution::Matched(selection.clone()),
            [] => TransformTemplateAdapterResolution::Unsupported,
            many => TransformTemplateAdapterResolution::Ambiguous(
                many.iter().map(|selection| selection.adapter_id).collect(),
            ),
        }
    }

    pub fn select_adapter(&self, identity: &FormatIdentity) -> TransformTemplateAdapterLookup {
        let matches = self
            .adapters
            .iter()
            .filter(|adapter| adapter.matches_template(identity))
            .cloned()
            .collect::<Vec<_>>();
        let candidates = preferred_adapter_matches(&matches);

        match candidates.as_slice() {
            [adapter] => TransformTemplateAdapterLookup::Matched(Arc::clone(adapter)),
            [] => TransformTemplateAdapterLookup::Unsupported,
            many => TransformTemplateAdapterLookup::Ambiguous(
                many.iter().map(|adapter| adapter.id()).collect(),
            ),
        }
    }
}

fn preferred_adapter_matches(
    matches: &[Arc<dyn TransformTemplateAdapter>],
) -> Vec<&Arc<dyn TransformTemplateAdapter>> {
    let executable = matches
        .iter()
        .filter(|adapter| adapter.capability() == TransformTemplateAdapterCapability::Executable)
        .collect::<Vec<_>>();
    if executable.is_empty() {
        matches.iter().collect()
    } else {
        executable
    }
}

#[derive(Debug, Clone)]
pub struct StaticTransformTemplateAdapter {
    id: &'static str,
    kind: TransformTemplateKind,
    content_types: Vec<String>,
    schemas: Vec<String>,
    namespaces: Vec<String>,
}

impl StaticTransformTemplateAdapter {
    pub fn new(
        id: &'static str,
        kind: TransformTemplateKind,
        content_types: &[&str],
        schemas: &[&str],
        namespaces: &[&str],
    ) -> Self {
        Self {
            id,
            kind,
            content_types: content_types
                .iter()
                .map(|content_type| content_type_essence(content_type))
                .collect(),
            schemas: schemas
                .iter()
                .map(|schema| schema.trim().to_owned())
                .collect(),
            namespaces: namespaces
                .iter()
                .map(|namespace| namespace.trim().to_owned())
                .collect(),
        }
    }
}

impl TransformTemplateAdapter for StaticTransformTemplateAdapter {
    fn id(&self) -> &'static str {
        self.id
    }

    fn kind(&self) -> TransformTemplateKind {
        self.kind
    }

    fn matches_template(&self, identity: &FormatIdentity) -> bool {
        if let Some(content_type) = identity.content_type.as_deref() {
            return self
                .content_types
                .iter()
                .any(|allowed| allowed == &content_type_essence(content_type));
        }

        let schema = identity
            .schema
            .as_deref()
            .map(str::trim)
            .unwrap_or_default();
        if !schema.is_empty() {
            return self.schemas.iter().any(|allowed| allowed == schema);
        }

        identity
            .default_namespace
            .as_deref()
            .is_some_and(|uri| self.namespaces.iter().any(|allowed| allowed == uri))
            || identity
                .namespaces
                .values()
                .any(|uri| self.namespaces.iter().any(|allowed| allowed == uri))
    }
}

fn content_type_essence(content_type: &str) -> String {
    content_type
        .split(';')
        .next()
        .unwrap_or(content_type)
        .trim()
        .to_ascii_lowercase()
}

const CEMT_FORMATTER_COLORING_PIPELINE_URI: &str =
    "schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt";
const CEMT_FORMATTER_COLORING_PIPELINE_SOURCE: &str =
    include_str!("../schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt");

struct CemtFormatterColoringPipelineExecution {
    formatted: Value,
    colored: Value,
    writer_output: String,
    colorizer: String,
}

pub fn cemt_formatter_coloring_pipeline_fixture_source() -> Result<String, String> {
    let source_ast = cemt_formatter_coloring_pipeline_showcase_source_ast();
    let execution = execute_cemt_formatter_coloring_pipeline(source_ast.clone())?;
    if execution.writer_output.is_empty() {
        return Err("CEMT pipeline writer output was empty".to_owned());
    }

    render_cemt_formatter_coloring_pipeline_fixture(
        CEMT_FORMATTER_COLORING_PIPELINE_URI,
        &source_ast,
        &execution.formatted,
        &execution.colored,
        &execution.colorizer,
    )
}

pub(crate) fn cemt_formatter_coloring_pipeline_showcase_source_ast() -> Value {
    serde_json::json!({
        "kind": "element",
        "name": "article",
        "sourceMap": null,
        "attributes": [],
        "children": [
            {"kind": "text", "value": "Ready ", "sourceMap": null},
            {
                "kind": "element",
                "name": "strong",
                "sourceMap": null,
                "attributes": [],
                "children": [{"kind": "text", "value": "now", "sourceMap": null}]
            },
            {"kind": "text", "value": ".", "sourceMap": null}
        ]
    })
}

fn execute_cemt_formatter_coloring_pipeline(
    source_ast: Value,
) -> Result<CemtFormatterColoringPipelineExecution, String> {
    let response = parse_cem_native_template_module_options(TransformTemplateModuleParseRequest {
        template: cemt_fixture_template_input(
            CEMT_FORMATTER_COLORING_PIPELINE_URI,
            CEMT_FORMATTER_COLORING_PIPELINE_SOURCE,
        ),
    });
    if !response.diagnostics.is_empty() {
        return Err(response
            .diagnostics
            .iter()
            .map(|diagnostic| diagnostic.message.as_str())
            .collect::<Vec<_>>()
            .join("; "));
    }

    let registry =
        TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
    let host_capabilities = BTreeSet::new();
    let value_bindings = BTreeMap::new();
    let format_request = TransformTemplateEncodeBindingRequest::new(
        source_ast.clone(),
        TransformTemplateEncodingTarget::new(CEM_ML_CONTENT_TYPE, CEM_ML_SCHEMA_URI, "cem-tree"),
    )
    .with_subject_type("cem-ast-node")
    .with_options(TransformTemplateEncodeOptions {
        formatter: Some("acme.showcase.format-tree".to_owned()),
        canonical: true,
        ..TransformTemplateEncodeOptions::default()
    });
    let format_binding = registry
        .resolve_format_binding(&format_request, &host_capabilities)
        .map_err(|error| {
            error
                .diagnostic(Some(CEMT_FORMATTER_COLORING_PIPELINE_URI))
                .message
        })?;
    let mut reject_fallback = |binding: &TransformTemplateEncodeBinding, _subject: &Value| {
        Err(format!(
            "unexpected fallback while generating CEMT fixture for `{}`",
            binding.function.name
        ))
    };
    let formatted = execute_transform_template_encode_binding(
        &format_binding,
        &source_ast,
        &TransformTemplateEncodeEvaluationContext {
            registry: &registry,
            value_bindings: &value_bindings,
            host_capabilities: &host_capabilities,
            output_color_type: None,
            uri: Some(CEMT_FORMATTER_COLORING_PIPELINE_URI),
        },
        &mut reject_fallback,
    )?;

    let color_request = TransformTemplateEncodeBindingRequest::new(
        formatted.clone(),
        TransformTemplateEncodingTarget::new(CEM_ML_CONTENT_TYPE, CEM_ML_SCHEMA_URI, "cem-tree"),
    )
    .with_subject_type("cem-tree")
    .with_options(TransformTemplateEncodeOptions {
        colorizer: Some("acme.showcase.color-tree".to_owned()),
        color_profile: Some("classes".to_owned()),
        ..TransformTemplateEncodeOptions::default()
    });
    let color_binding = registry
        .resolve_color_binding(&color_request, &host_capabilities)
        .map_err(|error| {
            error
                .diagnostic(Some(CEMT_FORMATTER_COLORING_PIPELINE_URI))
                .message
        })?
        .into_encode_binding();
    let colorizer = color_binding.function.name.clone();
    let colored = execute_transform_template_encode_binding(
        &color_binding,
        &color_request.subject,
        &TransformTemplateEncodeEvaluationContext {
            registry: &registry,
            value_bindings: &value_bindings,
            host_capabilities: &host_capabilities,
            output_color_type: None,
            uri: Some(CEMT_FORMATTER_COLORING_PIPELINE_URI),
        },
        &mut reject_fallback,
    )?;

    let writer_context = TransformTemplateEncodedArtifactInsertionContext {
        produces: Some(TransformTemplateOutputProducedKind::Text),
        content_type: HTML_CONTENT_TYPE.to_owned(),
        schema: HTML_SCHEMA_URI.to_owned(),
        category: Some("html-fragment".to_owned()),
        context: Some("fragment".to_owned()),
        formatter_profile: Some("acme.showcase.format-tree".to_owned()),
        color_profile: Some("classes".to_owned()),
        color_capability: None,
        output_color_type: None,
        binary_framing: None,
        mode: Some(TransformTemplateEncodedArtifactMode::Fragment),
        canonical: Some(true),
        source_map_policy: Some(TransformTemplateSourceMapPolicy::Generated),
    };
    transform_template_writer_cem_tree_artifact_to_text(
        &color_binding.artifact_from_value(colored.clone()),
        &writer_context,
    )
    .and_then(|artifact| {
        artifact
            .value
            .as_str()
            .map(str::to_owned)
            .ok_or_else(|| "CEMT pipeline writer output was not text".to_owned())
    })
    .map(|writer_output| CemtFormatterColoringPipelineExecution {
        formatted,
        colored,
        writer_output,
        colorizer,
    })
}

fn cemt_fixture_template_input(uri: &str, source: &str) -> TemplateInput {
    TemplateInput {
        uri: uri.to_owned(),
        bytes: source.as_bytes().to_vec(),
        identity: Some(FormatIdentity {
            schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
            ..FormatIdentity::default()
        }),
        root_scope: ScopeConfig::default(),
    }
}

pub(crate) fn render_cemt_formatter_coloring_pipeline_fixture(
    source_uri: &str,
    source_ast: &Value,
    formatted: &Value,
    colored: &Value,
    colorizer: &str,
) -> Result<String, String> {
    let formatter = cemt_fixture_required_str(formatted, "formatterProfile")?;
    let color_profile = cemt_fixture_required_str(colored, "colorProfile")?;
    let source_stage = cemt_fixture_render_node(source_ast, 0)?;
    let formatted_stage = cemt_fixture_render_cem_tree(formatted)?;
    let colored_stage = cemt_fixture_render_cem_tree(colored)?;
    Ok(format!(
        r#"@doc cem-ml 1
@ns showcase = "https://cem.dev/ns/showcase/1"
@default showcase

{{cemt-output-pipeline-fixture
    @source="{source_uri}"
    @formatter="{formatter}"
    @colorizer="{colorizer}"
    @color-profile="{color_profile}" |
    {{stage
        @name="source-ast"
        @content-type="application/cem"
        @schema="https://cem.dev/ns/cem-ml/1"
        @category="cem-fragment" |
```cem
{source_stage}
```
    }}

    {{stage
        @name="formatted-cem-tree"
        @content-type="application/cem"
        @schema="https://cem.dev/ns/cem-ml/1"
        @category="cem-tree" |
```cem
{formatted_stage}
```
    }}

    {{stage
        @name="colored-cem-tree"
        @content-type="application/cem"
        @schema="https://cem.dev/ns/cem-ml/1"
        @category="cem-tree" |
```cem
{colored_stage}
```
    }}
}}
"#
    ))
}

fn cemt_fixture_render_cem_tree(tree: &Value) -> Result<String, String> {
    let mut attributes = vec![
        cemt_fixture_attribute(
            "content-type",
            cemt_fixture_required_str(tree, "contentType")?,
        ),
        cemt_fixture_attribute("schema", cemt_fixture_required_str(tree, "schema")?),
        cemt_fixture_attribute("category", cemt_fixture_required_str(tree, "category")?),
        cemt_fixture_attribute("mode", cemt_fixture_required_str(tree, "mode")?),
        cemt_fixture_bool_attribute("canonical", cemt_fixture_required_bool(tree, "canonical")?),
        cemt_fixture_attribute(
            "formatter-profile",
            cemt_fixture_required_str(tree, "formatterProfile")?,
        ),
    ];
    if cemt_fixture_optional_bool(tree, "colored") == Some(true) {
        attributes.push(cemt_fixture_bool_attribute("colored", true));
    }
    if let Some(color_profile) = cemt_fixture_optional_str(tree, "colorProfile") {
        attributes.push(cemt_fixture_attribute("color-profile", color_profile));
    }

    let mut children = Vec::new();
    children.push(cemt_fixture_render_metadata_array(
        "format-nodes",
        cemt_fixture_required_array(tree, "formatNodes")?,
        1,
    )?);
    if let Some(color_nodes) = cemt_fixture_optional_array(tree, "colorNodes") {
        children.push(cemt_fixture_render_metadata_array(
            "color-nodes",
            color_nodes,
            1,
        )?);
    }
    if let Some(writer_boundaries) = cemt_fixture_optional_array(tree, "writerBoundaries") {
        children.push(cemt_fixture_render_metadata_array(
            "writer-boundaries",
            writer_boundaries,
            1,
        )?);
    }
    children.push(cemt_fixture_render_node_array(
        "nodes",
        cemt_fixture_required_array(tree, "nodes")?,
        1,
    )?);

    Ok(format!(
        "{{cem-tree {} |\n{}\n}}",
        attributes.join(" "),
        children.join("\n")
    ))
}

fn cemt_fixture_render_metadata_array(
    name: &str,
    values: &[Value],
    depth: usize,
) -> Result<String, String> {
    let children = values
        .iter()
        .map(|value| cemt_fixture_render_metadata(value, depth + 1))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(format!(
        "{}{{{} |\n{}\n{}}}",
        cemt_fixture_indent(depth),
        name,
        children.join("\n"),
        cemt_fixture_indent(depth)
    ))
}

fn cemt_fixture_render_metadata(value: &Value, depth: usize) -> Result<String, String> {
    let fields = value
        .as_object()
        .ok_or_else(|| "CEMT fixture metadata item must be an object".to_owned())?;
    let kind = fields
        .get("kind")
        .and_then(Value::as_str)
        .ok_or_else(|| "CEMT fixture metadata item is missing `kind`".to_owned())?;
    cemt_fixture_render_object_element(kind, fields, depth, true)
}

fn cemt_fixture_render_node_array(
    name: &str,
    values: &[Value],
    depth: usize,
) -> Result<String, String> {
    let children = values
        .iter()
        .map(|value| cemt_fixture_render_node(value, depth + 1))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(format!(
        "{}{{{} |\n{}\n{}}}",
        cemt_fixture_indent(depth),
        name,
        children.join("\n"),
        cemt_fixture_indent(depth)
    ))
}

fn cemt_fixture_render_node(value: &Value, depth: usize) -> Result<String, String> {
    let fields = value
        .as_object()
        .ok_or_else(|| "CEMT fixture node must be an object".to_owned())?;
    match fields.get("kind").and_then(Value::as_str) {
        Some("text") => {
            let text = cemt_fixture_required_str(value, "value")?;
            Ok(format!(
                "{}{{text | {}}}",
                cemt_fixture_indent(depth),
                cemt_fixture_escape_text(text)
            ))
        }
        Some("element") => cemt_fixture_render_element_node(fields, depth),
        Some(other) => Err(format!("unsupported CEMT fixture node kind `{other}`")),
        None => Err("CEMT fixture node is missing `kind`".to_owned()),
    }
}

fn cemt_fixture_render_element_node(
    fields: &serde_json::Map<String, Value>,
    depth: usize,
) -> Result<String, String> {
    let name = fields
        .get("name")
        .and_then(Value::as_str)
        .ok_or_else(|| "CEMT fixture element node is missing `name`".to_owned())?;
    let mut attributes = Vec::new();
    if let Some(color_role) = fields.get("colorRole").and_then(Value::as_str) {
        attributes.push(cemt_fixture_attribute("color-role", color_role));
    }
    let mut children = Vec::new();
    if let Some(format_layout) = fields.get("formatLayout").and_then(Value::as_object) {
        children.push(cemt_fixture_render_named_object_element(
            "format-layout",
            format_layout,
            depth + 1,
        )?);
    }
    if let Some(style) = fields.get("style").and_then(Value::as_object) {
        children.push(cemt_fixture_render_named_object_element(
            "style",
            style,
            depth + 1,
        )?);
    }
    if let Some(writer_attributes) = fields.get("writerAttributeNodes").and_then(Value::as_array) {
        for attribute in writer_attributes {
            children.push(cemt_fixture_render_named_object_value(
                "writer-attribute",
                attribute,
                depth + 1,
            )?);
        }
    }
    if let Some(color_wrappers) = fields.get("colorWrapperNodes").and_then(Value::as_array) {
        for wrapper in color_wrappers {
            children.push(cemt_fixture_render_metadata(wrapper, depth + 1)?);
        }
    }
    if let Some(child_nodes) = fields.get("children").and_then(Value::as_array) {
        for child in child_nodes {
            children.push(cemt_fixture_render_node(child, depth + 1)?);
        }
    }

    let suffix = if attributes.is_empty() {
        String::new()
    } else {
        format!(" {}", attributes.join(" "))
    };
    if children.is_empty() {
        return Ok(format!("{}{{{name}{suffix}}}", cemt_fixture_indent(depth)));
    }
    Ok(format!(
        "{}{{{name}{suffix} |\n{}\n{}}}",
        cemt_fixture_indent(depth),
        children.join("\n"),
        cemt_fixture_indent(depth)
    ))
}

fn cemt_fixture_render_named_object_value(
    element: &str,
    value: &Value,
    depth: usize,
) -> Result<String, String> {
    let fields = value
        .as_object()
        .ok_or_else(|| format!("CEMT fixture `{element}` value must be an object"))?;
    cemt_fixture_render_named_object_element(element, fields, depth)
}

fn cemt_fixture_render_named_object_element(
    element: &str,
    fields: &serde_json::Map<String, Value>,
    depth: usize,
) -> Result<String, String> {
    let skip_kind = fields.get("kind").and_then(Value::as_str) == Some(element);
    cemt_fixture_render_object_element(element, fields, depth, skip_kind)
}

fn cemt_fixture_render_object_element(
    element: &str,
    fields: &serde_json::Map<String, Value>,
    depth: usize,
    skip_kind: bool,
) -> Result<String, String> {
    let attributes = cemt_fixture_ordered_attributes(fields, skip_kind);
    let suffix = if attributes.is_empty() {
        String::new()
    } else {
        format!(" {}", attributes.join(" "))
    };
    Ok(format!(
        "{}{{{element}{suffix}}}",
        cemt_fixture_indent(depth)
    ))
}

fn cemt_fixture_ordered_attributes(
    fields: &serde_json::Map<String, Value>,
    skip_kind: bool,
) -> Vec<String> {
    const ORDER: &[(&str, &str)] = &[
        ("kind", "kind"),
        ("name", "name"),
        ("stage", "stage"),
        ("value", "value"),
        ("formatterRole", "formatter-role"),
        ("formatterProfile", "formatter-profile"),
        ("colorRole", "color-role"),
        ("colorProfile", "color-profile"),
        ("colorizerOwned", "colorizer-owned"),
        ("colorizerRole", "colorizer-role"),
    ];
    let mut attributes = Vec::new();
    for (field, attribute) in ORDER {
        let Some(value) = fields.get(*field) else {
            continue;
        };
        if matches!(value, Value::Null) || (*field == "kind" && skip_kind) {
            continue;
        }
        match value {
            Value::Bool(value) => attributes.push(cemt_fixture_bool_attribute(attribute, *value)),
            Value::String(value) => attributes.push(cemt_fixture_attribute(attribute, value)),
            _ => {}
        }
    }
    attributes
}

fn cemt_fixture_required_str<'a>(value: &'a Value, field: &str) -> Result<&'a str, String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("CEMT fixture value is missing string field `{field}`"))
}

fn cemt_fixture_optional_str<'a>(value: &'a Value, field: &str) -> Option<&'a str> {
    value.get(field).and_then(Value::as_str)
}

fn cemt_fixture_required_bool(value: &Value, field: &str) -> Result<bool, String> {
    value
        .get(field)
        .and_then(Value::as_bool)
        .ok_or_else(|| format!("CEMT fixture value is missing bool field `{field}`"))
}

fn cemt_fixture_optional_bool(value: &Value, field: &str) -> Option<bool> {
    value.get(field).and_then(Value::as_bool)
}

fn cemt_fixture_required_array<'a>(value: &'a Value, field: &str) -> Result<&'a [Value], String> {
    value
        .get(field)
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .ok_or_else(|| format!("CEMT fixture value is missing array field `{field}`"))
}

fn cemt_fixture_optional_array<'a>(value: &'a Value, field: &str) -> Option<&'a [Value]> {
    value
        .get(field)
        .and_then(Value::as_array)
        .map(Vec::as_slice)
}

fn cemt_fixture_attribute(name: &str, value: &str) -> String {
    format!("@{name}=\"{}\"", cemt_fixture_escape_attribute(value))
}

fn cemt_fixture_bool_attribute(name: &str, value: bool) -> String {
    format!("@{name}={value}")
}

fn cemt_fixture_escape_attribute(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
}

fn cemt_fixture_escape_text(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('{', "\\{")
        .replace('}', "\\}")
}

fn cemt_fixture_indent(depth: usize) -> String {
    "    ".repeat(depth)
}

