    fn evaluated_html_text(owner: &str, value: &str) -> TransformTemplateEvaluatedEncodeExpression {
        let mut artifact = encoded_html_text_artifact();
        artifact.value = Value::String(value.to_owned());
        artifact.source_map = Some(source_map_stack(20, 4));
        artifact.output_spans = vec![output_span(0, value.len() as u32)];

        let expression = TransformTemplateEncodeExpression {
            owner: Some(owner.to_owned()),
            expression: format!("encode($node.{owner}, {{ contentType: \"text/html\" }})"),
            subject: format!("$node.{owner}"),
            subject_type: Some("string".to_owned()),
            target: artifact.identity.target.clone(),
            options: TransformTemplateEncodeOptions {
                canonical: artifact.identity.canonical,
                mode: artifact.identity.mode,
                charset: artifact.identity.charset.clone(),
                formatter_profile: artifact.identity.formatter_profile.clone(),
                ..TransformTemplateEncodeOptions::default()
            },
        };
        let binding = TransformTemplateEncodeBinding {
            function: output_function_descriptor(),
            subject_type: "string".to_owned(),
            identity: artifact.identity.clone(),
            options: TransformTemplateEncodeOptions::default(),
        };

        TransformTemplateEvaluatedEncodeExpression {
            expression,
            subject: Value::String(value.to_owned()),
            binding,
            artifact,
        }
    }

    fn evaluated_colored_cem_tree(owner: &str) -> TransformTemplateEvaluatedEncodeExpression {
        let target = TransformTemplateEncodingTarget::new(
            CEM_ML_CONTENT_TYPE,
            CEM_ML_SCHEMA_URI,
            "cem-tree",
        );
        let mut identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::CemTree,
            target.clone(),
        );
        identity.formatter_profile = Some("compact".to_owned());
        identity.color_profile = Some("css-custom-properties".to_owned());
        identity.mode = TransformTemplateEncodedArtifactMode::Fragment;
        identity.canonical = true;
        let value = encode_colored_cem_tree_with_profile("css-custom-properties");
        let mut artifact = TransformTemplateEncodedArtifact::new(identity.clone(), value);
        artifact.source_map = Some(source_map_stack(60, 5));
        artifact.output_spans = vec![output_span(0, 5)];

        let expression = TransformTemplateEncodeExpression {
            owner: Some(owner.to_owned()),
            expression: format!(
                "encode($node.{owner}, {{ contentType: \"{CEM_ML_CONTENT_TYPE}\" }})"
            ),
            subject: format!("$node.{owner}"),
            subject_type: Some("cem-tree".to_owned()),
            target,
            options: TransformTemplateEncodeOptions {
                canonical: identity.canonical,
                mode: identity.mode,
                formatter_profile: identity.formatter_profile.clone(),
                color_profile: identity.color_profile.clone(),
                ..TransformTemplateEncodeOptions::default()
            },
        };
        let mut function = output_function_descriptor();
        function.kind = TransformTemplateOutputFunctionKind::Color;
        function.name = "cem.color-tree".to_owned();
        function.category = "cem-tree".to_owned();
        function.subject = "cem-tree".to_owned();
        function.produces = TransformTemplateOutputProducedKind::CemTree;
        function.content_type = CEM_ML_CONTENT_TYPE.to_owned();
        function.schema = CEM_ML_SCHEMA_URI.to_owned();
        function.profile = Some("css-custom-properties".to_owned());
        let binding = TransformTemplateEncodeBinding {
            function,
            subject_type: "cem-tree".to_owned(),
            identity,
            options: TransformTemplateEncodeOptions::default(),
        };

        TransformTemplateEvaluatedEncodeExpression {
            expression,
            subject: artifact.value.clone(),
            binding,
            artifact,
        }
    }

    #[test]
    fn artifact_function_contract_accepts_matching_formatter_metadata() {
        let function = cem_tree_format_function_descriptor();
        let mismatches = validate_transform_template_artifact_function_contract(
            &function,
            TransformTemplateArtifactFunctionContract {
                artifact_kind: Some("formatter"),
                target_content_type: Some("application/cem; charset=utf-8"),
                target_schema: Some(CEM_ML_SCHEMA_URI),
                target_category: Some("cem-tree"),
                function_profile: None,
            },
        );

        assert!(
            mismatches.is_empty(),
            "unexpected mismatches: {mismatches:?}"
        );
    }

    #[test]
    fn artifact_function_contract_reports_structured_mismatches() {
        let function = cem_tree_format_function_descriptor();
        let mismatches = validate_transform_template_artifact_function_contract(
            &function,
            TransformTemplateArtifactFunctionContract {
                artifact_kind: Some("formatter"),
                target_content_type: Some("text/html"),
                target_schema: Some(CEM_ML_SCHEMA_URI),
                target_category: Some("wrong-tree"),
                function_profile: Some("canonical"),
            },
        );

        assert_eq!(
            mismatches,
            vec![
                TransformTemplateArtifactFunctionContractMismatch {
                    field: "target content type",
                    expected: "text/html".to_owned(),
                    actual: CEM_ML_CONTENT_TYPE.to_owned(),
                },
                TransformTemplateArtifactFunctionContractMismatch {
                    field: "target category",
                    expected: "wrong-tree".to_owned(),
                    actual: "cem-tree".to_owned(),
                },
                TransformTemplateArtifactFunctionContractMismatch {
                    field: "function profile",
                    expected: "canonical".to_owned(),
                    actual: "<none>".to_owned(),
                },
            ]
        );
    }

    #[test]
    fn builtins_select_cem_native_and_xslt_template_adapters() {
        let registry = TransformTemplateAdapterRegistry::with_builtin_adapters();
        let cem = FormatIdentity {
            content_type: Some("text/cem-ml; charset=utf-8".to_owned()),
            ..FormatIdentity::default()
        };
        let native_template = FormatIdentity {
            content_type: Some(format!("{CEM_NATIVE_TEMPLATE_CONTENT_TYPE}; charset=utf-8")),
            ..FormatIdentity::default()
        };
        let transform = FormatIdentity {
            content_type: Some(format!("{CEM_TRANSFORM_CONTENT_TYPE}; charset=utf-8")),
            ..FormatIdentity::default()
        };
        let expression = FormatIdentity {
            content_type: Some(format!("{CEM_QL_EXPRESSION_CONTENT_TYPE}; charset=utf-8")),
            ..FormatIdentity::default()
        };
        let xslt = FormatIdentity {
            default_namespace: Some(crate::schema::xslt::XSL_NAMESPACE.to_owned()),
            ..FormatIdentity::default()
        };

        assert_eq!(
            registry.select(&cem),
            TransformTemplateAdapterResolution::Matched(TransformTemplateAdapterSelection {
                adapter_id: "cem-native-template",
                kind: TransformTemplateKind::CemNative,
            })
        );
        assert_eq!(
            registry.select(&native_template),
            TransformTemplateAdapterResolution::Matched(TransformTemplateAdapterSelection {
                adapter_id: "cem-native-template",
                kind: TransformTemplateKind::CemNative,
            })
        );
        assert_eq!(
            registry.select(&transform),
            TransformTemplateAdapterResolution::Matched(TransformTemplateAdapterSelection {
                adapter_id: "cem-native-template",
                kind: TransformTemplateKind::CemNative,
            })
        );
        assert_eq!(
            registry.select(&expression),
            TransformTemplateAdapterResolution::Matched(TransformTemplateAdapterSelection {
                adapter_id: "cem-ql-expression",
                kind: TransformTemplateKind::CemQlExpression,
            })
        );
        assert_eq!(
            registry.select(&xslt),
            TransformTemplateAdapterResolution::Matched(TransformTemplateAdapterSelection {
                adapter_id: "xslt-template",
                kind: TransformTemplateKind::Xslt,
            })
        );
    }

    #[test]
    fn native_template_module_options_model_imports_visibility_params_and_limits() {
        let import: TransformTemplateModuleImport = serde_json::from_value(json!({
            "alias": "ui",
            "uri": "templates/ui.cem"
        }))
        .expect("import defaults");
        let entrypoint: TransformTemplateModuleEntrypointDeclaration =
            serde_json::from_value(json!({"name": "card"})).expect("entrypoint defaults");
        let param: TransformTemplateModuleParamDeclaration = serde_json::from_value(json!({
            "name": "locale",
            "type": "string",
            "nullable": true,
            "defaultValue": "en-US"
        }))
        .expect("param defaults");
        let let_binding: TransformTemplateModuleLetBinding = serde_json::from_value(json!({
            "name": "layout",
            "type": "string",
            "value": "block"
        }))
        .expect("let binding defaults");
        let options = TransformTemplateModuleOptions {
            imports: vec![import],
            entrypoints: vec![entrypoint],
            params: vec![param],
            calls: Vec::new(),
            let_bindings: vec![let_binding],
            encode_expressions: Vec::new(),
            functions: Vec::new(),
            output_functions: Vec::new(),
            limits: TransformTemplateModuleLimits::default(),
        };

        assert_eq!(
            options.imports[0].kind,
            TransformTemplateModuleDependencyKind::Import
        );
        assert_eq!(
            options.entrypoints[0].visibility,
            TransformTemplateModuleVisibility::Private
        );
        assert_eq!(
            options.params[0].visibility,
            TransformTemplateModuleVisibility::Private
        );
        assert_eq!(
            options.params[0].value_type,
            TransformTemplateModuleParamType::String
        );
        assert_eq!(options.let_bindings[0].name, "layout");
        assert_eq!(
            options.let_bindings[0].value_type,
            TransformTemplateModuleParamType::String
        );
        assert_eq!(options.let_bindings[0].value, json!("block"));
        assert!(options.params[0].nullable);
        assert!(!options.params[0].required);
        assert_eq!(options.limits.max_import_depth, 32);
        assert_eq!(options.limits.max_recursion_depth, 64);
    }

    #[test]
    fn cem_native_template_schema_shape_declares_module_surface() {
        let module = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "module")
            .expect("module schema");
        let import = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "import")
            .expect("import schema");
        let template = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "template")
            .expect("template schema");
        let call = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "call")
            .expect("call schema");
        let let_decl = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "let")
            .expect("let schema");
        let param = CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS
            .iter()
            .find(|element| element.local_name == "param")
            .expect("param schema");

        assert_eq!(
            CEM_NATIVE_TEMPLATE_SCHEMA_URI,
            CEM_NATIVE_TEMPLATE_NAMESPACE_URI
        );
        assert_eq!(
            module.child_elements,
            &["import", "param", "template", "body"]
        );
        assert_eq!(import.required_attributes, &["as", "src"]);
        assert!(import.optional_attributes.contains(&"content-type"));
        assert!(param.optional_attributes.contains(&"type"));
        assert!(param.optional_attributes.contains(&"nullable"));
        assert_eq!(template.required_attributes, &["name"]);
        assert!(template.optional_attributes.contains(&"visibility"));
        assert_eq!(let_decl.required_attributes, &["name"]);
        assert!(let_decl.optional_attributes.contains(&"type"));
        assert!(let_decl.optional_attributes.contains(&"nullable"));
        assert!(let_decl.optional_attributes.contains(&"value"));
        assert!(let_decl.optional_attributes.contains(&"expr"));
        assert!(let_decl.optional_attributes.contains(&"expression"));
        assert_eq!(call.required_attributes, &["template"]);
        assert!(call.optional_attributes.contains(&"from"));
        assert!(call.optional_attributes.contains(&"with:*"));
    }

    #[test]
    fn cem_native_template_schema_artifact_matches_shape_table() {
        let artifact = include_str!(
            "../schema-packages/cem-native-template/v1/schema/cem-native-template.cem"
        );

        assert!(artifact.contains(CEM_NATIVE_TEMPLATE_SCHEMA_URI));
        assert!(artifact.contains(CEM_NATIVE_TEMPLATE_NAMESPACE_URI));
        for element in CEM_NATIVE_TEMPLATE_SCHEMA_ELEMENTS {
            assert!(
                artifact.contains(&format!("{{element @name=\"{}\"", element.local_name)),
                "artifact should document `{}`",
                element.local_name
            );
            for attribute in element
                .required_attributes
                .iter()
                .chain(element.optional_attributes.iter())
            {
                assert!(
                    artifact.contains(&format!("@name=\"{attribute}\"")),
                    "artifact should document `{}` attribute on `{}`",
                    attribute,
                    element.local_name
                );
            }
            for child in element.child_elements {
                assert!(
                    artifact.contains(child),
                    "artifact should document `{}` child on `{}`",
                    child,
                    element.local_name
                );
            }
        }
    }

