    #[test]
    fn cemt_runtime_metadata_accumulators_collect_formatter_coloring_and_writer_metadata() {
        let values = BTreeMap::from([(
            "node".to_owned(),
            json!({
                "name": "button",
                "colorRole": "syntax.name"
            }),
        )]);

        assert_eq!(
            resolve_encode_subject_expression(
                r#"appendWriterBoundary(
                    appendOutputSpan(
                        appendNamespace(
                            appendDiagnostic(
                                appendColorNode(
                                    appendFormatNode(
                                        { kind: "cem-tree" },
                                        {
                                            kind: "format-decision",
                                            name: "formatter.block",
                                            formatterRole: "formatter.block",
                                            value: "\t"
                                        }
                                    ),
                                    {
                                        kind: "color-decision",
                                        name: "color.syntax",
                                        colorizerRole: "colorizer.syntax",
                                        colorRole: $node.colorRole
                                    }
                                ),
                                diagnostic({
                                    code: "cem.format.metadata",
                                    message: $node.name
                                })
                            ),
                            {
                                prefix: "svg",
                                uri: "http://www.w3.org/2000/svg"
                            }
                        ),
                        {
                            kind: "generated",
                            start: 0,
                            end: 6
                        }
                    ),
                    {
                        kind: "writer-boundary",
                        stage: "pre-write"
                    }
                )"#,
                &values,
            ),
            Some(json!({
                "kind": "cem-tree",
                "formatNodes": [{
                    "kind": "format-decision",
                    "name": "formatter.block",
                    "formatterRole": "formatter.block",
                    "value": "\t"
                }],
                "colorNodes": [{
                    "kind": "color-decision",
                    "name": "color.syntax",
                    "colorizerRole": "colorizer.syntax",
                    "colorRole": "syntax.name"
                }],
                "diagnostics": [{
                    "code": "cem.format.metadata",
                    "severity": "info",
                    "message": "button"
                }],
                "namespaceDeclarations": [{
                    "prefix": "svg",
                    "uri": "http://www.w3.org/2000/svg"
                }],
                "outputSpans": [{
                    "kind": "generated",
                    "start": 0,
                    "end": 6
                }],
                "writerBoundaries": [{
                    "kind": "writer-boundary",
                    "stage": "pre-write"
                }]
            }))
        );
        assert_eq!(
            values.get("node"),
            Some(&json!({
                "name": "button",
                "colorRole": "syntax.name"
            })),
            "metadata accumulator helpers do not mutate source bindings"
        );
    }

    #[test]
    fn cemt_runtime_metadata_accumulators_default_formatter_and_color_source_maps() {
        let tree_source_map =
            serde_json::to_value(source_map_stack(120, 6)).expect("tree source map serializes");
        let explicit_source_map =
            serde_json::to_value(source_map_stack(140, 3)).expect("explicit source map serializes");
        let values = BTreeMap::from([
            (
                "tree".to_owned(),
                json!({
                    "kind": "cem-tree",
                    "sourceMap": tree_source_map
                }),
            ),
            ("explicit".to_owned(), explicit_source_map.clone()),
        ]);

        let tree = resolve_encode_subject_expression(
            r#"appendColorNode(
                appendFormatNode(
                    appendFormatNode(
                        $tree,
                        {
                            kind: "format-decision",
                            name: "layout",
                            formatterRole: "formatter.layout"
                        }
                    ),
                    {
                        kind: "format-decision",
                        name: "explicit",
                        formatterRole: "formatter.layout",
                        sourceMap: $explicit
                    }
                ),
                {
                    kind: "color-decision",
                    name: "syntax",
                    colorizerRole: "colorizer.syntax"
                }
            )"#,
            &values,
        )
        .expect("metadata helpers resolve");

        assert_cem_tree_source_map_current_transform(
            &tree["formatNodes"][0]["sourceMap"],
            |transform| {
                matches!(
                    transform,
                    TransformKind::TemplateTransform { function }
                        if function == "cem.format-tree"
                )
            },
        );
        assert_eq!(
            tree["formatNodes"][1]["sourceMap"], explicit_source_map,
            "explicit metadata source maps are preserved"
        );
        assert_cem_tree_source_map_current_transform(
            &tree["colorNodes"][0]["sourceMap"],
            |transform| {
                matches!(
                    transform,
                    TransformKind::TemplateTransform { function }
                        if function == "cem.color-tree"
                )
            },
        );
    }

