    #[test]
    fn cemt_runtime_call_expression_binds_parameters_for_formatter_helpers() {
        let values = BTreeMap::from([(
            "node".to_owned(),
            json!({
                "kind": "element",
                "name": "card",
                "children": [
                    {"kind": "text", "value": "Ready"},
                    {
                        "kind": "element",
                        "name": "badge",
                        "children": [{"kind": "text", "value": "New"}]
                    }
                ]
            }),
        )]);
        let functions = BTreeMap::from([
            (
                "formatNode".to_owned(),
                cemt_runtime_function(
                    vec![
                        cemt_required_param("node", TransformTemplateModuleParamType::Object),
                        cemt_required_param("slot", TransformTemplateModuleParamType::Integer),
                    ],
                    r#"match($node.kind, {
                        element: call(formatElement, { node: $node, slot: $slot }),
                        text: call(formatText, { node: $node, slot: $slot }),
                        default: { kind: "unknown", slot: $slot }
                    })"#,
                ),
            ),
            (
                "formatElement".to_owned(),
                cemt_runtime_function(
                    vec![
                        cemt_required_param("node", TransformTemplateModuleParamType::Object),
                        cemt_required_param("slot", TransformTemplateModuleParamType::Integer),
                    ],
                    r#"{
                        kind: "element",
                        name: $node.name,
                        slot: $slot,
                        children: map($node.children, call(formatNode, { node: $item, slot: $index }))
                    }"#,
                ),
            ),
            (
                "formatText".to_owned(),
                cemt_runtime_function(
                    vec![
                        cemt_required_param("node", TransformTemplateModuleParamType::Object),
                        cemt_required_param("slot", TransformTemplateModuleParamType::Integer),
                    ],
                    r#"{ kind: "text", text: $node.value, slot: $slot }"#,
                ),
            ),
        ]);

        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call(formatNode, { node: $node, slot: 0 })"#,
                &values,
                &functions,
            ),
            Some(json!({
                "kind": "element",
                "name": "card",
                "slot": 0,
                "children": [
                    {"kind": "text", "text": "Ready", "slot": 0},
                    {
                        "kind": "element",
                        "name": "badge",
                        "slot": 1,
                        "children": [{"kind": "text", "text": "New", "slot": 0}]
                    }
                ]
            }))
        );
        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call(formatNode, { node: $node })"#,
                &values,
                &functions,
            ),
            None
        );
    }

    #[test]
    fn cemt_runtime_call_expression_applies_param_defaults_and_validation() {
        let values = BTreeMap::from([(
            "node".to_owned(),
            json!({
                "kind": "element",
                "name": "card"
            }),
        )]);
        let functions = BTreeMap::from([(
            "decorate".to_owned(),
            cemt_runtime_function(
                vec![
                    cemt_required_param("subject", TransformTemplateModuleParamType::Object),
                    cemt_default_param(
                        "role",
                        TransformTemplateModuleParamType::String,
                        json!("syntax.name"),
                    ),
                    cemt_default_param(
                        "depth",
                        TransformTemplateModuleParamType::Integer,
                        json!(0),
                    ),
                ],
                r#"{
                    kind: $subject.kind,
                    name: $subject.name,
                    role: $role,
                    depth: $depth
                }"#,
            ),
        )]);

        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call(decorate, { subject: $node })"#,
                &values,
                &functions,
            ),
            Some(json!({
                "kind": "element",
                "name": "card",
                "role": "syntax.name",
                "depth": 0
            }))
        );
        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call(decorate, { subject: $node, role: "syntax.keyword", depth: 2 })"#,
                &values,
                &functions,
            ),
            Some(json!({
                "kind": "element",
                "name": "card",
                "role": "syntax.keyword",
                "depth": 2
            }))
        );

        let unknown = resolve_encode_subject_expression_at_depth(
            r#"call(decorate, { subject: $node, extra: true })"#,
            &values,
            &functions,
            None,
            0,
        )
        .expect_err("unknown call arguments are rejected");
        assert!(unknown.contains("unknown argument `extra`"));

        let missing = resolve_encode_subject_expression_at_depth(
            r#"call(decorate, { role: "syntax.keyword" })"#,
            &values,
            &functions,
            None,
            0,
        )
        .expect_err("missing required call arguments are rejected");
        assert!(missing.contains("requires argument `subject`"));

        let type_error = resolve_encode_subject_expression_at_depth(
            r#"call(decorate, { subject: $node, depth: "wide" })"#,
            &values,
            &functions,
            None,
            0,
        )
        .expect_err("call argument type is validated");
        assert!(type_error.contains("argument `depth` expected integer, got string"));
    }

    #[test]
    fn cemt_runtime_call_expression_validates_declared_return_type() {
        let functions = BTreeMap::from([(
            "buildNodes".to_owned(),
            cemt_typed_runtime_function(
                vec![cemt_required_param(
                    "subject",
                    TransformTemplateModuleParamType::Object,
                )],
                TransformTemplateModuleParamType::Array,
                r#"{ kind: $subject.kind }"#,
            ),
        )]);
        let values = BTreeMap::from([("node".to_owned(), json!({"kind": "element"}))]);

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(buildNodes, { subject: $node })"#,
            &values,
            &functions,
            None,
            0,
        )
        .expect_err("wrong return type is rejected");
        assert!(error.contains("CEMT function `buildNodes` returned object, expected array"));
    }

