    #[test]
    fn cemt_module_parser_lowers_internal_function_declarations() {
        let response =
            parse_cem_native_template_module_options(TransformTemplateModuleParseRequest {
                template: template_input(
                    "templates/internal-functions.cemt",
                    r#"{@doc cem-ml 1}
{module |
  {function
      @name="acme.build-nodes"
      @visibility="private"
      @returns="array"
      @deterministic=true |
      {param @name="subject" @type="array" @required=true}
      {body |
        {$ map($subject, { kind: $item.kind, slot: $index }) }
      }
  }
  {format-function
      @name="acme.format-root"
      @category="cem-tree"
      @subject="array"
      @produces="cem-tree"
      @content-type="application/cem"
      @schema="https://cem.dev/ns/cem-ml/1"
      @canonical=true
      @deterministic=true
      @streamable=true |
      {param @name="subject" @type="array" @required=true}
      {body |
        {$ { kind: "cem-tree", nodes: call("acme.build-nodes", { subject: $subject }) } }
      }
  }
}"#,
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            });

        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        let helper = response
            .module_options
            .functions
            .iter()
            .find(|function| function.name == "acme.build-nodes")
            .expect("internal helper function declaration");
        assert_eq!(helper.owner.as_deref(), Some("acme"));
        assert_eq!(
            helper.visibility,
            TransformTemplateModuleVisibility::Private
        );
        assert_eq!(helper.return_type, TransformTemplateModuleParamType::Array);
        assert!(helper.deterministic);
        assert_eq!(helper.params.len(), 1);
        assert!(helper
            .body_expression
            .as_deref()
            .is_some_and(|body| body.contains("map($subject")));

        let runtime_functions =
            cemt_runtime_functions_from_module_options(&response.module_options);
        assert!(runtime_functions.contains_key("acme.build-nodes"));
        assert!(runtime_functions.contains_key("acme.format-root"));
        let values = BTreeMap::from([(
            "nodes".to_owned(),
            json!([
                {"kind": "element"},
                {"kind": "text"}
            ]),
        )]);

        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call("acme.format-root", { subject: $nodes })"#,
                &values,
                &runtime_functions,
            ),
            Some(json!({
                "kind": "cem-tree",
                "nodes": [
                    {"kind": "element", "slot": 0},
                    {"kind": "text", "slot": 1}
                ]
            }))
        );
    }

    #[test]
    fn cemt_module_output_function_bodies_build_runtime_call_table() {
        let response = parse_cem_native_template_module_options(
            TransformTemplateModuleParseRequest {
                template: template_input(
                    "templates/runtime-function-bodies.cemt",
                    r#"{@doc cem-ml 1}
{module |
  {format-function
      @name="acme.format-node"
      @category="cem-tree"
      @subject="object"
      @produces="cem-tree"
      @content-type="application/cem"
      @schema="https://cem.dev/ns/cem-ml/1"
      @canonical=true
      @deterministic=true
      @streamable=true |
      {param @name="subject" @type="object" @required=true}
      {param @name="slot" @type="integer" @required=true}
      {body |
        {$ {
          kind: "element",
          name: $subject.name,
          slot: $slot,
          children: fold($subject.children, [], append($acc, call(acme.format-node, { subject: $item, slot: $index })))
        } }
      }
  }
  {format-function
      @name="acme.format-root"
      @category="cem-tree"
      @subject="object"
      @produces="cem-tree"
      @content-type="application/cem"
      @schema="https://cem.dev/ns/cem-ml/1"
      @canonical=true
      @deterministic=true
      @streamable=true |
      {param @name="subject" @type="object" @required=true}
      {body |
        {$ call(acme.format-node, { subject: $subject, slot: 0 }) }
      }
  }
}"#,
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            },
        );

        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        assert!(response.module_options.encode_expressions.is_empty());
        let format_node = response
            .module_options
            .output_functions
            .iter()
            .find(|function| function.name == "acme.format-node")
            .expect("format-node function");
        assert!(format_node.body_declared);
        assert!(format_node
            .body_expression
            .as_deref()
            .is_some_and(|body| body.contains("fold($subject.children")));

        let runtime_functions =
            cemt_runtime_functions_from_module_options(&response.module_options);
        assert_eq!(runtime_functions.len(), 2);
        let registry =
            TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
        assert_eq!(registry.runtime_functions.len(), 2);
        let values = BTreeMap::from([(
            "node".to_owned(),
            json!({
                "name": "card",
                "children": [
                    {"name": "title", "children": []},
                    {"name": "badge", "children": []}
                ]
            }),
        )]);

        assert_eq!(
            resolve_encode_subject_expression_with_functions(
                r#"call(acme.format-root, { subject: $node })"#,
                &values,
                &runtime_functions,
            ),
            Some(json!({
                "kind": "element",
                "name": "card",
                "slot": 0,
                "children": [
                    {"kind": "element", "name": "title", "slot": 0, "children": []},
                    {"kind": "element", "name": "badge", "slot": 1, "children": []}
                ]
            }))
        );
    }

    #[test]
    fn cemt_module_parser_lowers_output_function_declarations() {
        let response =
            parse_cem_native_template_module_options(TransformTemplateModuleParseRequest {
                template: template_input(
                    "schema-packages/cem-transform/v1/examples/function-declarations.cemt",
                    include_str!(
                        "../schema-packages/cem-transform/v1/examples/function-declarations.cemt"
                    ),
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            });

        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        assert!(response.module_declared);
        let normalize_callout = response
            .module_options
            .functions
            .iter()
            .find(|function| function.name == "acme.normalize-callout")
            .expect("internal helper function declaration");
        assert_eq!(normalize_callout.owner.as_deref(), Some("acme"));
        assert_eq!(
            normalize_callout.return_type,
            TransformTemplateModuleParamType::Object
        );
        assert!(normalize_callout.deterministic);
        assert!(normalize_callout
            .body_expression
            .as_deref()
            .is_some_and(|body| body.contains("kind: \"callout\"")));
        assert_eq!(response.module_options.output_functions.len(), 6);
        let html_text = &response.module_options.output_functions[0];
        assert_eq!(
            html_text.kind,
            TransformTemplateOutputFunctionKind::Encoding
        );
        assert_eq!(html_text.owner.as_deref(), Some("html"));
        assert_eq!(html_text.name, "html.text");
        assert_eq!(html_text.category, "html-text");
        assert_eq!(
            html_text.produces,
            TransformTemplateOutputProducedKind::Text
        );
        assert_eq!(html_text.content_type, "text/html");
        assert_eq!(html_text.schema, "https://cem.dev/ns/data/html/1");
        assert!(html_text.canonical);
        assert!(html_text.streamable);
        assert_eq!(html_text.params.len(), 2);

        let custom = response
            .module_options
            .output_functions
            .iter()
            .find(|function| function.name == "acme.markdown.callout-block")
            .expect("custom function declaration");
        assert_eq!(custom.owner.as_deref(), Some("acme"));
        assert_eq!(
            custom.implementation,
            TransformTemplateOutputFunctionImplementation::Cemt
        );
        assert_eq!(custom.visibility, TransformTemplateModuleVisibility::Public);
        assert!(custom.deterministic);
        assert_eq!(custom.extends.as_deref(), Some("markdown-document"));
        assert!(custom.body_declared);
        assert_eq!(custom.body_expression, None);

        let cem_tree = response
            .module_options
            .output_functions
            .iter()
            .find(|function| function.name == "cem.format-tree")
            .expect("CEM tree formatter declaration");
        assert_eq!(cem_tree.kind, TransformTemplateOutputFunctionKind::Format);
        assert_eq!(
            cem_tree.produces,
            TransformTemplateOutputProducedKind::CemTree
        );
        assert_eq!(cem_tree.category, "cem-tree");
        assert_eq!(cem_tree.subject, "cem-ast-node");

        let colored_cem_tree = response
            .module_options
            .output_functions
            .iter()
            .find(|function| function.name == "cem.color-tree")
            .expect("CEM tree colorizer declaration");
        assert_eq!(
            colored_cem_tree.kind,
            TransformTemplateOutputFunctionKind::Color
        );
        assert_eq!(
            colored_cem_tree.produces,
            TransformTemplateOutputProducedKind::CemTree
        );
        assert_eq!(colored_cem_tree.category, "cem-tree");
        assert_eq!(colored_cem_tree.subject, "cem-tree");
        assert_eq!(
            colored_cem_tree.profile.as_deref(),
            Some("css-custom-properties")
        );
    }

    #[test]
    fn cemt_formatter_coloring_pipeline_example_executes_before_writer() {
        let stage_fixture = include_str!(
            "../schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.fixture.cem"
        );
        let response =
            parse_cem_native_template_module_options(TransformTemplateModuleParseRequest {
                template: template_input(
                    "schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt",
                    include_str!(
                        "../schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt"
                    ),
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            });

        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        let registry =
            TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
        let host_capabilities = BTreeSet::new();
        let value_bindings = BTreeMap::new();
        let subject_source_map =
            serde_json::to_value(source_map_stack(200, 7)).expect("subject source map serializes");
        let subject = json!({
            "kind": "element",
            "name": "article",
            "sourceMap": subject_source_map,
            "attributes": [],
            "children": [
                {"kind": "text", "value": "Ready ", "sourceMap": subject_source_map},
                {
                    "kind": "element",
                    "name": "strong",
                    "sourceMap": subject_source_map,
                    "attributes": [],
                    "children": [{"kind": "text", "value": "now", "sourceMap": subject_source_map}]
                },
                {"kind": "text", "value": ".", "sourceMap": subject_source_map}
            ]
        });

        let format_request = TransformTemplateEncodeBindingRequest::new(
            subject.clone(),
            TransformTemplateEncodingTarget::new(
                CEM_ML_CONTENT_TYPE,
                CEM_ML_SCHEMA_URI,
                "cem-tree",
            ),
        )
        .with_subject_type("cem-ast-node")
        .with_options(TransformTemplateEncodeOptions {
            formatter: Some("acme.showcase.format-tree".to_owned()),
            canonical: true,
            ..TransformTemplateEncodeOptions::default()
        });
        let format_binding = registry
            .resolve_format_binding(&format_request, &host_capabilities)
            .expect("showcase formatter resolves");
        let mut reject_fallback = |binding: &TransformTemplateEncodeBinding, _subject: &Value| {
            Err(format!(
                "unexpected fallback for `{}`",
                binding.function.name
            ))
        };
        let formatted = execute_transform_template_encode_binding(
            &format_binding,
            &subject,
            &TransformTemplateEncodeEvaluationContext {
                registry: &registry,
                value_bindings: &value_bindings,
                host_capabilities: &host_capabilities,
                output_color_type: None,
                uri: Some(
                    "schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt",
                ),
            },
            &mut reject_fallback,
        )
        .expect("showcase formatter body executes");

        assert_eq!(formatted["kind"], "cem-tree");
        assert_eq!(formatted["formatterProfile"], "acme.showcase.format-tree");
        assert_eq!(
            cem_tree_format_decision(&formatted, "showcase")["value"],
            "formatted tree before writer"
        );
        assert_eq!(formatted["nodes"][0]["children"][1]["name"], "strong");
        assert_eq!(
            formatted["nodes"][0]["children"][1]["formatLayout"]["value"],
            "inline-emphasis"
        );
        assert_eq!(
            formatted["nodes"][0]["children"][1]["formatLayout"]["formatterRole"],
            "formatter.inline-emphasis"
        );
        assert!(stage_fixture.contains(r#"@formatter="acme.showcase.format-tree""#));
        assert!(stage_fixture.contains(r#"@formatter-profile="acme.showcase.format-tree""#));
        assert!(stage_fixture.contains(r#"@value="formatted tree before writer""#));
        assert!(formatted.get("colorNodes").is_none());
        assert!(formatted.get("colored").is_none());
        let formatted_artifact = format_binding.artifact_from_value(formatted.clone());
        let writer_context = TransformTemplateEncodedArtifactInsertionContext {
            produces: Some(TransformTemplateOutputProducedKind::Text),
            content_type: HTML_CONTENT_TYPE.to_owned(),
            schema: HTML_SCHEMA_URI.to_owned(),
            category: Some("html-fragment".to_owned()),
            context: Some("fragment".to_owned()),
            formatter_profile: Some("acme.showcase.format-tree".to_owned()),
            color_profile: Some("classes".to_owned()),
            color_capability: None,
            output_color_type: None,
            binary_framing: None,
            mode: Some(TransformTemplateEncodedArtifactMode::Fragment),
            canonical: Some(true),
            source_map_policy: Some(TransformTemplateSourceMapPolicy::Generated),
        };
        let formatted_writer_error = transform_template_writer_cem_tree_artifact_to_text(
            &formatted_artifact,
            &writer_context,
        )
        .expect_err("writer rejects formatted-only tree");
        assert!(
            formatted_writer_error.contains("run the package colorizer before the writer"),
            "{formatted_writer_error}"
        );

        let color_request = TransformTemplateEncodeBindingRequest::new(
            formatted,
            TransformTemplateEncodingTarget::new(
                CEM_ML_CONTENT_TYPE,
                CEM_ML_SCHEMA_URI,
                "cem-tree",
            ),
        )
        .with_subject_type("cem-tree")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("acme.showcase.color-tree".to_owned()),
            color_profile: Some("classes".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let color_binding = registry
            .resolve_color_binding(&color_request, &host_capabilities)
            .expect("showcase colorizer resolves")
            .into_encode_binding();
        let colored = execute_transform_template_encode_binding(
            &color_binding,
            &color_request.subject,
            &TransformTemplateEncodeEvaluationContext {
                registry: &registry,
                value_bindings: &value_bindings,
                host_capabilities: &host_capabilities,
                output_color_type: None,
                uri: Some(
                    "schema-packages/cem-transform/v1/examples/formatter-coloring-pipeline.cemt",
                ),
            },
            &mut reject_fallback,
        )
        .expect("showcase colorizer body executes");

        assert_eq!(colored["colored"], true);
        assert_eq!(colored["colorProfile"], "classes");
        assert_eq!(
            cem_tree_color_decision(&colored, "showcase")["value"],
            "colored tree before writer"
        );
        assert!(stage_fixture.contains(r#"@colorizer="acme.showcase.color-tree""#));
        assert!(stage_fixture.contains(r#"@color-profile="classes""#));
        assert!(stage_fixture.contains(r#"@value="colored tree before writer""#));
        assert_eq!(
            colored["writerBoundaries"][0]["stage"], "after-color",
            "coloring records the writer boundary after mutating the CEM tree"
        );
        assert_eq!(
            colored["writerBoundaries"][0]["value"],
            "writer consumes colored CEM tree"
        );
        assert_cem_tree_source_map_current_transform(
            &colored["writerBoundaries"][0]["sourceMap"],
            |transform| {
                matches!(
                    transform,
                    TransformKind::TemplateTransform { function }
                        if function == "acme.showcase.color-tree"
                )
            },
        );
        assert!(stage_fixture.contains(r#"@stage="after-color""#));
        assert!(stage_fixture.contains(r#"@value="writer consumes colored CEM tree""#));
        assert_eq!(
            cem_tree_writer_attribute_value(&colored["nodes"][0], "class"),
            "cem-color cem-color-syntax-name"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["formatLayout"]["value"], "inline-emphasis",
            "coloring preserves formatter layout metadata on nested nodes"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["colorRole"],
            "syntax.keyword"
        );
        assert_eq!(
            cem_tree_writer_attribute_value(&colored["nodes"][0]["children"][1], "class"),
            "cem-color cem-color-syntax-keyword"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["children"][0]["colorWrapperNodes"][0]
                ["colorizerRole"],
            "colorizer.text-wrapper"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["children"][0]["colorWrapperNodes"][1]["value"],
            "syntax.keyword"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["children"][0]["colorWrapperNodes"][2]
                ["colorizerRole"],
            "colorizer.queued-edit"
        );
        assert_eq!(
            colored["nodes"][0]["children"][1]["children"][0]["colorWrapperNodes"][2]["value"],
            "queued edit replay before writer"
        );
        assert_cem_tree_source_map_current_transform(
            &colored["nodes"][0]["children"][1]["children"][0]["colorWrapperNodes"][2]["sourceMap"],
            |transform| {
                matches!(
                    transform,
                    TransformKind::TemplateTransform { function }
                        if function == "acme.showcase.color-tree"
                )
            },
        );
        assert_eq!(
            colored["nodes"][0]["children"][2]["colorRole"], "syntax.string",
            "coloring maps over later text children instead of using fixed child indexes"
        );
        assert_eq!(
            colored["nodes"][0]["children"][2]["children"][0]["value"],
            "."
        );
        assert!(stage_fixture.contains(r#"@value="cem-color cem-color-syntax-name""#));
        assert!(stage_fixture.contains(r#"@value="cem-color cem-color-syntax-keyword""#));
        assert!(stage_fixture.contains(r#"@colorizer-role="colorizer.text-wrapper""#));
        assert!(stage_fixture.contains(r#"@colorizer-role="colorizer.queued-edit""#));
        assert!(stage_fixture.contains(r#"@value="queued edit replay before writer""#));
        let colored_artifact = color_binding.artifact_from_value(colored);
        let writer_artifact =
            transform_template_writer_cem_tree_artifact_to_text(&colored_artifact, &writer_context)
                .expect("writer consumes colored CEM tree");
        assert_eq!(
            writer_artifact.identity.produces,
            TransformTemplateOutputProducedKind::Text
        );
        let output = writer_artifact
            .value
            .as_str()
            .expect("writer output is text");
        assert!(output.contains("<article class=\"cem-color cem-color-syntax-name\""));
        assert!(output.contains("<span class=\"cem-color cem-color-syntax-string\""));
        assert!(output.contains("<strong class=\"cem-color cem-color-syntax-keyword\""));
        assert!(output.contains("<span class=\"cem-color cem-color-syntax-keyword\""));
        assert!(output.contains(">now</span>"));
    }

    #[test]
    fn cemt_formatter_coloring_pipeline_recurses_over_alternate_ast_shape() {
        let subject_source_map =
            serde_json::to_value(source_map_stack(240, 9)).expect("subject source map serializes");
        let subject = json!({
            "kind": "element",
            "name": "section",
            "sourceMap": subject_source_map,
            "attributes": [],
            "children": [
                {
                    "kind": "element",
                    "name": "p",
                    "sourceMap": subject_source_map,
                    "attributes": [],
                    "children": [
                        {"kind": "text", "value": "Alpha", "sourceMap": subject_source_map},
                        {
                            "kind": "element",
                            "name": "strong",
                            "sourceMap": subject_source_map,
                            "attributes": [],
                            "children": [
                                {"kind": "text", "value": "Beta", "sourceMap": subject_source_map}
                            ]
                        }
                    ]
                },
                {
                    "kind": "element",
                    "name": "aside",
                    "sourceMap": subject_source_map,
                    "attributes": [],
                    "children": [
                        {"kind": "text", "value": "Gamma", "sourceMap": subject_source_map}
                    ]
                }
            ]
        });

        let CemtFormatterColoringPipelineExecution {
            formatted,
            colored,
            writer_output,
            colorizer,
        } = execute_cemt_formatter_coloring_pipeline(subject)
            .expect("showcase formatter/colorizer executes alternate nested AST shape");

        assert_eq!(colorizer, "acme.showcase.color-tree");
        assert_eq!(formatted["nodes"][0]["name"], "section");
        assert_eq!(formatted["nodes"][0]["children"][0]["name"], "p");
        assert_eq!(
            formatted["nodes"][0]["children"][0]["formatLayout"]["value"],
            "inline"
        );
        assert_eq!(
            formatted["nodes"][0]["children"][0]["children"][1]["name"],
            "strong"
        );
        assert_eq!(
            formatted["nodes"][0]["children"][0]["children"][1]["formatLayout"]["value"],
            "inline-emphasis"
        );
        assert_eq!(formatted["nodes"][0]["children"][1]["name"], "aside");
        assert_eq!(
            formatted["nodes"][0]["children"][1]["formatLayout"]["formatterRole"],
            "formatter.layout"
        );
        assert!(formatted.get("writerBoundaries").is_none());

        let section = &colored["nodes"][0];
        assert_eq!(colored["writerBoundaries"][0]["stage"], "after-color");
        assert_eq!(section["colorRole"], "syntax.name");
        assert_eq!(
            cem_tree_writer_attribute_value(section, "class"),
            "cem-color cem-color-syntax-name"
        );

        let paragraph = &section["children"][0];
        assert_eq!(paragraph["colorRole"], "syntax.name");
        assert_eq!(
            cem_tree_writer_attribute_value(paragraph, "class"),
            "cem-color cem-color-syntax-name"
        );
        assert_eq!(paragraph["children"][0]["name"], "span");
        assert_eq!(paragraph["children"][0]["colorRole"], "syntax.string");
        assert_eq!(paragraph["children"][0]["children"][0]["value"], "Alpha");

        let strong = &paragraph["children"][1];
        assert_eq!(strong["colorRole"], "syntax.keyword");
        assert_eq!(
            strong["children"][0]["colorWrapperNodes"][1]["value"],
            "syntax.keyword"
        );
        assert_eq!(strong["children"][0]["children"][0]["value"], "Beta");

        let aside = &section["children"][1];
        assert_eq!(aside["colorRole"], "syntax.name");
        assert_eq!(aside["children"][0]["colorRole"], "syntax.string");
        assert_eq!(
            aside["children"][0]["colorWrapperNodes"][2]["colorizerRole"],
            "colorizer.queued-edit"
        );
        assert_eq!(
            aside["children"][0]["colorWrapperNodes"][2]["value"],
            "queued edit replay before writer"
        );
        assert_eq!(aside["children"][0]["children"][0]["value"], "Gamma");

        assert!(writer_output.contains("<section class=\"cem-color cem-color-syntax-name\""));
        assert!(writer_output.contains(
            "<p class=\"cem-color cem-color-syntax-name\"><span class=\"cem-color cem-color-syntax-string\">Alpha</span><strong class=\"cem-color cem-color-syntax-keyword\"><span class=\"cem-color cem-color-syntax-keyword\">Beta</span></strong></p>"
        ));
        assert!(writer_output.contains(
            "<aside class=\"cem-color cem-color-syntax-name\"><span class=\"cem-color cem-color-syntax-string\">Gamma</span></aside>"
        ));
    }

