    #[test]
    fn output_function_registry_resolves_identity_and_capabilities() {
        let response =
            parse_cem_native_template_module_options(TransformTemplateModuleParseRequest {
                template: template_input(
                    "schema-packages/cem-transform/v1/examples/function-declarations.cemt",
                    include_str!(
                        "../schema-packages/cem-transform/v1/examples/function-declarations.cemt"
                    ),
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            });
        let mut registry =
            TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
        let query = TransformTemplateOutputFunctionQuery::for_identity(
            TransformTemplateOutputFunctionKind::Encoding,
            "text/html; charset=utf-8",
            "https://cem.dev/ns/data/html/1",
            "html-text",
            "string",
        );
        let resolved = registry
            .resolve(&query, &BTreeSet::new())
            .expect("html text function resolves");
        assert_eq!(resolved.name, "html.text");

        let mut native = resolved.clone();
        native.name = "acme.native.html-text".to_owned();
        native.owner = Some("acme".to_owned());
        native.visibility = TransformTemplateModuleVisibility::Public;
        native.implementation = TransformTemplateOutputFunctionImplementation::Native;
        native.capability = Some("acme.native.HtmlTextEncoder".to_owned());
        registry.register(native.clone());
        let ambiguous = registry
            .resolve(&query, &BTreeSet::new())
            .expect_err("two matching encoders should be ambiguous");
        assert!(matches!(
            &ambiguous,
            TransformTemplateOutputFunctionResolutionError::Ambiguous { .. }
        ));
        let ambiguous_diagnostic = ambiguous.diagnostic(Some("template.cemt"));
        assert_eq!(
            ambiguous_diagnostic.code,
            TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_AMBIGUOUS_CODE
        );
        assert!(ambiguous_diagnostic.message.contains("html.text"));
        assert!(ambiguous_diagnostic
            .message
            .contains("acme.native.html-text"));

        let native_query = TransformTemplateOutputFunctionQuery {
            name: Some(native.name.clone()),
            ..query.clone()
        };
        let missing = registry
            .resolve(&native_query, &BTreeSet::new())
            .expect_err("native function requires host capability");
        assert!(matches!(
            missing,
            TransformTemplateOutputFunctionResolutionError::MissingCapability { .. }
        ));
        assert_eq!(
            missing.diagnostic(Some("template.cemt")).code,
            TRANSFORM_TEMPLATE_OUTPUT_FUNCTION_CAPABILITY_MISSING_CODE
        );

        let mut capabilities = BTreeSet::new();
        capabilities.insert("acme.native.HtmlTextEncoder".to_owned());
        let resolved_native = registry
            .resolve(&native_query, &capabilities)
            .expect("native function resolves with capability");
        assert_eq!(resolved_native.name, "acme.native.html-text");
    }

    #[test]
    fn output_function_registry_resolves_extends_alias_when_exact_name_is_absent() {
        let mut registry = TransformTemplateOutputFunctionRegistry::new();
        let mut alias = output_function_descriptor();
        alias.owner = Some("acme".to_owned());
        alias.name = "acme.html-text".to_owned();
        alias.visibility = TransformTemplateModuleVisibility::Public;
        alias.extends = Some("html.text".to_owned());
        registry.register(alias);

        let request = TransformTemplateEncodeBindingRequest::new(
            Value::String("Hello".to_owned()),
            TransformTemplateEncodingTarget::new(HTML_CONTENT_TYPE, HTML_SCHEMA_URI, "html-text"),
        )
        .with_subject_type("string")
        .with_options(TransformTemplateEncodeOptions {
            encoder: Some("html.text".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });

        let binding = registry
            .resolve_encode_binding(&request, &BTreeSet::new())
            .expect("standard encoder name resolves through explicit alias");
        assert_eq!(binding.function.owner.as_deref(), Some("acme"));
        assert_eq!(binding.function.name, "acme.html-text");
        assert_eq!(binding.function.extends.as_deref(), Some("html.text"));
    }

    #[test]
    fn output_function_registry_enforces_private_custom_visibility() {
        let mut registry = TransformTemplateOutputFunctionRegistry::new();
        let mut private = output_function_descriptor();
        private.owner = Some("acme".to_owned());
        private.name = "acme.html-private".to_owned();
        private.visibility = TransformTemplateModuleVisibility::Private;
        registry.register(private.clone());

        let mut package = private.clone();
        package.name = "acme.html-package".to_owned();
        package.visibility = TransformTemplateModuleVisibility::Package;
        registry.register(package.clone());

        let mut public = private.clone();
        public.name = "acme.html-public".to_owned();
        public.visibility = TransformTemplateModuleVisibility::Public;
        registry.register(public.clone());

        let private_query = TransformTemplateOutputFunctionQuery {
            name: Some(private.name.clone()),
            ..TransformTemplateOutputFunctionQuery::for_identity(
                TransformTemplateOutputFunctionKind::Encoding,
                HTML_CONTENT_TYPE,
                HTML_SCHEMA_URI,
                "html-text",
                "string",
            )
        };

        assert!(matches!(
            registry.resolve(&private_query, &BTreeSet::new()),
            Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. })
        ));

        let other_owner_query = TransformTemplateOutputFunctionQuery {
            owner: Some("other".to_owned()),
            ..private_query.clone()
        };
        assert!(matches!(
            registry.resolve(&other_owner_query, &BTreeSet::new()),
            Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. })
        ));

        let owner_query = TransformTemplateOutputFunctionQuery {
            owner: Some("acme".to_owned()),
            ..private_query
        };
        let resolved_private = registry
            .resolve(&owner_query, &BTreeSet::new())
            .expect("matching owner can resolve private custom function");
        assert_eq!(resolved_private.name, private.name);

        let package_query = TransformTemplateOutputFunctionQuery {
            name: Some(package.name.clone()),
            ..TransformTemplateOutputFunctionQuery::for_identity(
                TransformTemplateOutputFunctionKind::Encoding,
                HTML_CONTENT_TYPE,
                HTML_SCHEMA_URI,
                "html-text",
                "string",
            )
        };
        assert!(matches!(
            registry.resolve(&package_query, &BTreeSet::new()),
            Err(TransformTemplateOutputFunctionResolutionError::Unknown { .. })
        ));

        let package_owner_query = TransformTemplateOutputFunctionQuery {
            owner: Some("acme".to_owned()),
            ..package_query
        };
        let resolved_package = registry
            .resolve(&package_owner_query, &BTreeSet::new())
            .expect("matching owner can resolve package-visible custom function");
        assert_eq!(resolved_package.name, package.name);

        let public_query = TransformTemplateOutputFunctionQuery {
            name: Some(public.name.clone()),
            ..TransformTemplateOutputFunctionQuery::for_identity(
                TransformTemplateOutputFunctionKind::Encoding,
                HTML_CONTENT_TYPE,
                HTML_SCHEMA_URI,
                "html-text",
                "string",
            )
        };
        let resolved_public = registry
            .resolve(&public_query, &BTreeSet::new())
            .expect("public custom function resolves without owner scope");
        assert_eq!(resolved_public.name, public.name);
    }

