    #[test]
    fn format_binding_resolves_cem_tree_formatter_and_builtin_runs() {
        let mut registry = TransformTemplateOutputFunctionRegistry::new();
        registry.register(cem_tree_format_function_descriptor());
        let implementations =
            TransformTemplateEncodeImplementationRegistry::with_builtin_encoders();
        let subject_source_map =
            serde_json::to_value(source_map_stack(80, 4)).expect("subject source map serializes");
        let subject = json!({
            "subjectType": "cem-ast",
            "kind": "element",
            "name": "card",
            "sourceMap": subject_source_map,
            "attributes": [{"name": "tone", "value": "info"}],
            "children": [{"kind": "text", "value": "Ready"}]
        });
        let request = TransformTemplateEncodeBindingRequest::new(
            subject.clone(),
            TransformTemplateEncodingTarget::new(
                CEM_ML_CONTENT_TYPE,
                CEM_ML_SCHEMA_URI,
                "cem-tree",
            ),
        )
        .with_options(TransformTemplateEncodeOptions {
            formatter: Some("cem.format-tree".to_owned()),
            canonical: true,
            line_ending: Some("crlf".to_owned()),
            indent: Some("\t".to_owned()),
            ordering: Some("lexical".to_owned()),
            wrap_column: Some("88".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });

        let binding = registry
            .resolve_format_binding(&request, &BTreeSet::new())
            .expect("CEM tree formatter resolves");

        assert_eq!(
            binding.function.kind,
            TransformTemplateOutputFunctionKind::Format
        );
        assert_eq!(binding.function.name, "cem.format-tree");
        assert_eq!(binding.subject_type, "cem-ast-node");
        assert_eq!(
            binding.identity.produces,
            TransformTemplateOutputProducedKind::CemTree
        );
        assert_eq!(
            binding.identity.formatter_profile.as_deref(),
            Some("compact")
        );
        assert!(binding.identity.canonical);

        let formatted = implementations
            .encode(&binding, &subject)
            .expect("CEM tree formatter runs");
        assert_eq!(formatted["kind"], "cem-tree");
        assert_eq!(formatted["contentType"], CEM_ML_CONTENT_TYPE);
        assert_eq!(formatted["formatterProfile"], "compact");
        assert_eq!(formatted["formatNodes"][0]["kind"], "format-marker");
        assert_eq!(formatted["formatNodes"][0]["name"], "cem.format-tree");
        assert_eq!(
            formatted["formatNodes"][0]["formatterRole"],
            "formatter.boundary"
        );
        assert_eq!(formatted["formatNodes"][0]["colorRole"], "source.gutter");
        assert_eq!(formatted["formatNodes"][0]["formatterProfile"], "compact");
        assert_cem_tree_source_map_current_transform(
            &formatted["formatNodes"][0]["sourceMap"],
            |transform| {
                matches!(
                    transform,
                    TransformKind::TemplateTransform { function }
                        if function == "cem.format-tree"
                )
            },
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "line-ending")["value"],
            "crlf"
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "indent")["value"],
            "\t"
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "tab-size")["value"],
            "8"
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "ordering")["value"],
            "lexical"
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "wrapping")["value"],
            "88"
        );
        assert_eq!(
            cem_tree_format_decision(&formatted, "whitespace")["value"],
            "formatter-owned"
        );
        assert_eq!(formatted["nodes"][0]["name"], "card");
        assert_eq!(formatted["nodes"][0]["formatLayout"]["value"], "inline");
        assert_eq!(
            formatted["nodes"][0]["formatLayout"]["formatterRole"],
            "formatter.layout"
        );
        assert_eq!(
            formatted["nodes"][0]["formatBeforeAttributes"]["formatterRole"],
            "formatter.attribute-prefix"
        );
        assert_eq!(
            formatted["nodes"][0]["formatBeforeAttributes"]["value"],
            " "
        );
        assert_eq!(
            formatted["nodes"][0]["formatContentBoundary"][0]["formatterRole"],
            "formatter.boundary-spacing"
        );
        assert_eq!(
            formatted["nodes"][0]["formatContentBoundary"][1]["kind"],
            "raw"
        );
        assert_eq!(
            formatted["nodes"][0]["formatContentBoundary"][1]["value"],
            "|"
        );

        binding
            .artifact_from_value(formatted)
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoding_target(
                    &request.target,
                    Some(TransformTemplateOutputProducedKind::CemTree),
                ),
            )
            .expect("CEM tree artifact validates as a structured formatter output");
    }

    #[test]
    fn cemt_runtime_operations_build_cem_tree_formatter_envelope() {
        let mut registry = TransformTemplateOutputFunctionRegistry::new();
        registry.register(cem_tree_format_function_descriptor());
        let subject_source_map =
            serde_json::to_value(source_map_stack(84, 4)).expect("subject source map serializes");
        let subject = json!({
            "kind": "element",
            "name": "panel",
            "sourceMap": subject_source_map,
            "children": [{"kind": "text", "value": "Ready"}]
        });
        let request = TransformTemplateEncodeBindingRequest::new(
            subject.clone(),
            TransformTemplateEncodingTarget::new(
                CEM_ML_CONTENT_TYPE,
                CEM_ML_SCHEMA_URI,
                "cem-tree",
            ),
        )
        .with_subject_type("cem-ast-node")
        .with_options(TransformTemplateEncodeOptions {
            formatter: Some("cem.format-tree".to_owned()),
            canonical: true,
            indent: Some("    ".to_owned()),
            wrap_column: Some("96".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let binding = registry
            .resolve_format_binding(&request, &BTreeSet::new())
            .expect("CEM tree formatter resolves");
        let normalized_nodes =
            transform_template_cem_tree_nodes(&subject).expect("subject normalizes to CEM nodes");

        let formatted_nodes =
            transform_template_cem_tree_formatter_nodes(&binding, Value::Array(normalized_nodes))
                .expect("native formatter fallback node helper runs");
        assert_eq!(formatted_nodes[0]["kind"], "element");
        assert_eq!(formatted_nodes[0]["name"], "panel");
        assert_eq!(
            formatted_nodes[0]["formatLayout"]["formatterRole"],
            "formatter.layout"
        );
        assert_eq!(
            formatted_nodes[0]["formatContentBoundary"][1]["kind"],
            "raw"
        );

        let separated_nodes = transform_template_cem_tree_formatter_inter_node_whitespace(
            &binding,
            vec![
                json!({"kind": "element", "name": "first"}),
                json!({"kind": "element", "name": "second"}),
            ],
        );
        assert_eq!(separated_nodes[1]["kind"], "whitespace");
        assert_eq!(separated_nodes[1]["value"], "\n");
        assert_eq!(separated_nodes[1]["formatterRole"], "formatter.line-ending");

        let block_children = transform_template_cem_tree_formatter_block_children(
            &binding,
            vec![json!({"kind": "element", "name": "child"})],
            2,
        );
        assert_eq!(block_children[0]["kind"], "whitespace");
        assert_eq!(block_children[0]["value"], "        ");
        assert_eq!(block_children[0]["formatterRole"], "formatter.indent");
        assert_eq!(block_children[2]["formatterRole"], "formatter.line-ending");

        let content_boundary = transform_template_cem_tree_content_boundary_nodes(
            &binding.options,
            TransformTemplateCemTreeLayout::Block,
            None,
        );
        assert_eq!(
            content_boundary[0]["formatterRole"],
            "formatter.boundary-spacing"
        );
        assert_eq!(content_boundary[1]["kind"], "raw");
        assert_eq!(
            content_boundary[1]["formatterRole"],
            "formatter.content-boundary"
        );
        assert_eq!(
            content_boundary[2]["formatterRole"],
            "formatter.line-ending"
        );
        assert_eq!(content_boundary[2]["value"], "\n");

        let format_nodes = Value::Array(transform_template_cem_tree_format_nodes(
            formatted_nodes
                .as_array()
                .expect("formatted nodes are an array"),
            binding.identity.formatter_profile.as_deref(),
            &binding.options,
        ));
        assert_eq!(format_nodes[0]["kind"], "format-marker");
        assert_eq!(format_nodes[0]["name"], "cem.format-tree");
        assert_eq!(
            format_nodes[0]["formatterProfile"],
            binding.identity.formatter_profile.as_deref().unwrap()
        );
        assert_eq!(
            format_nodes
                .as_array()
                .expect("formatNodes are an array")
                .len(),
            7
        );

        let envelope =
            transform_template_cem_tree_formatter_envelope(&binding, formatted_nodes.clone())
                .expect("native formatter fallback envelope helper runs");
        assert_eq!(envelope["kind"], "cem-tree");
        assert_eq!(envelope["canonical"], true);
        assert_eq!(envelope["formatterProfile"], "compact");
        assert_eq!(envelope["formatNodes"], format_nodes);
        assert_eq!(envelope["nodes"], formatted_nodes);
        assert_eq!(
            cem_tree_format_decision(&envelope, "indent")["value"],
            "    "
        );
        assert_eq!(
            cem_tree_format_decision(&envelope, "tab-size")["value"],
            "8"
        );
        assert_eq!(
            cem_tree_format_decision(&envelope, "wrapping")["value"],
            "96"
        );

        binding
            .artifact_from_value(envelope)
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoding_target(
                    &request.target,
                    Some(TransformTemplateOutputProducedKind::CemTree),
                ),
            )
            .expect("native fallback envelope validates as CEM tree output");

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.envelope, { subject: [] })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter envelope operation");
        assert!(
            error.contains("CEMT runtime operation `cem.format-tree.envelope` has been removed")
        );
        assert!(error.contains("schema-owned `cem.format-tree.build-envelope` helpers"));

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.nodes, { subject: [] })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter node operation");
        assert!(error.contains("CEMT runtime operation `cem.format-tree.nodes` has been removed"));
        assert!(error.contains("schema-owned `cem.format-tree.build-node-list` helpers"));

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.format-nodes, { subject: [] })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter metadata operation");
        assert!(error
            .contains("CEMT runtime operation `cem.format-tree.format-nodes` has been removed"));
        assert!(error.contains("schema-owned `cem.format-tree.add-format-nodes` helpers"));

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.content-boundary, { subject: { layout: "block" } })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter content boundary operation");
        assert!(error.contains(
            "CEMT runtime operation `cem.format-tree.content-boundary` has been removed"
        ));
        assert!(error.contains("schema-owned `cem.format-tree.build-content-boundary` helpers"));

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.inter-node-whitespace, { subject: [] })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter inter-node whitespace operation");
        assert!(error.contains(
            "CEMT runtime operation `cem.format-tree.inter-node-whitespace` has been removed"
        ));
        assert!(
            error.contains("schema-owned `cem.format-tree.format-inter-node-whitespace` helpers")
        );

        let error = resolve_encode_subject_expression_at_depth(
            r#"call(cem.format-tree.block-children, { subject: { nodes: [], depth: 0 } })"#,
            &BTreeMap::new(),
            &BTreeMap::new(),
            Some(&binding),
            0,
        )
        .expect_err("direct CEMT body rejects removed formatter block children operation");
        assert!(error
            .contains("CEMT runtime operation `cem.format-tree.block-children` has been removed"));
        assert!(error.contains("schema-owned `cem.format-tree.format-block-children` helpers"));
    }

