    #[test]
    fn builtin_colorizers_emit_terminal_and_html_text() {
        let mut functions = TransformTemplateOutputFunctionRegistry::new();
        functions.register(color_output_function_descriptor(
            "terminal.ansi256",
            "terminal-color",
            "text/plain",
            "https://cem.dev/ns/data/text/terminal/1",
            Some("ansi-256"),
        ));
        functions.register(color_output_function_descriptor(
            "html.css-vars",
            "html-color-fragment",
            HTML_CONTENT_TYPE,
            HTML_SCHEMA_URI,
            Some("css-custom-properties"),
        ));
        let implementations =
            TransformTemplateEncodeImplementationRegistry::with_builtin_encoders();
        let tokens = json!([
            {"role": "diagnostic.error", "text": "Broken"},
            {"role": "syntax.string", "text": "\"ok\""}
        ]);

        let terminal_request = TransformTemplateEncodeBindingRequest::new(
            tokens.clone(),
            TransformTemplateEncodingTarget::new(
                "text/plain",
                "https://cem.dev/ns/data/text/terminal/1",
                "terminal-color",
            ),
        )
        .with_subject_type("tokens")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("terminal.ansi256".to_owned()),
            color_profile: Some("ansi-256".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let terminal_binding = functions
            .resolve_color_binding(&terminal_request, &BTreeSet::new())
            .expect("terminal color binding resolves")
            .into_encode_binding();
        let terminal = implementations
            .encode(&terminal_binding, &terminal_request.subject)
            .expect("terminal colorizer runs");
        assert_eq!(
            terminal,
            Value::String(
                "\u{1b}[1;38;5;196mBroken\u{1b}[0m\u{1b}[38;5;76m\"ok\"\u{1b}[0m\u{1b}[0m"
                    .to_owned()
            )
        );

        let html_request = TransformTemplateEncodeBindingRequest::new(
            tokens,
            TransformTemplateEncodingTarget::new(
                HTML_CONTENT_TYPE,
                HTML_SCHEMA_URI,
                "html-color-fragment",
            ),
        )
        .with_subject_type("tokens")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("html.css-vars".to_owned()),
            color_profile: Some("css-custom-properties".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let html_binding = functions
            .resolve_color_binding(&html_request, &BTreeSet::new())
            .expect("HTML color binding resolves")
            .into_encode_binding();
        let html = implementations
            .encode(&html_binding, &html_request.subject)
            .expect("HTML colorizer runs");
        assert_eq!(
            html,
            Value::String(
                r#"<span class="cem-color cem-color-diagnostic-error" data-role="diagnostic.error" style="color: var(--cem-color-diagnostic-error, #b42318); font-weight: 600">Broken</span><span class="cem-color cem-color-syntax-string" data-role="syntax.string" style="color: var(--cem-color-syntax-string, #067647)">"ok"</span>"#
                    .to_owned()
            )
        );
    }

    #[test]
    fn color_binding_rejects_unsupported_profiles_before_lookup() {
        let registry = TransformTemplateOutputFunctionRegistry::new();
        let terminal_request = TransformTemplateEncodeBindingRequest::new(
            json!([{"role": "syntax.token", "text": "let"}]),
            TransformTemplateEncodingTarget::new(
                "text/plain",
                "https://cem.dev/ns/data/text/terminal/1",
                "terminal-color",
            ),
        )
        .with_subject_type("tokens")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("missing.terminal".to_owned()),
            color_profile: Some("ansi-1024".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let terminal_error = registry
            .resolve_color_binding(&terminal_request, &BTreeSet::new())
            .expect_err("invalid terminal profile is rejected before lookup");
        assert_eq!(
            terminal_error.diagnostic(None).code,
            TRANSFORM_TEMPLATE_TERMINAL_COLOR_CAPABILITY_UNSUPPORTED_CODE
        );
        assert!(terminal_error
            .diagnostic(None)
            .message
            .contains("unsupported terminal color capability `ansi-1024`"));

        let html_request = TransformTemplateEncodeBindingRequest::new(
            json!([{"role": "syntax.token", "text": "let"}]),
            TransformTemplateEncodingTarget::new(HTML_CONTENT_TYPE, HTML_SCHEMA_URI, "html-color"),
        )
        .with_subject_type("tokens")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("missing.html".to_owned()),
            color_profile: Some("none".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let html_error = registry
            .resolve_color_binding(&html_request, &BTreeSet::new())
            .expect_err("terminal no-color profile is rejected for HTML targets");
        assert_eq!(
            html_error.diagnostic(None).code,
            TRANSFORM_TEMPLATE_HTML_PALETTE_INACCESSIBLE_CODE
        );
        assert!(html_error
            .diagnostic(None)
            .message
            .contains("HTML color palette `none`"));

        let opaque_request = TransformTemplateEncodeBindingRequest::new(
            json!([{"role": "syntax.token", "text": "let"}]),
            TransformTemplateEncodingTarget::new(
                "text/plain",
                "https://example.test/ns/text/1",
                "custom-color",
            ),
        )
        .with_subject_type("tokens")
        .with_options(TransformTemplateEncodeOptions {
            colorizer: Some("missing.opaque".to_owned()),
            color_profile: Some("rainbow".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        });
        let opaque_error = registry
            .resolve_color_binding(&opaque_request, &BTreeSet::new())
            .expect_err("unknown generic color profile is rejected before lookup");
        assert_eq!(
            opaque_error.diagnostic(None).code,
            TRANSFORM_TEMPLATE_COLOR_PROFILE_INVALID_CODE
        );
        assert!(opaque_error
            .diagnostic(None)
            .message
            .contains("unsupported color profile `rainbow`"));
    }

    #[test]
    fn color_output_profiles_validate_terminal_capabilities_and_roles() {
        let profile = TransformTemplateColorOutputProfile::terminal_from_selector("ansi-256")
            .expect("ansi-256 terminal profile resolves");

        assert_eq!(profile.output, TransformTemplateColorOutputKind::Terminal);
        assert_eq!(
            profile.terminal_capability,
            TransformTemplateTerminalColorCapability::Ansi256
        );
        assert!(profile.reset_at_artifact_boundaries);
        assert!(profile.non_color_cues);
        assert!(profile.supports_role("diagnostic.error"));
        assert!(profile.supports_role("syntax.token"));
        profile.validate().expect("terminal profile is valid");

        let linked_profile =
            TransformTemplateColorOutputProfile::terminal_from_selector("ansi-256+hyperlinks")
                .expect("ansi-256 terminal hyperlink profile resolves");
        assert_eq!(
            linked_profile.terminal_capability,
            TransformTemplateTerminalColorCapability::Ansi256
        );
        assert!(linked_profile.hyperlinks);
        linked_profile
            .validate()
            .expect("terminal hyperlink profile is valid");

        let none_profile = TransformTemplateColorOutputProfile::terminal_from_selector("none")
            .expect("none terminal profile resolves");
        assert!(none_profile.no_color);
        none_profile
            .validate()
            .expect("plain terminal fallback profile is valid");

        let terminal_profile =
            TransformTemplateColorOutputProfile::terminal_from_selector("terminal")
                .expect("terminal alias profile resolves");
        assert_eq!(
            terminal_profile.terminal_capability,
            TransformTemplateTerminalColorCapability::Auto
        );
        terminal_profile
            .validate()
            .expect("terminal alias profile is valid");

        let mut unsupported_links =
            TransformTemplateColorOutputProfile::terminal_from_selector("none+hyperlinks")
                .expect("none terminal hyperlink selector parses");
        let link_error = unsupported_links
            .validate()
            .expect_err("terminal hyperlinks require a capable terminal");
        assert!(link_error.contains("only when terminal capability allows them"));
        unsupported_links.hyperlinks = false;
        unsupported_links
            .validate()
            .expect("plain terminal profile is valid once hyperlinks are disabled");

        let selector_error =
            TransformTemplateColorOutputProfile::terminal_from_selector("ansi-1024")
                .expect_err("unknown terminal profile is rejected");
        assert!(selector_error.contains("unsupported terminal color profile"));

        let mut missing_reset = profile.clone();
        missing_reset.reset_at_artifact_boundaries = false;
        let reset_error = missing_reset
            .validate()
            .expect_err("terminal profile must reset");
        assert!(reset_error.contains("reset styles at artifact boundaries"));

        let mut bad_role = profile.clone();
        bad_role.roles.push("custom.rainbow".to_owned());
        let role_error = bad_role
            .validate()
            .expect_err("unknown semantic role is rejected");
        assert!(role_error.contains("unsupported color role `custom.rainbow`"));
    }

    #[test]
    fn color_output_profiles_validate_html_safety_contract() {
        let profile =
            TransformTemplateColorOutputProfile::html_from_selector("css-custom-properties")
                .expect("CSS custom-property HTML profile resolves");

        assert_eq!(profile.output, TransformTemplateColorOutputKind::Html);
        assert_eq!(
            profile.html_mode,
            TransformTemplateHtmlColorMode::CssCustomProperties
        );
        assert_eq!(
            profile.contrast_policy,
            TransformTemplateHtmlContrastPolicy::WcagAa
        );
        assert!(profile.escape_text);
        assert!(profile.escape_attributes);
        assert!(profile.fragment_safe);
        assert!(profile.non_color_cues);
        assert!(profile.supports_role("diff.added"));
        profile.validate().expect("HTML profile is valid");

        let inline = TransformTemplateColorOutputProfile::html_from_selector("inline-style")
            .expect("inline HTML profile resolves");
        assert_eq!(
            inline.html_mode,
            TransformTemplateHtmlColorMode::InlineStyle
        );
        inline.validate().expect("inline profile is valid");

        let html = TransformTemplateColorOutputProfile::html_from_selector("html")
            .expect("html alias profile resolves");
        assert_eq!(html.html_mode, TransformTemplateHtmlColorMode::Classes);
        html.validate().expect("html alias profile is valid");

        let selector_error = TransformTemplateColorOutputProfile::html_from_selector("table")
            .expect_err("unknown HTML color profile is rejected");
        assert!(selector_error.contains("unsupported HTML color profile"));

        let mut unsafe_html = profile.clone();
        unsafe_html.escape_attributes = false;
        let escape_error = unsafe_html
            .validate()
            .expect_err("HTML profile must escape attributes");
        assert!(escape_error.contains("escape text and attribute content"));

        let mut inaccessible_html = profile.clone();
        inaccessible_html.contrast_policy = TransformTemplateHtmlContrastPolicy::None;
        let contrast_error = inaccessible_html
            .validate()
            .expect_err("HTML profile must keep contrast policy");
        assert!(contrast_error.contains("accessible contrast policy"));

        let mut color_only_html = profile.clone();
        color_only_html.non_color_cues = false;
        let cue_error = color_only_html
            .validate()
            .expect_err("HTML profile must keep non-color cues");
        assert!(cue_error.contains("non-color fallback cues"));
    }

    #[test]
    fn encode_subject_type_candidates_prefer_specific_types() {
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!(3)),
            vec!["integer".to_owned(), "number".to_owned(), "json".to_owned()]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({"a": 1})),
            vec!["map".to_owned(), "object".to_owned(), "json".to_owned()]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(
                &json!({"tokens": [{"kind": "text", "text": "hello"}]})
            ),
            vec![
                "tokens".to_owned(),
                "token-stream".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "subjectType": "HTMLNode",
                "node": {"localName": "section"}
            })),
            vec![
                "html-node".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "chunks": [{"kind": "frame", "bytes": [1, 2, 3], "sealed": true}]
            })),
            vec![
                "sealed-binary-chunks".to_owned(),
                "binary-chunks".to_owned(),
                "chunks".to_owned(),
                "chunk-stream".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!("<strong>Raw</strong>")),
            vec!["string".to_owned(), "json".to_owned()]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "rawSyntax": "html",
                "text": "<strong>Raw</strong>"
            })),
            vec![
                "raw-html".to_owned(),
                "raw-syntax".to_owned(),
                "raw".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "kind": "raw",
                "syntax": "xml",
                "text": "<node/>"
            })),
            vec![
                "raw-xml".to_owned(),
                "raw-syntax".to_owned(),
                "raw".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "kind": "raw",
                "text": "opaque"
            })),
            vec![
                "raw".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "attributes": [{"name": "id", "value": "main"}]
            })),
            vec![
                "attributes".to_owned(),
                "attribute-list".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
        assert_eq!(
            transform_template_encode_subject_type_candidates(&json!({
                "slots": {"default": [{"kind": "text", "value": "Hello"}]}
            })),
            vec![
                "slots".to_owned(),
                "slot-list".to_owned(),
                "map".to_owned(),
                "object".to_owned(),
                "json".to_owned()
            ]
        );
    }

    #[test]
    fn target_syntax_rules_describe_html_writer_boundaries() {
        let target = TransformTemplateEncodingTarget::new(
            "text/html; charset=utf-8",
            HTML_SCHEMA_URI,
            "html-text",
        );
        let options = TransformTemplateEncodeOptions {
            mode: TransformTemplateEncodedArtifactMode::Fragment,
            charset: Some("windows-1252".to_owned()),
            namespace_policy: Some("repair".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        };

        let rules = target
            .syntax_rules(&options)
            .expect("HTML syntax rules resolve");

        assert_eq!(rules.syntax, TransformTemplateTargetSyntaxKind::Html);
        assert_eq!(
            rules.element_boundary_policy,
            TransformTemplateElementBoundaryPolicy::HtmlVoidElements
        );
        assert_eq!(
            rules.namespace_repair_policy,
            TransformTemplateNamespaceRepairPolicy::Repair
        );
        assert_eq!(
            rules.writer_boundaries.default_charset.as_deref(),
            Some("windows-1252")
        );
        assert!(rules.writer_boundaries.requires_valid_utf8);
        assert!(rules.permits_mode(TransformTemplateEncodedArtifactMode::Fragment));
        assert!(rules.permits_mode(TransformTemplateEncodedArtifactMode::Document));
        assert!(rules.is_void_element("BR"));
        assert!(!rules.is_void_element("div"));
        assert_eq!(
            rules.raw_text_mode_for_element("style"),
            Some(TransformTemplateRawTextMode::RawText)
        );
        assert_eq!(
            rules.raw_text_mode_for_element("title"),
            Some(TransformTemplateRawTextMode::Rcdata)
        );
        assert_eq!(
            rules.raw_text_mode_for_element("script"),
            Some(TransformTemplateRawTextMode::ScriptData)
        );
        assert!(rules.is_valid_identifier("custom-element"));
        assert!(!rules.is_valid_identifier("bad name"));
    }

    #[test]
    fn target_syntax_rules_describe_xml_namespaces_and_empty_elements() {
        let target =
            TransformTemplateEncodingTarget::new(XML_CONTENT_TYPE, XML_SCHEMA_URI, "xml-text");
        let options = TransformTemplateEncodeOptions {
            namespace_policy: Some("canonical".to_owned()),
            namespace_placement: Some("root".to_owned()),
            ..TransformTemplateEncodeOptions::default()
        };

        let rules = target
            .syntax_rules(&options)
            .expect("XML syntax rules resolve");

        assert_eq!(rules.syntax, TransformTemplateTargetSyntaxKind::Xml);
        assert_eq!(
            rules.element_boundary_policy,
            TransformTemplateElementBoundaryPolicy::XmlEmptyElements
        );
        assert_eq!(
            rules.namespace_repair_policy,
            TransformTemplateNamespaceRepairPolicy::Canonical
        );
        assert_eq!(
            rules.namespace_declaration_placement,
            TransformTemplateNamespaceDeclarationPlacement::Root
        );
        assert!(rules.permits_mode(TransformTemplateEncodedArtifactMode::Fragment));
        assert!(rules.is_valid_identifier("svg:path"));
        assert!(!rules.is_valid_identifier("1bad"));
        assert_eq!(rules.raw_text_mode_for_element("script"), None);

        let canonical_rules = target
            .syntax_rules(&TransformTemplateEncodeOptions {
                namespace_policy: Some("canonical".to_owned()),
                ..TransformTemplateEncodeOptions::default()
            })
            .expect("canonical XML syntax rules resolve");
        assert_eq!(
            canonical_rules.namespace_declaration_placement,
            TransformTemplateNamespaceDeclarationPlacement::Canonical
        );
    }

    #[test]
    fn target_syntax_rules_gate_json_csv_and_unknown_targets() {
        let json_target = TransformTemplateEncodingTarget::new(
            "application/json",
            JSON_VALUE_SCHEMA_URI,
            "json-value",
        );
        let json_rules = json_target
            .syntax_rules(&TransformTemplateEncodeOptions::default())
            .expect("JSON syntax rules resolve");
        assert_eq!(json_rules.syntax, TransformTemplateTargetSyntaxKind::Json);
        assert_eq!(
            json_rules.field_header_policy,
            TransformTemplateFieldHeaderPolicy::JsonObjectFields
        );
        assert_eq!(
            json_rules.namespace_repair_policy,
            TransformTemplateNamespaceRepairPolicy::None
        );
        assert!(!json_rules.permits_mode(TransformTemplateEncodedArtifactMode::Fragment));
        assert!(json_rules.permits_mode(TransformTemplateEncodedArtifactMode::Document));
        assert!(json_rules.is_valid_identifier("field with spaces"));
        assert!(!json_rules.is_valid_identifier("field\nbreak"));
        assert!(json_rules.is_valid_field_name("field with spaces"));
        assert!(!json_rules.is_valid_field_name("field\nbreak"));
        assert!(!json_rules.is_valid_header_name("field"));

        let json_namespace_error = json_target
            .syntax_rules(&TransformTemplateEncodeOptions {
                namespace_policy: Some("repair".to_owned()),
                ..TransformTemplateEncodeOptions::default()
            })
            .expect_err("JSON rejects namespace policy");
        assert!(json_namespace_error.contains("not supported for `json` target syntax"));

        let json_namespace_placement_error = json_target
            .syntax_rules(&TransformTemplateEncodeOptions {
                namespace_placement: Some("root".to_owned()),
                ..TransformTemplateEncodeOptions::default()
            })
            .expect_err("JSON rejects namespace declaration placement");
        assert!(json_namespace_placement_error
            .contains("namespace declaration placement `root` is not supported for `json`"));

        let yaml_rules = TransformTemplateEncodingTarget::new(
            "text/yaml; charset=utf-8",
            YAML_SCHEMA_URI,
            "yaml-value",
        )
        .syntax_rules(&TransformTemplateEncodeOptions::default())
        .expect("YAML syntax rules resolve");
        assert_eq!(yaml_rules.syntax, TransformTemplateTargetSyntaxKind::Yaml);
        assert_eq!(
            yaml_rules.writer_boundaries.default_charset.as_deref(),
            Some("utf-8")
        );
        assert!(yaml_rules.permits_mode(TransformTemplateEncodedArtifactMode::Fragment));

        let csv_rules = TransformTemplateEncodingTarget::new(
            "text/csv; charset=utf-8",
            CSV_SCHEMA_URI,
            "csv-record",
        )
        .syntax_rules(&TransformTemplateEncodeOptions::default())
        .expect("CSV syntax rules resolve");
        assert_eq!(csv_rules.syntax, TransformTemplateTargetSyntaxKind::Csv);
        assert_eq!(
            csv_rules.field_header_policy,
            TransformTemplateFieldHeaderPolicy::CsvHeaders
        );
        assert_eq!(
            csv_rules.writer_boundaries.final_newline,
            TransformTemplateFinalNewlinePolicy::Optional
        );
        assert!(csv_rules.is_valid_identifier("Column A"));
        assert!(!csv_rules.is_valid_identifier("Column\nA"));
        assert!(csv_rules.is_valid_header_name("Column A"));
        assert!(!csv_rules.is_valid_header_name("Column\nA"));
        assert!(!csv_rules.is_valid_field_name("Column A"));

        let binary_rules = TransformTemplateEncodingTarget::new(
            "application/octet-stream",
            "https://example.test/ns/blob/1",
            "binary",
        )
        .syntax_rules(&TransformTemplateEncodeOptions::default())
        .expect("binary syntax rules resolve");
        assert_eq!(
            binary_rules.syntax,
            TransformTemplateTargetSyntaxKind::Binary
        );
        assert!(!binary_rules.writer_boundaries.requires_valid_utf8);
        assert!(binary_rules.writer_boundaries.allows_binary_output);
        assert!(binary_rules.writer_boundaries.default_charset.is_none());

        let opaque_rules = TransformTemplateEncodingTarget::new(
            "application/x-custom",
            "https://example.test/ns/opaque/1",
            "opaque",
        )
        .syntax_rules(&TransformTemplateEncodeOptions::default())
        .expect("opaque syntax rules resolve");
        assert_eq!(
            opaque_rules.syntax,
            TransformTemplateTargetSyntaxKind::Opaque
        );
        assert!(!opaque_rules.permits_mode(TransformTemplateEncodedArtifactMode::Document));
        assert!(!opaque_rules.is_valid_identifier("field"));
        assert!(opaque_rules.writer_boundaries.default_charset.is_none());
    }

    #[test]
    fn parse_encode_expression_lowers_target_and_options() {
        let parsed = parse_transform_template_encode_expression(
            r#"encode(
                $node.data,
                {
                    contentType: "text/html",
                    schema: "https://cem.dev/ns/data/html/1",
                    category: "html-text",
                    context: "text"
                },
                {
                    mode: "fragment",
                    encoder: "html.text",
                    formatter: "html.pretty",
                    colorizer: "html.classes",
                    profile: "html-pretty",
                    formatterProfile: "html.formatter-profile",
                    colorProfile: "classes",
                    charset: "utf-8",
                    lineEnding: "lf",
                    quotePolicy: "double",
                    ordering: "lexical",
                    wrapColumn: "72",
                    indent: "  ",
                    tabSize: "6",
                    namespacePolicy: "repair",
                    namespacePlacement: "root",
                    binaryFraming: "cem-bin/ast-v1",
                    raw: true,
                    allowLossy: true,
                    sourceMap: "generated"
                }
            )"#,
            Some("main"),
        )
        .expect("parse should succeed")
        .expect("encode expression");

        assert_eq!(parsed.owner.as_deref(), Some("main"));
        assert_eq!(parsed.subject, "$node.data");
        assert_eq!(parsed.target.content_type, "text/html");
        assert_eq!(parsed.target.schema, "https://cem.dev/ns/data/html/1");
        assert_eq!(parsed.target.category, "html-text");
        assert_eq!(parsed.target.context.as_deref(), Some("text"));
        assert_eq!(
            parsed.options.mode,
            TransformTemplateEncodedArtifactMode::Fragment
        );
        assert_eq!(parsed.options.encoder.as_deref(), Some("html.text"));
        assert_eq!(parsed.options.formatter.as_deref(), Some("html.pretty"));
        assert_eq!(parsed.options.colorizer.as_deref(), Some("html.classes"));
        assert_eq!(parsed.options.profile.as_deref(), Some("html-pretty"));
        assert_eq!(
            parsed.options.formatter_profile.as_deref(),
            Some("html.formatter-profile")
        );
        assert_eq!(parsed.options.color_profile.as_deref(), Some("classes"));
        assert_eq!(parsed.options.charset.as_deref(), Some("utf-8"));
        assert_eq!(parsed.options.line_ending.as_deref(), Some("lf"));
        assert_eq!(parsed.options.quote_policy.as_deref(), Some("double"));
        assert_eq!(parsed.options.ordering.as_deref(), Some("lexical"));
        assert_eq!(parsed.options.wrap_column.as_deref(), Some("72"));
        assert_eq!(parsed.options.indent.as_deref(), Some("  "));
        assert_eq!(parsed.options.tab_size.as_deref(), Some("6"));
        assert_eq!(parsed.options.namespace_policy.as_deref(), Some("repair"));
        assert_eq!(parsed.options.namespace_placement.as_deref(), Some("root"));
        assert_eq!(
            parsed.options.binary_framing.as_deref(),
            Some("cem-bin/ast-v1")
        );
        assert!(parsed.options.raw);
        assert!(parsed.options.allow_lossy);
        assert_eq!(
            parsed.options.source_map_policy,
            TransformTemplateSourceMapPolicy::Generated
        );
    }

    #[test]
    fn parse_encode_expression_supports_all_option_mode_selectors() {
        for (mode, expected) in [
            (
                "canonical",
                (
                    true,
                    false,
                    false,
                    TransformTemplateEncodedArtifactMode::Document,
                ),
            ),
            (
                "preserve",
                (
                    false,
                    true,
                    false,
                    TransformTemplateEncodedArtifactMode::Document,
                ),
            ),
            (
                "pretty",
                (
                    false,
                    false,
                    true,
                    TransformTemplateEncodedArtifactMode::Document,
                ),
            ),
            (
                "fragment",
                (
                    false,
                    false,
                    false,
                    TransformTemplateEncodedArtifactMode::Fragment,
                ),
            ),
            (
                "document",
                (
                    false,
                    false,
                    false,
                    TransformTemplateEncodedArtifactMode::Document,
                ),
            ),
        ] {
            let expression = format!(
                r#"encode($node.data, {{ contentType: "text/html", schema: "https://cem.dev/ns/data/html/1", category: "html-text" }}, {{ mode: "{mode}" }})"#
            );
            let parsed = parse_transform_template_encode_expression(&expression, None)
                .expect("parse should succeed")
                .expect("encode expression");

            assert_eq!(parsed.options.canonical, expected.0, "{mode} canonical");
            assert_eq!(parsed.options.preserve, expected.1, "{mode} preserve");
            assert_eq!(parsed.options.pretty, expected.2, "{mode} pretty");
            assert_eq!(parsed.options.mode, expected.3, "{mode} artifact mode");
        }
    }

