    #[test]
    fn evaluate_encode_expressions_resolves_subject_and_wraps_artifact() {
        let response = parse_cem_native_template_module_options(
            TransformTemplateModuleParseRequest {
                template: template_input(
                    "templates/runtime-encoding.cemt",
                    r#"{@doc cem-ml 1}
{module |
  {encoding-function
      @name="html.text"
      @category="html-text"
      @subject="string"
      @produces="text"
      @content-type="text/html"
      @schema="https://cem.dev/ns/data/html/1"
      @canonical=true
      @streamable=true
      @deterministic=true |
      {param @name="subject" @type="string" @required=true}
  }
  {template @name="main" @visibility="public" |
    {body |
      {$ encode($node.data, { contentType: "text/html", schema: "https://cem.dev/ns/data/html/1", category: "html-text", context: "text" }, { mode: "fragment", encoder: "html.text" }) }
    }
  }
}"#,
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            },
        );
        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        let registry =
            TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
        let mut values = BTreeMap::new();
        values.insert("node".to_owned(), json!({"data": "Hello & CEM"}));

        let evaluated = evaluate_transform_template_encode_expressions(
            &response.module_options.encode_expressions,
            TransformTemplateEncodeEvaluationContext {
                registry: &registry,
                value_bindings: &values,
                host_capabilities: &BTreeSet::new(),
                output_color_type: None,
                uri: Some("templates/runtime-encoding.cemt"),
            },
            |binding, subject| {
                assert_eq!(binding.function.name, "html.text");
                assert_eq!(subject, &Value::String("Hello & CEM".to_owned()));
                Ok(Value::String("Hello &amp; CEM".to_owned()))
            },
        );

        assert!(
            evaluated.diagnostics.is_empty(),
            "{:?}",
            evaluated.diagnostics
        );
        assert_eq!(evaluated.encoded.len(), 1);
        let artifact = &evaluated.encoded[0].artifact;
        assert_eq!(
            artifact.identity.produces,
            TransformTemplateOutputProducedKind::Text
        );
        assert_eq!(artifact.identity.target.category, "html-text");
        assert_eq!(artifact.identity.target.context.as_deref(), Some("text"));
        assert!(artifact.identity.canonical);
        assert_eq!(artifact.value, Value::String("Hello &amp; CEM".to_owned()));

        let insertion_context =
            TransformTemplateEncodedArtifactInsertionContext::from_encoding_target(
                &evaluated.encoded[0].expression.target,
                Some(TransformTemplateOutputProducedKind::Text),
            );
        assert!(evaluated
            .validate_insertions(&insertion_context, Some("templates/runtime-encoding.cemt"))
            .is_empty());

        let mismatch_context = insertion_context
            .clone()
            .with_context("double-quoted-attribute");
        let insertion_diagnostics = evaluated
            .validate_insertions(&mismatch_context, Some("templates/runtime-encoding.cemt"));
        assert!(insertion_diagnostics.iter().any(|diagnostic| {
            diagnostic.code == TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_CONTEXT_MISMATCH_CODE
                && diagnostic.node.as_deref() == Some("main")
        }));
        assert!(insertion_diagnostics.iter().any(|diagnostic| {
            diagnostic.code == TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_INSERTION_INCOMPATIBLE_CODE
                && diagnostic.node.as_deref() == Some("main")
                && diagnostic.message.contains("context")
        }));
    }

    #[test]
    fn evaluate_encode_expressions_runs_formatter_bindings_to_cem_tree() {
        let response = parse_cem_native_template_module_options(
            TransformTemplateModuleParseRequest {
                template: template_input(
                    "templates/runtime-format.cemt",
                    r#"{@doc cem-ml 1}
{module |
  {format-function
      @name="cem.format-tree"
      @category="cem-tree"
      @subject="cem-ast-node"
      @produces="cem-tree"
      @content-type="application/cem"
      @schema="https://cem.dev/ns/cem-ml/1"
      @canonical=true
      @deterministic=true
      @streamable=true |
      {param @name="subject" @type="object" @required=true}
  }
  {color-function
      @name="cem.color-tree"
      @category="cem-tree"
      @subject="cem-tree"
      @produces="cem-tree"
      @content-type="application/cem"
      @schema="https://cem.dev/ns/cem-ml/1"
      @profile="css-custom-properties"
      @canonical=false
      @deterministic=true
      @streamable=true |
      {param @name="subject" @type="object" @required=true}
  }
  {template @name="main" @visibility="public" |
    {body |
      {let @name="formatterName" @value="cem.format-tree"}
      {let @name="colorizerName" @value="cem.color-tree"}
      {let @name="colorProfile" @value="css-custom-properties"}
      {$ encode($node.ast, { contentType: "application/cem", schema: "https://cem.dev/ns/cem-ml/1", category: "cem-tree", subjectType: "cem-ast-node" }, { formatter: match($node.ast.kind, { element: $formatterName, default: "cem.format-tree" }), colorizer: match($node.ast.name, { card: $colorizerName, default: "cem.color-tree" }), colorProfile: match(exists($node.ast.children.0), { true: $colorProfile, false: "none" }), canonical: true }) }
    }
  }
}"#,
                    Some(FormatIdentity {
                        schema: Some(CEM_TRANSFORM_SCHEMA_URI.to_owned()),
                        ..FormatIdentity::default()
                    }),
                ),
            },
        );
        assert!(
            response.diagnostics.is_empty(),
            "{:?}",
            response.diagnostics
        );
        assert_eq!(response.module_options.let_bindings.len(), 3);
        let registry =
            TransformTemplateOutputFunctionRegistry::from_module_options(&response.module_options);
        let implementations =
            TransformTemplateEncodeImplementationRegistry::with_builtin_encoders();
        let mut values = BTreeMap::new();
        values.insert(
            "node".to_owned(),
            json!({
                "ast": {
                    "kind": "element",
                    "name": "card",
                    "children": [{"kind": "text", "value": "Ready"}]
                }
            }),
        );
        apply_transform_template_let_bindings(
            &mut values,
            &response.module_options.let_bindings,
            Some("main"),
        );

        let mut executed = Vec::new();
        let evaluated = evaluate_transform_template_encode_expressions(
            &response.module_options.encode_expressions,
            TransformTemplateEncodeEvaluationContext {
                registry: &registry,
                value_bindings: &values,
                host_capabilities: implementations.host_capabilities(),
                output_color_type: None,
                uri: Some("templates/runtime-format.cemt"),
            },
            |binding, subject| {
                executed.push(binding.function.name.clone());
                if binding.function.kind == TransformTemplateOutputFunctionKind::Color {
                    assert_eq!(subject["kind"], "cem-tree");
                }
                implementations.encode(binding, subject)
            },
        );

        assert!(
            evaluated.diagnostics.is_empty(),
            "{:?}",
            evaluated.diagnostics
        );
        assert_eq!(evaluated.encoded.len(), 1);
        assert_eq!(executed, vec!["cem.format-tree", "cem.color-tree"]);
        let evaluated = &evaluated.encoded[0];
        assert_eq!(evaluated.binding.function.name, "cem.color-tree");
        assert_eq!(
            evaluated.artifact.identity.produces,
            TransformTemplateOutputProducedKind::CemTree
        );
        assert_eq!(
            evaluated.artifact.identity.color_profile.as_deref(),
            Some("css-custom-properties")
        );
        assert_eq!(evaluated.artifact.value["kind"], "cem-tree");
        assert_eq!(evaluated.artifact.value["colored"], true);
        assert_eq!(
            evaluated.artifact.value["formatNodes"][0]["style"]["colorRole"],
            "source.gutter"
        );
        assert_eq!(
            evaluated.artifact.value["colorNodes"][0]["name"],
            "cem.color-tree"
        );
        assert_eq!(
            cem_tree_color_decision(&evaluated.artifact.value, "profile")["value"],
            "css-custom-properties"
        );
        assert_eq!(evaluated.artifact.value["nodes"][0]["name"], "card");
        assert_eq!(
            evaluated.artifact.value["nodes"][0]["style"]["colorRole"],
            "syntax.name"
        );
        assert_eq!(
            evaluated.artifact.value["nodes"][0]["formatContentBoundary"][1]["style"]["colorRole"],
            "syntax.raw"
        );
        assert_eq!(
            evaluated.artifact.value["nodes"][0]["formatLayout"]["style"]["colorRole"],
            "source.gutter"
        );
    }

