    #[test]
    fn encoded_text_artifact_composition_reports_writer_adapter_boundary_for_non_token_artifacts() {
        let base = evaluated_html_text("body", "CEM");
        let context = TransformTemplateEncodedArtifactInsertionContext::from_encoding_target(
            &base.expression.target,
            Some(TransformTemplateOutputProducedKind::Text),
        );

        let cases = [
            (
                "bytes",
                TransformTemplateEncodedArtifact::from_writer_bytes(
                    base.artifact.identity.clone(),
                    b"CEM".to_vec(),
                ),
            ),
            (
                "diagnostics",
                TransformTemplateEncodedArtifact::from_writer_diagnostics(
                    base.artifact.identity.clone(),
                    vec![Diagnostic {
                        code: "cem.writer.example".to_owned(),
                        message: "writer diagnostic".to_owned(),
                        details: None,
                        ..Diagnostic::default()
                    }],
                ),
            ),
        ];

        for (kind, artifact) in cases {
            let mut evaluated = base.clone();
            evaluated.artifact = artifact;

            let response = compose_transform_template_encoded_text_artifacts(
                &[evaluated],
                &context,
                Some("templates/runtime-encoding.cemt"),
            );

            assert!(response.artifact.is_none());
            assert!(response.diagnostics.iter().any(|diagnostic| {
                diagnostic.code == TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_WRITER_ADAPTER_MISSING_CODE
                    && diagnostic.node.as_deref() == Some("body")
                    && diagnostic.message.contains(kind)
                    && diagnostic.message.contains("writer adapter")
            }));
        }
    }

    #[test]
    fn writer_artifacts_construct_typed_token_byte_chunk_and_diagnostic_values() {
        let target = TransformTemplateEncodingTarget::new(
            JSON_CONTENT_TYPE,
            JSON_VALUE_SCHEMA_URI,
            "writer-stream",
        );
        let token_artifact = TransformTemplateEncodedArtifact::from_writer_tokens(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Text,
                target.clone(),
            ),
            vec![
                TransformTemplateWriterToken::new("syntax.name")
                    .with_text("button")
                    .with_role("element")
                    .with_style_property("color", Value::String("syntax.element".to_owned()))
                    .with_style_property("emphasis", Value::Bool(true)),
                TransformTemplateWriterToken::new("syntax.attribute")
                    .with_value(json!({"name": "type", "value": "button"})),
            ],
        );
        assert_eq!(
            token_artifact.identity.produces,
            TransformTemplateOutputProducedKind::Tokens
        );
        assert_eq!(token_artifact.value["tokens"][0]["kind"], "syntax.name");
        assert_eq!(
            token_artifact.value["tokens"][0]["style"]["color"],
            "syntax.element"
        );
        assert_eq!(token_artifact.value["tokens"][0]["style"]["emphasis"], true);
        token_artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &token_artifact.identity,
                ),
            )
            .expect("token stream value shape is valid");

        let byte_artifact = TransformTemplateEncodedArtifact::from_writer_bytes(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Text,
                target.clone(),
            ),
            vec![0, 127, 255],
        );
        assert_eq!(
            byte_artifact.identity.produces,
            TransformTemplateOutputProducedKind::Bytes
        );
        assert_eq!(byte_artifact.value["encoding"], "u8-array");
        assert_eq!(byte_artifact.value["byteLength"], 3);
        byte_artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &byte_artifact.identity,
                ),
            )
            .expect("byte stream value shape is valid");

        let chunk_artifact = TransformTemplateEncodedArtifact::from_writer_chunks(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Text,
                target.clone(),
            ),
            vec![
                TransformTemplateWriterChunk::text("header", "<doc>").with_id("c1"),
                TransformTemplateWriterChunk::bytes("payload", vec![1, 2, 3]).sealed(),
            ],
        );
        assert_eq!(
            chunk_artifact.identity.produces,
            TransformTemplateOutputProducedKind::Chunks
        );
        assert_eq!(chunk_artifact.value["chunks"][1]["sealed"], true);
        chunk_artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &chunk_artifact.identity,
                ),
            )
            .expect("chunk stream value shape is valid");

        let diagnostic_artifact = TransformTemplateEncodedArtifact::from_writer_diagnostics(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Text,
                target,
            ),
            vec![Diagnostic {
                code: "cem.writer.example".to_owned(),
                severity: Severity::Warning,
                message: "writer warning".to_owned(),
                details: None,
                ..Diagnostic::default()
            }],
        );
        assert_eq!(
            diagnostic_artifact.identity.produces,
            TransformTemplateOutputProducedKind::Diagnostics
        );
        assert_eq!(
            diagnostic_artifact.value["diagnostics"][0]["code"],
            "cem.writer.example"
        );
        diagnostic_artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &diagnostic_artifact.identity,
                ),
            )
            .expect("diagnostic stream value shape is valid");
    }

    #[test]
    fn binary_writer_artifact_validates_binary_framing_identity() {
        let target = TransformTemplateEncodingTarget::new(
            CEM_AST_PROJECTION_CONTENT_TYPE,
            CEM_AST_PROJECTION_SCHEMA_URI,
            "cem-bin-document",
        );
        let mut identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::Bytes,
            target,
        );
        identity.binary_framing = Some("cem-bin/ast-v1".to_owned());
        let artifact = TransformTemplateEncodedArtifact::from_writer_bytes(
            identity.clone(),
            vec![0x43, 0x45, 0x4d],
        );

        artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &artifact.identity,
                ),
            )
            .expect("matching binary framing is accepted");
        artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::new(
                    CEM_AST_PROJECTION_CONTENT_TYPE,
                    CEM_AST_PROJECTION_SCHEMA_URI,
                )
                .with_category("cem-bin-document")
                .with_produces(TransformTemplateOutputProducedKind::Bytes)
                .with_binary_framing("cem-bin/ast-v1"),
            )
            .expect("explicit matching binary framing is accepted");

        let mut chunk_identity = identity.clone();
        chunk_identity.produces = TransformTemplateOutputProducedKind::Chunks;
        let chunk_artifact = TransformTemplateEncodedArtifact::from_writer_chunks(
            chunk_identity,
            vec![TransformTemplateWriterChunk::bytes("payload", vec![0x43, 0x45, 0x4d]).sealed()],
        );
        chunk_artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::new(
                    CEM_AST_PROJECTION_CONTENT_TYPE,
                    CEM_AST_PROJECTION_SCHEMA_URI,
                )
                .with_category("cem-bin-document")
                .with_produces(TransformTemplateOutputProducedKind::Chunks)
                .with_binary_framing("cem-bin/ast-v1"),
            )
            .expect("matching chunk binary framing is accepted");

        let framing_error = artifact
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::new(
                    CEM_AST_PROJECTION_CONTENT_TYPE,
                    CEM_AST_PROJECTION_SCHEMA_URI,
                )
                .with_category("cem-bin-document")
                .with_produces(TransformTemplateOutputProducedKind::Bytes)
                .with_binary_framing("cem-bin/dom-v1"),
            )
            .expect_err("mismatched binary framing is rejected");
        assert_eq!(
            framing_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_CONTEXT_MISMATCH_CODE
        );
        assert!(framing_error.message().contains("binaryFraming"));
        assert!(framing_error.message().contains("cem-bin/dom-v1"));
    }

    #[test]
    fn writer_artifact_value_shape_validation_rejects_invalid_envelopes() {
        let target = TransformTemplateEncodingTarget::new(
            JSON_CONTENT_TYPE,
            JSON_VALUE_SCHEMA_URI,
            "writer-stream",
        );
        let token_identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::Tokens,
            target.clone(),
        );
        let invalid_tokens = TransformTemplateEncodedArtifact::new(
            token_identity,
            json!({"tokens": [{"text": "x"}]}),
        );
        let token_error = invalid_tokens
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &invalid_tokens.identity,
                ),
            )
            .expect_err("token without kind is rejected");
        assert_eq!(
            token_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(token_error.message().contains("tokens[0].kind"));

        let null_token_span = TransformTemplateEncodedArtifact::new(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Tokens,
                target.clone(),
            ),
            json!({"tokens": [{"kind": "syntax.text", "text": "x", "outputSpan": null}]}),
        );
        null_token_span
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &null_token_span.identity,
                ),
            )
            .expect("null optional token output span is treated as absent");

        let invalid_token_span = TransformTemplateEncodedArtifact::new(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Tokens,
                target.clone(),
            ),
            json!({"tokens": [{"kind": "syntax.text", "text": "x", "outputSpan": "bad"}]}),
        );
        let token_span_error = invalid_token_span
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &invalid_token_span.identity,
                ),
            )
            .expect_err("invalid token output span is rejected");
        assert_eq!(
            token_span_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(token_span_error.message().contains("tokens[0].outputSpan"));

        let invalid_token_style = TransformTemplateEncodedArtifact::new(
            TransformTemplateEncodedArtifactIdentity::new(
                TransformTemplateOutputProducedKind::Tokens,
                target.clone(),
            ),
            json!({"tokens": [{"kind": "syntax.text", "text": "x", "style": {"color": {"bad": true}}}]}),
        );
        let token_style_error = invalid_token_style
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &invalid_token_style.identity,
                ),
            )
            .expect_err("invalid token style is rejected");
        assert_eq!(
            token_style_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(token_style_error
            .message()
            .contains("tokens[0].style.color"));

        let byte_identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::Bytes,
            target.clone(),
        );
        let invalid_bytes = TransformTemplateEncodedArtifact::new(
            byte_identity,
            json!({"encoding": "u8-array", "bytes": [0, 256], "byteLength": 2}),
        );
        let byte_error = invalid_bytes
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &invalid_bytes.identity,
                ),
            )
            .expect_err("out-of-range byte is rejected");
        assert_eq!(
            byte_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(byte_error.message().contains("bytes[1]"));

        let chunk_identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::Chunks,
            target,
        );
        let invalid_chunks = TransformTemplateEncodedArtifact::new(
            chunk_identity,
            json!({"chunks": [{"kind": "empty"}]}),
        );
        let chunk_error = invalid_chunks
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &invalid_chunks.identity,
                ),
            )
            .expect_err("chunk without payload is rejected");
        assert_eq!(
            chunk_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(chunk_error.message().contains("chunks[0]"));
    }

    #[test]
    fn cem_tree_artifact_value_shape_validation_rejects_invalid_pipeline_metadata() {
        let target = TransformTemplateEncodingTarget::new(
            CEM_ML_CONTENT_TYPE,
            CEM_ML_SCHEMA_URI,
            "cem-tree",
        );
        let mut identity = TransformTemplateEncodedArtifactIdentity::new(
            TransformTemplateOutputProducedKind::CemTree,
            target,
        );
        identity.formatter_profile = Some("compact".to_owned());
        identity.color_profile = Some("css-custom-properties".to_owned());

        let mut missing_writer_nodes =
            encode_colored_cem_tree_with_profile("css-custom-properties");
        missing_writer_nodes
            .get_mut("nodes")
            .and_then(Value::as_array_mut)
            .and_then(|nodes| nodes.first_mut())
            .and_then(Value::as_object_mut)
            .expect("colored element object")
            .remove("writerAttributeNodes");
        let missing_writer_nodes =
            TransformTemplateEncodedArtifact::new(identity.clone(), missing_writer_nodes);
        let writer_nodes_error = missing_writer_nodes
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &missing_writer_nodes.identity,
                ),
            )
            .expect_err("colored CEM tree without materialized writer nodes is rejected");
        assert_eq!(
            writer_nodes_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(writer_nodes_error
            .message()
            .contains("writerAttributeNodes"));

        let mut missing_format_nodes =
            encode_colored_cem_tree_with_profile("css-custom-properties");
        missing_format_nodes
            .as_object_mut()
            .expect("colored CEM tree object")
            .remove("formatNodes");
        let missing_format_nodes =
            TransformTemplateEncodedArtifact::new(identity, missing_format_nodes);
        let format_nodes_error = missing_format_nodes
            .validate_insertion(
                &TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                    &missing_format_nodes.identity,
                ),
            )
            .expect_err("formatted CEM tree without format nodes is rejected");
        assert_eq!(
            format_nodes_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_VALUE_TYPE_CODE
        );
        assert!(format_nodes_error.message().contains("formatNodes"));
    }

    #[test]
    fn encoded_artifact_validates_matching_insertion_context() {
        let artifact = encoded_html_text_artifact();
        let context = TransformTemplateEncodedArtifactInsertionContext {
            produces: Some(TransformTemplateOutputProducedKind::Text),
            content_type: "text/html; charset=utf-8".to_owned(),
            schema: "https://cem.dev/ns/data/html/1".to_owned(),
            category: Some("html-text".to_owned()),
            context: Some("text".to_owned()),
            formatter_profile: Some("html-pretty".to_owned()),
            color_profile: None,
            color_capability: None,
            output_color_type: None,
            binary_framing: None,
            mode: Some(TransformTemplateEncodedArtifactMode::Fragment),
            canonical: Some(true),
            source_map_policy: Some(TransformTemplateSourceMapPolicy::Generated),
        };

        artifact
            .validate_insertion(&context)
            .expect("matching insertion context");

        let output = artifact.into_output_artifact(Some("out/page.html".to_owned()));
        assert_eq!(output.uri.as_deref(), Some("out/page.html"));
        assert_eq!(
            output
                .identity
                .as_ref()
                .and_then(|identity| identity.content_type.as_deref()),
            Some("text/html")
        );
        assert_eq!(
            output
                .identity
                .as_ref()
                .and_then(|identity| identity.schema.as_deref()),
            Some("https://cem.dev/ns/data/html/1")
        );
        assert_eq!(output.value, Value::String("Hello &amp; CEM".to_owned()));
    }

    #[test]
    fn encoded_artifact_rejects_incompatible_context_and_double_encoding() {
        let artifact = encoded_html_text_artifact();
        let context_error = artifact
            .validate_insertion(&TransformTemplateEncodedArtifactInsertionContext {
                produces: Some(TransformTemplateOutputProducedKind::Text),
                content_type: "text/html".to_owned(),
                schema: "https://cem.dev/ns/data/html/1".to_owned(),
                category: Some("html-attribute".to_owned()),
                context: Some("double-quoted-attribute".to_owned()),
                formatter_profile: None,
                color_profile: None,
                color_capability: None,
                output_color_type: None,
                binary_framing: None,
                mode: None,
                canonical: None,
                source_map_policy: None,
            })
            .expect_err("category/context mismatch is rejected");

        assert!(matches!(
            context_error,
            TransformTemplateEncodedArtifactError::ContextMismatch { .. }
        ));
        assert_eq!(
            context_error.diagnostic(Some("template.cemt")).code,
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_CONTEXT_MISMATCH_CODE
        );
        assert_eq!(
            context_error
                .incompatible_insertion_diagnostic(Some("template.cemt"))
                .code,
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_INSERTION_INCOMPATIBLE_CODE
        );

        let double_encoding = artifact
            .validate_as_encode_input()
            .expect_err("encoded artifacts cannot be encoded again");
        assert_eq!(
            double_encoding.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_DOUBLE_ENCODING_CODE
        );

        let mut source_map_context =
            TransformTemplateEncodedArtifactInsertionContext::from_encoded_artifact_identity(
                &artifact.identity,
            );
        source_map_context.source_map_policy = Some(TransformTemplateSourceMapPolicy::None);
        let source_map_error = artifact
            .validate_insertion(&source_map_context)
            .expect_err("source map policy mismatch is rejected");
        assert_eq!(
            source_map_error.code(),
            TRANSFORM_TEMPLATE_ENCODED_ARTIFACT_CONTEXT_MISMATCH_CODE
        );
        assert!(source_map_error.message().contains("sourceMapPolicy"));
    }

